Println()
{
    printf '\n%b\n' "$1"
}

Trim()
{
    local text="${!1}"
    text="${text#"${text%%[![:space:]]*}"}"
    text="${text%"${text##*[![:space:]]}"}"
    read -r ${1} <<< "$text"
}

JoinByChar()
{
    local IFS="$1"
    shift
    printf "%s" "$*"
}

JoinByString()
{
    local separator="$1"
    shift
    local first="$1"
    shift
    printf "%s" "$first" "${@/#/$separator}"
}

JoinByStringUnquote()
{
    local separator="$1"
    shift

    local cleaned=( "${@#\"}" )
    cleaned=( "${cleaned[@]%\"}" )
    cleaned=( "${cleaned[@]//\\\"/\"}" )
    cleaned=( "${cleaned[@]//\\\\/\\}" )

    local result
    printf -v result "%s%s" "${cleaned[@]/#/$separator}"

    printf "%s" "${result#"$separator"}"
}

ToJsonArray()
{
    local var=("$1"[@])
    if [[ -z "${!var:-}" ]]
    then
        echo "[]"
        return 0
    fi
    local arr=("${!var}")
    local json_array=$(printf '%s\n' "${arr[@]}" | $JQ_FILE -R . | $JQ_FILE -s -c .)
    echo $json_array
}

ToQuoteArray()
{
    if [[ -z "${1:-}" ]]
    then
        return 1
    fi

    local keys
    eval "keys=(\"\${!$1[@]}\")"

    if [[ ${#keys[@]} -eq 0 ]]
    then
        return 0
    fi

    local i quoted_ele val

    for i in "${keys[@]}"
    do
        eval "val=\"\${$1[$i]}\""

        quoted_ele="${val//\\/\\\\}"
        quoted_ele="${quoted_ele//\"/\\\"}"
        quoted_ele="\"$quoted_ele\""

        eval "$1[$i]=\"\$quoted_ele\""
    done

    return 0
}

ToUnquoteArray()
{
    if [[ -z "${1:-}" ]]
    then
        return 1
    fi

    local keys
    eval "keys=(\"\${!$1[@]}\")"

    local i val unquoted

    for i in "${keys[@]}"
    do
        eval "val=\"\${$1[$i]}\""

        unquoted="${val#\"}"
        unquoted="${unquoted%\"}"
        unquoted="${unquoted//\\\"/\"}"
        unquoted="${unquoted//\\\\/\\}"

        eval "$1[$i]=\"\$unquoted\""
    done

    return 0
}

ArrayToQuotedList()
{
    ToQuoteArray "$@"

    local var=("$1"[@])

    if [[ -z "${!var:-}" ]]
    then
        return 0
    fi

    local arr=("${!var}")

    JoinByString ', ' "${arr[@]}"
}

ArrayToList()
{
    local var=("$1"[@])

    if [[ -z "${!var:-}" ]]
    then
        return 0
    fi

    local arr=("${!var}")

    JoinByString ', ' "${arr[@]}"
}

ArrayToPath()
{
    local var=("$1"[@])

    if [[ -z "${!var:-}" ]]
    then
        return 0
    fi

    local arr=("${!var}")

    JoinByChar , "${arr[@]}"
}

StringToList()
{
    local text="${!1}"

    if [ -z "${text:-}" ]
    then
        return 0
    fi

    IFS=" " read -r -a array_to_list <<< "$text"

    ArrayToList array_to_list
}

StringToQuotedList()
{
    local text="${!1}"

    if [ -z "${text:-}" ]
    then
        return 0
    fi

    IFS=" " read -r -a array_to_list <<< "$text"

    ArrayToQuotedList array_to_list
}

StringToPath()
{
    local text="${!1}"

    if [ -z "${text:-}" ]
    then
        return 0
    fi

    IFS=" " read -r -a array_to_list <<< "$text"

    ArrayToPath array_to_list
}

shopt -s extglob

EleInArray()
{
    local ele="$1"
    shift
    local var=("$1"[@])
    if [[ -z "${!var:-}" ]]
    then
        return 1
    fi
    local arr=("${!var}")
    [[ "$ele" == @($(JoinByChar '|' "${arr[@]//|/\\|}")) ]]
}

printf()
{
    if [ "${BASH_VERSINFO[0]}" -lt 4 ]
    then
        if [[ "${3:-}" =~ \%\((.+)\)T ]]
        then
            if [ "${4:--1}" == "-1" ]
            then
                read -r $2 < <(date +"${BASH_REMATCH[1]}")
            elif [ "$dist" == "mac" ] && ! type -p gdate &>/dev/null
            then
                read -r $2 < <(date -r $4 +"${BASH_REMATCH[1]}")
            else
                read -r $2 < <(date +"${BASH_REMATCH[1]}" -d @$4)
            fi

            return 0
        elif [[ "$1" =~ \%\((.+)\)T ]]
        then
            if [ "${2:--1}" == "-1" ]
            then
                echo $(date +"${BASH_REMATCH[1]}")
            elif [ "$dist" == "mac" ] && ! type -p gdate &>/dev/null
            then
                echo $(date -r $2 +"${BASH_REMATCH[1]}")
            else
                echo $(date +"${BASH_REMATCH[1]}" -d @$2)
            fi

            return 0
        fi
    fi

    builtin printf "$@"
}

CurlFake()
{
    CurlImpersonateInstall
    local service_name="$1"
    if [[ -x "${CURL_IMPERSONATE_FILE}-$service_name" ]]
    then
        shift
        "${CURL_IMPERSONATE_FILE}-$service_name" "$@"
        return 0
    elif [ "$service_name" == "xtream_codes" ]
    then
        rm -f "${CURL_IMPERSONATE_FILE}-$service_name"
        awk '!x{x=sub(/dir=.*/,"dir='"$DEPENDS_ROOT/curl-impersonate"'")}1' "$DEPENDS_ROOT/curl-impersonate/curl_chrome99_android" > "${CURL_IMPERSONATE_FILE}-$service_name"
        chmod +x "${CURL_IMPERSONATE_FILE}-$service_name"
        echo "$(awk '!x{x=sub(/-H '\''User-Agent: .*'\'' \\/,"-H '\''User-Agent: '"$USER_AGENT_TV"''\'' \\")}1' "${CURL_IMPERSONATE_FILE}-$service_name")" > "${CURL_IMPERSONATE_FILE}-$service_name"
        shift
        "${CURL_IMPERSONATE_FILE}-$service_name" "$@"
        return 0
    fi
    $CURL_IMPERSONATE_FILE "$@"
}

SetDelimiters()
{
    [ -n "${delimiters:-}" ] && return 0

    delimiters=(
        $'\x02' $'\x03' $'\x04' $'\x05' $'\x06'
        $'\x11' $'\x12' $'\x13' $'\x14' $'\x15'
        $'\x16' $'\x17' $'\x18' $'\x19' $'\x1A'
        $'\x1B' $'\x1C' $'\x1D' $'\x1E' $'\x1F'
    )

    field_sep="${delimiters[19]}"
    json_delimiters="$(ToJsonArray delimiters)"
}

RandStr()
{
    local str_size=${1:-8}
    local str_array=(
        q w e r t y u i o p a s d f g h j k l z x c v b n m
        Q W E R T Y U I O P A S D F G H J K L Z X C V B N M
    )
    local str_array_size=${#str_array[*]}
    local str_len=0
    local rand_str="" str_index
    while [[ $str_len -lt $str_size ]]
    do
        str_index=$((RANDOM%str_array_size))
        rand_str="$rand_str${str_array[str_index]}"
        str_len=$((str_len+1))
    done
    echo "$rand_str"
}

# printf %s "$1" | jq -s -R -r @uri
Urlencode()
{
    local LC_ALL='' LANG=C i c e=''
    for ((i=0;i<${#1};i++))
    do
        c=${1:$i:1}
        [[ $c =~ [a-zA-Z0-9\.\~\_\-] ]] || printf -v c '%%%02x' "'$c"
        e+="$c"
    done
    echo "$e"
}

UrlencodeUpper()
{
    local LC_ALL='' LANG=C i c e=''
    for ((i=0;i<${#1};i++))
    do
        c=${1:$i:1}
        [[ $c =~ [a-zA-Z0-9\.\~\_\-] ]] || printf -v c '%%%02X' "'$c"
        e+="$c"
    done
    echo "$e"
}

Urldecode()
{
    local i="${*//+/ }"
    echo -e "${i//%/\\x}"
}

GetServerIp()
{
    local ip
    ip=$(dig +short myip.opendns.com @resolver1.opendns.com) || true
    if [ -z "$ip" ] || [ "${#ip}" -gt 15 ]
    then
        ip=$(curl -s whatismyip.akamai.com)
    fi
    [ -z "$ip" ] && ip=$(curl -s ipv4.icanhazip.com)
    [ -z "$ip" ] && ip=$(curl -s api.ip.sb/ip)
    [ -z "$ip" ] && ip=$(curl -s ipinfo.io/ip)
    echo "$ip"
}

GetFreePort()
{
    local lport uport
    if [ -n "${1:-}" ] && [ -n "${2:-}" ]
    then
        lport=$1
        uport=$2
    elif [ "$dist" == "mac" ]
    then
        lport=1024
        uport=49151
    else
        read lport uport < /proc/sys/net/ipv4/ip_local_port_range
    fi

    if [ "$dist" == "mac" ]
    then
        DepInstall lsof
        while true
        do
            candidate=$((lport+RANDOM%(uport-lport)))
            if ! lsof -Pi :"$candidate" -sTCP:LISTEN -t &>/dev/null
            then
                echo "$candidate"
                break
            fi
        done
    else
        while true
        do
            candidate=$((lport+RANDOM%(uport-lport)))
            if ! ( echo -n "" >/dev/tcp/127.0.0.1/"$candidate" )  >/dev/null 2>&1
            then
                echo "$candidate"
                break
            fi
        done
    fi
}

GetRandomMac()
{
    echo $RANDOM|md5sum|sed 's/../&:/g'|cut -c 1-17
}

RemoveQuotes()
{
    local text="${!1}"
    if [[ "$text" =~ ^\"(.*)\"$ ]] || [[ "$text" =~ ^\'(.*)\'$ ]]
    then
        text="${BASH_REMATCH[1]}"
        read -r ${1} <<< "$text"
    fi
}

PrepTerm()
{
    unset term_child_pid
    unset term_kill_needed
    unset term_signal
    trap 'HandleTerm' TERM
}

HandleTerm()
{
    if [ -n "${term_child_pid:-}" ]
    then
        if [ "${pkill:-0}" -eq 1 ]
        then
            pkill -TERM -P "$term_child_pid" 2> /dev/null || true
        elif [ "${force_exit:-0}" -eq 1 ]
        then
            kill -9 "$term_child_pid" 2> /dev/null || true
        else
            kill -TERM "$term_child_pid" 2> /dev/null || true
        fi
    else
        term_kill_needed=1
    fi
}

WaitTerm()
{
    term_child_pid=$!
    if [ "${term_kill_needed:-0}" -eq 1 ]
    then
        if [ "${pkill:-0}" -eq 1 ]
        then
            pkill -TERM -P "$term_child_pid" 2> /dev/null || true
        elif [ "${force_exit:-0}" -eq 1 ]
        then
            kill -9 "$term_child_pid" 2> /dev/null || true
        else
            kill -TERM "$term_child_pid" 2> /dev/null || true
        fi
    fi
    wait $term_child_pid 2> /dev/null || term_signal=1
    trap - TERM
    wait $term_child_pid 2> /dev/null || true
    if [ "${term_signal:-0}" -eq 1 ]
    then
        rm -rf "${delete_on_term:-notfound}"
        exit 1
    fi
}

VersionLt()
{
    local v1="${1:-0.0.0}"
    local v2="${2:-0.0.0}"
    local a1=() a2=()
    local IFS='.'
    read -r -a a1 <<< "$v1"
    read -r -a a2 <<< "$v2"
    local i n1 n2
    for i in 0 1 2
    do
        n1="${a1[$i]:-0}"
        n2="${a2[$i]:-0}"
        n1="${n1%%[^0-9]*}"
        n2="${n2%%[^0-9]*}"
        n1="${n1:-0}"
        n2="${n2:-0}"

        if [ "$n1" -lt "$n2" ]
        then
            return 0
        elif [ "$n1" -gt "$n2" ]
        then
            return 1
        fi
    done
    return 1
}

GetSubshellPid()
{
    if [ -n "${BASHPID:-}" ]
    then
        printf '%s\n' "$BASHPID"
    else
        sh -c 'echo $PPID'
    fi
}

DateEpoch()
{
    date +%s
}

DateMs()
{
    if command -v gdate > /dev/null 2>&1
    then
        gdate +%s%3N
    else
        local out
        out=$(date +%s%3N 2> /dev/null || true)
        if [[ $out =~ ^[0-9]+$ ]]
        then
            printf '%s\n' "$out"
        else
            printf '%s000\n' "$(date +%s)"
        fi
    fi
}

FormatEpoch()
{
    local ts="$1"
    local fmt="${2:-+%c}"
    if date -r "$ts" "$fmt" 2> /dev/null
    then
        return 0
    fi
    date --date="@$ts" "$fmt" 2> /dev/null
}

FilterFileLines()
{
    local needle="$1"
    local file="$2"
    local tmp_f
    tmp_f=$(mktemp "${TMPDIR:-/tmp}/aios-flt.XXXXXX")
    if [ -f "$file" ]
    then
        grep -Fv -- "$needle" "$file" > "$tmp_f" || true
        mv "$tmp_f" "$file"
    else
        rm -f "$tmp_f"
    fi
}

GenUuid()
{
    if [ -r /proc/sys/kernel/random/uuid ]
    then
        cat /proc/sys/kernel/random/uuid
    elif command -v uuidgen > /dev/null 2>&1
    then
        uuidgen | tr '[:upper:]' '[:lower:]'
    else
        openssl rand -hex 16 | sed -E 's/^(.{8})(.{4})(.{4})(.{4})(.{12})$/\1-\2-\3-\4-\5/'
    fi
}

Md5Hex()
{
    if command -v md5sum > /dev/null 2>&1
    then
        md5sum | awk '{print $1}'
    else
        md5 -q
    fi
}

StripSuffix()
{
    local str="$1"
    local n="${2:-0}"
    local len=${#str}
    if [ "$n" -le 0 ]
    then
        printf '%s' "$str"
    elif [ "$n" -ge "$len" ]
    then
        printf ''
    else
        printf '%s' "${str:0:$((len - n))}"
    fi
}

RunEditor()
{
    local target="$1"
    if [ -n "${EDITOR:-}" ] && command -v "$EDITOR" > /dev/null 2>&1
    then
        "$EDITOR" "$target"
    elif command -v vim > /dev/null 2>&1
    then
        vim "$target"
    elif command -v nano > /dev/null 2>&1
    then
        nano "$target"
    elif command -v editor > /dev/null 2>&1
    then
        editor "$target"
    else
        vi "$target"
    fi
}

WithFileLock()
{
    local lock_file="$1"
    shift

    if command -v flock > /dev/null 2>&1
    then
        (
            flock -x 200 || exit 1
            "$@"
        ) 200>"$lock_file"
    else
        local lock_dir="${lock_file}.d"
        local tries=0
        while ! mkdir "$lock_dir" 2> /dev/null
        do
            tries=$((tries + 1))
            if [ "$tries" -ge 300 ]
            then
                return 1
            fi
            sleep 0.1
        done
        local rc=0
        "$@" || rc=$?
        rmdir "$lock_dir" 2> /dev/null || true
        return $rc
    fi
}

DistCheck()
{
    [ -n "${dist:-}" ] && return 0

    local dist_files=( /etc/issue /etc/os-release /proc/version ) dist_file
    dist=""

    for dist_file in "${dist_files[@]}"
    do
        if [ ! -s "$dist_file" ]
        then
            continue
        fi

        if grep -qi "Ubuntu" < "$dist_file"
        then
            dist="ubu"
            break
        elif grep -qi "Debian" < "$dist_file"
        then
            dist="deb"
            break
        elif grep -Eqi "Red Hat|redhat|rhel|CentOS|Fedora|Amazon" < "$dist_file"
        then
            dist="rpm"
            break
        fi
    done

    if [ -z "$dist" ]
    then
        if [[ $OSTYPE =~ darwin ]] || [[ $(uname | tr '[:upper:]' '[:lower:]') =~ darwin ]]
        then
            dist="mac"
        else
            Println "${red}[ERROR]${normal} not support yet...\n"
            return 1
        fi
    fi
}

ArchCheck()
{
    [ -n "${arch:-}" ] && return 0

    arch=$(uname -m)

    if grep -Eqi "x86_64|amd64" <<< "$arch"
    then
        arch="x86_64"
    elif grep -Eqi "i386|i686|x86" <<< "$arch"
    then
        arch="i386"
    elif grep -Eqi "aarch64|armv8|arm64" <<< "$arch"
    then
        arch="arm64"
    elif grep -qi "armv7" <<< "$arch"
    then
        arch="armhf"
    elif grep -qi "armv6" <<< "$arch"
    then
        arch="armv6l"
    elif grep -qi "arm" <<< "$arch"
    then
        arch="armel"
    elif grep -qi "s390" <<< "$arch"
    then
        arch="s390x"
    fi
}

DebFixSources()
{
    if [ "${deb_fix:-1}" -eq 1 ]
    then
        sed -i 's/^mozilla\/DST_Root_CA_X3.crt/!mozilla\/DST_Root_CA_X3.crt/g' /etc/ca-certificates.conf
        update-ca-certificates -f >/dev/null 2>&1 || true

        if [ -f /etc/apt/sources.list.d/sources-aliyun-0.list ]
        then
            deb_list=$(< /etc/apt/sources.list.d/sources-aliyun-0.list)
            rm -f /etc/apt/sources.list.d/sources-aliyun-0.list
            rm -rf /var/lib/apt/lists/*
        else
            deb_list=$(< /etc/apt/sources.list)
        fi

        if grep -q "jessie" <<< "$deb_list"
        then
cat > /etc/apt/sources.list <<EOF
deb http://archive.debian.org/debian/ jessie main
deb-src http://archive.debian.org/debian/ jessie main

deb http://security.debian.org jessie/updates main
deb-src http://security.debian.org jessie/updates main
EOF
            apt-get clean >/dev/null 2>&1
        elif grep -q "wheezy" <<< "$deb_list"
        then
cat > /etc/apt/sources.list <<EOF
deb http://archive.debian.org/debian/ wheezy main
deb-src http://archive.debian.org/debian/ wheezy main

deb http://security.debian.org wheezy/updates main
deb-src http://security.debian.org wheezy/updates main
EOF
            apt-get clean >/dev/null 2>&1
        fi

        deb_fix=0
        sed -i '/deb_fix=/d' "$i18n_FILE"
        printf "deb_fix=%s" "$deb_fix" >> "$i18n_FILE"
    fi
}

AptFixBrokenRepos()
{
    local err_file="$1"
    local sources_dir="${APT_SOURCES_DIR:-/etc/apt/sources.list.d}"
    local sources_file="${APT_SOURCES_FILE:-/etc/apt/sources.list}"
    local broken_urls=()
    local line url

    while IFS= read -r line
    do
        if [[ $line =~ The\ repository\ \'([^[:space:]\']+)[[:space:]]+[^\']*\'\ (no\ longer\ has|does\ not\ have)\ a\ Release\ file ]]
        then
            url="${BASH_REMATCH[1]}"

            if ! EleInArray "$url" broken_urls
            then
                broken_urls+=("$url")
            fi
        elif [[ $line =~ 仓库[[:space:]]*[“\"\'‘]([^[:space:]”\"\'’]+)[[:space:]]+[^”\"\'’]*[”\"\'’].*Release ]]
        then
            url="${BASH_REMATCH[1]}"

            if ! EleInArray "$url" broken_urls
            then
                broken_urls+=("$url")
            fi
        elif [[ $line =~ ^(Err|错误):[0-9]+[[:space:]]+(https?://[^[:space:]]+) ]]
        then
            url="${BASH_REMATCH[2]}"

            if grep -q "404" "$err_file" && ! EleInArray "$url" broken_urls
            then
                broken_urls+=("$url")
            fi
        fi
    done < "$err_file"

    if [ "${#broken_urls[@]}" -eq 0 ]
    then
        return 1
    fi

    local action_types=()
    local action_files=()
    local action_urls=()
    local action_descs=()
    local list_file

    for url in "${broken_urls[@]}"
    do
        if [ -d "$sources_dir" ]
        then
            for list_file in "$sources_dir"/*.list "$sources_dir"/*.sources
            do
                if [ ! -f "$list_file" ]
                then
                    continue
                fi

                if grep -Fq -- "$url" "$list_file"
                then
                    if [[ $url == *apt.postgresql.org/pub/repos/apt* ]] && ! grep -Fq "apt-archive.postgresql.org" "$list_file"
                    then
                        action_types+=("pg_archive")
                        action_files+=("$list_file")
                        action_urls+=("$url")
                        action_descs+=("切换 PostgreSQL 归档源: $list_file (apt.postgresql.org -> apt-archive.postgresql.org)")
                    else
                        action_types+=("disable_file")
                        action_files+=("$list_file")
                        action_urls+=("$url")
                        action_descs+=("禁用失效源: $list_file -> ${list_file}.disabled ($url)")
                    fi
                fi
            done
        fi

        if [ -f "$sources_file" ] && grep -Fq -- "$url" "$sources_file"
        then
            action_types+=("comment_line")
            action_files+=("$sources_file")
            action_urls+=("$url")
            action_descs+=("在 $sources_file 中注释失效源: $url")
        fi
    done

    if [ "${#action_types[@]}" -eq 0 ]
    then
        return 1
    fi

    Println "\n$tip 检测到以下失效 APT 软件源导致 apt-get update 失败:"

    local idx
    for((idx=0;idx<${#action_descs[@]};idx++));
    do
        Println "  $((idx + 1)). ${yellow}${action_descs[idx]}${normal}"
    done

    if [ "${APT_AUTO_FIX:-false}" != true ]
    then
        if [ -t 0 ]
        then
            local fix_opts=( '否' '是' )
            local fix_idx=0
            echo
            inquirer list_input_index "是否允许按上述方案修改 APT 软件源并重试?" fix_opts fix_idx

            if [ "$fix_idx" -ne 1 ]
            then
                Println "$info 已取消修改 APT 软件源, 请手动处理后重试\n"
                return 1
            fi
        else
            Println "$info 非交互模式不会自动修改 APT 软件源, 请手动处理上述失效源后重试\n"
            return 1
        fi
    fi

    local act_type act_file act_url tmp_f
    for((idx=0;idx<${#action_types[@]};idx++));
    do
        act_type="${action_types[idx]}"
        act_file="${action_files[idx]}"
        act_url="${action_urls[idx]}"

        case "$act_type" in
            pg_archive)
                tmp_f=$(mktemp "${TMPDIR:-/tmp}/aios-apt.XXXXXX")
                sed 's|apt\.postgresql\.org/pub/repos/apt|apt-archive.postgresql.org/pub/repos/apt|g' "$act_file" > "$tmp_f"
                mv "$tmp_f" "$act_file"
                Println "$info 已切换至 apt-archive.postgresql.org: ${green}$act_file${normal}"
            ;;
            disable_file)
                mv "$act_file" "${act_file}.disabled"
                Println "$info 已禁用失效源: ${yellow}${act_file} -> ${act_file}.disabled${normal}"
            ;;
            comment_line)
                tmp_f=$(mktemp "${TMPDIR:-/tmp}/aios-apt.XXXXXX")
                awk -v u="$act_url" '
                    index($0, u) > 0 && $0 !~ /^[[:space:]]*#/ { print "# [AIOS disabled broken repo] " $0; next }
                    { print }
                ' "$act_file" > "$tmp_f"
                mv "$tmp_f" "$act_file"
                Println "$info 已在 $act_file 中注释失效源: ${yellow}$act_url${normal}"
            ;;
        esac
    done

    return 0
}

AptGetCodename()
{
    local os_release="${OS_RELEASE_FILE:-/etc/os-release}"
    local sources_file="${APT_SOURCES_FILE:-/etc/apt/sources.list}"
    local codename="" id="" id_like="" ubu_code="" deb_code="" ver_code=""

    if [ -r "$os_release" ]
    then
        id=$(sed -nE 's/^ID="?([^"[:space:]]+)"?/\1/p' "$os_release" | head -n 1)
        id_like=$(sed -nE 's/^ID_LIKE="?([^"]+)"?/\1/p' "$os_release" | head -n 1)
        ubu_code=$(sed -nE 's/^UBUNTU_CODENAME="?([^"[:space:]]+)"?/\1/p' "$os_release" | head -n 1)
        deb_code=$(sed -nE 's/^DEBIAN_CODENAME="?([^"[:space:]]+)"?/\1/p' "$os_release" | head -n 1)
        ver_code=$(sed -nE 's/^VERSION_CODENAME="?([^"[:space:]]+)"?/\1/p' "$os_release" | head -n 1)

        if [ "$id" == "ubuntu" ] || [[ " $id_like " == *" ubuntu "* ]] || [ -n "$ubu_code" ]
        then
            codename="${ubu_code:-$ver_code}"
        elif [ "$id" == "debian" ] || [[ " $id_like " == *" debian "* ]] || [ -n "$deb_code" ]
        then
            codename="${deb_code:-$ver_code}"
        else
            codename="${ver_code:-${ubu_code:-$deb_code}}"
        fi
    fi

    if [ -z "$codename" ] && [[ -x $(command -v lsb_release) ]]
    then
        codename=$(lsb_release -cs 2> /dev/null || true)
    fi

    if [ -z "$codename" ] && [ -r "$sources_file" ]
    then
        codename=$(awk '
            /^[[:space:]]*deb[[:space:]]/ {
                for (i = 2; i <= NF; i++) {
                    if ($i ~ /^\[/) {
                        while (i <= NF && $i !~ /\]$/) i++
                        continue
                    }
                    if ($i ~ /^https?:\/\//) {
                        if (i + 1 <= NF) {
                            suite = $(i + 1)
                            sub(/-(updates|backports|security)$/, "", suite)
                            if (suite !~ /\//) {
                                print suite
                                exit
                            }
                        }
                    }
                }
            }
        ' "$sources_file")
    fi

    printf '%s\n' "$codename"
}

AptRepoCheck()
{
    local repo_url="${1%/}"
    local suite="${2:-}"

    if [ -z "$repo_url" ] || [ -z "$suite" ]
    then
        return 1
    fi

    if curl -fsI -m 10 "${repo_url}/dists/${suite}/InRelease" > /dev/null 2>&1
    then
        return 0
    fi

    if curl -fsI -m 10 "${repo_url}/dists/${suite}/Release" > /dev/null 2>&1
    then
        return 0
    fi

    return 1
}

AptUpdate()
{
    local force="${1:-}"

    if [ "$force" != "force" ] && [ "${apt_updated:-false}" = true ]
    then
        return 0
    fi

    Println "$info 更新软件包列表..."

    local apt_err_file attempt=0 max_attempts=3 rc=0
    apt_err_file=$(mktemp "${TMPDIR:-/tmp}/aios-apt-update.XXXXXX")

    while [ "$attempt" -lt "$max_attempts" ]
    do
        attempt=$((attempt + 1))
        rc=0

        if [ "$force" == "force" ]
        then
            LC_ALL=C apt-get update --allow-releaseinfo-change -o Acquire::http::No-Cache=true -o Acquire::BrokenProxy=true > "$apt_err_file" 2>&1 || rc=$?
        else
            LC_ALL=C apt-get update --allow-releaseinfo-change > "$apt_err_file" 2>&1 || rc=$?
        fi

        if [ "$rc" -eq 0 ]
        then
            rm -f "$apt_err_file"
            apt_updated=true
            return 0
        fi

        if [ "$attempt" -lt "$max_attempts" ] && AptFixBrokenRepos "$apt_err_file"
        then
            continue
        fi

        break
    done

    Println "$error apt-get update 失败:\n$(cat "$apt_err_file")\n"
    rm -f "$apt_err_file"
    return "$rc"
}

AptInstall()
{
    if [ $# -eq 0 ]
    then
        return 0
    fi

    AptUpdate || return 1

    local inst_err rc=0
    inst_err=$(mktemp "${TMPDIR:-/tmp}/aios-apt-install.XXXXXX")
    LC_ALL=C DEBIAN_FRONTEND=noninteractive apt-get -y install "$@" > "$inst_err" 2>&1 || rc=$?

    if [ "$rc" -eq 0 ]
    then
        rm -f "$inst_err"
        return 0
    fi

    if grep -Eq 'Unable to fetch some archives|404[[:space:]]+Not Found|Failed to fetch' "$inst_err"
    then
        Println "$tip 软件包索引可能已过期, 正在强制刷新软件源 (No-Cache) 并重试安装..."

        if AptUpdate force
        then
            rc=0
            LC_ALL=C DEBIAN_FRONTEND=noninteractive apt-get -y install --fix-missing "$@" > "$inst_err" 2>&1 || rc=$?

            if [ "$rc" -eq 0 ]
            then
                rm -f "$inst_err"
                return 0
            fi
        fi

        if grep -Eq '404[[:space:]]+Not Found|Failed to fetch' "$inst_err" && [ -t 0 ]
        then
            local codename
            codename=$(AptGetCodename)

            Println "\n$tip 刷新软件源后仍有软件包返回 404 (可能是老版本 Debian/Ubuntu 安全源已归档或镜像同步异常):"
            grep -E '^(Err:|E: Failed to fetch)' "$inst_err" | head -n 6

            local retry_opts=(
                "不修改源，尝试从发行版主源 (-t ${codename:-stable}) 安装"
                "将 /etc/apt/sources.list 中的 security.debian.org 切换至 archive.debian.org 并重试"
                "放弃安装，自行手动处理"
            )
            local retry_idx=2
            echo
            inquirer list_input_index "请选择处理方式" retry_opts retry_idx

            if [ "$retry_idx" -eq 0 ] && [ -n "$codename" ]
            then
                rc=0
                LC_ALL=C DEBIAN_FRONTEND=noninteractive apt-get -y install --allow-downgrades -t "$codename" "$@" > "$inst_err" 2>&1 || rc=$?

                if [ "$rc" -eq 0 ]
                then
                    rm -f "$inst_err"
                    return 0
                fi
            elif [ "$retry_idx" -eq 1 ]
            then
                local sources_file="${APT_SOURCES_FILE:-/etc/apt/sources.list}"

                if [ -f "$sources_file" ] && grep -Fq "security.debian.org" "$sources_file"
                then
                    local tmp_arc
                    tmp_arc=$(mktemp "${TMPDIR:-/tmp}/aios-apt.XXXXXX")
                    sed 's|security\.debian\.org|archive.debian.org|g' "$sources_file" > "$tmp_arc"
                    mv "$tmp_arc" "$sources_file"
                    Println "$info 已将 $sources_file 中的 security.debian.org 切换至 archive.debian.org\n"

                    if AptUpdate force
                    then
                        rc=0
                        LC_ALL=C DEBIAN_FRONTEND=noninteractive apt-get -y install --fix-missing "$@" > "$inst_err" 2>&1 || rc=$?

                        if [ "$rc" -eq 0 ]
                        then
                            rm -f "$inst_err"
                            return 0
                        fi
                    fi
                fi
            fi
        fi
    fi

    Println "$error 软件包安装失败 ($*):\n$(cat "$inst_err")\n"
    rm -f "$inst_err"
    return "$rc"
}

BrewInstall()
{
    if [[ ! -x $(command -v brew) ]]
    then
        export NONINTERACTIVE=1
        Println "${green}[info]${normal} 安装 Homebrew ...\n"
        if ! curl -s -S -Lm 20 https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh | bash
        then
            Println "${green}[info]${normal} 尝试更换国内源 ...\n"

            export HOMEBREW_BREW_GIT_REMOTE="https://mirrors.ustc.edu.cn/brew.git"
            export HOMEBREW_CORE_GIT_REMOTE="https://mirrors.ustc.edu.cn/homebrew-core.git"
            export HOMEBREW_BOTTLE_DOMAIN="https://mirrors.ustc.edu.cn/homebrew-bottles"
            export HOMEBREW_API_DOMAIN="https://mirrors.ustc.edu.cn/homebrew-bottles/api"

            if ! curl -s -S -Lm 20 https://mirrors.ustc.edu.cn/misc/brew-install.sh | bash
            then
                Println "${green}[ERROR]${normal} 无法安装 Homebrew\n"
                return 1
            fi
        fi
        brew update >/dev/null 2>&1
        add_homebrew_path=true
    fi
}

DepInstall()
{
    local dependency=$1 check=${2:-}

    if [ -z "$check" ] && [[ -x $(command -v $dependency) ]]
    then
        return 0
    fi

    if [ "$dependency" == "gettext" ] || [ "$dependency" == "wget" ] || [ "$dependency" == "gsed" ] || [ "$dependency" == "gdate" ] || [ "$dependency" == "ggrep" ]
    then
        Println "${green}[INFO]${normal} Installing $dependency, it takes awhile..."

        if [ "$dist" == "mac" ]
        then
            if [ "$dependency" == "gsed" ]
            then
                dependency=gnu-sed
            elif [ "$dependency" == "gdate" ]
            then
                dependency=coreutils
            elif [ "$dependency" == "ggrep" ]
            then
                dependency=grep
            fi

            if ! brew list $dependency &>/dev/null
            then
                if brew install $dependency &>/dev/null
                then
                    Println "${green}[INFO]${normal} $dependency installation succeed..."
                else
                    Println "${green}[ERROR]${normal} $dependency installation failed...\n"
                    return 1
                fi
            fi
        elif [ "$dist" == "rpm" ]
        then
            if [[ -x $(command -v getenforce) ]] && [ "$(getenforce)" != "Disabled" ]
            then
                setenforce 0
            fi

            if ! rpm -q $dependency &>/dev/null
            then
                if yum -y install $dependency &>/dev/null
                then
                    Println "${green}[INFO]${normal} $dependency installation succeed..."
                else
                    Println "${green}[ERROR]${normal} $dependency installation failed...\n"
                    return 1
                fi
            fi
        else
            if [ "$dist" == "deb" ]
            then
                DebFixSources
            fi

            if ! dpkg -s $dependency &>/dev/null
            then
                AptUpdate
                if AptInstall $dependency
                then
                    Println "${green}[INFO]${normal} $dependency installation succeed..."
                else
                    Println "${green}[ERROR]${normal} $dependency installation failed...\n"
                    return 1
                fi
            fi
        fi

        return 0
    fi

    if [ "$dist" == "mac" ]
    then
        if [ "$dependency" == "tput" ]
        then
            dependency="ncurses"
        fi

        if ! brew list $dependency &>/dev/null
        then
            Println "`eval_gettext \"\\\$info 安装 \\\$dependency, 请稍等...\"`"
            if brew install $dependency >/dev/null 2>&1
            then
                Println "`eval_gettext \"\\\$info \\\$dependency 安装成功\"`"
            else
                Println "`eval_gettext \"\\\$error \\\$dependency 安装失败\"`\n"
                return 1
            fi
        fi
    elif [ "$dist" == "rpm" ]
    then
        if [[ -x $(command -v getenforce) ]] && [ "$(getenforce)" != "Disabled" ]
        then
            setenforce 0
        fi

        if [ "$dependency" == "dig" ]
        then
            dependency="bind-utils"
        elif [ "$dependency" == "hexdump" ]
        then
            dependency="util-linux"
        elif [ "$dependency" == "ss" ]
        then
            dependency="iproute"
        elif [ "$dependency" == "tput" ]
        then
            dependency="ncurses"
        fi

        if ! rpm -q $dependency &>/dev/null
        then
            Println "`eval_gettext \"\\\$info 安装 \\\$dependency, 请稍等...\"`"
            if yum -y install $dependency >/dev/null 2>&1
            then
                Println "`eval_gettext \"\\\$info \\\$dependency 安装成功\"`"
            else
                Println "`eval_gettext \"\\\$error \\\$dependency 安装失败\"`\n"
                return 1
            fi
        fi
    else
        if [ "$dist" == "deb" ]
        then
            DebFixSources
        fi

        if [ "$dependency" == "dig" ]
        then
            dependency="dnsutils"
        elif [ "$dependency" == "hexdump" ]
        then
            dependency="bsdmainutils"
        elif [ "$dependency" == "ss" ]
        then
            dependency="iproute2"
        elif [ "$dependency" == "tput" ]
        then
            dependency="ncurses-bin"
        fi

        if ! dpkg -s $dependency &>/dev/null
        then
            AptUpdate
            Println "`eval_gettext \"\\\$info 安装 \\\$dependency, 请稍等...\"`"
            if AptInstall "$1"
            then
                Println "`eval_gettext \"\\\$info \\\$dependency 安装成功\"`"
            else
                Println "`eval_gettext \"\\\$error \\\$dependency 安装失败\"`\n"
                return 1
            fi
        fi
    fi
}

DepsCheck()
{
    if [ "${deps_checked:-false}" = true ]
    then
        return 0
    fi

    DepInstall tput

    Spinner "`gettext \"检查依赖, 耗时可能会很长\"`" DepsInstall

    deps_checked=true
}

DepsInstall()
{
    if [ "$dist" == "mac" ]
    then
        depends=(wget unzip vim curl patchutils)

        for depend in "${depends[@]}"
        do
            [[ -x $(command -v $depend) ]] && continue
            if ! brew list "$depend" &> /dev/null
            then
                if brew install "$depend" >/dev/null 2>&1
                then
                    Println "`eval_gettext \"\\\$info 依赖 \\\$depend 安装成功\"`"
                else
                    Println "`eval_gettext \"\\\$error 依赖 \\\$depend 安装失败\"`\n"
                    return 1
                fi
            fi
        done
    elif [ "$dist" == "rpm" ]
    then
        if [[ -x $(command -v getenforce) ]] && [ "$(getenforce)" != "Disabled" ]
        then
            setenforce 0
        fi

        depends=(sudo wget unzip vim curl crond logrotate patch nscd bind-utils util-linux iproute ncurses)

        if [ "${rpm_fix:-1}" -eq 1 ]
        then
            yum -y update ca-certificates &> /dev/null || yum -y reinstall ca-certificates &> /dev/null
            rpm_fix=0
            sed -i '/rpm_fix=/d' "$i18n_FILE"
            printf "rpm_fix=%s" "$rpm_fix" >> "$i18n_FILE"
        fi

        for depend in "${depends[@]}"
        do
            [[ -x $(command -v $depend) ]] && continue
            if ! rpm -q "$depend" &> /dev/null
            then
                if yum -y install "$depend" &> /dev/null
                then
                    Println "`eval_gettext \"\\\$info 依赖 \\\$depend 安装成功\"`"
                else
                    Println "`eval_gettext \"\\\$error 依赖 \\\$depend 安装失败\"`\n"
                    return 1
                fi
            fi
        done
    else
        if [ "$dist" == "deb" ]
        then
            DebFixSources
        fi

        AptUpdate

        depends=(ca-certificates sudo wget unzip vim curl cron ufw python3 logrotate patch nscd dnsutils bsdmainutils ncurses-bin)

        for depend in "${depends[@]}"
        do
            [[ -x $(command -v $depend) ]] && continue
            if ! dpkg -s "$depend" &> /dev/null
            then
                if AptInstall "$depend"
                then
                    Println "`eval_gettext \"\\\$info 依赖 \\\$depend 安装成功\"`"
                else
                    Println "`eval_gettext \"\\\$error 依赖 \\\$depend 安装失败\"`\n"
                    return 1
                fi
            fi
        done
    fi
}

ResourceLimit()
{
    if [ "$dist" == "mac" ]
    then
        return 0
    fi

    if [ ! -e /proc/sys/fs/file-max ]
    then
        echo 65536 > /proc/sys/fs/file-max
        echo "fs.file-max=65536" >> /etc/sysctl.conf
    fi

    file_max=$(< /proc/sys/fs/file-max)

    if [ "$file_max" -lt 65000 ]
    then
        file_max=$((file_max*95/100))
    else
        file_max=64000
    fi

    limits=(
        "$USER soft fsize unlimited"
        "$USER hard fsize unlimited"
        "$USER soft cpu unlimited"
        "$USER hard cpu unlimited"
        "$USER soft as unlimited"
        "$USER hard as unlimited"
        "$USER soft memlock unlimited"
        "$USER hard memlock unlimited"
        "$USER soft nofile $file_max"
        "$USER hard nofile $file_max"
        "$USER soft nproc 64000"
        "$USER hard nproc 64000"
        "* soft nofile $file_max"
        "* hard nofile $file_max"
    )

    limits_append=""
    for limit in "${limits[@]}"
    do
        if ! grep -q "${limit% *}" < "/etc/security/limits.conf"
        then
            limits_append="$limits_append$limit\n"
        fi
    done

    if [ -n "$limits_append" ]
    then
        # systemd ignores limits set in the /etc/security/limits.conf
        echo -e "$limits_append" >> "/etc/security/limits.conf"
    fi

    ulimit -f unlimited
    ulimit -t unlimited
    ulimit -v unlimited
    ulimit -l unlimited
    ulimit -n $file_max
    ulimit -m unlimited
    ulimit -u 64000

    if [ "$dist" == "rpm" ]
    then
        if [ ! -e ~/.bash_profile ] || ! grep -q ulimit < ~/.bash_profile
        then
cat >> ~/.bash_profile <<EOF
ulimit -f unlimited
ulimit -t unlimited
ulimit -v unlimited
ulimit -l unlimited
ulimit -n $file_max
ulimit -m unlimited
ulimit -u 64000
EOF
        fi
    else
        if [ ! -e ~/.profile ] || ! grep -q ulimit < ~/.profile
        then
cat >> ~/.profile <<EOF
ulimit -f unlimited
ulimit -t unlimited
ulimit -v unlimited
ulimit -l unlimited
ulimit -n $file_max
ulimit -m unlimited
ulimit -u 64000
EOF
        fi
    fi

    # The limits defined in these files are set by PAM when starting a login session, but daemons started by systemd do not use PAM login sessions
    #if [ ! -e /etc/security/limits.d/99-mongodb-nproc.conf ] && ls -A /etc/security/limits.d/*-nproc.conf > /dev/null 2>&1
    #then
    #    echo -e "mongodb soft nproc 64000\nmongodb hard nproc 64000" > /etc/security/limits.d/99-mongodb-nproc.conf
    #fi
}

