LocaleFix()
{
    Println "${green}[INFO]${normal} Installing language (locale) support, it takes awhile..."

    if [ "$dist" == "rpm" ] 
    then
        if [[ -x $(command -v getenforce) ]] && [ "$(getenforce)" != "Disabled" ]
        then
            setenforce 0
        fi

        yum -y install glibc-common glibc-locale-source glibc-all-langpacks glibc-langpack-en glibc-langpacks-zh langpacks-zh_CN >/dev/null 2>&1 || true

        if [[ -x $(command -v localectl) ]] 
        then
            localectl set-locale LANG=$1.UTF-8 >/dev/null
        elif [ -s /etc/sysconfig/i18n ] 
        then
            sed -i '/LANG=/d' /etc/sysconfig/i18n
            echo "LANG=$1.UTF-8" >> /etc/sysconfig/i18n
        fi
    else
        if [ "$dist" == "deb" ] 
        then
            DebFixSources
        fi

        if [[ ! -x $(command -v locale-gen) ]] 
        then
            AptUpdate
            if ! AptInstall locales
            then
                Println "${red}[ERROR]${normal} locales installation failed\n" && exit 1
            fi
        fi

        if [ -s /etc/locale.gen ] 
        then
            sed -i "s/# $1.UTF-8 UTF-8/$1.UTF-8 UTF-8/" /etc/locale.gen
        fi

        locale-gen $1.UTF-8 >/dev/null
        update-locale LANG=$1.UTF-8 LANGUAGE
    fi

    if ! grep -q "$1" < <(locale -a 2> /dev/null) 
    then
        Println "${red}[ERROR]${normal} locales installation failed\n" && exit 1
    fi
}

i18nCheck()
{
    if [ -z "${sh_locale:-}" ] 
    then
        sh_locale="zh_CN"

        if [ "${locale_fix:-1}" -eq 1 ] && ! grep -q 'zh_CN' < <(locale -a 2> /dev/null) 
        then
            LocaleFix zh_CN
        fi

        echo -e "sh_locale=$sh_locale\nexport LANG=zh_CN.UTF-8\nlocale_fix=0" > "$i18n_FILE"
    elif [ "$sh_locale" == "zh_CN" ] 
    then
        if [ "${locale_fix:-1}" -eq 1 ] 
        then
            if ! grep -q 'zh_CN' < <(locale -a 2> /dev/null) 
            then
                LocaleFix zh_CN
            fi
            echo -e "sh_locale=$sh_locale\nexport LANG=zh_CN.UTF-8\nlocale_fix=0" > "$i18n_FILE"
        fi
    else
        if [ "${locale_fix:-1}" -eq 1 ] && [ "$sh_locale" == "en" ] && ! grep -q 'en_US' < <(locale -a 2> /dev/null) 
        then
            LocaleFix en_US
            echo -e "sh_locale=$sh_locale\nexport LANG=en_US.UTF-8\nlocale_fix=0" > "$i18n_FILE"
        fi

        if [ ! -s "$TEXTDOMAINDIR/$sh_locale/LC_MESSAGES/${TEXTDOMAIN}.mo" ] 
        then
            i18nInstall "$sh_locale"
        fi
    fi
}

eval_gettext()
{
    gettext "$1" | (export PATH `envsubst --variables "$1"`; envsubst "$1")
}

if [ -s "$i18n_FILE" ] 
then
    # shellcheck source=/dev/null
    . "$i18n_FILE"
fi

i18nCheck

i18nGetMsg
PackageInstallReady()
{
    DepInstall curl
    DepInstall ca-certificates

    . /etc/os-release

    case $dist in
        mac)
            if ! xcode-select -p &> /dev/null
            then
                xcode-select --install
            fi
        ;;
        rpm)
            DepInstall yum-utils
        ;;
        ubu)
            DepInstall lsb-release
            DepInstall ubuntu-keyring
            DepInstall gpg
        ;;
        deb)
            DepInstall lsb-release
            DepInstall debian-archive-keyring
            DepInstall gpg
        ;;
    esac

    return 0
}

SourceInstallReady()
{
    local package

    case $dist in
        mac)
            if ! xcode-select -p &> /dev/null
            then
                xcode-select --install
            fi
            if [ -n "${1:-}" ] 
            then
                for package in "$@"
                do
                    if ! brew list "$package" &> /dev/null
                    then
                        brew install "$package"
                    fi
                done
            fi
        ;;
        rpm)
            if ! rpm -q epel-release &> /dev/null 
            then
                . /etc/os-release
                case ${VERSION_ID%%.*} in
                    9) 
                        dnf config-manager --set-enabled crb
                        dnf install -y epel-release
                        if dnf list epel-next-release &>/dev/null 
                        then
                            dnf install -y epel-next-release
                        fi
                    ;;
                    8) 
                        dnf config-manager --set-enabled powertools
                        dnf install -y epel-release
                        if dnf list epel-next-release &>/dev/null 
                        then
                            dnf install -y epel-next-release
                        fi
                    ;;
                    7) 
                        yum install -y epel-release
                    ;;
                    *) Println "$error 不支持的系统版本\n"; return 1
                    ;;
                esac
            fi

            yum groupinstall -y 'Development Tools'
            # timedatectl set-timezone Asia/Shanghai
            # systemctl restart crond
            if [ -n "${1:-}" ] 
            then
                for package in "$@"
                do
                    if ! rpm -q "$package" &> /dev/null 
                    then
                        yum install -y "$package"
                    fi
                done
            fi
        ;;
        ubu|deb)
            # timedatectl set-timezone Asia/Shanghai
            # systemctl restart cron
            if ! dpkg -s debconf-utils &> /dev/null 
            then
                AptInstall debconf-utils
            fi
            echo '* libraries/restart-without-asking boolean true' | debconf-set-selections
            if [ -n "${1:-}" ] 
            then
                for package in build-essential "$@"
                do
                    if ! dpkg -s "$package" &> /dev/null 
                    then
                        AptInstall "$package"
                    fi
                done
            fi
        ;;
    esac

    return 0
}
inquirer()
{
    local _inq_mock_tty=false
    if [ ! -t 0 ] || [ ! -t 1 ]
    then
        _inq_mock_tty=true
        tput()
        {
            case "${1:-}" in
                cols) printf '%s\n' "${COLUMNS:-${DEFAULT_TERM_COLS:-140}}" ;;
                lines) printf '%s\n' "${LINES:-${DEFAULT_TERM_LINES:-40}}" ;;
                *) return 0 ;;
            esac
        }
        stty()
        {
            return 0
        }
    else
        DepInstall tput
    fi

    inquirer:print() {
        tput el
        printf '%b' "$1"
    }

    inquirer:print_input() {
        tput el
        printf '%s' "$1"
    }

    inquirer:join() {
        local var=("$1"[@])
        if [[ -z ${!var:-} ]] 
        then
            return
        fi
        local join_list=("${!var}") first=true item
        for item in "${join_list[@]}"
        do
            if [ "$first" = true ]
            then
                printf '%b' "$item"
                first=false
            else
                printf "${2-, }%b" "$item"
            fi
        done
    }

    inquirer:on_default() {
        return
    }

    inquirer:on_keypress() {
        local oIFS=$IFS
        local key char_read byte_len
        local oLC_ALL=${LC_ALL:-} oLANG=${LANG:-}
        local on_up=${1:-inquirer:on_default}
        local on_down=${2:-inquirer:on_default}
        local on_space=${3:-inquirer:on_default}
        local on_enter=${4:-inquirer:on_default}
        local on_left=${5:-inquirer:on_default}
        local on_right=${6:-inquirer:on_default}
        local on_ascii=${7:-inquirer:on_default}
        local on_backspace=${8:-inquirer:on_default}
        local on_not_ascii=${9:-inquirer:on_default}
        break_keypress=false

        while IFS= read -rsn1 key
        do
            case "$key" in
                $'\x1b')
                    read -rsn1 key
                    if [ "$key" == "[" ]
                    then
                        read -rsn1 key
                        case "$key" in
                        'A') $on_up;;
                        'B') $on_down;;
                        'D') $on_left;;
                        'C') $on_right;;
                        esac
                    fi
                ;;
                $'\x20') $on_space;;
                $'\x7f') $on_backspace "$key";;
                '') $on_enter "$key";;
                # The space is the first printable character listed on http://www.asciitable.com/, ~ is the last
                # [^ -~]
                *[$'\x80'-$'\xFF']*) 
                    if [[ ${BASH_VERSINFO[0]} -lt 4 ]] 
                    then
                        char_read="${char_read:-}$key"
                        LC_ALL= LANG=C
                        byte_len=${#char_read}
                        LC_ALL=$oLC_ALL LANG=$oLANG
                        if [ "$byte_len" -ne "${#char_read}" ] 
                        then
                            $on_not_ascii "$char_read"
                            char_read=""
                        fi
                    else
                        $on_not_ascii "$key"
                    fi
                ;;
                $'\x09')
                    local i
                    for((i=0;i<4;i++));
                    do
                        $on_space
                    done
                ;;
                *) $on_ascii "$key";;
            esac
            if [ "$break_keypress" = true ]
            then
                break
            fi
        done

        IFS="$oIFS"
    }

    inquirer:cleanup() {
        tput sgr0
        tput cnorm
        stty echo
    }

    inquirer:control_c() {
        inquirer:cleanup
        exit $?
    }

    inquirer:remove_instructions() {
        if [ "$first_keystroke" = true ]
        then
            tput cuu $((current_index+1))
            tput cub "$(tput cols)"
            tput cuf $((prompt_width+3))
            tput el
            if [ -n "${pages_tip:-}" ] 
            then
                inquirer:print "$pages_tip"
            fi
            tput cud $((current_index+1))
            first_keystroke=false
        fi
    }

    inquirer:page_instructions() {
        tput cuu $((current_index+1))
        tput cub "$(tput cols)"
        tput cuf $((prompt_width+3))
        tput el
        inquirer:print "$pages_tip"
        tput cud $((current_index+1))
    }

    inquirer:on_checkbox_input_up() {
        if [ "$input_search" = true ] 
        then
            tput cub "$(tput cols)"
            tput el
            tput cuu1
            tput el
            tput cuu1
            tput el

            stty -echo
            tput civis

            local i

            for((i=0;i<page_list_count;i++));
            do
                if [ "$i" = "$current_index" ] 
                then
                    if [ "${checkbox_page_selected[i]}" = true ]
                    then
                        inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[i]}\n"
                    else
                        inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[i]}\n"
                    fi
                else
                    if [ "${checkbox_page_selected[i]}" = true ]
                    then
                        inquirer:print " ${green}${checked}${normal} ${page_list[i]}\n"
                    else
                        inquirer:print " ${unchecked} ${page_list[i]}\n"
                    fi
                fi
            done

            tput cuu $((page_list_count-current_index))

            input_search=false
            return
        fi

        inquirer:remove_instructions
        tput cub "$(tput cols)"

        if [ "${checkbox_page_selected[current_index]}" = true ]
        then
            inquirer:print " ${green}${checked}${normal} ${page_list[current_index]}"
        else
            inquirer:print " ${unchecked} ${page_list[current_index]}"
        fi

        if [ $current_index = 0 ]
        then
            current_index=$((page_list_count-1))
            tput cud $((page_list_count-1))
        else
            current_index=$((current_index-1))
            tput cuu1
        fi

        tput cub "$(tput cols)"

        if [ "${checkbox_page_selected[current_index]}" = true ]
        then
            inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[current_index]}"
        else
            inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[current_index]}"
        fi
    }

    inquirer:on_checkbox_input_down() {
        if [ "$input_search" = true ] 
        then
            return
        fi

        inquirer:remove_instructions
        tput cub "$(tput cols)"

        if [ "${checkbox_page_selected[current_index]}" = true ]
        then
            inquirer:print " ${green}${checked}${normal} ${page_list[current_index]}"
        else
            inquirer:print " ${unchecked} ${page_list[current_index]}"
        fi

        if [ $current_index = $((page_list_count-1)) ]
        then
            current_index=0
            tput cuu $((page_list_count-1))
        else
            current_index=$((current_index+1))
            tput cud1
        fi

        tput cub "$(tput cols)"

        if [ "${checkbox_page_selected[current_index]}" = true ]
        then
            inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[current_index]}"
        else
            inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[current_index]}"
        fi
    }

    inquirer:on_checkbox_input_left() {
        if [ -z "${pages_tip:-}" ] 
        then
            return
        fi

        if [ "$input_search" = true ] 
        then
            inquirer:on_text_input_left
            return
        fi

        local i

        if [ "$pages_index" -eq 0 ] 
        then
            pages_index=$((pages_count-1))
            page_list_count=$((list_count-list_perpage*pages_index))
        else
            pages_index=$((pages_index-1))
            page_list_count=$list_perpage
        fi

        pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal}"

        inquirer:page_instructions
        tput cub "$(tput cols)"
        tput cud $((list_perpage-current_index+1))

        for((i=0;i<=list_perpage;i++));
        do
            tput el
            tput cuu1
        done

        tput el

        if [ "$current_index" -gt "$page_list_count" ] 
        then
            current_index=$page_list_count
        fi

        page_list=()
        checkbox_page_selected=()
        checkbox_page_select_all=true

        for((i=0;i<page_list_count;i++));
        do
            page_list+=("${checkbox_list[i+list_perpage*pages_index]}")

            if [ "$i" = "$current_index" ] 
            then
                if [ "${checkbox_selected[i+list_perpage*pages_index]}" = true ]
                then
                    checkbox_page_selected+=("true")
                    inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[i]}\n"
                else
                    checkbox_page_selected+=("false")
