ProxyRenderOverview()
{
    local config_file="$1"
    local core_type="${2:-xray}"

    if [ ! -s "$config_file" ]
    then
        return 1
    fi

    $JQ_FILE -r \
        --arg core "$core_type" \
        --arg g "$green" \
        --arg r "$red" \
        --arg n "$normal" \
    '
    def cv($v): "\($g)\($v)\($n)";
    def yv($v): if $v == true then "\($g)是\($n)" else "\($r)否\($n)" end;
    def arr($a): if ($a | type) == "array" then ($a | map(select(. != null) | tostring) | join(", ")) else ($a // "" | tostring) end;

    [
        (if (.log | type) == "object" then
            (if (.log.access | type) == "string" and (.log.access | length) > 0 then .log.access else "stdout" end) as $lacc
            | (if (.log.error | type) == "string" and (.log.error | length) > 0 then .log.error else "stdout" end) as $lerr
            | "Log: level=\(cv(.log.logLevel // .log.loglevel // "warning")) access=\(cv($lacc)) error=\(cv($lerr))"
              + (if $core == "xray" then " dnsLog=\(yv(.log.dnsLog // false))" + (if (.log.maskAddress // "") != "" then " maskAddress=\(cv(.log.maskAddress))" else "" end) else "" end)
        else empty end),
        (if (.api | type) == "object" then
            "API: tag=\(cv(.api.tag // ""))"
            + (if $core == "xray" and (.api.listen // "") != "" then " listen=\(cv(.api.listen))" else "" end)
            + " services=\(cv(arr(.api.services // [])))"
        else empty end),
        (if (.stats | type) == "object" then
            "Stats: \(cv("已启用"))"
        else empty end),
        (if (.env | type) == "object" and (.env | length) > 0 then
            "Env: \(cv(.env | to_entries | map("\(.key)=\(.value | tostring)") | join(", ")))"
        else empty end),
        (if (.transport | type) == "object" and (.transport | length) > 0 then
            "Transport: \(cv(.transport | keys | join(", ")))"
        else empty end),
        (if (.fakedns | type) == "array" then
            "FakeDNS: " + (.fakedns | map(select(type == "object") | "\(.ipPool // "")(\(.poolSize // 65535))") | join(", ") | cv(.))
        elif (.fakedns | type) == "object" then
            "FakeDNS: \(cv("\(.fakedns.ipPool // "")(\(.fakedns.poolSize // 65535))"))"
        else empty end),
        (if (.observatory | type) == "object" then
            "Observatory: selector=\(cv(arr(.observatory.subjectSelector // .observatory.selector // []))) probe=\(cv(.observatory.probeUrl // .observatory.probeURL // "")) interval=\(cv(.observatory.probeInterval // ""))"
            + (if $core == "xray" then " concurrency=\(yv(.observatory.enableConcurrency // false))" else "" end)
        else empty end),
        (if $core == "xray" and (.burstObservatory | type) == "object" then
            (if (.burstObservatory.pingConfig | type) == "object" then .burstObservatory.pingConfig else {} end) as $pc
            | "BurstObservatory: selector=\(cv(arr(.burstObservatory.subjectSelector // []))) dest=\(cv($pc.destination // "")) interval=\(cv($pc.interval // ""))"
        else empty end),
        (if $core == "xray" and (.metrics | type) == "object" then
            "Metrics: tag=\(cv(.metrics.tag // "")) listen=\(cv(.metrics.listen // ""))"
        else empty end),
        (if $core == "xray" and (.geodata | type) == "object" then
            "Geodata: cron=\(cv(.geodata.cron // "")) outbound=\(cv(.geodata.outbound // "")) assets=\(cv((if (.geodata.assets | type) == "array" then (.geodata.assets | length) else 0 end)))"
        else empty end),
        (if $core == "xray" and (.version | type) == "object" then
            "Version: min=\(cv(.version.min // "")) max=\(cv(.version.max // ""))"
        else empty end),
        (if $core == "v2ray" and (.browserForwarder | type) == "object" then
            "BrowserForwarder: \(cv("\(.browserForwarder.listenAddr // ""):\(.browserForwarder.listenPort // "")"))"
        else empty end)
    ] | join("\n")
    ' "$config_file"
}

ProxyAddBound()
{
    local config_file="$1"
    local bound_type="$2"
    local bound_json="$3"
    local rc=0

    jq_path='["'"$bound_type"'"]'
    JQ add "$config_file" "[$bound_json]" || rc=$?
    jq_path=""
    return "$rc"
}

ProxyDeleteBound()
{
    local config_file="$1"
    local bound_type="$2"
    local bound_index="$3"
    local rc=0

    jq_path='["'"$bound_type"'",'"$bound_index"']'
    JQ delete "$config_file" || rc=$?
    jq_path=""
    return "$rc"
}

ProxySelectBound()
{
    local config_file="$1"
    local bound_type="$2"
    local prompt_title="$3"

    local options=()
    local i ridx
    if [ "$bound_type" == "inbounds" ]
    then
        ProxyLoadInboundsIndex "$config_file"
        if [ "$inbounds_count" -eq 0 ]
        then
            Println "$error 请先添加入站\n"
            return 1
        fi
        for((i=0;i<inbounds_count;i++));
        do
            ridx="${inbounds_json_index[i]}"
            options+=("$((i+1)). [${inbounds_protocol[ridx]}] ${inbounds_tag[ridx]} (${inbounds_listen[ridx]}:${inbounds_port[ridx]})")
        done
        echo
        inquirer list_input_index "$prompt_title" options selected_bound_index
        selected_bound_index="${inbounds_json_index[selected_bound_index]}"
    else
        ProxyLoadOutboundsIndex "$config_file"
        if [ "$outbounds_count" -eq 0 ]
        then
            Println "$error 没有出站\n"
            return 1
        fi
        for((i=0;i<outbounds_count;i++));
        do
            ridx="${outbounds_json_index[i]}"
            options+=("$((i+1)). [${outbounds_protocol[ridx]}] ${outbounds_tag[ridx]} (${outbounds_sendThrough[ridx]})")
        done
        echo
        inquirer list_input_index "$prompt_title" options selected_bound_index
        selected_bound_index="${outbounds_json_index[selected_bound_index]}"
    fi
}

ProxyToggleService()
{
    local service_name="$1"
    local config_file="$2"

    if [ ! -e "$config_file" ]
    then
        Println "$error $service_name 未安装...\n"
        exit 1
    fi

    echo
    local err_msg=""
    if ServiceControl is-active "$service_name"
    then
        ExitOnList y "`eval_gettext \"\\\$service_name 正在运行, 是否关闭\"`"
        if err_msg=$(ServiceControl stop "$service_name" 2>&1)
        then
            Println "$info $service_name 已关闭\n"
        else
            Println "$error $service_name 关闭失败: ${err_msg}\n"
            return 1
        fi
    else
        ExitOnList y "`eval_gettext \"\\\$service_name 未运行, 是否开启\"`"
        if err_msg=$(ServiceControl start "$service_name" 2>&1)
        then
            Println "$info $service_name 已开启\n"
        else
            Println "$error $service_name 开启失败: ${err_msg}\n"
            return 1
        fi
    fi
}

ProxyRestartService()
{
    local service_name="$1"
    local config_file="$2"

    if [ ! -e "$config_file" ]
    then
        Println "$error $service_name 未安装...\n"
        exit 1
    fi

    local err_msg=""
    if err_msg=$(ServiceControl restart "$service_name" 2>&1)
    then
        Println "$info $service_name 已重启\n"
    else
        Println "$error $service_name 重启失败: ${err_msg}\n"
        return 1
    fi
}

ProxyRestartIfActive()
{
    local service_name="$1"
    if ServiceControl is-active "$service_name"
    then
        local err_msg=""
        if ! err_msg=$(ServiceControl restart "$service_name" 2>&1)
        then
            Println "$error $service_name 重启失败: ${err_msg}\n"
            return 1
        fi
    fi
}
ServiceControlIsActive()
{
    exceptions=( v2ray xray nginx openresty trojan dnscrypt-proxy )
    service_label="$1"
    if [ "$dist" == "mac" ]
    then
        if ! EleInArray "$service_label" exceptions
        then
            service_label="com.aios.$service_label"
        fi
        service_file="$HOME/Library/LaunchAgents/${service_label}.plist"
        if [ ! -f "$service_file" ] || ! { launchctl print "gui/$UID/$service_label" 2> /dev/null | grep -q "pid ="; }
        then
            return 1
        fi
    else
        if ! EleInArray "$service_label" exceptions
        then
            service_label="aios.$service_label"
        fi
        service_file="/etc/systemd/system/${service_label}.service"
        if [ ! -f "$service_file" ] || ! systemctl is-active --quiet "$service_label"
        then
            return 1
        fi
    fi
    return 0
}

ServiceControlIsEnabled()
{
    exceptions=( v2ray xray nginx openresty trojan dnscrypt-proxy )
    service_label="$1"
    if [ "$dist" == "mac" ]
    then
        if ! EleInArray "$service_label" exceptions
        then
            service_label="com.aios.$service_label"
        fi
        service_file="$HOME/Library/LaunchAgents/${service_label}.plist"
        if [ ! -f "$service_file" ]
        then
            return 1
        fi
    else
        if ! EleInArray "$service_label" exceptions
        then
            service_label="aios.$service_label"
        fi
        service_file="/etc/systemd/system/${service_label}.service"
        if [ ! -f "$service_file" ]
        then
            return 1
        fi
    fi
    return 0
}

ServiceControlStatus()
{
    exceptions=( v2ray xray nginx openresty trojan dnscrypt-proxy )
    service_label="$1"
    if [ "$dist" == "mac" ]
    then
        if ! EleInArray "$service_label" exceptions
        then
            service_label="com.aios.$service_label"
        fi
        launchctl print "gui/$UID/$service_label"
    else
        if ! EleInArray "$service_label" exceptions
        then
            service_label="aios.$service_label"
        fi
        systemctl --no-pager -l status $service_label
    fi
}

ServiceControlStart()
{
    if ServiceControlIsActive "$1"
    then
        echo "服务已启动"
        return 0
    fi

    local args=() arg arr

    if [ -n "${2:-}" ]
    then
        local var=("$2"[@])
        if [[ -n "${!var:-}" ]]
        then
            args=("${!var}")
            if [[ ! -x "${args[0]}" ]]
            then
                echo "${args[0]} 不存在"
                return 1
            fi
        fi
    fi

    if [ "${#args[@]}" -eq 0 ] && [ ! -f "$service_file" ]
    then
        echo "$service_file 不存在"
        return 1
    fi

    if [ "$dist" == "mac" ]
    then
        if [ ! -f "$service_file" ] || [ -n "${3:-}" ]
        then
            arr="<array>"
            for arg in "${args[@]}"
            do
                arr="$arr\n        <string>$arg</string>"
            done
            arr="$arr\n    </array>"
            arr=$(echo -e "$arr")
cat > "$service_file" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$service_label</string>
    <key>ProgramArguments</key>
    $arr
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
</dict>
</plist>
EOF
        fi
        launchctl load "$service_file"
    else
        if [ ! -f "$service_file" ] || [ -n "${3:-}" ]
        then
            local work_dir="/"
            if [ "${#args[@]}" -gt 0 ]
            then
                work_dir="${args[0]%/*}/"
            fi
cat > "$service_file" <<EOF
[Unit]
Description=${service_label}
After=syslog.target network-online.target nss-lookup.target
Wants=network-online.target

[Service]
ExecStart=${args[*]}
WorkingDirectory=${work_dir}
StartLimitInterval=60s
StartLimitBurst=5
RestartSec=5
Restart=on-failure

[Install]
WantedBy=multi-user.target
EOF
        fi
        systemctl daemon-reload
        systemctl enable "${service_label}.service"
        systemctl start "${service_label}.service"
    fi
}

ServiceControlStop()
{
    if ! ServiceControlIsActive "$1"
    then
        echo "服务未启动"
        return 0
    fi

    if [ "$dist" == "mac" ]
    then
        launchctl unload "$service_file"
    else
        systemctl stop "${service_label}.service"
    fi
}

ServiceControlRestart()
{
    if ServiceControlIsActive "$1"
    then
        ServiceControlStop "$1"
    fi

    ServiceControlStart "$@"
}

ServiceControlDisable()
{
    if ServiceControlIsActive "$1"
    then
        ServiceControlStop "$1"
    fi

    if [ "$dist" == "mac" ]
    then
        rm -f "$service_file"
    else
        systemctl disable "${service_label}".service --now > /dev/null 2> /dev/null || true
        rm -f /etc/systemd/system/"${service_label}".service
        rm -f /lib/systemd/system/"${service_label}".service
        rm -f /etc/init.d/"${service_label}"
    fi
}

ServiceControlRename()
{
    local old_service_label="$1"
    local new_service_label="$2"
    if [ "$dist" == "mac" ]
    then
        mv "$HOME/Library/LaunchAgents/com.aios.$old_service_label.plist" "$HOME/Library/LaunchAgents/com.aios.$new_service_label.plist"
    else
        mv "/etc/systemd/system/aios.$old_service_label.service" "/etc/systemd/system/aios.$new_service_label.service"
    fi
}

ServiceControl()
{
    DistCheck

    local cmd=$1
    shift
    case $cmd in
        is-active)
            ServiceControlIsActive "$@"
        ;;
        is-enabled)
            ServiceControlIsEnabled "$@"
        ;;
        status)
            ServiceControlStatus "$@"
        ;;
        start)
            ServiceControlStart "$@"
        ;;
        stop)
            ServiceControlStop "$@"
        ;;
        restart)
            ServiceControlRestart "$@"
        ;;
        disable)
            ServiceControlDisable "$@"
        ;;
        rename)
            ServiceControlRename "$@"
        ;;
    esac
    return $?
}
PythonInstall()
{
    if [[ -x $(command -v python3) ]] && [[ -x $(command -v pip3) ]] 
    then
        return 0
    fi

    Println "`eval_gettext \"\\\$info 安装 python3 ...\"`"

    Progress &
    progress_pid=$!

    trap '
        kill $progress_pid
        wait $progress_pid 2> /dev/null
    ' EXIT

    if [ "$dist" == "mac" ] 
    then
        DepInstall python > /dev/null
    elif [ "$dist" == "rpm" ] 
    then
        if ! yum -y install python3 python3-pip > /dev/null 2>&1
        then
            yum groupinstall -y 'Development Tools' >/dev/null 2>&1
            yum install -y gcc openssl-devel bzip2-devel libffi-devel >/dev/null 2>&1
            echo -n "...50%..."
            cd ~
            wget --timeout=10 --tries=3 --no-check-certificate "${PYTHON_FTP_LINK}/${PYTHON_FALLBACK_VER}/Python-${PYTHON_FALLBACK_VER}.tgz" -qO "Python-${PYTHON_FALLBACK_VER}.tgz"
            tar xzf "Python-${PYTHON_FALLBACK_VER}.tgz"
            cd "Python-${PYTHON_FALLBACK_VER}"
            ./configure >/dev/null 2>&1
            make >/dev/null 2>&1
            make install >/dev/null 2>&1
            pip3 install requests > /dev/null
        fi
    else
        AptInstall python3 python3-pip
    fi

    kill $progress_pid
    wait $progress_pid 2> /dev/null || true
    trap - EXIT
    echo "...100%"
}
OpensslFetchPackUrl()
{
    local list_url="${1%/}"
    local major_filter="${2:-}"
    local href=""

    href=$(curl -s -L "${list_url}/" \
        | grep -oE "href=\"[^\"]*openssl-[0-9]+\.[0-9]+\.[0-9]+[a-z]?\.tar\.gz\"" \
        | sed -E 's/^href="//; s/"$//' \
        | while IFS= read -r u
          do
              local fname="${u##*/}"
              if [ -z "$major_filter" ] || [[ "$fname" == openssl-${major_filter}.* ]]
              then
                  printf '%s\n' "$u"
                  break
              fi
          done)

    if [ -z "$href" ]
    then
        return 1
    fi

    if [[ "$href" == http://* ]] || [[ "$href" == https://* ]]
    then
        printf '%s\n' "$href"
    else
        printf '%s/%s\n' "$list_url" "${href#./}"
    fi
}

OpensslSourceInstall()
{
    local build_dir=build args=() openssl_path="$DEPENDS_ROOT"/openssl

    DepInstall ca-certificates
    DepInstall perl

    if [ -z "${1:-}" ] 
    then
        openssl_install_options=( openssl@1.1 )
    else
        openssl_install_options=("$@")
    fi

    local openssl_pack_url=""
    if EleInArray openssl@4 openssl_install_options
    then
        openssl_url="$OPENSSL_SOURCE_LINK"
        openssl_path+=4
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "4")
    elif EleInArray openssl@3 openssl_install_options
    then
        openssl_url="$OPENSSL_SOURCE_LINK"
        openssl_path+=3
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "3")
    else
        openssl_url="$OPENSSL_SOURCE_LINK/old/1.1.1"
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "1")
    fi

    if [ -z "$openssl_pack_url" ]
    then
        Println "$error 无法从 $openssl_url 获取 OpenSSL 源码包地址\n"
        return 1
    fi

    openssl_pack="${openssl_pack_url##*/}"
    openssl_name="${openssl_pack%.tar*}"

    if EleInArray static openssl_install_options
    then
        build_dir+=-static
        openssl_path+=-static
    fi

    if [ -d "$DEPENDS_ROOT/$openssl_name/$build_dir" ] 
    then
        ln -sfn "$DEPENDS_ROOT/$openssl_name/$build_dir" "$openssl_path"
        return 0
    fi

    unset OPENSSL_LOCAL_CONFIG_DIR

    args=(
        --prefix="$DEPENDS_ROOT/$openssl_name/$build_dir"
        --openssldir="$DEPENDS_ROOT/$openssl_name/$build_dir"/etc
        --libdir=lib
    )

    if EleInArray static openssl_install_options
    then
        args+=(no-shared)
    fi

    ArchCheck

    if [ "$dist" == "mac" ] 
    then
        export PERL="$HOMEBREW_PREFIX"/opt/perl/bin/perl
        args+=( darwin64-${arch}-cc )
        SourceInstallReady
    else
        case $arch in
            x86_64) args+=( linux-x86_64 )
            ;;
            i386) args+=( linux-elf )
            ;;
            arm64) args+=( linux-aarch64 )
            ;;
            arm*) args+=( linux-armv4 )
            ;;
            *) Println "$error 不支持的架构 $arch\n"; return 1
        esac

        if [ "$dist" == "rpm" ] 
        then
            SourceInstallReady glibc-devel openssl-devel systemd-devel zlib-devel
        else
            SourceInstallReady gcc libc6-dev libssl-dev libsystemd-dev make zlib1g-dev
        fi
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    curl -L "$openssl_pack_url" -o "$openssl_pack"
    Println "$info 解压 $openssl_name ..."
    tar xzf "$openssl_pack"
    cd "$openssl_name"

    perl ./Configure ${args[@]+"${args[@]}"}
    make
    make install

    ln -sfn "$DEPENDS_ROOT/$openssl_name/$build_dir" "$openssl_path"
}

OpensslPackageInstall()
{
    if [ "$dist" == "rpm" ] 
    then
        DepInstall openssl-devel
    elif [ "$dist" != "mac" ] 
    then
        DepInstall libssl-dev
    fi
}

OpensslInstall()
{
    DepInstall openssl
}
GoInstall()
{
    if [[ ! "$PATH" =~ /usr/local/go/bin ]]
    then
        PATH="$PATH":/usr/local/go/bin
    fi

    go_path=${GOPATH:-"$HOME"/go}

    if [[ ! "$PATH" =~ $go_path ]]
    then
        PATH="${PATH}:${go_path}/bin"
    fi

    export PATH

    if [[ -x $(command -v go) ]] 
    then
        go_version_list=($(go version))
        if [[ "${go_version_list[2]}" =~ ^go([0-9]+)\.([0-9]+)\. ]] && [ "${BASH_REMATCH[1]}" -ge 1 ] && [ "${BASH_REMATCH[2]}" -ge 11 ]
        then
            return 0
        fi
    fi

    if [ "$dist" == "mac" ] 
    then
        DepInstall go
        return 0
    fi

    ArchCheck

    DepInstall curl

    JQInstall

    if ! go_version=$(curl -s -Lm 20 "${GO_DL_LINK}/?mode=json" | $JQ_FILE -r '.[0].version')
    then
        Println "$error 无法连接 go.dev ?"
        go_version="$GO_FALLBACK_VER"
    fi

    if [ "$arch" == "i386" ] 
    then
        go_package="$go_version.linux-386.tar.gz"
    elif [ "$arch" == "x86_64" ] 
    then
        go_package="$go_version.linux-amd64.tar.gz"
    elif [ "$arch" == "arm64" ] || [ "$arch" == "armv6l" ]
    then
        go_package="$go_version.linux-$arch.tar.gz"
    else
        DepInstall golang
        return 0
    fi

    if ! curl -L "${GO_DL_LINK}/$go_package" -o ~/$go_package && ! curl -L "${GO_DL_MIRROR_LINK}/$go_package" -o ~/$go_package
    then
        Println "$error 下载 golang 失败, 请稍后再试\n"
        return 1
    fi

    rm -rf /usr/local/go
    tar -C /usr/local -xzf ~/$go_package
}
NodejsInstall()
{
    if [[ -x $(command -v node) ]] && [[ -x $(command -v npm) ]]
    then
        return 0
    fi

    DepsCheck

    if [ "$dist" == "mac" ] 
    then
        DepInstall node
        return 0
    elif [ "$dist" == "rpm" ] && { [[ -x $(command -v node) ]] || [[ -x $(command -v npm) ]]; }
    then
        yum remove -y nodejs npm || true
    fi

    Progress &
    progress_pid=$!

    trap '
        kill $progress_pid
        wait $progress_pid 2> /dev/null
    ' EXIT

    if [ "$dist" == "rpm" ] 
    then
        yum -y install gcc-c++ make >/dev/null 2>&1
        # yum groupinstall 'Development Tools'

        if curl -fsSL "${NODESOURCE_RPM_LINK}/setup_${NODEJS_VER}.x" | sudo bash - > /dev/null
        then
            sudo yum install -y nsolid > /dev/null 2>&1
        fi
    else
        if curl -fsSL "${NODESOURCE_DEB_LINK}/setup_${NODEJS_VER}.x" | sudo bash - > /dev/null
        then
            AptInstall nodejs
        fi
    fi

    kill $progress_pid
    wait $progress_pid 2> /dev/null || true
    trap - EXIT

    echo -n "...100%"
    Println "$info nodejs 安装完成"
}
MongodbInstall()
{
    if [[ -x $(command -v mongod) ]]
    then
        return 0
    fi

    DepsCheck

    if ! ResourceLimit 
    then
        Println "$error 可能环境是 Unprivileged Container ?\n"
    fi

    DepInstall curl
    DepInstall ca-certificates

    ArchCheck

    if [ "$arch" == "arm64" ] 
    then
        arch_path="aarch64"
    elif [ "$arch" == "x86_64" ] || [ "$arch" == "s390x" ]
    then
        arch_path="$arch"
    else
        Println "$error 不支持当前系统\n"
        return 1
    fi

    case $dist in
        mac) 
            if ! xcode-select -p &> /dev/null
            then
                xcode-select --install
            fi
            brew tap mongodb/brew
            macos_version=$(sw_vers -productVersion)
            if [ "${macos_version%%.*}" -lt 12 ] 
            then
                mkdir -p "$DEPENDS_ROOT"
                if ! curl -Lm 20 https://github.com/Homebrew/homebrew-core/raw/HEAD/Formula/m/mongosh.rb -o "$DEPENDS_ROOT"/mongosh.rb
                then
                    curl -Lm 20 "$FFMPEG_MIRROR_LINK"/mongosh.rb -o "$DEPENDS_ROOT"/mongosh.rb
                fi
                sed -i "s/\"node\"/\"node@${NODEJS_VER}\"/g" "$DEPENDS_ROOT"/mongosh.rb
                brew install "$DEPENDS_ROOT"/mongosh.rb
                brew install mongodb-community --without-mongosh
            else
                brew install mongodb-community
            fi
            brew services start mongodb/brew/mongodb-community
            Println "$info mongodb 安装成功\n"
            return 0
        ;;
        rpm) 
            DepInstall yum-utils
            if [ ! -f "/etc/yum.repos.d/mongodb-org-${MONGODB_VER}.repo" ] 
            then
                if grep -qi Amazon <<< "$ID" || grep -qi Amazon <<< "$NAME" 
                then
cat > "/etc/yum.repos.d/mongodb-org-${MONGODB_VER}.repo" <<EOF
[mongodb-org-${MONGODB_VER}]
name=MongoDB Repository
baseurl=${MONGODB_REPO_LINK}/yum/amazon/$VERSION/mongodb-org/${MONGODB_VER}/$arch_path/
gpgcheck=1
enabled=1
gpgkey=https://pgp.mongodb.com/server-${MONGODB_VER}.asc
EOF
                else
cat > "/etc/yum.repos.d/mongodb-org-${MONGODB_VER}.repo" <<EOF
[mongodb-org-${MONGODB_VER}]
name=MongoDB Repository
baseurl=${MONGODB_REPO_LINK}/yum/redhat/${VERSION_ID%%.*}/mongodb-org/${MONGODB_VER}/$arch_path/
gpgcheck=1
enabled=1
gpgkey=https://pgp.mongodb.com/server-${MONGODB_VER}.asc
EOF
                fi
            fi
            sudo yum-config-manager --enable "mongodb-org-${MONGODB_VER}"
            sudo yum install -y mongodb-org
        ;;
        ubu) 
            local mongo_codename
            mongo_codename=$(AptGetCodename)

            if [ ! -f "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list" ] 
            then
                if ! AptRepoCheck "${MONGODB_REPO_LINK}/apt/ubuntu" "${mongo_codename}/mongodb-org/${MONGODB_VER}"
                then
                    Println "$error MongoDB ${MONGODB_VER} 官方源暂不支持当前系统 (${mongo_codename:-unknown}), 未写入失效源\n"
                    return 1
                fi

                DepInstall ubuntu-keyring
                DepInstall gpg
                curl -fsSL "https://www.mongodb.org/static/pgp/server-${MONGODB_VER}.asc" | gpg --batch --yes --dearmor -o "/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg"
                echo "deb [arch=amd64,arm64 signed-by=/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg] ${MONGODB_REPO_LINK}/apt/ubuntu \
                ${mongo_codename}/mongodb-org/${MONGODB_VER} multiverse" | tee "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list"
                AptUpdate force
            fi

            AptInstall mongodb-org
        ;;
        deb)
            local mongo_codename
            mongo_codename=$(AptGetCodename)

            if [ ! -f "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list" ] 
            then
                if ! AptRepoCheck "${MONGODB_REPO_LINK}/apt/debian" "${mongo_codename}/mongodb-org/${MONGODB_VER}"
                then
                    Println "$error MongoDB ${MONGODB_VER} 官方源暂不支持当前系统 (${mongo_codename:-unknown}), 未写入失效源\n"
                    return 1
                fi

                DepInstall debian-archive-keyring
                DepInstall gpg
                curl -fsSL "https://www.mongodb.org/static/pgp/server-${MONGODB_VER}.asc" | gpg --batch --yes --dearmor -o "/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg"
                echo "deb [ signed-by=/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg ] ${MONGODB_REPO_LINK}/apt/debian \
                ${mongo_codename}/mongodb-org/${MONGODB_VER} main" | tee "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list"
                AptUpdate force
            fi

            AptInstall mongodb-org
        ;;
        sles)
            sudo zypper addrepo --gpgcheck "${MONGODB_REPO_LINK}/zypper/suse/${VERSION_ID%%.*}/mongodb-org/${MONGODB_VER}/$arch_path/" mongodb
            sudo zypper -n install mongodb-org
        ;;
    esac

    if [[ $(ps --no-headers -o comm 1) == "systemd" ]] 
    then
        sed -i "s/LimitNOFILE=.*/LimitNOFILE=$file_max/" /lib/systemd/system/mongod.service
        sed -i '/TasksAccounting=/a StartLimitInterval=60s\nStartLimitBurst=5\nRestartSec=5\nRestart=on-failure' /lib/systemd/system/mongod.service
        systemctl daemon-reload
        sed -i "s/destination: file/destination: syslog/" /etc/mongod.conf
        sed -i "s/  logAppend: true/  #logAppend: true/" /etc/mongod.conf
        sed -i "s+  path: /var/log/mongodb/mongod.log+  #path: /var/log/mongodb/mongod.log+" /etc/mongod.conf
        systemctl start mongod
        systemctl enable mongod
    else
        service mongod start
    fi

    Println "$info mongodb 安装成功\n"
}
ServiceGet()
{
    JQInstall

    local service_id=$1

    if [ ! -s "$SERVICES_CONFIG" ] 
    then
        mkdir -p "$SERVICES_ROOT"
        printf '{"%s":{"%s":[]}}' "4gtv" "accounts" > "$SERVICES_CONFIG"
    fi

    SetDelimiters

    jq_payload=$(JQs flat "$SERVICES_CONFIG")

    case $service_id in
        4gtv) 
            jq_path='[
                ["4gtv","proxy"],
                ["4gtv","accounts","email"],
                ["4gtv","accounts","password"],
                ["4gtv","accounts","token"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            d_4gtv_proxy="$jq_4gtv_proxy"
            _4gtv_acc_email="$jq_4gtv_accounts_email"
            _4gtv_acc_pass="$jq_4gtv_accounts_password"
            _4gtv_acc_token="$jq_4gtv_accounts_token"

            IFS="${delimiters[3]}" read -r -a _4gtv_accs_email <<< "$_4gtv_acc_email"
            IFS="${delimiters[3]}" read -r -a _4gtv_accs_pass <<< "$_4gtv_acc_pass"
            IFS="${delimiters[3]}" read -r -a _4gtv_accs_token <<< "$_4gtv_acc_token"

            _4gtv_accs_count=${#_4gtv_accs_email[@]}
        ;;
        openlist) 
            jq_path='[
                ["openlist","name"],
                ["openlist","url"],
                ["openlist","accs","username"],
                ["openlist","accs","password"],
                ["openlist","accs","token"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            IFS="${delimiters[2]}" read -r -a openlists_name <<< "$jq_openlist_name"
            IFS="${delimiters[2]}" read -r -a openlists_url <<< "$jq_openlist_url"
            IFS="${delimiters[3]}" read -r -a openlists_acc_username <<< "$jq_openlist_accs_username"
            IFS="${delimiters[3]}" read -r -a openlists_acc_password <<< "$jq_openlist_accs_password"
            IFS="${delimiters[3]}" read -r -a openlists_acc_token <<< "$jq_openlist_accs_token"

            openlists_count=${#openlists_name[@]}
        ;;
        rclone) 
        case ${2:-} in
            serve) 
                jq_path='[
                    ["rclone","serve","remote"],
                    ["rclone","serve","protocol"],
                    ["rclone","serve","addr"],
                    ["rclone","serve","htpasswd"],
                    ["rclone","serve","args"],
                    ["rclone","serve","accs","user"],
                    ["rclone","serve","accs","pass"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[3]}" read -r -a rclone_serves_remote <<< "$jq_rclone_serve_remote"
                IFS="${delimiters[3]}" read -r -a rclone_serves_protocol <<< "$jq_rclone_serve_protocol"
                IFS="${delimiters[3]}" read -r -a rclone_serves_addr <<< "$jq_rclone_serve_addr"
                IFS="${delimiters[3]}" read -r -a rclone_serves_htpasswd <<< "$jq_rclone_serve_htpasswd"
                IFS="${delimiters[3]}" read -r -a rclone_serves_args <<< "$jq_rclone_serve_args"
                IFS="${delimiters[4]}" read -r -a rclone_serves_user <<< "$jq_rclone_serve_accs_user"
                IFS="${delimiters[4]}" read -r -a rclone_serves_pass <<< "$jq_rclone_serve_accs_pass"

                rclone_serves_count=${#rclone_serves_remote[@]}
            ;;
            sync) 
                jq_path='[
                    ["rclone","sync","rsync"],
                    ["rclone","sync","source"],
                    ["rclone","sync","target"],
                    ["rclone","sync","args"],
                    ["rclone","sync","exclude_before"],
                    ["rclone","sync","include"],
                    ["rclone","sync","exclude_after"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[3]}" read -r -a rclone_syncs_rsync <<< "$jq_rclone_sync_rsync"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_source <<< "$jq_rclone_sync_source"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_target <<< "$jq_rclone_sync_target"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_args <<< "$jq_rclone_sync_args"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_exclude_before <<< "$jq_rclone_sync_exclude_before"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_include <<< "$jq_rclone_sync_include"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_exclude_after <<< "$jq_rclone_sync_exclude_after"

                rclone_syncs_count=${#rclone_syncs_rsync[@]}
            ;;
            *) 
                jq_path='[
                    ["rclone","remote","name"],
                    ["rclone","remote","type"],
                    ["rclone","remote","url"],
                    ["rclone","remote","vendor"],
                    ["rclone","remote","user"],
                    ["rclone","remote","pass"],
                    ["rclone","remote","mount","path"],
                    ["rclone","remote","mount","mount_path"],
                    ["rclone","remote","mount","flags"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[3]}" read -r -a rclone_remotes_name <<< "$jq_rclone_remote_name"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_type <<< "$jq_rclone_remote_type"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_url <<< "$jq_rclone_remote_url"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_vendor <<< "$jq_rclone_remote_vendor"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_user <<< "$jq_rclone_remote_user"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_pass <<< "$jq_rclone_remote_pass"
                IFS="${delimiters[4]}" read -r -a rclone_remotes_path <<< "$jq_rclone_remote_mount_path"
                IFS="${delimiters[4]}" read -r -a rclone_remotes_mount_path <<< "$jq_rclone_remote_mount_mount_path"
                IFS="${delimiters[4]}" read -r -a rclone_remotes_mount_flag <<< "${jq_rclone_remote_mount_flags}"

                rclone_remotes_count=${#rclone_remotes_name[@]}
            ;;
        esac
        ;;
        kcc)
            jq_path='[
                ["kcc","format"],
                ["kcc","process"],
                ["kcc","args"],
                ["kcc","output"],
                ["kcc","source"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            kcc_format="$jq_kcc_format"
            kcc_process="$jq_kcc_process"
            kcc_args="$jq_kcc_args"
            kcc_output="$jq_kcc_output"

            IFS="${delimiters[2]}" read -r -a kcc_sources <<< "$jq_kcc_source"
        ;;
        iperf)
            jq_path='[
                ["iperf","name"],
                ["iperf","type"],
                ["iperf","target"],
                ["iperf","args"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            IFS="${delimiters[2]}" read -r -a iperf_names <<< "$jq_iperf_name"
            IFS="${delimiters[2]}" read -r -a iperf_types <<< "$jq_iperf_type"
            IFS="${delimiters[2]}" read -r -a iperf_targets <<< "$jq_iperf_target"
            IFS="${delimiters[2]}" read -r -a iperf_args <<< "$jq_iperf_args"

            iperf_count=${#iperf_types[@]}
        ;;
        *)
            jq_path='[
                ["'"$service_id"'","accounts","user_name"],
                ["'"$service_id"'","accounts","phone_number"],
                ["'"$service_id"'","accounts","password"],
                ["'"$service_id"'","accounts","access_token"],
                ["'"$service_id"'","accounts","device_no"],
                ["'"$service_id"'","accounts","device_id"],
                ["'"$service_id"'","accounts","refresh"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name##*_accounts_}
                var_name=m_"$var_name"
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            if [ -z "$m_user_name" ] 
            then
                ts_accs_count=0
                return 0
            fi

            IFS="${delimiters[3]}" read -r -a ts_accs_user_name <<< "$m_user_name"

            if [ -z "$m_phone_number" ] 
            then
                ts_accs_phone_number=("${ts_accs_user_name[@]//*/}")
            else
                IFS="${delimiters[3]}" read -r -a ts_accs_phone_number <<< "$m_phone_number"
            fi

            IFS="${delimiters[3]}" read -r -a ts_accs_password <<< "$m_password"
            IFS="${delimiters[3]}" read -r -a ts_accs_access_token <<< "$m_access_token"
            IFS="${delimiters[3]}" read -r -a ts_accs_device_no <<< "$m_device_no"
            IFS="${delimiters[3]}" read -r -a ts_accs_device_id <<< "$m_device_id"
            IFS="${delimiters[3]}" read -r -a ts_accs_refresh <<< "$m_refresh"

            ts_accs_count=${#ts_accs_user_name[@]}
        ;;
    esac

    return 0
}
NginxParseConfig()
{
    CrossplaneInstall

    if TMP_FILE=$(mktemp -q)
    then
        chmod +r "$TMP_FILE"
    else
        exit $?
    fi

    trap '
        rm -f "$TMP_FILE"
    ' EXIT

    if [ -z "${1:-}" ] 
    then
        parse_file="$nginx_prefix/conf/nginx.conf"
        parse_in=$(< $parse_file)
        parse_domain=0
    else
        parse_file="$nginx_prefix/conf/sites_available/$1.conf"
        parse_in="http {$(< $parse_file)}"
        parse_domain=1
    fi

    echo "$parse_in" > "$TMP_FILE"

    parse_out=$(crossplane parse "$TMP_FILE" --single-file)

    rm -f "$TMP_FILE"

    trap - EXIT

    jq_path='["config",0,"file"]'
    JQs update parse_out "$parse_file"
}
NginxGetConfig()
{
    SetDelimiters

    local jq_status="" jq_errors_error=""
    local jq_l1_dir="" jq_l1_args=""
    local jq_l2_dir="" jq_l2_args=""
    local jq_l3_dir="" jq_l3_args=""
    local jq_l4_dir="" jq_l4_args=""
    local jq_l5_dir="" jq_l5_args=""
    local key val

    while IFS="$field_sep" read -r key val
    do
        case "$key" in
            status) jq_status="$val" ;;
            errors) jq_errors_error="$val" ;;
            l1_dir) jq_l1_dir="$val" ;;
            l1_args) jq_l1_args="$val" ;;
            l2_dir) jq_l2_dir="$val" ;;
            l2_args) jq_l2_args="$val" ;;
            l3_dir) jq_l3_dir="$val" ;;
            l3_args) jq_l3_args="$val" ;;
            l4_dir) jq_l4_dir="$val" ;;
            l4_args) jq_l4_args="$val" ;;
            l5_dir) jq_l5_dir="$val" ;;
            l5_args) jq_l5_args="$val" ;;
        esac
    done < <($JQ_FILE -r --arg sep "$field_sep" --argjson d "$json_delimiters" '
        def jp($sep): if length == 0 then "" else map((. // "") + $sep) | join("") end;
        def arr_objs($x): if ($x | type) == "array" then ($x | map(select(type == "object"))) else [] end;
        def ea($sep): if (.args | type) == "array" then (.args | map(tostring) | join($sep)) else (.args // "" | tostring) end;
        def b: arr_objs(.block);
        (if (.config | type) == "array" and ((.config[0] // null) | type) == "object" then arr_objs(.config[0].parsed) else [] end) as $l1
        | ($l1 | map(b)) as $l2
        | ($l2 | map(map(b))) as $l3
        | ($l3 | map(map(map(b)))) as $l4
        | ($l4 | map(map(map(map(b))))) as $l5
        | [
            ["status", (if (.status | type) == "string" then .status else "" end)],
            ["errors", (if (.errors | type) == "array" then (.errors | map(if type == "object" then (.error // "") else tostring end) | join($d[0])) else "" end)],
            ["l1_dir", ($l1 | map(.directive // "") | jp($d[3]))],
            ["l1_args", ($l1 | map(ea($d[4])) | jp($d[3]))],
            ["l2_dir", (if ($l2 | map(length) | add // 0) == 0 then "" else ($l2 | map(map(.directive // "") | jp($d[4])) | jp($d[3])) end)],
            ["l2_args", (if ($l2 | map(length) | add // 0) == 0 then "" else ($l2 | map(map(ea($d[5])) | jp($d[4])) | jp($d[3])) end)],
            ["l3_dir", (if ($l3 | map(map(length) | add // 0) | add // 0) == 0 then "" else ($l3 | map(map(map(.directive // "") | jp($d[6])) | jp($d[5])) | jp($d[4])) end)],
            ["l3_args", (if ($l3 | map(map(length) | add // 0) | add // 0) == 0 then "" else ($l3 | map(map(map(ea($d[7])) | jp($d[6])) | jp($d[5])) | jp($d[4])) end)],
            ["l4_dir", (if ($l4 | map(map(map(length) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l4 | map(map(map(map(.directive // "") | jp($d[8])) | jp($d[7])) | jp($d[6])) | jp($d[5])) end)],
            ["l4_args", (if ($l4 | map(map(map(length) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l4 | map(map(map(map(ea($d[9])) | jp($d[8])) | jp($d[7])) | jp($d[6])) | jp($d[5])) end)],
            ["l5_dir", (if ($l5 | map(map(map(map(length) | add // 0) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l5 | map(map(map(map(map(.directive // "") | jp($d[10])) | jp($d[9])) | jp($d[8])) | jp($d[7])) | jp($d[6])) end)],
            ["l5_args", (if ($l5 | map(map(map(map(length) | add // 0) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l5 | map(map(map(map(map(ea($d[11])) | jp($d[10])) | jp($d[9])) | jp($d[8])) | jp($d[7])) | jp($d[6])) end)]
          ][]
        | "\(.[0])\($sep)\(.[1])"
    ' <<< "$parse_out")

    status="$jq_status"
    error_message="$jq_errors_error"
    level_1_directive="$jq_l1_dir"
    level_1_args="$jq_l1_args"
    level_2_directive="$jq_l2_dir"
    level_2_args="$jq_l2_args"
    level_3_directive="$jq_l3_dir"
    level_3_args="$jq_l3_args"
    level_4_directive="$jq_l4_dir"
    level_4_args="$jq_l4_args"
    level_5_directive="$jq_l5_dir"
    level_5_args="$jq_l5_args"

    if [ "$status" == "failed" ]
    then
        Println "$error ${error_message//${delimiters[0]}/$'\n'}\n"
        exit 1
    fi

    # level 1 - stream,http...
    # level 2 - map,upstream,server...
    # level 3 - location...
    # level 4 - proxy_pass,root,index...
    # level 5 - return...

    level_1_count=0
    level_2_d1_count=0
    level_3_d1_count=0
    level_4_d1_count=0
    level_5_d1_count=0

    level_1_directive_arr=()
    level_1_args_arr=()
    level_2_directive_arr=()
    level_2_args_arr=()
    level_3_directive_arr=()
    level_3_args_arr=()
    level_4_directive_arr=()
    level_4_args_arr=()
    level_5_directive_arr=()
    level_5_args_arr=()

    if [ -z "$level_1_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[3]}" read -r -a level_1_directive_arr <<< "$level_1_directive"
    IFS="${delimiters[3]}" read -r -a level_1_args_arr <<< "$level_1_args"

    level_1_count=${#level_1_directive_arr[@]}

    if [ -z "$level_2_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[3]}" read -r -a level_2_directive_arr <<< "$level_2_directive"
    IFS="${delimiters[3]}" read -r -a level_2_args_arr <<< "$level_2_args"

    level_2_d1_count=${#level_2_directive_arr[@]}

    if [ -z "$level_3_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[4]}" read -r -a level_3_directive_arr <<< "$level_3_directive"
    IFS="${delimiters[4]}" read -r -a level_3_args_arr <<< "$level_3_args"

    level_3_d1_count=${#level_3_directive_arr[@]}

    if [ -z "$level_4_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[5]}" read -r -a level_4_directive_arr <<< "$level_4_directive"
    IFS="${delimiters[5]}" read -r -a level_4_args_arr <<< "$level_4_args"

    level_4_d1_count=${#level_4_directive_arr[@]}

    if [ -z "$level_5_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[6]}" read -r -a level_5_directive_arr <<< "$level_5_directive"
    IFS="${delimiters[6]}" read -r -a level_5_args_arr <<< "$level_5_args"

    level_5_d1_count=${#level_5_directive_arr[@]}
}
NginxBuildConf()
{
    if TMP_FILE=$(mktemp -q)
    then
        chmod +r "$TMP_FILE"
    else
        exit $?
    fi

    trap '
        rm -f "$TMP_FILE"
    ' EXIT

    if [ "$parse_domain" -eq 1 ]
    then
        parse_out_domain=${!1}
        jq_path='["config",0,"parsed",0,"block"]'
        domain_conf=$(JQs get parse_out_domain)
        jq_path='["config",0,"parsed"]'
        JQs replace parse_out_domain "$domain_conf"
        echo "$parse_out_domain" > "$TMP_FILE"
    else
        echo "${!1}" > "$TMP_FILE"
    fi

    crossplane build -f --no-headers "$TMP_FILE"

    rm -f "$TMP_FILE"

    trap - EXIT
}
AcmeCheck()
{
    [ -n "${ca_server:-}" ] && return 0

    if [ ! -f "$HOME/.acme.sh/acme.sh" ] 
    then
        DepInstall socat
        mkdir -p "$DEPENDS_ROOT"
        { curl -s -m 20 https://raw.githubusercontent.com/acmesh-official/acme.sh/master/acme.sh || curl -s -m 20 "$FFMPEG_MIRROR_LINK/acme.sh"; } \
        | sed "s+https://raw.githubusercontent.com/acmesh-official+$FFMPEG_MIRROR_LINK/acmesh-content+g" \
        | sed "s+| sh+| sed 's~PROJECT=\"https://github.com/acmesh-official~PROJECT=\"$FFMPEG_MIRROR_LINK/acmesh-project~' | sed 's~https://api.github.com~$FFMPEG_MIRROR_LINK/acmesh-api~g' | sh+g" > "$DEPENDS_ROOT"/acme.sh
        cd "$DEPENDS_ROOT"
        bash acme.sh --install
    else
        echo
        inquirer list_input_index "更新 acme.sh" ny_options ny_index

        if [ "$ny_index" -eq 1 ] 
        then
            ~/.acme.sh/acme.sh --upgrade
        fi
    fi

    Println "$tip zerossl 不支持 tls-alpn-01"
    ca_options=( letsencrypt zerossl )
    inquirer list_input "选择 CA" ca_options ca_server

    if [ "$ca_server" == "zerossl" ] 
    then
        if [ -e ~/.acme.sh/ca/acme.zerossl.com/ca.conf ] 
        then
            . ~/.acme.sh/ca/acme.zerossl.com/ca.conf
        elif [ -e ~/.acme.sh/ca/acme.zerossl.com/v2/DV90/ca.conf ] 
        then
            . ~/.acme.sh/ca/acme.zerossl.com/v2/DV90/ca.conf
        fi

        if [ -n "${CA_EAB_KEY_ID:-}" ] && [ -n "${CA_EAB_HMAC_KEY:-}" ]
        then
            Println "$tip 请确保已有账号的 EAB 认证信息未过期, 否则请重新设置"
            inquirer list_input "是否重新设置 zerossl 账号" ny_options yn_option
            if [ "$yn_option" == "$i18n_no" ] 
            then
                return 0
            fi
        fi

        echo
        zerossl_options=( '注册新账号' '输入已有账号的 EAB 认证信息' )
        inquirer list_input_index "未发现 zerossl 账号" zerossl_options zerossl_options_index

        if [ "$zerossl_options_index" -eq 0 ] 
        then
            echo
            ExitOnText "输入邮箱: " zerossl_email

            if ! ~/.acme.sh/acme.sh --register-account -m "$zerossl_email" --server zerossl 
            then
                Println "$error 注册账号失败, 请稍后再试或前往官网注册 https://app.zerossl.com/signup?fpr=iptv-sh \n"
                exit 1
            fi
        else
            Println "$tip 可以在 https://app.zerossl.com/developer?fpr=iptv-sh 页面获取"
            ExitOnText "输入 EAB KID: " zerossl_eab_kid

            echo
            ExitOnText "输入 EAB HMAC Key: " zerossl_eab_hmac_key

            if ! ~/.acme.sh/acme.sh --register-account --server zerossl --eab-kid "$zerossl_eab_kid" --eab-hmac-key "$zerossl_eab_hmac_key" 
            then
                Println "$error 注册账号失败, 请确保输入正确\n"
                exit 1
            fi
        fi

        Println "$info 账号注册成功\n"
    fi
}
NginxPackageInstall()
{
    DepInstall curl
    DepInstall ca-certificates

    . /etc/os-release

    case $dist in
        ubu)
            local nginx_codename nginx_repo_base
            nginx_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/nginx.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    nginx_repo_base="https://${USTC_MIRROR_HOST}/nginx/mainline/ubuntu"
                else
                    nginx_repo_base="${NGINX_REPO_LINK}/ubuntu"
                fi

                if AptRepoCheck "$nginx_repo_base" "$nginx_codename"
                then
                    DepInstall ubuntu-keyring
                    DepInstall gpg
                    curl -fsSL https://nginx.org/keys/nginx_signing.key | gpg --batch --yes --dearmor -o /usr/share/keyrings/nginx-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/nginx-archive-keyring.gpg] ${nginx_repo_base} \
                    ${nginx_codename} nginx" | tee /etc/apt/sources.list.d/nginx.list
                    echo -e "Package: *\nPin: origin nginx.org\nPin: release o=nginx\nPin-Priority: 900\n" | sudo tee /etc/apt/preferences.d/99nginx
                    AptUpdate force
                else
                    Println "$tip Nginx 官方源暂不支持当前系统 (${nginx_codename:-unknown}), 改用系统默认源安装"
                fi
            fi

            AptInstall nginx
        ;;
        deb)
            local nginx_codename nginx_repo_base
            nginx_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/nginx.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    nginx_repo_base="https://${USTC_MIRROR_HOST}/nginx/mainline/debian"
                else
                    nginx_repo_base="${NGINX_REPO_LINK}/debian"
                fi

                if AptRepoCheck "$nginx_repo_base" "$nginx_codename"
                then
                    DepInstall debian-archive-keyring
                    DepInstall gpg
                    curl -fsSL https://nginx.org/keys/nginx_signing.key | gpg --batch --yes --dearmor -o /usr/share/keyrings/nginx-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/nginx-archive-keyring.gpg] ${nginx_repo_base} \
                    ${nginx_codename} nginx" | sudo tee /etc/apt/sources.list.d/nginx.list
                    echo -e "Package: *\nPin: origin nginx.org\nPin: release o=nginx\nPin-Priority: 900\n" | sudo tee /etc/apt/preferences.d/99nginx
                    AptUpdate force
                else
                    Println "$tip Nginx 官方源暂不支持当前系统 (${nginx_codename:-unknown}), 改用系统默认源安装"
                fi
            fi

            AptInstall nginx
        ;;
        rpm)
            if [ "${VERSION_ID%%.*}" -eq 7 ]
            then
                Println "$tip 官方说明: Packages for RHEL 7 and SLES 12 are built without HTTP/3 support because OpenSSL used by those doesn't support TLSv1.3."
            fi

            DepInstall yum-utils

            if [ ! -f /etc/yum.repos.d/nginx.repo ]
            then
                if grep -q Amazon < /etc/os-release
                then
                    if [ "$VERSION" == "2" ]
                    then
cat > /etc/yum.repos.d/nginx.repo <<EOF
[nginx-stable]
name=nginx stable repo
baseurl=http://nginx.org/packages/amzn2/\$releasever/\$basearch/
gpgcheck=1
enabled=1
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9

[nginx-mainline]
name=nginx mainline repo
baseurl=http://nginx.org/packages/mainline/amzn2/\$releasever/\$basearch/
gpgcheck=1
enabled=0
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9
EOF
                    elif [ "$VERSION" == "2023" ]
                    then
cat > /etc/yum.repos.d/nginx.repo <<EOF
[nginx-stable]
name=nginx stable repo
baseurl=http://nginx.org/packages/amzn/2023/\$basearch/
gpgcheck=1
enabled=1
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9

[nginx-mainline]
name=nginx mainline repo
baseurl=http://nginx.org/packages/mainline/amzn/2023/\$basearch/
gpgcheck=1
enabled=0
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9
EOF
                    else
                        Println "$error 不支持的系统\n"
                        return 1
                    fi
                else
cat > /etc/yum.repos.d/nginx.repo <<EOF
[nginx-stable]
name=nginx stable repo
baseurl=http://nginx.org/packages/centos/\$releasever/\$basearch/
gpgcheck=1
enabled=1
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true

[nginx-mainline]
name=nginx mainline repo
baseurl=http://nginx.org/packages/mainline/centos/\$releasever/\$basearch/
gpgcheck=1
enabled=0
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
EOF
                fi
            fi
            sudo yum-config-manager --disable nginx-stable
            sudo yum-config-manager --enable nginx-mainline
            sudo yum -y install nginx
        ;;
        alpine)
            sudo apk add openssl curl ca-certificates
            printf "%s%s%s%s\n" \
            "@nginx " \
            "http://nginx.org/packages/mainline/alpine/v" \
            `egrep -o '^[0-9]+\.[0-9]+' /etc/alpine-release` \
            "/main" \
            | sudo tee -a /etc/apk/repositories
            curl -o /tmp/nginx_signing.rsa.pub https://nginx.org/keys/nginx_signing.rsa.pub
            sudo mv /tmp/nginx_signing.rsa.pub /etc/apk/keys/
            sudo apk add nginx@nginx
        ;;
        sles)
            if [ "${VERSION_ID%%.*}" -eq 12 ]
            then
                Println "$tip 官方说明: Packages for RHEL 7 and SLES 12 are built without HTTP/3 support because OpenSSL used by those doesn't support TLSv1.3."
            fi
            sudo zypper install curl ca-certificates gpg2
            sudo zypper addrepo --gpgcheck --type yum --refresh --check 'http://nginx.org/packages/mainline/sles/$releasever_major' nginx-mainline
            curl -o /tmp/nginx_signing.key https://nginx.org/keys/nginx_signing.key
            sudo rpmkeys --import /tmp/nginx_signing.key
            sudo zypper install nginx
        ;;
        *)
            Println "$error 不支持的系统\n"
            return 1
        ;;
    esac

    if [ ! -d "$nginx_prefix" ]
    then
        mkdir -p "$nginx_prefix"/sbin
        mv /usr/sbin/nginx* "$nginx_prefix"/sbin/
        ln -sfn /etc/nginx "$nginx_prefix"/conf
        ln -sfn /var/log/nginx "$nginx_prefix"/logs
        ln -sfn /usr/share/nginx/html "$nginx_prefix"/html
        ln -sf /var/run/nginx.pid "$nginx_prefix"/logs/nginx.pid
        for file in "$nginx_prefix"/sbin/*
        do
            if [[ -x "$AIOS_PREFIX"/bin/${file##*/} ]]
            then
                continue
            fi
cat > "$AIOS_PREFIX"/bin/${file##*/} <<EOF
#!/bin/sh
$file -p "$nginx_prefix" "\$@"
EOF
            chmod +x "$AIOS_PREFIX"/bin/*
        done
    fi

    if ! grep -q "$nginx_name:" < "/etc/passwd"
    then
        if grep -q '\--group ' < <(adduser --help)
        then
            adduser "$nginx_name" --system --group --no-create-home > /dev/null
        else
            adduser "$nginx_name" --system --no-create-home > /dev/null
        fi
        usermod -s /usr/sbin/nologin "$nginx_name"
    fi

    sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"
    sed -i '/conf.d/d' "$nginx_prefix/conf/nginx.conf"
    sed -i 's|/var/log/nginx|logs|g' "$nginx_prefix/conf/nginx.conf"
    sed -i 's|/var/run|logs|g' "$nginx_prefix/conf/nginx.conf"
    sed -i 's|/etc/nginx/||g' "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$info $nginx_name 安装成功\n"
}

NginxSourceInstall()
{
    local install="更新"

    if [ -z "${1:-}" ]
    then
        if [[ -x $(command -v $nginx_name) ]]
        then
            return 0
        fi
        install="安装"
    elif [[ ! -x $(command -v $nginx_name) ]]
    then
        install="安装"
    fi

    DepsCheck

    echo
    pcre_options=( pcre pcre2 )
    inquirer list_input_index "选择 pcre 版本" pcre_options pcre_options_index

    Println "$tip 如果选择 openssl, $nginx_name 将不支持 ssl_early_data (0-RTT)"
    openssl_options=( openssl@1.1 openssl@3 quictls )
    inquirer list_input_index "选择 openssl 版本" openssl_options openssl_options_index

    if [ "$dist" == "mac" ] && [ ! -d "$nginx_prefix" ]
    then
        Println "$info 建立目录 $nginx_prefix, 可能需要输入密码\n"
        sudo mkdir "$nginx_prefix"
        sudo chown $USER "$nginx_prefix"
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    rm -rf nginx-http-flv-module-master
    curl -L "$FFMPEG_MIRROR_LINK/nginx-http-flv-module.zip" -o nginx-http-flv-module.zip
    Println "$info 解压 nginx-http-flv-module ..."
    unzip nginx-http-flv-module.zip >/dev/null 2>&1

    #cd nginx-http-flv-module-master
    #curl -s -L "$FFMPEG_MIRROR_LINK/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch" -o Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #patch -p1 < Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #cd "$DEPENDS_ROOT"

    while IFS= read -r line
    do
        if [[ $line == *"/download/"* ]]
        then
            nginx_package_name=${line#*/download/}
            nginx_package_name=${nginx_package_name%%.tar.gz*}
            break
        fi
    done < <(curl -s -Lm 20 -H "User-Agent: $USER_AGENT_BROWSER" https://nginx.org/en/download.html 2> /dev/null)

    if [ ! -d "./$nginx_package_name" ]
    then
        curl -L "https://nginx.org/download/$nginx_package_name.tar.gz" -o "$nginx_package_name.tar.gz"
        Println "$info 解压 $nginx_package_name ..."
        tar xzf "$nginx_package_name.tar.gz"
    fi

    if [ "$dist" == "mac" ]
    then
        SourceInstallReady "${pcre_options[pcre_options_index]}" zlib

        cc_opt="-I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/include -I$HOMEBREW_PREFIX/opt/zlib/include"
        ld_opt="-I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib -L$HOMEBREW_PREFIX/opt/zlib/lib"

        if [ "$openssl_options_index" -eq 2 ]
        then
            QuictlsInstall
            cc_opt="$cc_opt -I$DEPENDS_ROOT/quictls/build/include"
            ld_opt="$ld_opt -L$DEPENDS_ROOT/quictls/build/lib"
        else
            DepInstall "${openssl_options[openssl_options_index]}"
            cc_opt="$cc_opt -I$HOMEBREW_PREFIX/opt/${openssl_options[openssl_options_index]}/include"
            ld_opt="$ld_opt -L$HOMEBREW_PREFIX/opt/${openssl_options[openssl_options_index]}/lib"
        fi

        cd "$DEPENDS_ROOT/$nginx_package_name/"

        ./configure \
        --with-cc-opt="$cc_opt" \
        --with-ld-opt="$ld_opt" \
        --add-module=../nginx-http-flv-module-master \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_gunzip_module \
        --with-http_gzip_static_module \
        --with-http_mp4_module \
        --with-http_random_index_module \
        --with-http_realip_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_ssl_module \
        --with-http_stub_status_module \
        --with-http_sub_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --with-http_flv_module \
        --with-mail \
        --with-mail_ssl_module \
        --with-pcre \
        --with-pcre-jit \
        --with-stream \
        --with-stream_realip_module \
        --with-stream_ssl_module \
        --with-stream_ssl_preread_module \
        --with-threads
    else
        if [ "$dist" == "rpm" ]
        then
            SourceInstallReady openssl-devel gcc
        else
            SourceInstallReady perl software-properties-common pkg-config libssl-dev libghc-zlib-dev libcurl4-gnutls-dev libexpat1-dev unzip gettext
        fi

        while IFS= read -r line
        do
            if [[ $line =~ \<A\ HREF=\"(.+)\.tar\.gz ]]
            then
                zlib_name=${BASH_REMATCH[1]}
                break
            fi
        done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://www.zlib.net 2> /dev/null)

        if [ ! -d $zlib_name ]
        then
            curl -L https://www.zlib.net/$zlib_name.tar.gz -o $zlib_name.tar.gz
            Println "$info 解压 $zlib_name ..."
            tar xzf $zlib_name.tar.gz
        fi

        if [ "$pcre_options_index" -eq 0 ]
        then
            pcre_name="pcre-${PCRE_LEGACY_VER}"
            if [ ! -d $pcre_name ]
            then
                curl -L https://downloads.sourceforge.net/pcre/pcre/${pcre_name#*-}/$pcre_name.zip -o $pcre_name.zip
                Println "$info 解压 $pcre_name ..."
                unzip $pcre_name.zip >/dev/null 2>&1
            fi
        else
            pcre_name=$(curl -s -Lm 20 "$FFMPEG_MIRROR_LINK/pcre2.json" | $JQ_FILE -r '.tag_name')
            if [ ! -d $pcre_name ]
            then
                curl -L $FFMPEG_MIRROR_LINK/pcre2/$pcre_name/$pcre_name.zip -o $pcre_name.zip
                Println "$info 解压 $pcre_name ..."
                unzip $pcre_name.zip >/dev/null 2>&1
            fi
        fi

        if [ "$openssl_options_index" -eq 2 ]
        then
            openssl_name="openssl-${QUICTLS_TAG}"
            Println "$info 下载 ${openssl_name#*-} ..."
            if ! curl -Lm 30 "${QUICTLS_REPO_LINK}/${openssl_name#*-}.tar.gz" -o "$openssl_name".tar.gz
            then
                curl -L "$FFMPEG_MIRROR_LINK/${openssl_name#*-}".tar.gz -o "$openssl_name".tar.gz
            fi
            Println "$info 解压 ${openssl_name#*-} ..."
            tar xzf "$openssl_name".tar.gz
        else
            local openssl_pack_url=""
            if [ "$openssl_options_index" -eq 0 ]
            then
                openssl_url="${OPENSSL_SOURCE_LINK}/old/1.1.1"
                openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "1")
            else
                openssl_url="$OPENSSL_SOURCE_LINK"
                openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "3")
            fi

            if [ -z "$openssl_pack_url" ]
            then
                Println "$error 无法从 $openssl_url 获取 OpenSSL 源码包地址\n"
                return 1
            fi

            openssl_pack="${openssl_pack_url##*/}"
            openssl_name="${openssl_pack%.tar*}"

            if [ ! -d "./$openssl_name" ]
            then
                curl -L "$openssl_pack_url" -o "$openssl_pack"
                Println "$info 解压 $openssl_name ..."
                tar xzf "$openssl_pack"
            fi
        fi

        cd "$nginx_package_name/"

        ./configure \
        --add-module=../nginx-http-flv-module-master \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_gunzip_module \
        --with-http_gzip_static_module \
        --with-http_mp4_module \
        --with-http_random_index_module \
        --with-http_realip_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_ssl_module \
        --with-http_stub_status_module \
        --with-http_sub_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --with-http_flv_module \
        --with-mail \
        --with-mail_ssl_module \
        --with-pcre=../$pcre_name \
        --with-pcre-jit \
        --with-zlib=../$zlib_name \
        --with-stream \
        --with-stream_realip_module \
        --with-stream_ssl_module \
        --with-stream_ssl_preread_module \
        --with-openssl=../$openssl_name \
        --with-threads
    fi

    nproc="-j$(nproc 2> /dev/null)" || nproc="-j1"

    make $nproc
    make install

    ln -sf "$nginx_prefix"/sbin/nginx "$AIOS_PREFIX"/bin/

    if [ "$dist" != "mac" ]
    then
        if ! grep -q "$nginx_name:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser "$nginx_name" --system --group --no-create-home > /dev/null
            else
                adduser "$nginx_name" --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin "$nginx_name"
        fi

        sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    fi

    sed -i "s/worker_processes .*/worker_processes  ${nproc:2};/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$info $nginx_name ${install}成功\n"
}

NginxInstall()
{
    if [ -d "$nginx_prefix" ]
    then
        Println "$error $nginx_name 已经存在 $nginx_prefix !\n"
        return 1
    elif [[ -x $(command -v $nginx_name) ]]
    then
        Println "$error $nginx_name 已经存在 $(command -v $nginx_name), 请先卸载!\n"
        return 1
    fi

    if [ "$dist" != "mac" ]
    then
        Println "$tip 选择快速安装将缺少 nginx-http-flv-module 以及 quictls 选择"
        nginx_install_options=( "${nginx_name}官方包 (快速安装)" '编译安装' )
        inquirer list_input_index "选择安装方式" nginx_install_options nginx_install_options_index

        if [ "$nginx_install_options_index" -eq 0 ]
        then
            NginxPackageInstall
            return
        fi
    fi

    NginxSourceInstall
}

NginxUninstall()
{
    if [ ! -d "$nginx_prefix" ]
    then
        Println "$error $nginx_name 未安装 !\n"
        return 1
    fi

    echo
    ExitOnList n "`eval_gettext \"确定删除 \\\$nginx_name 包括所有配置文件, 操作不可恢复\"`"

    ServiceControl disable $nginx_name

    DepInstall file

    if file -h "$nginx_prefix/conf" | grep -q 'symbolic link'
    then
        if [ "$dist" == "yum" ]
        then
            yum -y remove "$nginx_name" || true
        else
            apt-get -y --purge remove "$nginx_name"* || true
        fi
        rm -f "$AIOS_PREFIX"/bin/"$nginx_name"*
    elif [ "$dist" == "mac" ]
    then
        brew uninstall "$nginx_name"
        Println "$info 可能需要输入密码删除目录 "$nginx_prefix"\n"
    fi

    sudo rm -rf "$nginx_prefix"

    Println "$info $nginx_name 卸载完成\n"
}

NginxUpdate()
{
    ShFileUpdate "$nginx_name"

    if [ ! -d "$nginx_prefix" ]
    then
        Println "$error $nginx_name 未安装 !\n"
        return 1
    fi

    DepInstall file

    if ! file -h "$nginx_prefix/conf" | grep -q 'symbolic link'
    then
        NginxSourceInstall update
        return
    fi

    if [ "$dist" == "rpm" ]
    then
        yum update -y "$nginx_name"
    else
        apt-get -y install --only-upgrade "$nginx_name"
    fi
}
CrossplaneInstall()
{
    if [[ -x $(command -v crossplane) ]] 
    then
        return 0
    fi

    Println "$info 安装 crossplane ..."

    PythonInstall
    pip3 install crossplane
}
PostfixInstall()
{
    if [ "$dist" == "rpm" ] 
    then
        yum -y install postfix > /dev/null
    else
        AptInstall postfix
    fi
}
TesseractInstall()
{
    if [[ -x $(command -v tesseract) ]] 
    then
        Println "$error tesseract 已存在!\n"
        return 0
    fi

    DepsCheck

    if [ "$dist" == "ubu" ] 
