NginxAddDomain()
{
    NginxListDomains

    Println "$tip 多个域名用空格分隔"
    ExitOnText "输入指向本机的IP或域名" domains

    NginxCheckLocalhost
    NginxAddHttp

    new_domains=( $domains )
    domain_options=( http 'http => https' 'http + https' )

    for server_domain in "${new_domains[@]}"
    do
        if [ -e "$nginx_prefix/conf/sites_available/$server_domain.conf" ] 
        then
            Println "$error $server_domain 已存在"
            continue
        fi

        if [[ $server_domain =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$ ]] || [[ ! $server_domain =~ ^([a-zA-Z0-9](([a-zA-Z0-9-]){0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$ ]]
        then
            domain_options_index=0
        else
            echo
            inquirer list_input_index "选择网站 $server_domain 类型" domain_options domain_options_index
        fi

        case $domain_options_index in
            0) 
                NginxConfigServerHttpPort
                echo
                inquirer list_input "是否设置跳转到其它网址" ny_options http_redirect_yn

                if [ "$http_redirect_yn" == "$i18n_yes" ] 
                then
                    NginxAppendHttpRedirectConf
                else
                    NginxConfigServerRoot
                    NginxConfigServerLiveRoot
                    NginxAppendHttpConf
                fi

                updated=0
                NginxAddCorsHost
                [ "$updated" -eq 1 ] && NginxBuildConf parse_out

                NginxEnableDomain
                Println "$info $server_domain 配置成功\n"
            ;;
            1) 
                NginxSitesCrtInstall "$server_domain"
                inquirer list_input "是否设置 http 跳转 https" yn_options http_to_https_yn

                if [ "$http_to_https_yn" == "$i18n_yes" ] 
                then
                    Println "$info 设置 $server_domain http 配置"
                    NginxConfigServerHttpPort
                    NginxAppendHttpRedirectToHttpsConf
                fi

                NginxConfigServerHttpsPort
                echo
                inquirer list_input "是否设置 https 跳转到其它网址" ny_options https_redirect_yn

                if [ "$https_redirect_yn" == "$i18n_yes" ] 
                then
                    NginxAppendHttpsRedirectConf
                else
                    NginxConfigServerRoot
                    NginxConfigServerLiveRoot
                    NginxAppendHttpsConf
                fi

                updated=0
                NginxAddCorsHost
                [ "$updated" -eq 1 ] && NginxBuildConf parse_out

                NginxEnableDomain
                Println "$info $server_domain 配置成功\n"
            ;;
            2) 
                NginxSitesCrtInstall "$server_domain"
                inquirer list_input "http 和 https 是否使用相同的目录" yn_options http_https_same_dir_yn

                if [ "$http_https_same_dir_yn" == "$i18n_yes" ] 
                then
                    NginxConfigServerHttpPort
                    NginxConfigServerHttpsPort
                    echo
                    inquirer list_input "是否设置跳转到其它网址" ny_options http_https_redirect_yn
                    if [ "$http_https_redirect_yn" == "$i18n_yes" ] 
                    then
                        NginxAppendHttpHttpsRedirectConf
                    else
                        NginxConfigServerRoot
                        NginxConfigServerLiveRoot
                        NginxAppendHttpHttpsConf
                    fi
                else
                    NginxConfigServerHttpPort
                    echo
                    inquirer list_input "是否设置 http 跳转到其它网址" ny_options http_redirect_yn
                    if [ "$http_redirect_yn" == "$i18n_yes" ] 
                    then
                        NginxAppendHttpRedirectConf
                        NginxConfigServerHttpsPort

                        echo
                        inquirer list_input "是否设置 https 跳转到其它网址" yn_options https_redirect_yn

                        if [ "$https_redirect_yn" == "$i18n_yes" ] 
                        then
                            NginxAppendHttpsRedirectConf
                        else
                            NginxConfigServerRoot
                            NginxConfigServerLiveRoot
                            NginxAppendHttpsConf
                        fi
                    else
                        NginxConfigServerRoot
                        NginxConfigServerLiveRoot

                        server_http_root="$server_root"
                        server_http_live_root="$server_live_root"
                        server_http_deny="$deny_aliyun"

                        NginxConfigServerHttpsPort

                        echo
                        inquirer list_input "是否设置 https 跳转到其它网址" yn_options https_redirect_yn

                        if [ "$https_redirect_yn" == "$i18n_yes" ] 
                        then
                            NginxAppendHttpConf
                            NginxAppendHttpsRedirectConf
                        else
                            server_root=""
                            server_live_root=""
                            deny_aliyun=""
                            NginxConfigServerRoot
                            NginxConfigServerLiveRoot

                            server_https_root="$server_root"
                            server_https_live_root="$server_live_root"
                            server_https_deny="$deny_aliyun"

                            if [ "$server_http_root" == "$server_https_root" ] && [ "$server_http_live_root" == "$server_https_live_root" ] && [ "$server_http_deny" == "$server_https_deny" ]
                            then
                                NginxAppendHttpHttpsConf
                            else
                                NginxAppendHttpConf
                                NginxAppendHttpsConf
                            fi
                        fi
                    fi
                fi

                updated=0
                NginxAddCorsHost
                [ "$updated" -eq 1 ] && NginxBuildConf parse_out

                NginxEnableDomain
                Println "$info $server_domain 配置成功\n"
            ;;
        esac
    done
}
NodejsConfig()
{
    echo
    nodejs_options=( '域名' '本地' )
    inquirer list_input "选择使用 nodejs 的对象" nodejs_options nodejs_option

    if [ "$nodejs_option" == "域名" ] 
    then
        NginxListDomain
        NginxSelectDomainServer

        server_name=${nginx_domain_servers_name[nginx_domain_servers_index]}

        if [[ $server_name =~ , ]] 
        then
            IFS="," read -r -a domains <<< "$server_name"

            echo
            inquirer list_input "选择域名: " domains server_name
        fi
    else
        NginxListLocalhost
        NginxSelectLocalhostServer
    fi

    NginxConfigServerLiveRoot

    updated=0

    NginxAddFlv

    NginxAddNodejs

    if [ "$updated" -eq 1 ] 
    then
        NginxBuildConf parse_out
        Println "$info nodejs 配置添加成功"
    fi

    if [ "$nodejs_option" == "域名" ] 
    then
        NginxCheckLocalhost
        NginxAddHttp
    fi

    updated=0

    NginxAddCorsHost

    NginxAddSameSiteNone

    nodejs_port=$(GetFreePort)

    NginxAddUpstreamNodejs

    if [ "$updated" -eq 1 ] 
    then
        NginxBuildConf parse_out
    fi

    username=$(RandStr)
    password=$(RandStr)

    mongosh admin --eval "db.getSiblingDB('admin').createUser({user: '${username}', pwd: '${password}', roles: ['root']})"

    if [[ $(ps --no-headers -o comm 1) == "systemd" ]] 
    then
        systemctl restart mongod
    else
        service mongod restart
    fi

    mkdir -p "$NODE_ROOT"

    cat > "$NODE_ROOT/index.js" <<EOF
const express = require('express');
const session = require('express-session');
const MongoStore = require('connect-mongo');
const mongoose = require('mongoose');
const path = require('path');

const app = express();
const port = $nodejs_port;

const clientP = mongoose.connect(
    'mongodb://$username:$password@127.0.0.1/admin',
    { useNewUrlParser: true, useUnifiedTopology: true }
).then(m => m.connection.getClient())

app.set('trust proxy', 1);
app.use(session({
    name: '$(RandStr)',
    secret: '$(RandStr)',
    resave: false,
    saveUninitialized: false,
    store: MongoStore.create({
        clientPromise: clientP,
        dbName: 'encrypt',
        stringify: false,
        collectionName: 'sessions',
        autoRemove: 'interval',
        autoRemoveInterval: 120
    }),
    cookie: {
        domain: 'localhost',
        maxAge: 60 * 60 * 2000,
        httpOnly: true
    }
}));

app.get('/keys', (req, res) => {
    const { key, channel } = req.query;
    if (!req.session.websiteUser || !key || !channel){
        res.status(400).end();
    } esle {
        res.sendFile(channel + '/' + key + '.key', {root: path.join(__dirname, '../${LIVE_ROOT##*/}')});
    }
});

app.get('/', (req, res) => {
    req.session.websiteUser = true;
    res.sendFile('$server_root/index.html');
});

app.get('/remote', (req, res) => {
    req.session.websiteUser = true;
    res.sendFile('$server_root/channels.json');
});

app.get('/channels', (req, res) => {
    if (!req.session.websiteUser){
        res.status(403).end();
    } else {
        res.sendFile('$server_root/channels.json');
    }
});

app.listen(port, () => console.log(\`App listening on port \${port}!\`))

EOF

    cat > "$NODE_ROOT/package.json" <<EOF
{
  "name": "node",
  "version": "1.0.0",
  "description": "",
  "main": "index.js",
  "scripts": {
    "test": "echo \"Error: no test specified\" && exit 1",
    "start": "node index.js"
  },
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.17.1",
    "express-session": "^1.17.0",
    "mongodb": "^4.1.2",
    "connect-mongo": "^4.6.0",
    "mongoose": "^6.0.8",
    "path": "^0.12.7"
  }
}
EOF

    GitInstall

    cd "$NODE_ROOT"
    npm install
    npm install -g pm2
    pm2 start "$NODE_ROOT/index.js"
    pm2 startup
    Println "$info nodejs 配置完成"
}
NodejsMenu()
{
    [ ! -d "$IPTV_ROOT" ] && Println "$error 请先输入 tv 安装 !\n" && exit 1

    echo
    nodejs_options=( '安装' '升级' '运行 iptv node' )
    inquirer list_input_index "选择操作" nodejs_options nodejs_options_index

    if [ "$nodejs_options_index" -eq 0 ] 
    then
        if [[ -x $(command -v node) ]] && [[ -x $(command -v npm) ]] 
        then
            Println "$error nodejs 已存在\n"
            exit 1
        fi

        NodejsInstall
    elif [ "$nodejs_options_index" -eq 1 ] 
    then
        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]] 
        then
            Println "$error 请先安装 nodejs\n"
            exit 1
        fi

        NodejsInstall
    else
        if [ -f "$NODE_ROOT/index.js" ] 
        then
            Println "$error iptv node 已存在\n"
            exit 1
        fi

        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]] 
        then
            Println "$error 请先安装 nodejs\n"
            exit 1
        fi

        if [[ ! -x $(command -v mongod) ]] 
        then
            Println "$error 请先安装 mongodb\n"
            exit 1
        fi

        NodejsConfig
    fi
}
MongodbMenu()
{
    echo
    mongodb_options=( '查看' '安装' '升级' )
    inquirer list_input_index "选择操作" mongodb_options mongodb_options_index

    if [ "$mongodb_options_index" -eq 0 ] 
    then
        if [[ ! -x $(command -v mongod) ]] 
        then
            Println "$error 请先安装 mongodb\n"
            return 1
        fi

        systemctl --no-pager -l status mongod
    elif [ "$mongodb_options_index" -eq 1 ] 
    then
        if [[ -x $(command -v mongod) ]]
        then
            Println "$error mongodb 已存在\n"
            return 1
        fi

        MongodbInstall
    else
        if [[ ! -x $(command -v mongod) ]] 
        then
            Println "$error 请先安装 mongodb\n"
            return 1
        fi

        echo
        ExitOnList n "升级会清除现有 mongodb 配置, 是否继续"

        service mongod stop

        if [ "$dist" == "rpm" ] 
        then
            yum -y erase mongodb-org*

            rm -f /etc/yum.repos.d/mongodb-org-*.repo
        else
            apt-get -y --purge remove mongodb-org*
            apt-get -y autoremove

            rm -f /etc/apt/sources.list.d/mongodb-org-*.list
        fi

        MongodbInstall
    fi
}
NginxSitesCrtInstall()
{
    local domain=$1

    if [ -e "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt" ] && [ -d "$AIOS_PREFIX"/openresty/nginx/conf ] && [ ! -e "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt" ]
    then
        mkdir -p "$AIOS_PREFIX"/openresty/nginx/conf/sites_crt
        ln "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt" "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt"
        ln "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.key" "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.key"
    elif [ -e "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt" ] && [ -d "$AIOS_PREFIX"/nginx/conf ] && [ ! -e "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt" ] 
    then
        mkdir -p "$AIOS_PREFIX"/nginx/conf/sites_crt
        ln "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt" "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt"
        ln "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.key" "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.key"
    fi

    if [ -e "$nginx_prefix/conf/sites_crt/$domain.crt" ] && [ -e "$nginx_prefix/conf/sites_crt/$domain.key" ]
    then
        echo
        inquirer list_input "检测到证书已存在, 是否重新安装证书" ny_options reinstall_crt_yn
        if [ "$reinstall_crt_yn" == "$i18n_no" ] 
        then
            return 0
        fi
    fi

    AcmeCheck

    Println "$info 安装 $domain 证书..."

    NginxDomainUpdateCrt "$domain" 1

    Println "$info $domain 证书安装成功\n"
}

NginxSitesCrtSelfSignValid()
{
    local domain=$1

    if [ -e "$cert_root/$domain".crt ] && [ -e "$cert_root/$domain".key ]
    then
        return 1
    fi
}

NginxSitesCrtManage()
{
    if [ ! -d "$nginx_prefix"/conf/sites_crt ] 
    then
        Println "$error 请先安装 $nginx_name\n"
        return 1
    fi

    echo
    crt_options=( '浏览证书' '安装自签名证书' '安装ACME证书' )
    inquirer list_input_index "选择操作" crt_options crt_options_index

    case $crt_options_index in
        0) ServiceBrowse "$nginx_prefix"/conf/sites_crt
        ;;
        1) 
            cd "$nginx_prefix"/conf/sites_crt

            if [ ! -f "$nginx_prefix"/conf/sites_crt/openssl.cnf ] 
            then
                if ! curl -Lm 20 -o "$nginx_prefix"/conf/sites_crt/openssl.cnf "$FFMPEG_MIRROR_LINK"/openssl.cnf 
                then
                    Println "$error 下载 openssl.cnf 失败, 请稍后再试\n"
                    return 1
                fi
            fi

            if [ ! -f "$nginx_prefix"/conf/sites_crt/root.crt ] 
            then
                echo
                inquirer text_input "请输入你想设置的根证书公用名CN (Common Name)" root_cn root.yourdomain.com
                openssl req -new -nodes -text -out root.csr -newkey rsa:4096 -keyout root.key -subj "/CN=$root_cn"
                chmod og-rwx root.key
                openssl x509 -req -in root.csr -text -days 3650 -extfile "$nginx_prefix"/conf/sites_crt/openssl.cnf -extensions v3_ca -signkey root.key -out root.crt
                Println "$info "$nginx_prefix"/conf/root.crt 可以添加到用户端系统用来验证之后自签名的证书\n"
            fi

            cert_root="$nginx_prefix"/conf/sites_crt

            mkdir -p newcerts

            echo
            inquirer text_input "请输入自签名证书公用名CN (Common Name)" server_cn localhost NginxSitesCrtSelfSignValid "证书已存在"

            ny_index=0

            if ! [[ "$server_cn" =~ \* ]] 
            then
                echo
                inquirer list_input_index "是否将子域名 *.$server_cn 加到 SAN" ny_options ny_index
            fi

            if [ "$ny_index" -eq 1 ] 
            then
                root_domain="${server_cn#\*.}"
                san="DNS:$root_domain,DNS:*.$root_domain,IP:127.0.0.1,IP:::1"
            else
                san="DNS:$server_cn,IP:127.0.0.1,IP:::1"
            fi

            openssl req -new -nodes -text -out "$cert_root/${server_cn}".csr -newkey rsa:4096 -keyout "$cert_root/${server_cn}".key -subj "/CN=$server_cn" -addext "subjectAltName=$san"

            chmod og-rwx "$cert_root/${server_cn}".key

            if openssl help x509 2>&1 | grep -q "copy_extensions"
            then
                openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$cert_root/${server_cn}".csr -text -days 365 -CA root.crt -CAkey root.key -CAcreateserial -out "$cert_root/${server_cn}".crt)
            else
                openssl_cmds=(openssl ca -batch -config "$nginx_prefix"/conf/sites_crt/openssl.cnf -policy signing_policy -extensions signing_req -out "$cert_root/${server_cn}".crt -infiles "$cert_root/${server_cn}".csr)
            fi

            if [ ! -f ./index.txt ] 
            then
                touch index.txt
            fi

            if [ ! -f ./serial ] 
            then
                echo 01 > serial
            fi

            "${openssl_cmds[@]}"

            openssl x509 -in "$cert_root/${server_cn}".crt -outform PEM -out "$cert_root/${server_cn}".pem

            if [ "$ny_index" -eq 1 ] 
            then
                openssl req -new -nodes -text -out "$cert_root/*.${server_cn}".csr -newkey rsa:4096 -keyout "$cert_root/*.${server_cn}".key -subj "/CN=*.$server_cn" -addext "subjectAltName=$san"
                chmod og-rwx '*'.${server_cn}.key
                if openssl help x509 2>&1 | grep -q "copy_extensions"
                then
                    openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$cert_root/*.${server_cn}".csr -text -days 365 -CA ../root.crt -CAkey ../root.key -CAcreateserial -out "$cert_root/*.${server_cn}".crt)
                else
                    openssl_cmds=(openssl ca -batch -config "$nginx_prefix"/conf/sites_crt/openssl.cnf -policy signing_policy -extensions signing_req -out "$cert_root/*.${server_cn}".crt -infiles "$cert_root/*.${server_cn}".csr)
                fi
                "${openssl_cmds[@]}"
                openssl x509 -in "$cert_root/*.${server_cn}".crt -outform PEM -out "$cert_root/*.${server_cn}".pem
                cat "$cert_root/${server_cn}".pem "$cert_root/*.${server_cn}".pem > "$cert_root/${server_cn}".pem.tmp
                mv "$cert_root/${server_cn}".pem.tmp "$cert_root/${server_cn}".pem
            fi

            Println "$info 自签名证书安装成功\n"
        ;;
        2) NginxConfigDomain
        ;;
    esac

    return 0
}
OpenrestyPackageInstall()
{
    # nc -vz 127.0.0.1 80
    DepInstall lsof
    if lsof -Pi :80 -sTCP:LISTEN -t &>/dev/null
    then
        Println "$error 80 端口被占用, 请先关闭占用端口的程序\n"
        return 1
    fi

    DepInstall curl
    DepInstall ca-certificates

    ArchCheck

    if [ "$arch" == "arm64" ]
    then
        arch_path="/arm64"
    else
        arch_path=""
    fi

    . /etc/os-release

    case $dist in
        ubu)
            local or_codename or_repo_base or_key_url
            or_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/openresty.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    or_repo_base="https://${USTC_MIRROR_HOST}/openresty${arch_path}/ubuntu"
                    or_key_url="https://${USTC_MIRROR_HOST}/openresty/pubkey.gpg"
                else
                    or_repo_base="${OPENRESTY_LINK}/package${arch_path}/ubuntu"
                    or_key_url="${OPENRESTY_LINK}/package/pubkey.gpg"
                fi

                if ! AptRepoCheck "$or_repo_base" "$or_codename"
                then
                    Println "$error OpenResty 官方源暂不支持当前系统 (${or_codename:-unknown}), 未写入失效源\n"
                    return 1
                fi

                DepInstall ubuntu-keyring
                DepInstall gpg
                curl -fsSL "$or_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/openresty.gpg
                echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/openresty.gpg] ${or_repo_base} \
                ${or_codename} main" | tee /etc/apt/sources.list.d/openresty.list
                AptUpdate force
            fi

            AptInstall openresty --no-install-recommends
        ;;
        deb)
            local or_codename or_repo_base or_key_url
            or_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/openresty.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    or_repo_base="https://${USTC_MIRROR_HOST}/openresty${arch_path}/debian"
                    or_key_url="https://${USTC_MIRROR_HOST}/openresty/pubkey.gpg"
                else
                    or_repo_base="${OPENRESTY_LINK}/package${arch_path}/debian"
                    or_key_url="${OPENRESTY_LINK}/package/pubkey.gpg"
                fi

                if ! AptRepoCheck "$or_repo_base" "$or_codename"
                then
                    Println "$error OpenResty 官方源暂不支持当前系统 (${or_codename:-unknown}), 未写入失效源\n"
                    return 1
                fi

                DepInstall debian-archive-keyring
                DepInstall gpg
                curl -fsSL "$or_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/openresty.gpg
                echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/openresty.gpg] ${or_repo_base} \
                ${or_codename} openresty" | sudo tee /etc/apt/sources.list.d/openresty.list
                AptUpdate force
            fi

            AptInstall openresty --no-install-recommends
        ;;
        rpm)
            DepInstall yum-utils

            if [ ! -f /etc/yum.repos.d/openresty.repo ]
            then
                dist_names=( amazon alinux tlinux oracle rocky fedora centos rhel )

                for dist_name in "${dist_names[@]}"
                do
                    if grep -qi "$dist_name" <<< "$ID" || grep -qi "$dist_name" <<< "$NAME"
                    then
                        case $dist_name in
                            amazon|alinux|tlinux|oracle|fedora)
                                curl -s -L https://openresty.org/package/$dist_name/openresty.repo -o /etc/yum.repos.d/openresty.repo
                            ;;
                            rocky|centos|rhel)
                                if [ "${VERSION_ID%%.*}" -gt 8 ]
                                then
                                    curl -s -L https://openresty.org/package/$dist_name/openresty2.repo -o /etc/yum.repos.d/openresty.repo
                                else
                                    curl -s -L https://openresty.org/package/$dist_name/openresty.repo -o /etc/yum.repos.d/openresty.repo
                                fi
                            ;;
                        esac
                        break
                    fi
                done
            fi
            sudo yum check-update
            sudo yum install -y openresty openresty-opm openresty-doc
        ;;
        *)
            Println "$error 不支持的系统\n"
            return 1
        ;;
    esac

    if ! grep -q "$nginx_name:" < "/etc/passwd"
    then
        if grep -q '\--group ' < <(adduser --help)
        then
            adduser "$nginx_name" --system --group --no-create-home > /dev/null
        else
            adduser "$nginx_name" --system --no-create-home > /dev/null
        fi
        usermod -s /usr/sbin/nologin "$nginx_name"
    fi

    sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$info $nginx_name 安装成功\n"
}

OpenrestySourceInstall()
{
    local install="更新"

    if [ -z "${1:-}" ]
    then
        if [[ -x $(command -v $nginx_name) ]]
        then
            return 0
        fi
        install="安装"
    elif [[ ! -x $(command -v $nginx_name) ]]
    then
        install="安装"
    fi

    DepsCheck

    echo
    pcre_options=( pcre pcre2 )
    inquirer list_input_index "选择 pcre 版本" pcre_options pcre_options_index

    Println "$tip 如果选择 openssl, $nginx_name 将不支持 ssl_early_data (0-RTT)"
    openssl_options=( openssl@1.1 quictls )
    inquirer list_input_index "选择 openssl 版本" openssl_options openssl_options_index

    echo
    inquirer list_input_index "额外添加编译选项" ny_options ny_index
    install_options_selected=()
    if [ "$ny_index" -eq 1 ]
    then
        echo
        install_options=( --with-http_iconv_module --with-http_postgres_module --with-http_slice_module )
        inquirer checkbox_input "选择编译选项" install_options install_options_selected
    fi

    if [ "$dist" == "mac" ]
    then
        Println "$tip 如果选择官方编译, $nginx_name 将缺少 nginx-http-flv-module 和 quictls 选择"
        inquirer list_input_index "使用官方编译" yn_options yn_index
        if [ "$yn_index" -eq 0 ]
        then
            brew tap openresty/brew
            brew install openresty ${install_options_selected[@]+"${install_options_selected[@]}"}
            if [ ! -d "$nginx_prefix" ]
            then
                Println "$info 建立目录 $nginx_prefix, 可能需要输入密码\n"
                sudo mkdir -p "$nginx_prefix"/html/localhost/
                sudo chown "$USER" "$nginx_prefix"
                ln -s "$HOMEBREW_PREFIX"/etc/openresty "$nginx_prefix"/conf
                ln -s "$HOMEBREW_PREFIX"/var/log/nginx "$nginx_prefix"/logs
            fi
            return
        fi
        if [ ! -d "$nginx_prefix" ]
        then
            Println "$info 建立目录 $nginx_prefix, 可能需要输入密码\n"
            sudo mkdir "$nginx_prefix"
            sudo chown $USER "$nginx_prefix"
            sudo chown $USER "${nginx_prefix%/*}"
            if [ ! -f /etc/paths.d/openresty ]
            then
                sudo mkdir -p /etc/paths.d
                echo "$HOMEBREW_PREFIX"/openresty/bin | sudo tee /etc/paths.d/openresty
            fi
        fi
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    rm -rf nginx-http-flv-module-master
    curl -L "$FFMPEG_MIRROR_LINK/nginx-http-flv-module.zip" -o nginx-http-flv-module.zip
    Println "$info 解压 nginx-http-flv-module ..."
    unzip nginx-http-flv-module.zip >/dev/null 2>&1

    #cd nginx-http-flv-module-master
    #curl -L "$FFMPEG_MIRROR_LINK/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch" -o Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #patch -p1 < Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #cd "$DEPENDS_ROOT"

    latest_release=0
    while IFS= read -r line
    do
        if [[ $line == *"Lastest release"* ]]
        then
            latest_release=1
        elif [ "$latest_release" -eq 1 ] && [[ $line == *"<a "* ]]
        then
            openresty_package_name=${line#*/download/}
            openresty_package_name=${openresty_package_name%%.tar.gz*}
            break
        fi
    done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://openresty.org/en/download.html 2> /dev/null)

    curl -L "https://openresty.org/download/$openresty_package_name.tar.gz" -o "$openresty_package_name.tar.gz"
    Println "$info 解压 $openresty_package_name ..."
    tar xzf "$openresty_package_name.tar.gz"

    if [ "$dist" == "mac" ]
    then
        SourceInstallReady "${pcre_options[pcre_options_index]}" zlib geoip

        cc_opt="-I$HOMEBREW_PREFIX/opt/geoip/include -I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/include -I$HOMEBREW_PREFIX/opt/zlib/include"
        ld_opt="-L$HOMEBREW_PREFIX/opt/geoip/lib -I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib -L$HOMEBREW_PREFIX/opt/zlib/lib"

        for install_option in "${install_options_selected[@]}"
        do
            if [ "$install_option" == "--with-http_postgres_module" ]
            then
                DepInstall "$POSTGRESQL_MAC_PKG"
                cc_opt="$cc_opt -I$HOMEBREW_PREFIX/opt/$POSTGRESQL_MAC_PKG/include"
                ld_opt="$ld_opt -L$HOMEBREW_PREFIX/opt/$POSTGRESQL_MAC_PKG/lib"
                break
            fi
        done

        if [ "$openssl_options_index" -eq 1 ]
        then
            QuictlsInstall
            cc_opt="$cc_opt -I$DEPENDS_ROOT/quictls/build/include"
            ld_opt="$ld_opt -L$DEPENDS_ROOT/quictls/build/lib"
        else
            DepInstall "$OPENRESTY_OPENSSL_MAC_PKG"
            cc_opt="$cc_opt -I$HOMEBREW_PREFIX/opt/${OPENRESTY_OPENSSL_MAC_PKG##*/}/include"
            ld_opt="$ld_opt -L$HOMEBREW_PREFIX/opt/${OPENRESTY_OPENSSL_MAC_PKG##*/}/lib"
        fi

        cd "$openresty_package_name/bundle/ngx_lua-"*

        curl -L "$FFMPEG_MIRROR_LINK/fix_ngx_lua_resp_get_headers_key_whitespace.patch" -o fix_ngx_lua_resp_get_headers_key_whitespace.patch
        patch -p1 < fix_ngx_lua_resp_get_headers_key_whitespace.patch || true

        cd ../../

        ./configure \
        --add-module=../nginx-http-flv-module-master \
        --with-cc-opt="$cc_opt" \
        --with-ld-opt="$ld_opt" \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_gunzip_module \
        --with-http_geoip_module \
        --with-http_gzip_static_module \
        --with-http_mp4_module \
        --with-http_random_index_module \
        --with-http_realip_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_ssl_module \
        --with-http_stub_status_module \
        --with-http_sub_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --with-http_flv_module \
        --without-mail_pop3_module \
        --without-mail_imap_module \
        --without-mail_smtp_module \
        --with-pcre-jit \
        --without-http_rds_json_module \
        --without-http_rds_csv_module \
        --without-lua_rds_parser \
        --with-stream \
        --with-stream_realip_module \
        --with-stream_ssl_module \
        --with-stream_ssl_preread_module \
        --with-threads \
        --with-luajit-xcflags=-DLUAJIT_NUMMODE=2\ -DLUAJIT_ENABLE_LUA52COMPAT\ -fno-stack-check ${install_options_selected[@]+"${install_options_selected[@]}"}
    else
        if [ "$dist" == "rpm" ]
        then
            SourceInstallReady openssl-devel gcc libpq-devel
        else
            SourceInstallReady perl software-properties-common pkg-config libssl-dev libghc-zlib-dev libcurl4-gnutls-dev libexpat1-dev unzip gettext libpq-dev
        fi

        while IFS= read -r line
        do
            if [[ $line =~ \<A\ HREF=\"(.+)\.tar\.gz ]]
            then
                zlib_name=${BASH_REMATCH[1]}
                break
            fi
        done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://www.zlib.net 2> /dev/null)

        if [ ! -d $zlib_name ]
        then
            curl -L https://www.zlib.net/$zlib_name.tar.gz -o $zlib_name.tar.gz
            Println "$info 解压 $zlib_name ..."
            tar xzf $zlib_name.tar.gz
        fi

        if [ "$pcre_options_index" -eq 0 ]
        then
            pcre_name="pcre-${PCRE_LEGACY_VER}"
            if [ ! -d $pcre_name ]
            then
                curl -L https://downloads.sourceforge.net/pcre/pcre/${pcre_name#*-}/$pcre_name.zip -o $pcre_name.zip
                Println "$info 解压 $pcre_name ..."
                unzip $pcre_name.zip > /dev/null 2>&1
            fi
        else
            pcre_name=$(curl -Lm 20 "$FFMPEG_MIRROR_LINK/pcre2.json" | $JQ_FILE -r '.tag_name')
            if [ ! -d $pcre_name ]
            then
                curl -L $FFMPEG_MIRROR_LINK/pcre2/$pcre_name/$pcre_name.zip -o $pcre_name.zip
                Println "$info 解压 $pcre_name ..."
                unzip $pcre_name.zip > /dev/null 2>&1
            fi
        fi

        local openssl_pack_url=""
        openssl_url="${OPENSSL_SOURCE_LINK}/old/1.1.1"
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "1")

        if [ -z "$openssl_pack_url" ]
        then
            Println "$error 无法从 $openssl_url 获取 OpenSSL 源码包地址\n"
            return 1
        fi

        openssl_pack="${openssl_pack_url##*/}"
        openssl_name="${openssl_pack%.tar*}"

        if [ "$openssl_options_index" -eq 1 ]
        then
            openssl_ver=${openssl_name#*-}
            openssl_name=openssl-OpenSSL_${openssl_ver//./_}-quic1
        fi

        if [ ! -d "${openssl_name}-patched" ] || [ ! -s "${openssl_name}-patched/${OPENRESTY_OPENSSL_PATCH}" ]
        then
            rm -rf "${openssl_name}-patched"

            if [ "$openssl_options_index" -eq 1 ]
            then
                Println "$info 下载 ${openssl_name#*-} ..."
                if ! curl -Lm 30 "${QUICTLS_REPO_LINK}/${openssl_name#*-}.tar.gz" -o "$openssl_name".tar.gz
                then
                    curl -L "$FFMPEG_MIRROR_LINK/${openssl_name#*-}".tar.gz -o "$openssl_name".tar.gz
                fi
                Println "$info 解压 ${openssl_name#*-} ..."
                tar xzf ${openssl_name}.tar.gz
            else
                curl -L "$openssl_pack_url" -o "$openssl_pack"
                Println "$info 解压 $openssl_name ..."
                tar xzf "$openssl_pack"
            fi

            cp -r ${openssl_name} "${openssl_name}-patched"
            cd "${openssl_name}-patched"

            curl -L "$FFMPEG_MIRROR_LINK/${OPENRESTY_OPENSSL_PATCH}" -o "$OPENRESTY_OPENSSL_PATCH"
            patch -p1 < "$OPENRESTY_OPENSSL_PATCH" || true
            cd "$DEPENDS_ROOT"
        fi

        cd "$openresty_package_name/bundle/ngx_lua-"*

        curl -L "$FFMPEG_MIRROR_LINK/fix_ngx_lua_resp_get_headers_key_whitespace.patch" -o fix_ngx_lua_resp_get_headers_key_whitespace.patch
        patch -p1 < fix_ngx_lua_resp_get_headers_key_whitespace.patch || true

        cd ../..

        ./configure \
        --add-module=../nginx-http-flv-module-master \
        --with-pcre=../$pcre_name \
        --with-pcre-jit \
        --with-zlib=../$zlib_name \
        --with-openssl=../${openssl_name}-patched \
        --with-openssl-opt="no-threads shared zlib -g enable-ssl3 enable-ssl3-method enable-ec_nistp_64_gcc_128" \
        --with-http_ssl_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --without-mail_pop3_module \
        --without-mail_imap_module \
        --without-mail_smtp_module \
        --without-http_rds_json_module \
        --without-http_rds_csv_module \
        --without-lua_rds_parser \
        --with-http_stub_status_module \
        --with-http_realip_module \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_random_index_module \
        --with-http_gzip_static_module \
        --with-http_sub_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_flv_module \
        --with-http_mp4_module \
        --with-http_gunzip_module \
        --with-stream \
        --with-stream_ssl_preread_module \
        --with-stream_ssl_module \
        --with-stream_realip_module \
        --with-threads \
        --with-luajit-xcflags=-DLUAJIT_NUMMODE=2\ -DLUAJIT_ENABLE_LUA52COMPAT\ -fno-stack-check ${install_options_selected[@]+"${install_options_selected[@]}"}
    fi

    nproc="-j$(nproc 2> /dev/null)" || nproc="-j1"

    make $nproc
    make install

    ln -sf "$nginx_prefix"/sbin/nginx "$AIOS_PREFIX"/bin/

    if [ "$dist" != "mac" ]
    then
        if ! grep -q "$nginx_name:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser "$nginx_name" --system --group --no-create-home > /dev/null
            else
                adduser "$nginx_name" --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin "$nginx_name"
        fi

        sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    fi

    sed -i "s/worker_processes .*/worker_processes  ${nproc:2};/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$info $nginx_name ${install}成功\n"
}

OpenrestyInstall()
{
    if [ -d "$nginx_prefix" ]
    then
        Println "$error $nginx_name 已经存在 $nginx_prefix !\n"
        return 1
    elif [[ -x $(command -v $nginx_name) ]]
    then
        Println "$error $nginx_name 已经存在 $(command -v $nginx_name), 请先卸载!\n"
        return 1
    fi

    if [ "$dist" != "mac" ]
    then
        Println "$tip 选择快速安装将缺少 nginx-http-flv-module 和 quictls 选择"
        openresty_install_options=( "${nginx_name}官方包 (快速安装)" '编译安装' )
        inquirer list_input_index "选择安装方式" openresty_install_options openresty_install_options_index

        if [ "$openresty_install_options_index" -eq 0 ]
        then
            OpenrestyPackageInstall
            return
        fi
    fi

    OpenrestySourceInstall
}

OpenrestyUninstall()
{
    if [ ! -d "$nginx_prefix" ]
    then
        Println "$error $nginx_name 未安装 !\n"
        return 1
    fi

    echo
    ExitOnList n "`eval_gettext \"确定删除 \\\$nginx_name 包括所有配置文件, 操作不可恢复\"`"

    ServiceControl disable "$nginx_name"

    case $dist in
        mac)
            if brew list "$nginx_name" &>/dev/null
            then
                brew uninstall "$nginx_name"
            fi
        ;;
        rpm)
            if rpm -q "$nginx_name" &> /dev/null
            then
                yum remove -y "$nginx_name"* || true
            fi
        ;;
        *)
            if dpkg -s "$nginx_name" &> /dev/null
            then
                apt-get -y --purge remove "$nginx_name"* || true
            fi
        ;;
    esac

    rm -rf "${nginx_prefix%/*}"

    Println "$info $nginx_name 卸载完成\n"
}

OpenrestyUpdate()
{
    ShFileUpdate "$nginx_name"

    if [ ! -d "$nginx_prefix" ]
    then
        Println "$error $nginx_name 未安装 !\n"
        return 1
    fi

    if [ "$dist" == "rpm" ] && rpm -q "$nginx_name" &> /dev/null
    then
        yum update -y "$nginx_name"
    elif { [ "$dist" == "deb" ] || [ "$dist" == "ubu" ]; } && dpkg -s "$nginx_name" &> /dev/null
    then
        apt-get -y install --only-upgrade "$nginx_name"
    else
        OpenrestySourceInstall update
    fi
}
VimConfig()
{
    DepInstall vim

    if [ -e ~/.vimrc ] 
    then
        echo
        ExitOnList n "`gettext \"将安装 vim-plug 并覆盖 ~/.vimrc , 是否继续\"`"
    fi

    if curl -s -fLo ~/.vim/autoload/plug.vim --create-dirs "$FFMPEG_MIRROR_LINK/vim-plug.vim"
    then
cat > "$HOME"/.vimrc <<EOF
call plug#begin('~/.vim/plugged')
Plug 'preservim/nerdcommenter'
Plug 'ryanpcmcquen/fix-vim-pasting'
call plug#end()

set number
set mouse=a
set tabstop=2
set shiftwidth=2
set expandtab

autocmd BufRead,BufNewFile *.conf setfiletype conf
filetype indent off
EOF
        GitInstall
        Println "$info vimrc 设置完成, 请在 vim 下执行 PlugInstall\n"
    else
        Println "$error 无法连接服务器, 请稍后再试\n"
    fi
}
AptSetSources()
{
    echo
    apt_sources_options=( '国内' '国外' )
    inquirer list_input_index "选择源" apt_sources_options apt_sources_options_index
    if [ "$apt_sources_options_index" -eq 0 ]
    then
        sed -i "s/deb.debian.org/${USTC_MIRROR_HOST}/g" /etc/apt/sources.list
        sed -i "s/ftp.debian.org/${USTC_MIRROR_HOST}/g" /etc/apt/sources.list
        sed -i "s|security.debian.org|${USTC_MIRROR_HOST}/debian-security|g" /etc/apt/sources.list
        if [ -f "/etc/apt/sources.list.d/armbian.list" ]
        then
            sed -i "s|http[s]*://apt.armbian.com|http://${USTC_MIRROR_HOST}/armbian|g" /etc/apt/sources.list.d/armbian.list
            sed -i "s|http://mirrors.nju.edu.cn/armbian|http://${USTC_MIRROR_HOST}/armbian|g" /etc/apt/sources.list.d/armbian.list
        fi
        if [ -f "/etc/apt/sources.list.d/docker.list" ] 
        then
            DepInstall gpg
            curl -fsSL "http://${USTC_MIRROR_HOST}/docker-ce/linux/debian/gpg" | gpg --batch --yes --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg
            echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] http://${USTC_MIRROR_HOST}/docker-ce/linux/debian \
            $(AptGetCodename) stable" | tee /etc/apt/sources.list.d/docker.list > /dev/null
        fi
    else
        sed -i "s/${USTC_MIRROR_HOST}/deb.debian.org/g" /etc/apt/sources.list
        sed -i "s|${USTC_MIRROR_HOST}/debian-security|security.debian.org|g" /etc/apt/sources.list
        if [ -f "/etc/apt/sources.list.d/armbian.list" ]
        then
            sed -i 's|http://mirrors.nju.edu.cn/armbian|http://apt.armbian.com|g' /etc/apt/sources.list.d/armbian.list
            sed -i "s|http://${USTC_MIRROR_HOST}/armbian|http://apt.armbian.com|g" /etc/apt/sources.list.d/armbian.list
            sed -i 's/https:/http:/g' /etc/apt/sources.list.d/armbian.list
        fi
        if [ -f "/etc/apt/sources.list.d/docker.list" ] 
        then
            DepInstall gpg
            curl -fsSL "${DOCKER_REPO_LINK}/debian/gpg" | gpg --batch --yes --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg
            echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] ${DOCKER_REPO_LINK}/debian \
            $(AptGetCodename) stable" | tee /etc/apt/sources.list.d/docker.list > /dev/null
        fi
    fi
    Println "$info 源更改成功\n"
}
CloudflareDisableWorkersMonitor()
{
    # deprecated
    if [ -s "/tmp/cf_workers.pid" ]
    then
        cf_workers_pid=$(< /tmp/cf_workers.pid)

        if kill -0 "$cf_workers_pid" 2> /dev/null
        then
            kill "$cf_workers_pid" 2> /dev/null
            [ ! -d "${MONITOR_LOG%/*}" ] && MONITOR_LOG="$HOME/monitor.log"
            MonitorLog "关闭 workers 监控 PID $cf_workers_pid !"
            Println "$info workers 监控 关闭成功\n"
        else
            Println "$error workers 监控 未开启\n"
        fi
    elif [ -s "$CF_WORKERS_ROOT/cf_workers.pid" ]
    then
        PID=$(< "$CF_WORKERS_ROOT/cf_workers.pid")

        if kill -0 "$PID" 2> /dev/null
        then
            Println "$info 关闭 workers 监控, 稍等..."
            kill "$PID" 2> /dev/null

            if flock -E 1 -w 20 -x "$CF_WORKERS_ROOT/cf_workers.pid" rm -f "$CF_WORKERS_ROOT/cf_workers.pid"
            then
                MonitorLog "关闭 workers 监控 PID $PID !"
                Println "$info workers 监控 关闭成功 !\n"
            else
                Println "$error workers 监控 关闭超时, 请重试\n"
                exit 1
            fi
        else
            rm -f "$CF_WORKERS_ROOT/cf_workers.pid"
            Println "$error workers 监控 未开启\n"
        fi
    else
        [ -e "$CF_WORKERS_ROOT/cf_workers.pid" ] && rm -f "$CF_WORKERS_ROOT/cf_workers.pid"
        Println "$error workers 监控 未开启\n"
    fi
}
XtreamCodesGetDomains()
{
    [ -n "${xtream_codes_domains:-}" ] && return 0

    if [ ! -s "$XTREAM_CODES" ] 
    then
        ShFallback
        curl -s -L "$SH_FALLBACK/$XTREAM_CODES_CHANNELS" -o "$XTREAM_CODES"
    fi

    IFS="," read -ra xtream_codes_domains <<< $(awk -v ORS=, '$1 { gsub(/\|/, ",", $2); print $2 }' "$XTREAM_CODES")
}
XtreamCodesGetChnls()
{
    xc_chnls=()
    xc_chnls_mac=()
    if [ -n "${xtream_codes_domains:-}" ] 
    then
        GetChannels
        if [ "$chnls_count" -gt 0 ] 
        then
            for((xc_i=0;xc_i<chnls_count;xc_i++));
            do
                if { [ "${chnls_status[xc_i]}" == "on" ] && [ "${chnls_output_dir_name[xc_i]}" != "${chnl_output_dir_name:-}" ]; } || { [ "${chnls_flv_status[xc_i]}" == "on" ] && [ "${chnls_flv_push_link[xc_i]}" != "${chnl_flv_push_link:-}" ]; } 
                then
                    if [[ ${chnls_stream_link[xc_i]##*|} =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                    then
                        f_domain=${chnls_stream_link[xc_i]%%|*}
                        for xc_domain in "${xtream_codes_domains[@]}"
                        do
                            if [ "$f_domain" == "$xc_domain" ] 
                            then
                                xc_chnls_mac+=("$f_domain/${BASH_REMATCH[0]}")
                                break
                            fi
                        done
                    elif [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/([^/]+)/([^/]+)/ ]]
                    then
                        if [ "${BASH_REMATCH[2]}" != "live" ] || [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/live/([^/]+)/([^/]+)/ ]]
                        then
                            f_domain=${BASH_REMATCH[1]}
                            for xc_domain in "${xtream_codes_domains[@]}"
                            do
                                if [ "$f_domain" == "$xc_domain" ] 
                                then
                                    xc_chnls+=("$f_domain/${BASH_REMATCH[2]}:${BASH_REMATCH[3]}")
                                    break
                                fi
                            done
                        fi
                    fi
                fi
            done
        fi
    fi
}
XtreamCodesAddAccount()
{
    echo && read -p "请输入账号(需包含服务器地址): " xtream_codes_input
    [ -z "$xtream_codes_input" ] && Println "$i18n_canceled...\n" && exit 1

    if [[ $xtream_codes_input == *"username="* ]] 
    then
        domain=${xtream_codes_input#*http://}
        domain=${domain%%/*}
        username=${xtream_codes_input#*username=}
        username=${username%%&*}
        password=${xtream_codes_input#*password=}
        password=${password%%&*}
        ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
    elif [[ $xtream_codes_input =~ ^http://([^/]+)/([^/]+)/([^/]+)/ ]] 
    then
        if [ "${BASH_REMATCH[2]}" == "live" ] 
        then
            if [[ $line =~ ^http://([^/]+)/live/([^/]+)/([^/]+)/ ]] 
            then
                domain=${BASH_REMATCH[1]}
                username=${BASH_REMATCH[2]}
                password=${BASH_REMATCH[3]}
            else
                Println "$error 输入错误\n" && exit 1
            fi
        else
            domain=${BASH_REMATCH[1]}
            username=${BASH_REMATCH[2]}
            password=${BASH_REMATCH[3]}
        fi
        ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
    else
        Println "$error 输入错误\n" && exit 1
    fi

    [ -z "${ip:-}" ] && Println "$error 无法解析域名 !\n" && exit 1
    printf '%s\n' "$ip $domain $username:$password" >> "$XTREAM_CODES_EXAM"

    Println "$info 账号添加成功 !\n"
}
VerifyXtreamCodesMac()
{
    to_continue=0

    if [ "${test_mac_domain:-}" != "$domain" ] 
    then
        test_mac_domain=$domain

        if [ "${skip_ip_check:-0}" -eq 0 ] 
        then
            ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
        fi

        if [ "$verify_mac" -eq 0 ] 
        then
            return 0
        fi

        Println "$info 验证 $domain ..."

        server="http://$domain"
        token_url="$server/portal.php?type=stb&action=handshake&token=&prehash=0&JsHttpRequest=1-xml"
        profile_url="$server/portal.php?type=stb&action=get_profile"
        account_info_url="$server/portal.php?type=account_info&action=get_main_info"
        [ -z "${timezone:-}" ] && timezone=$(UrlencodeUpper "Europe/Amsterdam")
    fi

    if [ -z "$ip" ] 
    then
        to_continue=1
        return 0
    fi

    if [ "$verify_mac" -eq 0 ] 
    then
        return 0
    fi

    mac_address="$account"
    access_token=""
    profile=""
    exp_date=""
    mac=$(UrlencodeUpper "$mac_address")

    access_token=$(CurlFake xtream_codes -s -Lm 10 \
        -H "User-Agent: $USER_AGENT_TV" \
        --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$token_url" \
        | $JQ_FILE -r '.js.token' 2> /dev/null) || true

    if [ -z "$access_token" ] 
    then
        Println "$error $domain $mac_address"
        to_continue=1
        return 0
    fi

    profile=$(CurlFake xtream_codes -s -Lm 10 \
        -H "User-Agent: $USER_AGENT_TV" \
        -H "Authorization: Bearer $access_token" \
        --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$profile_url" | $JQ_FILE -r '.js.id // ""' 2> /dev/null) || true

    exp_date=$(CurlFake xtream_codes -s -Lm 10 \
        -H "User-Agent: $USER_AGENT_TV" \
        -H "Authorization: Bearer $access_token" \
        --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$account_info_url" | $JQ_FILE -r '.js.phone' 2> /dev/null) || true

    if [ -z "$exp_date" ] 
    then
        if [ -z "$profile" ] 
        then
            Println "$error $domain $mac_address profile"
        else
            Println "$error $domain $mac_address exp_date"
        fi
        to_continue=1
        return 0
    fi

    account="$mac_address"
}
XtreamCodesList()
{
    if [ -s "$XTREAM_CODES_EXAM" ] && [ ! -f "$XTREAM_CODES" ]
    then
        printf '%s' "" > "$XTREAM_CODES"
    elif [ ! -s "$XTREAM_CODES" ] 
    then
        Println "$error 没有账号 !\n"
        exit 1
    fi

    ips=()
    new_domains=()
    new_accounts=()
    verify_mac=${verify_mac:-0}

    if [ "$verify_mac" -eq 0 ] 
    then
        IFS=" " read -r m_ip m_domains m_accounts < <(awk '$1 {a=a $1",";b=b $2",";$1=$2="";c=c substr($0,3)","} END {print a,b,c}' "$XTREAM_CODES")
        IFS="," read -r -a ips <<< "$m_ip"
        IFS="," read -r -a new_domains <<< "$m_domains"
        IFS="," read -r -a new_accounts <<< "$m_accounts"
    fi

    if [ -s "$XTREAM_CODES_EXAM" ] 
    then
        while IFS= read -r line 
        do
            if [[ $line =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3} ]] 
            then
                if [[ $line =~ ([^ ]+)\ ([^ ]+)\ ([^ ]+) ]] 
                then
                    skip_ip_check=1
                    ip=${BASH_REMATCH[1]}
                    domain=${BASH_REMATCH[2]}
                    account=${BASH_REMATCH[3]}

                    if [[ $account =~ (([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})) ]] 
                    then
                        VerifyXtreamCodesMac 2> /dev/null
                        if [ "$to_continue" -eq 1 ] 
                        then
                            skip_ip_check=0
                            continue
                        fi
                    fi

                    skip_ip_check=0
                else
                    continue
                fi
            elif [[ $line == *"username="* ]] 
            then
                domain=${line#*http://}
                if [ "${test_mac_domain:-}" != "$domain" ] 
                then
                    test_mac_domain=$domain
                    ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
                fi
                [ -z "$ip" ] && continue
                domain=${domain%%/*}
                username=${line#*username=}
                username=${username%%&*}
                password=${line#*password=}
                password=${password%%&*}
                account="$username:$password"
            elif [[ $line =~ http://([^/]+)/([^/]+)/([^/]+)/ ]] 
            then
                if [ "${BASH_REMATCH[2]}" == "live" ] 
                then
                    if ! [[ $line =~ http://([^/]+)/live/([^/]+)/([^/]+)/ ]] 
                    then
                        continue
                    fi
                fi

                domain=${BASH_REMATCH[1]}
                if [ "${test_mac_domain:-}" != "$domain" ] 
                then
                    test_mac_domain=$domain
                    ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
                fi
                [ -z "$ip" ] && continue
                username=${BASH_REMATCH[2]}
                password=${BASH_REMATCH[3]}
                account="$username:$password"
            elif [[ $line =~ http://([^/]+)/ ]] 
            then
                stb_domain=${BASH_REMATCH[1]}

                if [[ ! $line =~ (([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})) ]] 
                then
                    continue
                fi

                domain="$stb_domain"
                account=${BASH_REMATCH[1]}

                VerifyXtreamCodesMac 2> /dev/null

                if [ "$to_continue" -eq 1 ] 
                then
                    continue
                fi
            elif [ -n "${stb_domain:-}" ] && [[ $line =~ (([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})) ]] 
            then
                domain="$stb_domain"
                account=${BASH_REMATCH[1]}

                VerifyXtreamCodesMac 2> /dev/null

                if [ "$to_continue" -eq 1 ] 
                then
                    continue
                fi
            else
                continue
            fi

            for((i=0;i<${#ips[@]};i++));
            do
                if [[ ${ips[i]} == *"$ip"* ]] 
                then
                    if ! [[ ${new_domains[i]} == *"$domain"* ]] 
                    then
                        new_domains[i]="${new_domains[i]}|$domain"
                    fi

                    if ! [[ ${new_accounts[i]} == *"$account"* ]] 
                    then
                        new_accounts[i]="${new_accounts[i]} $account"
                    fi
                    continue 2
                fi
            done

            for((i=0;i<${#new_domains[@]};i++));
            do
                if [[ ${new_domains[i]} == *"$domain"* ]] 
                then
                    if ! [[ ${ips[i]} == *"$ip"* ]] 
                    then
                        ips[i]="${ips[i]}|$ip"
                    fi

                    if ! [[ ${new_accounts[i]} == *"$account"* ]] 
                    then
                        new_accounts[i]="${new_accounts[i]} $account"
                    fi
                    continue 2
                fi
            done

            ips+=("$ip")
            new_domains+=("$domain")
            new_accounts+=("$account")
        done < <(awk '$1=$1' "$XTREAM_CODES_EXAM")
    fi

    if [ -n "${ips:-}" ] 
    then
        ips_count=${#ips[@]}
        print_list=""
        xtream_codes_list=""
        ips_acc_count=0
        ips_acc=()
        ips_mac_count=0
        ips_mac=()

        for((i=0;i<ips_count;i++));
        do
            print_list="$print_list${ips[i]} ${new_domains[i]} ${new_accounts[i]}\n"
            IFS=" " read -ra accounts <<< "${new_accounts[i]}"
            accounts_list=""
            macs_num=0
            accs_num=0
            for account in "${accounts[@]}"
            do
                if [ "${1:-}" == "mac" ] 
                then
                    if [[ $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                    then
                        macs_num=$((macs_num+1))
                        accounts_list="$accounts_list${account}\n"
                    fi
                elif [[ ! $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                then
                    accs_num=$((accs_num+1))
                    accounts_list="$accounts_list${account%:*}${indent_20}${account#*:}\n"
                fi
            done
            if [ -n "$accounts_list" ] 
            then
                if [ "${1:-}" == "mac" ] 
                then
                    ips_mac+=("$i")
                    ips_mac_count=$((ips_mac_count+1))
                    xtream_codes_list="$xtream_codes_list ${green}$ips_mac_count.${normal} IP: ${green}${ips[i]//|/, }${normal} 域名: ${green}${new_domains[i]//|/, }${normal} mac 地址个数: ${green}$macs_num${normal}\n\n"
                else
                    ips_acc+=("$i")
                    ips_acc_count=$((ips_acc_count+1))
                    xtream_codes_list="$xtream_codes_list ${green}$ips_acc_count.${normal} IP: ${green}${ips[i]//|/, }${normal} 域名: ${green}${new_domains[i]//|/, }${normal} 账号个数: ${green}$accs_num${normal}\n\n"
                fi
            fi
        done

        if [ -s "$XTREAM_CODES_EXAM" ] 
        then
            printf '%b' "$print_list" > "$XTREAM_CODES"
            printf '%s' "" > "$XTREAM_CODES_EXAM"
        fi

        if [ "${1:-}" == "mac" ] && [ "$ips_mac_count" -eq 0 ]
        then
            Println "$error 请先添加 mac 地址!\n" && exit 1
        else
            Println "$xtream_codes_list"
        fi
    else
        Println "$error 没有账号!\n" && exit 1
    fi
}
XtreamCodesListAcc()
{
    XtreamCodesList

    Println "请输入服务器的序号"
    while read -p "$i18n_default_cancel" server_num
    do
        case $server_num in
            "") Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*) Println "$error $i18n_input_correct_number\n"
            ;;
            *) 
                if [ "$server_num" -gt 0 ] && [ "$server_num" -le "$ips_acc_count" ]
                then
                    ips_index=${ips_acc[server_num-1]}
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done

    domain=${new_domains[ips_index]}

    if [[ $domain == *"|"* ]] 
    then
        IFS="|" read -ra domains <<< "$domain"
        domains_list=""
        domains_count=${#domains[@]}
        for((i=0;i<domains_count;i++));
        do
            domains_list="$domains_list ${green}$((i+1)).${normal}${indent_6}${domains[i]}\n\n"
        done
        Println "$domains_list"

        Println "请选择域名"
        while read -p "$i18n_default_cancel" domains_num
        do
            case $domains_num in
                "") Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                ;;
                *) 
                    if [ "$domains_num" -gt 0 ] && [ "$domains_num" -le "$domains_count" ]
                    then
                        domain=${domains[domains_num-1]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    fi

    account=${new_accounts[ips_index]}
    IFS=" " read -ra accounts <<< "$account"

    accs=()
    for account in "${accounts[@]}"
    do
        if [[ ! $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
        then
            accs+=("$account")
        fi
    done

    XtreamCodesGetDomains
    XtreamCodesGetChnls

    accs_count=${#accs[@]}
    if [ "$accs_count" -gt 1 ] 
    then
        accs_list="账号: \n\n"
        for((i=0;i<accs_count;i++));
        do
            using=""
            for xc_chnl in ${xc_chnls[@]+"${xc_chnls[@]}"}
            do
                if [ "$xc_chnl" == "$domain/${accs[i]}" ] 
                then
                    using="${red}[使用中]${normal}"
                    break
                fi
            done
            accs_list="$accs_list ${green}$((i+1)).${normal}${indent_6}${accs[i]%:*}${indent_20}${accs[i]#*:} $using\n\n"
        done
        Println "$accs_list"
    else
        using=""
        for xc_chnl in ${xc_chnls[@]+"${xc_chnls[@]}"}
        do
            if [ "$xc_chnl" == "$domain/${accs[i]}" ] 
            then
                using="${red}[使用中]${normal}"
                break
            fi
        done
        Println "账号: \n\n${green}1.${normal} ${accs[0]%:*}${indent_20}${accs[0]#*:} $using\n"
    fi
}
XtreamCodesTestAcc()
{
    XtreamCodesList

    Println "请输入服务器的序号"
    while read -p "$i18n_default_cancel" server_num
    do
        case $server_num in
            "") Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*) Println "$error $i18n_input_correct_number\n"
            ;;
            *) 
                if [ "$server_num" -gt 0 ] && [ "$server_num" -le "$ips_acc_count" ]
                then
                    ips_index=${ips_acc[server_num-1]}
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done

    Println "请输入测试的频道ID"
    while read -p "$i18n_default_cancel" channel_id
    do
        case $channel_id in
            "") Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*) Println "$error $i18n_input_correct_number\n"
            ;;
            *) 
                if [ "$channel_id" -gt 0 ]
                then
                    break
                else
                    Println "$error 请输入正确的频道ID(大于0)\n"
                fi
            ;;
        esac
    done

    chnls=()

    Println "比如 http://username:passsword@127.0.0.1:5555"
    inquirer text_input "输入 FFmpeg 代理: " proxy "$i18n_blank"

    if [ -z "$proxy" ] 
    then
        proxy_command=""
    else
        proxy_command="-http_proxy $proxy"
        Println "代理服务器如果有正在使用的账号需要排除, 输入代理服务器的 channels.json 链接或本地路径"
        read -p "(默认: 无): " proxy_channels_json
        if [ -n "$proxy_channels_json" ] 
        then
            if [ "${proxy_channels_json:0:1}" == "/" ] 
            then
                proxy_channels=$(< "$proxy_channels_json")
            else
                proxy_channels=$(curl -s -Lm 10 "$proxy_channels_json")
            fi
            while IFS= read -r line 
            do
                if [[ $line == *\"status\":* ]] 
                then
                    line=${line#*: \"}
                    status=${line%\",*}
                elif [[ $line == *\"stream_link\":* ]] && [[ $line == *http://*/*/*/* ]]
                then
                    line=${line#*: \"http://}
                    chnl_domain=${line%%/*}
                    line=${line#*/}
                    chnl_username=${line%%/*}
                    if [ "$chnl_username" == "live" ] 
                    then
                        line=${line#*/}
                        chnl_username=${line%%/*}
                    fi
                    line=${line#*/}
                    chnl_password=${line%%/*}
                elif [[ $line == *\"flv_status\":* ]] 
                then
                    line=${line#*: \"}
                    flv_status=${line%\",*}
                    if [ -n "${chnl_domain:-}" ] 
                    then
                        if [ "$status" == "on" ] || [ "$flv_status" == "on" ]
                        then
                            chnls+=("$chnl_domain/$chnl_username/$chnl_password")
                        fi
                    fi
                    chnl_domain=""
                fi
            done <<< "$proxy_channels"
        fi
    fi

    if [ -e "$CHANNELS_FILE" ] 
    then
        GetChannels
        if [ "$chnls_count" -gt 0 ] 
        then
            for((xc_i=0;xc_i<chnls_count;xc_i++));
            do
                if [ "${chnls_status[xc_i]}" == "on" ] || [ "${chnls_flv_status[xc_i]}" == "on" ]
                then
                    if [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/([^/]+)/([^/]+)/ ]]
                    then
                        if [ "${BASH_REMATCH[2]}" != "live" ] || [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/live/([^/]+)/([^/]+)/ ]]
                        then
                            chnls+=("${BASH_REMATCH[1]}/${BASH_REMATCH[2]}:${BASH_REMATCH[3]}")
                        fi
                    fi
                fi
            done
        fi
    fi

    IFS="|" read -ra domains <<< "${new_domains[ips_index]}"
    IFS=" " read -ra accounts <<< "${new_accounts[ips_index]}"
    Println "IP: ${green}${ips[ips_index]}${normal} 域名: ${green}${new_domains[ips_index]//|/ }${normal}"
    Println "${green}账号:${normal}"

    FFmpegInstall

    for account in "${accounts[@]}"
    do
        if [[ $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
        then
            continue
        fi
        username=${account%%:*}
        account=${account#*:}
        password=${account%%:*}

        for domain in "${domains[@]}"
        do
            for chnl in ${chnls[@]+"${chnls[@]}"}
            do
                if [ "$domain/$username/$password" == "$chnl" ] 
                then
                    # https://f-hauri.ch/vrac/diffU8test.sh
                    printf "${green}%s${normal}\r\033[12C%-21s%-21s\n" "[使用中]" "$username" "$password"
                    continue 2
                fi
            done

            # curl --output /dev/null -m 3 -s --fail -r 0-0
            if $FFPROBE_FILE $proxy_command -rw_timeout 5000000 -i "http://$domain/$username/$password/$channel_id" -show_streams -select_streams a -loglevel quiet > /dev/null
            then
                printf "${green}%s${normal}\r\033[12C%-21s%-21s${green}%s${normal}\n%s\n\n" "[成功]" "$username" "$password" "$domain" "http://$domain/$username/$password/$channel_id"
            elif $FFPROBE_FILE $proxy_command -rw_timeout 5000000 -i "http://$domain/live/$username/$password/$channel_id.ts" -show_streams -select_streams a -loglevel quiet > /dev/null
            then
                printf "${green}%s${normal}\r\033[12C%-21s%-21s${green}%s${normal}\n%s\n\n" "[成功]" "$username" "$password" "$domain" "http://$domain/live/$username/$password/$channel_id.ts"
            else
                printf "${red}%s${normal}\r\033[12C%-21s%-21s${red}%s${normal}\n%s" "[失败]" "$username" "$password" "$domain"
            fi
        done
    done
    echo
}
