        if ! curl -L $FFMPEG_MIRROR_LINK/yt-dlp -o /usr/local/bin/yt-dlp_tmp || [ ! -s /usr/local/bin/yt-dlp_tmp ]
        then
            rm -f /usr/local/bin/yt-dlp_tmp

