    SetSegLength()
    {
        while true 
        do
            echo
            inquirer text_input "请输入分片时长(单位: s): " seg_length "$d_seg_length"
            case "$seg_length" in
                "")
                    seg_length="$d_seg_length"
                    break
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_number [>0]"
                ;;
                *)
                    if [ "$seg_length" -ge 1 ]
                    then
                        break
                    else
                        Println "$error $i18n_input_correct_number [>0]"
                    fi
                ;;
            esac
        done
    }

