                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"hls_change"]'
                JQ update "$CHANNELS_FILE" "$schedule_hls_change"

                jq_bool=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"hls_change_once"]'
