    ScheduleMenu()
    {
        echo
        chnls_schedule_options=( '查看' '添加' '修改' '排序' '删除' )
        inquirer list_input_index "请选择" chnls_schedule_options chnls_schedule_options_index

        if [ "$chnls_schedule_options_index" -eq 0 ] 
