                                do
                                    if [ "${chnl_schedules_status[chnl_schedules_index]}" -eq 0 ] || [ "${chnl_schedules_status[chnl_schedules_index]}" -eq 1 ]
                                    then
                                        if [ "${chnl_schedules_end_time[chnl_schedules_index]}" -le "$now" ] 
                                        then
