                                                jq_path='["channels"]'
                                                jq_path2='["schedule",'"$chnl_schedules_index"']'
                                                JQ update "$CHANNELS_FILE" output_dir_name "$output_dir_name" "$update"
                                            elif [ "${chnl_schedules_auto_remove[chnl_schedules_index]}" = true ] 
