                                                    then
                                                        hls_indices+=("$i")
                                                        hls_change[i]="${chnl_schedules_hls_change[chnl_schedules_index]}"
                                                        if [ "${chnl_schedules_hls_change_once[chnl_schedules_index]}" = true ] 
                                                        then
                                                            hls_change_once[i]=true
                                                        else
                                                            if [ "${hls_changed[i]:-false}" = true ] 
                                                            then
                                                                hls_changed[i]=false
