    # -reconnect_on_network_error 1 -reconnect_on_http_error 4xx,5xx -timeout 2000000000 

    Install()
    {
        if [ -e "$IPTV_ROOT" ]
        then
            Println "`eval_gettext \"\\\$error 目录已存在, 请先卸载...\"`\n" && exit 1
        else
            DepsCheck

            #if grep -q '\--show-progress' < <(wget --help)
            #then
            #    _PROGRESS_OPT="--show-progress"
            #else
            #    _PROGRESS_OPT=""
            #fi

            sudo mkdir -p "$IPTV_ROOT"
            sudo chown $USER "$IPTV_ROOT"

            FFmpegInstall
            JQInstall
            CurlImpersonateInstall

            if [ -s "$CHANNELS_FILE" ] && [ ! -s "$IPTV_CONFIG" ] && $JQ_FILE -e '(.default | type) == "object"' "$CHANNELS_FILE" > /dev/null 2>&1
            then
                local tmp_cfg
                tmp_cfg=$(mktemp "${TMPDIR:-/tmp}/aios-cfg.XXXXXX")
                if $JQ_FILE --arg version "$sh_ver" '.default | .ffmpeg_bin = (.ffmpeg_bin // "") | .version = (.version // $version) | .schema_version = (.schema_version // 3)' "$CHANNELS_FILE" > "$tmp_cfg" && [ -s "$tmp_cfg" ] && $JQ_FILE empty "$tmp_cfg" > /dev/null 2>&1
                then
                    chmod +r "$tmp_cfg"
                    mv "$tmp_cfg" "$IPTV_CONFIG"
                    JQ mutate "$CHANNELS_FILE" 'del(.default)'
                else
                    rm -f "$tmp_cfg"
                fi
            fi

            if [ ! -s "$IPTV_CONFIG" ]
            then
                local tmp_cfg
                tmp_cfg=$(mktemp "${TMPDIR:-/tmp}/aios-cfg.XXXXXX")
                $JQ_FILE -n \
                    --arg proxy '' \
                    --arg xc_proxy '' \
                    --arg user_agent "$USER_AGENT_TV" \
                    --arg headers '' \
                    --arg cookies 'stb_lang=en; timezone=Europe/Amsterdam' \
                    --arg playlist_name '' \
                    --arg seg_dir_name '' \
                    --arg seg_name '' \
                    --arg seg_length 6 \
                    --arg seg_count 5 \
                    --arg video_codec "libx264" \
                    --arg audio_codec "aac" \
                    --arg video_audio_shift '' \
                    --arg draw_text '' \
                    --arg quality '' \
                    --arg bitrate "900" \
                    --arg resolution "1280x720" \
                    --arg const "false" \
                    --arg const_cbr "false" \
                    --arg encrypt "false" \
                    --arg encrypt_session "false" \
                    --arg keyinfo_name '' \
                    --arg key_name '' \
                    --arg input_flags "-copy_unknown -reconnect 1 -reconnect_at_eof 1 -reconnect_streamed 1 -reconnect_delay_max 2000 -rw_timeout 10000000 -y -nostats -nostdin -hide_banner -loglevel error" \
                    --arg output_flags "-g 60 -sc_threshold 0 -sn -preset superfast -pix_fmt yuv420p -profile:v main" \
                    --arg sync "true" \
                    --arg sync_file '' \
                    --arg sync_index "data:0:channels" \
                    --arg sync_pairs "chnl_name:channel_name,chnl_id:output_dir_name,chnl_pid:pid,chnl_cat=港澳台,url=http://xxx.com/live" \
                    --arg schedule_file '' \
                    --arg flv_delay_seconds 20 \
                    --arg flv_restart_nums 20 \
                    --arg hls_delay_seconds 120 \
                    --arg hls_min_bitrate 500 \
                    --arg hls_max_seg_size 5 \
                    --arg hls_restart_nums 20 \
                    --arg hls_key_period 30 \
                    --arg hls_end_list "false" \
                    --arg anti_ddos_port 80 \
                    --arg anti_ddos_syn_flood "false" \
                    --arg anti_ddos_syn_flood_delay_seconds 3 \
                    --arg anti_ddos_syn_flood_seconds 3600 \
                    --arg anti_ddos "false" \
                    --arg anti_ddos_seconds 120 \
                    --arg anti_ddos_level 6 \
                    --arg anti_leech "false" \
                    --arg anti_leech_restart_nums 3 \
                    --arg anti_leech_restart_flv_changes "true" \
                    --arg anti_leech_restart_hls_changes "true" \
                    --arg recheck_period 0 \
                    --arg ffmpeg_bin '' \
                    --arg version "$sh_ver" \
                    '{
                        proxy: $proxy,
                        xc_proxy: $xc_proxy,
                        user_agent: $user_agent,
                        headers: $headers,
                        cookies: $cookies,
                        playlist_name: $playlist_name,
                        seg_dir_name: $seg_dir_name,
                        seg_name: $seg_name,
                        seg_length: $seg_length | tonumber,
                        seg_count: $seg_count | tonumber,
                        video_codec: $video_codec,
                        audio_codec: $audio_codec,
                        video_audio_shift: $video_audio_shift,
                        draw_text: $draw_text,
                        quality: $quality,
                        bitrate: $bitrate,
                        resolution: $resolution,
                        const: $const | test("true"),
                        const_cbr: $const_cbr | test("true"),
                        encrypt: $encrypt | test("true"),
                        encrypt_session: $encrypt_session | test("true"),
                        keyinfo_name: $keyinfo_name,
                        key_name: $key_name,
                        input_flags: $input_flags,
                        output_flags: $output_flags,
                        sync: $sync | test("true"),
                        sync_file: $sync_file,
                        sync_index: $sync_index,
                        sync_pairs: $sync_pairs,
                        schedule_file: $schedule_file,
                        flv_delay_seconds: $flv_delay_seconds | tonumber,
                        flv_restart_nums: $flv_restart_nums | tonumber,
                        hls_delay_seconds: $hls_delay_seconds | tonumber,
                        hls_min_bitrate: $hls_min_bitrate | tonumber,
                        hls_max_seg_size: $hls_max_seg_size | tonumber,
                        hls_restart_nums: $hls_restart_nums | tonumber,
                        hls_key_period: $hls_key_period | tonumber,
                        hls_end_list: $hls_end_list | test("true"),
                        anti_ddos_port: $anti_ddos_port,
                        anti_ddos_syn_flood: $anti_ddos_syn_flood | test("true"),
                        anti_ddos_syn_flood_delay_seconds: $anti_ddos_syn_flood_delay_seconds | tonumber,
                        anti_ddos_syn_flood_seconds: $anti_ddos_syn_flood_seconds | tonumber,
                        anti_ddos: $anti_ddos | test("true"),
                        anti_ddos_seconds: $anti_ddos_seconds | tonumber,
                        anti_ddos_level: $anti_ddos_level | tonumber,
                        anti_leech: $anti_leech | test("true"),
                        anti_leech_restart_nums: $anti_leech_restart_nums | tonumber,
                        anti_leech_restart_flv_changes: $anti_leech_restart_flv_changes | test("true"),
                        anti_leech_restart_hls_changes: $anti_leech_restart_hls_changes | test("true"),
                        recheck_period: $recheck_period | tonumber,
                        ffmpeg_bin: $ffmpeg_bin,
                        version: $version,
                        schema_version: 3
                    }' > "$tmp_cfg"
                chmod +r "$tmp_cfg"
                mv "$tmp_cfg" "$IPTV_CONFIG"
            fi

            if [ ! -s "$CHANNELS_FILE" ]
            then
                local tmp_chnls
                tmp_chnls=$(mktemp "${TMPDIR:-/tmp}/aios-chnls.XXXXXX")
                $JQ_FILE -n '{ channels: [] }' > "$tmp_chnls"
                chmod +r "$tmp_chnls"
                mv "$tmp_chnls" "$CHANNELS_FILE"
            fi

            Println "`eval_gettext \"\\\$info 安装完成\"`\n"
        fi
    }

    Uninstall()
    {
        [ ! -d "$IPTV_ROOT" ] && Println "`eval_gettext \"\\\$error 尚未安装, 请检查 !\"`\n" && exit 1

        echo
        ExitOnList n "`gettext \"确定要 卸载此脚本以及产生的全部文件\"`"

        MonitorStop
        VipDisable
        CloudflareDisableWorkersMonitor

        if [ -e "$NODE_ROOT/index.js" ]
        then
            pm2 stop 0 2> /dev/null || true
        fi

        if crontab -l | grep -q "$LOGROTATE_CONFIG" 2> /dev/null
        then
            crontab -l > "$IPTV_ROOT/cron_tmp" 2> /dev/null || true
            FilterFileLines "$LOGROTATE_CONFIG" "$IPTV_ROOT/cron_tmp"
            crontab "$IPTV_ROOT/cron_tmp" > /dev/null
            rm -f "$IPTV_ROOT/cron_tmp"
            Println "$info 已停止 logrotate\n"
        fi

        i18nGetMsg get_channel

        while IFS= read -r chnl_pid
        do
            GetChannel
            if [ "$chnl_flv_status" == "on" ] 
            then
                kind="flv"
                StopChannel
            elif [ "$chnl_status" == "on" ]
            then
                kind=""
                StopChannel
            fi
        done < <($JQ_FILE '.channels[].pid' $CHANNELS_FILE)

        StopChannelsForce 2> /dev/null || true

        rm -rf "${IPTV_ROOT:-notfound}"

        Println "`eval_gettext \"\\\$info 卸载完成 !\"`\n"
    }

    Update()
    {
        ShFileUpdate

        pkill -f 'tv s -' 2> /dev/null || true

        [ ! -d "$IPTV_ROOT" ] && Println "`eval_gettext \"\\\$error 尚未安装, 请检查 !\"`\n" && exit 1

        while IFS= read -r line 
        do
            if [[ $line == *"built on "* ]] 
            then
                line=${line#*built on }
                git_date=${line%<*}
                break
            fi
        done < <(curl -s -Lm 10 "$FFMPEG_MIRROR_LINK/index.html" 2> /dev/null)

        if [ -z "${git_date:-}" ] 
        then
            Println "`eval_gettext \"\\\$error 暂时无法连接服务器, 请稍后再试 !\"`\n"
            exit 1
        fi

        if [ -s "$IPTV_ROOT/monitor.pid" ] || [ -s "$IPTV_ROOT/antiddos.pid" ]
        then
            echo
            ExitOnList y "`gettext \"需要先关闭监控, 是否继续\"`"
            MonitorStop
        fi

        FFmpegInstall

        if [ "$dist" != "mac" ] 
        then
            if [[ ${FFMPEG_FILE_ROOT##*/} == *"${git_date:-20200101}"* ]] 
            then
                echo
                inquirer list_input "`gettext \"FFmpeg 已经是最新, 是否重装\"`" ny_options reinstall_ffmpeg_yn
                if [ "$reinstall_ffmpeg_yn" == "$i18n_no" ]
                then
                    reinstall_ffmpeg_yn="N"
                else
                    reinstall_ffmpeg_yn="Y"
                fi
            else
                reinstall_ffmpeg_yn="Y"
            fi

            if [[ ${reinstall_ffmpeg_yn:-N} == [Yy] ]] 
            then
                rm -rf "$FFMPEG_ROOT"/ffmpeg-git-*/
                Spinner "`gettext \"更新 FFmpeg\"`" FFmpegInstall
            fi

            # A limitation of statically linking glibc is the loss of DNS resolution.
            DepInstall nscd
        fi

        JQInstall

        Println "`eval_gettext \"脚本已更新为最新版本 [ \\\${green}\\\$sh_new_ver\\\${normal} ] ! (输入: tv 使用)\"`\n" && exit 0
    }

    if [ -e "$IPTV_ROOT" ] && [ ! -e "$LOCK_FILE" ] 
    then
        UpdateSelfRollback()
        {
            if [ -n "${channels_backup:-}" ] && [ -f "$channels_backup" ]
            then
                cp -f "$channels_backup" "$CHANNELS_FILE"
            fi

            if [ -n "${config_backup:-}" ] && [ -f "$config_backup" ]
            then
                cp -f "$config_backup" "$IPTV_CONFIG"
            elif [ "${config_existed_before:-false}" = false ]
            then
                rm -f "$IPTV_CONFIG"
            fi
            Println "$error 配置迁移失败, 已从备份回滚 !\n"
        }

        if [ ! -e "$JQ_FILE" ]
        then
            echo
            ExitOnList y "`gettext \"检测到安装未完成, 是否卸载重装\"`"

            Uninstall
            Install
            exit 0
        fi

        has_legacy_default=false
        if [ -s "$CHANNELS_FILE" ] && $JQ_FILE -e '(.default | type) == "object"' "$CHANNELS_FILE" > /dev/null 2>&1
        then
            has_legacy_default=true
        fi

        config_existed_before=false
        if [ -s "$IPTV_CONFIG" ]
        then
            config_existed_before=true
            cur_ver=$($JQ_FILE -r '.version // "0.0.0"' "$IPTV_CONFIG" 2> /dev/null || printf '0.0.0')
            cur_schema=$($JQ_FILE -r '.schema_version // 0' "$IPTV_CONFIG" 2> /dev/null || printf '0')
        elif [ "$has_legacy_default" = true ]
        then
            cur_ver=$($JQ_FILE -r '.default.version // "0.0.0"' "$CHANNELS_FILE" 2> /dev/null || printf '0.0.0')
            cur_schema=$($JQ_FILE -r '.default.schema_version // 0' "$CHANNELS_FILE" 2> /dev/null || printf '0')
        else
            cur_ver="0.0.0"
            cur_schema="0"
        fi

        if ! [[ $cur_schema =~ ^[0-9]+$ ]]
        then
            cur_schema=0
        fi

        if [ "$has_legacy_default" = true ] || [ ! -s "$IPTV_CONFIG" ] || VersionLt "$cur_ver" "$sh_ver" || [ "$cur_schema" -lt 3 ]
        then
            if VersionLt "$cur_ver" "1.35.0" && [ "$cur_ver" != "0.0.0" ]
            then
                Println "$info 需要先关闭所有频道, 请稍等...\n"
                StopChannelsForce
                rm -rf "/tmp/flv.lockdir/"
                rm -rf "/tmp/monitor.lockdir"
                rm -f "$FFMPEG_LOG_ROOT/"*.lock
            fi

            Println "$info 更新中, 请稍等...\n"
            update_date=$(date '+%m-%d-%H:%M:%S')
            channels_backup=""
            config_backup=""
            orig_chnls_count=0

            if [ -s "$CHANNELS_FILE" ]
            then
                if ! $JQ_FILE empty "$CHANNELS_FILE" > /dev/null 2>&1
                then
                    Println "$error $CHANNELS_FILE JSON 格式错误, 取消迁移 !\n"
                    exit 1
                fi
                orig_chnls_count=$($JQ_FILE '(.channels // []) | length' "$CHANNELS_FILE" 2> /dev/null || printf '-1')
                channels_backup="${CHANNELS_FILE}_$update_date"
                cp -f "$CHANNELS_FILE" "$channels_backup"
            fi

            if [ -s "$IPTV_CONFIG" ]
            then
                if ! $JQ_FILE empty "$IPTV_CONFIG" > /dev/null 2>&1
                then
                    Println "$error $IPTV_CONFIG JSON 格式错误, 取消迁移 !\n"
                    exit 1
                fi
                config_backup="${IPTV_CONFIG}_$update_date"
                cp -f "$IPTV_CONFIG" "$config_backup"
            fi

            if [ "$has_legacy_default" = true ]
            then
                if [ ! -s "$IPTV_CONFIG" ]
                then
                    tmp_cfg=$(mktemp "${TMPDIR:-/tmp}/aios-cfg.XXXXXX")
                    if ! $JQ_FILE '.default' "$CHANNELS_FILE" > "$tmp_cfg" || [ ! -s "$tmp_cfg" ] || ! $JQ_FILE empty "$tmp_cfg" > /dev/null 2>&1
                    then
                        rm -f "$tmp_cfg"
                        UpdateSelfRollback
                        exit 1
                    fi
                    chmod +r "$tmp_cfg"
                    mv "$tmp_cfg" "$IPTV_CONFIG"
                fi

                if ! JQ mutate "$CHANNELS_FILE" 'del(.default)'
                then
                    UpdateSelfRollback
                    exit 1
                fi
            fi

            if [ ! -s "$IPTV_CONFIG" ]
            then
                printf '{}\n' > "$IPTV_CONFIG"
            fi

            if [ ! -s "$CHANNELS_FILE" ]
            then
                printf '{"channels":[]}\n' > "$CHANNELS_FILE"
            fi

            def_input_flags="-copy_unknown -reconnect 1 -reconnect_at_eof 1 -reconnect_streamed 1 -reconnect_delay_max 2000 -rw_timeout 10000000 -y -nostats -nostdin -hide_banner -loglevel error"
            def_output_flags="-g 60 -sc_threshold 0 -sn -preset superfast -pix_fmt yuv420p -profile:v main"
            def_sync_pairs="chnl_name:channel_name,chnl_id:output_dir_name,chnl_pid:pid,chnl_cat=港澳台,url=http://xxx.com/live"

            cfg_migrate_jq='
                def collapse_bs:
                    if type == "string" then
                        if test("\\\\\\\\") then gsub("\\\\\\\\"; "\\") | collapse_bs else . end
                    else
                        ""
                    end;
                def to_bool($def):
                    if type == "boolean" then .
                    elif type == "string" then (. == "true" or . == "yes")
                    else $def
                    end;
                def to_num($def):
                    if type == "number" then .
                    elif type == "string" and test("^-?[0-9]+(\\.[0-9]+)?$") then tonumber
                    else $def
                    end;
                (if type == "object" then . else {} end)
                | (if has("bitrates") and (.bitrates | type) == "string" and (.bitrates != "") then
                    if (.bitrates | contains("-")) then
                        .bitrate = ((.bitrates | split("-"))[0])
                        | .resolution = ((.bitrates | split("-"))[1:] | join("-"))
                    elif (.bitrates | contains("x")) then
                        .resolution = .bitrates
                        | .bitrate = ""
                    else
                        .bitrate = .bitrates
                    end
                else . end)
                | (if has("hls_min_bitrates") and (.hls_min_bitrates != null) and (.hls_min_bitrates != "") then
                    .hls_min_bitrate = (.hls_min_bitrates | to_num(500))
                else . end)
                | del(.bitrates, .hls_min_bitrates, .txt_format)
                | .proxy = (.proxy // "")
                | .xc_proxy = (.xc_proxy // "")
                | .user_agent = (if (.user_agent // "") == "" then $def_ua else .user_agent end)
                | .headers = ((.headers // "") | collapse_bs)
                | .cookies = (if (.cookies // "") == "" then "stb_lang=en; timezone=Europe/Amsterdam" else .cookies end)
                | .playlist_name = (.playlist_name // "")
                | .seg_dir_name = (.seg_dir_name // "")
                | .seg_name = (.seg_name // "")
                | .seg_length = (.seg_length | to_num(6))
                | .seg_count = (.seg_count | to_num(5))
                | .video_codec = (.video_codec // "libx264")
                | .audio_codec = (.audio_codec // "aac")
                | .video_audio_shift = (.video_audio_shift // "")
                | .draw_text = (.draw_text // "")
                | .quality = (.quality // "")
                | .bitrate = ((.bitrate // "900") | tostring)
                | .resolution = (.resolution // "1280x720")
                | .const = (.const | to_bool(false))
                | .const_cbr = (.const_cbr | to_bool(false))
                | .encrypt = (.encrypt | to_bool(false))
                | .encrypt_session = (.encrypt_session | to_bool(false))
                | .keyinfo_name = (.keyinfo_name // "")
                | .key_name = (.key_name // "")
                | .input_flags = (
                    (.input_flags // $def_in)
                    | if type == "string" then
                        (if (contains("-copy_unknown") | not) then "-copy_unknown " + . else . end)
                        | gsub("-timeout 2000000000"; "-rw_timeout 10000000")
                    else $def_in end
                )
                | .output_flags = (.output_flags // $def_out)
                | .sync = (.sync | to_bool(true))
                | .sync_file = (.sync_file // "")
                | .sync_index = (.sync_index // "data:0:channels")
                | .sync_pairs = (.sync_pairs // $def_sp)
                | .schedule_file = (.schedule_file // "")
                | .flv_delay_seconds = (.flv_delay_seconds | to_num(20))
                | .flv_restart_nums = (.flv_restart_nums | to_num(20))
                | .hls_delay_seconds = (.hls_delay_seconds | to_num(120))
                | .hls_min_bitrate = (.hls_min_bitrate | to_num(500))
                | .hls_max_seg_size = (.hls_max_seg_size | to_num(5))
                | .hls_restart_nums = (.hls_restart_nums | to_num(20))
                | .hls_key_period = (.hls_key_period | to_num(30))
                | .hls_end_list = (.hls_end_list | to_bool(false))
                | .anti_ddos_port = ((.anti_ddos_port // "80") | tostring)
                | .anti_ddos_syn_flood = (.anti_ddos_syn_flood | to_bool(false))
                | .anti_ddos_syn_flood_delay_seconds = (.anti_ddos_syn_flood_delay_seconds | to_num(3))
                | .anti_ddos_syn_flood_seconds = (.anti_ddos_syn_flood_seconds | to_num(3600))
                | .anti_ddos = (.anti_ddos | to_bool(false))
                | .anti_ddos_seconds = (.anti_ddos_seconds | to_num(120))
                | .anti_ddos_level = (.anti_ddos_level | to_num(6))
                | .anti_leech = (.anti_leech | to_bool(false))
                | .anti_leech_restart_nums = (.anti_leech_restart_nums | to_num(3))
                | .anti_leech_restart_flv_changes = (.anti_leech_restart_flv_changes | to_bool(true))
                | .anti_leech_restart_hls_changes = (.anti_leech_restart_hls_changes | to_bool(true))
                | .recheck_period = (.recheck_period | to_num(0))
                | .ffmpeg_bin = (.ffmpeg_bin // "")
                | .version = $ver
                | .schema_version = 3
            '

            if ! JQ mutate "$IPTV_CONFIG" "$cfg_migrate_jq" \
                --arg def_ua "$USER_AGENT_TV" \
                --arg def_in "$def_input_flags" \
                --arg def_out "$def_output_flags" \
                --arg def_sp "$def_sync_pairs" \
                --arg ver "$sh_ver"
            then
                UpdateSelfRollback
                exit 1
            fi

            chnls_migrate_jq='
                def collapse_bs:
                    if type == "string" then
                        if test("\\\\\\\\") then gsub("\\\\\\\\"; "\\") | collapse_bs else . end
                    else
                        ""
                    end;
                def to_bool($def):
                    if type == "boolean" then .
                    elif type == "string" then (. == "true" or . == "yes")
                    else $def
                    end;
                def to_num($def):
                    if type == "number" then .
                    elif type == "string" and test("^-?[0-9]+(\\.[0-9]+)?$") then tonumber
                    else $def
                    end;
                (if type == "object" then . else {} end)
                | del(.default)
                | .channels = (
                    (.channels // [])
                    | if type == "array" then
                        map(
                            (if has("bitrates") and (.bitrates | type) == "string" then
                                if .bitrates == "" then
                                    .bitrate = (.bitrate // "")
                                    | .resolution = (.resolution // "")
                                else
                                    (.bitrates | split(",")) as $parts
                                    | .bitrate = ($parts | map(if contains("-") then (split("-")[0]) elif contains("x") then "" else . end) | join(","))
                                    | .resolution = ($parts | map(if contains("-") then (split("-")[1:] | join("-")) elif contains("x") then . else "" end) | join(","))
                                end
                            else
                                .bitrate = (.bitrate // "")
                                | .resolution = (.resolution // "")
                            end)
                            | del(.bitrates, .txt_format)
                            | .pid = (.pid | to_num(0))
                            | .status = (.status // "off")
                            | .hide = (.hide | to_bool(false))
                            | .stream_link = (
                                if (.stream_link | type) == "string" then
                                    (.stream_link | split(" ") | map(select(length > 0)))
                                elif (.stream_link | type) == "array" then
                                    .stream_link
                                else
                                    []
                                end
                            )
                            | .live = (.live | to_bool(false))
                            | .proxy = (.proxy // "")
                            | .xc_proxy = (.xc_proxy // "")
                            | .user_agent = (.user_agent // "")
                            | .headers = ((.headers // "") | collapse_bs)
                            | .cookies = (.cookies // "")
                            | .output_dir_name = (.output_dir_name // "")
                            | .playlist_name = (.playlist_name // "")
                            | .seg_dir_name = (.seg_dir_name // "")
                            | .seg_name = (.seg_name // "")
                            | .seg_length = (.seg_length | to_num(6))
                            | .seg_count = (.seg_count | to_num(5))
                            | .video_codec = (.video_codec // "")
                            | .audio_codec = (.audio_codec // "")
                            | .video_audio_shift = (.video_audio_shift // "")
                            | .subtitle = (
                                if (.subtitle | type) == "array" then
                                    (.subtitle | map({
                                        name: (.name // ""),
                                        language: (.language // ""),
                                        default: (.default | to_bool(false)),
                                        auto_select: (.auto_select | to_bool(false)),
                                        map: (.map | to_num(0))
                                    }))
                                else
                                    []
                                end
                            )
                            | .draw_text = (.draw_text // "")
                            | .quality = (.quality // "")
                            | .const = (.const | to_bool(false))
                            | .const_cbr = (.const_cbr | to_bool(false))
                            | .encrypt = (if .encrypt == "-e" then false else (.encrypt | to_bool(false)) end)
                            | .encrypt_session = (.encrypt_session | to_bool(false))
                            | .keyinfo_name = (.keyinfo_name // "")
                            | .key_name = (.key_name // "")
                            | .key_time = (.key_time | to_num(0))
                            | .input_flags = (
                                (.input_flags // "")
                                | if type == "string" then
                                    (if (contains("-copy_unknown") | not) then "-copy_unknown " + . else . end)
                                    | gsub("-timeout 2000000000"; "-rw_timeout 10000000")
                                else "" end
                            )
                            | .output_flags = (.output_flags // "")
                            | .channel_name = (.channel_name // "")
                            | .channel_time = (.channel_time | to_num(0))
                            | .schedule = (
                                if (.schedule | type) == "array" then
                                    (.schedule | map({
                                        start_time: (.start_time | to_num(0)),
                                        end_time: (.end_time | to_num(0)),
                                        loop: (.loop | to_bool(false)),
                                        auto_remove: (.auto_remove | to_bool(false)),
                                        hls_change: (.hls_change | to_bool(true)),
                                        hls_change_once: (.hls_change_once | to_bool(false)),
                                        channel_name: (.channel_name // ""),
                                        status: (.status | to_num(0))
                                    }))
                                else
                                    []
                                end
                            )
                            | .sync = (.sync | to_bool(false))
                            | .sync_file = (.sync_file // "")
                            | .sync_index = (.sync_index // "")
                            | .sync_pairs = (.sync_pairs // "")
                            | .hls_end_list = (.hls_end_list | to_bool(false))
                            | .flv_status = (.flv_status // "off")
                            | .flv_h265 = (.flv_h265 | to_bool(false))
                            | .flv_push_link = (.flv_push_link // "")
                            | .flv_pull_link = (.flv_pull_link // "")
                        )
                    else
                        []
                    end
                )
            '

            if ! JQ mutate "$CHANNELS_FILE" "$chnls_migrate_jq"
            then
                UpdateSelfRollback
                exit 1
            fi

            new_chnls_count=$($JQ_FILE '(.channels // []) | length' "$CHANNELS_FILE" 2> /dev/null || printf '-1')
            if ! $JQ_FILE empty "$IPTV_CONFIG" > /dev/null 2>&1 || ! $JQ_FILE empty "$CHANNELS_FILE" > /dev/null 2>&1 || [ "$new_chnls_count" != "$orig_chnls_count" ]
            then
                UpdateSelfRollback
                exit 1
            fi

            d_version=""
        fi

        GetDefault

        printf '%s' "" > "$LOCK_FILE"
    fi

    if [[ -n ${1+x} ]]
    then
        case $1 in
            4g)
                if [ ! -d "$IPTV_ROOT" ] 
                then
                    Println "$error 请先安装脚本 !\n" && exit 1
                fi

                user_agent="$USER_AGENT_BROWSER"

                if [ "${2:-}" == "-" ] 
                then
                    _4gtvCron
                    exit 0
                fi

                OpensslInstall

                Println "  4gtv 面板

  ${green}1.${normal} 注册账号
  ${green}2.${normal} 登录账号
  ${green}3.${normal} 查看账号
  ${green}4.${normal} 修改账号
  ${green}5.${normal} 删除账号
  ${green}6.${normal} 使用免费频道
  ${green}7.${normal} 使用豪华频道
  ${green}8.${normal} 开启计划任务
  ${green}9.${normal} 关闭计划任务

                "
                while read -p "(默认: 6): " _4gtv_menu_num 
                do
                    _4gtv_menu_num=${_4gtv_menu_num:-6}
                    case "$_4gtv_menu_num" in
                        1) 
                            Reg4gtvAcc
                            exit 0
                        ;;
                        2) 
                            Login4gtvAcc
                            exit 0
                        ;;
                        3) 
                            List4gtvAcc
                            exit 0
                        ;;
                        4) 
                            Edit4gtvAcc
                            exit 0
                        ;;
                        5) 
                            Del4gtvAcc
                            exit 0
                        ;;
                        6) 
                            _4gtv_set_id=4
                            fsVALUE=""
                            Use4gtvProxy
                            break
                        ;;
                        7) 
                            Get4gtvAccToken
                            _4gtv_set_id=1
                            Use4gtvProxy
                            break
                        ;;
                        8) 
                            Enable4gtvCron
                            exit 0
                        ;;
                        9) 
                            Disable4gtvCron
                            exit 0
                        ;;
                        *) Println "$error $i18n_input_correct_number [1-9]\n"
                        ;;
                    esac
                done

                hinet_4gtv=(
                    "litv-ftv13:民視新聞台"
                    "litv-longturn14:寰宇新聞台"
                    "4gtv-4gtv052:華視新聞資訊台"
                    "4gtv-4gtv012:空中英語教室"
                    "litv-ftv07:民視旅遊台"
                    "litv-ftv15:i-Fun動漫台"
                    "4gtv-live206:幸福空間居家台"
                    "4gtv-4gtv070:愛爾達娛樂台"
                    "litv-longturn17:亞洲旅遊台"
                    "4gtv-4gtv025:MTV Live HD"
                    "litv-longturn15:寰宇新聞台灣台"
                    "4gtv-4gtv001:民視台灣台"
                    "4gtv-4gtv074:中視新聞台"
                    "4gtv-4gtv011:影迷數位電影台"
                    "4gtv-4gtv047:靖天日本台"
                    "litv-longturn11:龍華日韓台"
                    "litv-longturn12:龍華偶像台"
                    "4gtv-4gtv042:公視戲劇"
                    "litv-ftv12:i-Fun動漫台3"
                    "4gtv-4gtv002:民視無線台"
                    "4gtv-4gtv027:CI 罪案偵查頻道"
                    "4gtv-4gtv013:CNEX紀實頻道"
                    "litv-longturn03:龍華電影台"
                    "4gtv-4gtv004:民視綜藝台"
                    "litv-longturn20:ELTV英語學習台"
                    "litv-longturn01:龍華卡通台"
                    "4gtv-4gtv040:中視無線台"
                    "litv-longturn02:Baby First"
                    "4gtv-4gtv003:民視第一台"
                    "4gtv-4gtv007:大愛電視台"
                    "4gtv-4gtv076:SMART 知識頻道"
                    "4gtv-4gtv030:CNBC"
                    "litv-ftv10:半島電視台"
                )

                GetChannels

                hinet_4gtv_count=${#hinet_4gtv[@]}
                hinet_4gtv_list=""
                for((i=0;i<hinet_4gtv_count;i++));
                do
                    hinet_4gtv_chnl_added=""
                    for chnl in ${chnls_stream_link[@]+"${chnls_stream_link[@]}"}
                    do
                        if [[ $chnl =~ embed.4gtv.tv/HiNet ]] && [[ $chnl =~ asset_id=${hinet_4gtv[i]%:*}\& ]] 
                        then
                            hinet_4gtv_chnl_added=" ${green}[已添加]${normal}"
                            break
                        fi
                    done
                    hinet_4gtv_list="$hinet_4gtv_list ${green}$((i+1)).${normal}${indent_6}${hinet_4gtv[i]#*:}$hinet_4gtv_chnl_added\n\n"
                done

                cookies=""

                Println "$info 获取频道 ..."
                IFS="^" read -r _4gtv_chnl_id _4gtv_chnl_name _4gtv_chnl_aid < <(CurlFake -s -Lm 10 \
                    -H "Referer: https://www.4gtv.tv/channel.html?channelSet_id=$_4gtv_set_id" \
                    "https://api2.4gtv.tv/Channel/GetChannelBySetId/$_4gtv_set_id/pc/L" \
                    | $JQ_FILE -r '[([.Data[].fnID]|join("|")),([.Data[].fsNAME]|join("|")),([.Data[].fs4GTV_ID]|join("|"))]|join("^")'
                ) || true

                IFS="|" read -r -a _4gtv_chnls_id <<< "$_4gtv_chnl_id"
                IFS="|" read -r -a _4gtv_chnls_name <<< "$_4gtv_chnl_name"
                IFS="|" read -r -a _4gtv_chnls_aid <<< "$_4gtv_chnl_aid"

                if [ -n "${_4gtv_chnls_id:-}" ] 
                then
                    _4gtv_list=""
                    _4gtv_chnls_count=${#_4gtv_chnls_id[@]}
                    for((i=0;i<_4gtv_chnls_count;i++));
                    do
                        _4gtv_chnl_added=""
                        for chnl in ${chnls_stream_link[@]+"${chnls_stream_link[@]}"}
                        do
                            if [[ $chnl =~ 4gtv.tv/channel_sub.html ]] && [[ $chnl =~ asset_id=${_4gtv_chnls_aid[i]}\& ]] 
                            then
                                _4gtv_chnl_added=" ${green}[已添加]${normal}"
                                break
                            fi
                        done
                        _4gtv_list="$_4gtv_list ${green}$((i+hinet_4gtv_count+1)).${normal}${indent_6}${_4gtv_chnls_name[i]}$_4gtv_chnl_added\n\n"
                    done
                    chnls_list="HiNet 4gtv 频道:\n\n${hinet_4gtv_list}4gtv 官网频道:\n\n$_4gtv_list"
                else
                    _4gtv_chnls_count=0
                    chnls_list="HiNet 4gtv 频道:\n\n$hinet_4gtv_list"
                fi

                chnls_count=$((hinet_4gtv_count+_4gtv_chnls_count))
                Println "$chnls_list"
                echo "选择需要添加的频道序号, 多个频道用空格分隔, 比如 5 7 9-11"
                while read -p "$i18n_default_cancel" chnls_num 
                do
                    [ -z "$chnls_num" ] && Println "$i18n_canceled...\n" && exit 1
                    IFS=" " read -ra chnls_num_arr <<< "$chnls_num"

                    error_no=0
                    for chnl_num in "${chnls_num_arr[@]}"
                    do
                        case "$chnl_num" in
                            *"-"*)
                                chnl_num_start=${chnl_num%-*}
                                chnl_num_end=${chnl_num#*-}
                                if [[ $chnl_num_start == *[!0-9]* ]] || [[ $chnl_num_end == *[!0-9]* ]] || \
                                [ "$chnl_num_start" -eq 0 ] || [ "$chnl_num_end" -eq 0 ] || \
                                [ "$chnl_num_end" -gt "$chnls_count" ] || \
                                [ "$chnl_num_start" -ge "$chnl_num_end" ]
                                then
                                    error_no=3
                                    break
                                fi
                            ;;
                            *[!0-9]*)
                                error_no=1
                                break
                            ;;
                            *)
                                if [ "$chnl_num" -lt 1 ] || [ "$chnl_num" -gt "$chnls_count" ] 
                                then
                                    error_no=2
                                    break
                                fi
                            ;;
                        esac
                    done

                    case "$error_no" in
                        1|2|3)
                            Println "$error $i18n_input_correct_number\n"
                        ;;
                        *)
                            declare -a new_array
                            for element in "${chnls_num_arr[@]}"
                            do
                                if [[ $element =~ - ]] 
                                then
                                    start=${element%-*}
                                    end=${element#*-}
                                    for((i=start;i<=end;i++));
                                    do
                                        new_array+=("$i")
                                    done
                                else
                                    new_array+=("$element")
                                fi
                            done
                            chnls_num_arr=("${new_array[@]}")
                            unset new_array
                            break
                        ;;
                    esac
                done

                for chnl_num in "${chnls_num_arr[@]}"
                do
                    stream_link_parsed=true
                    if [ "$chnl_num" -le "$hinet_4gtv_count" ] 
                    then
                        hinet_4gtv_chnl_index=$((chnl_num-1))
                        hinet_4gtv_chnl_id=${hinet_4gtv[hinet_4gtv_chnl_index]%%:*}
                        hinet_4gtv_chnl_name=${hinet_4gtv[hinet_4gtv_chnl_index]#*:}
                        hinet_4gtv_chnl_name_enc=$(Urlencode "$hinet_4gtv_chnl_name")
                        Println "$info 添加频道 [ $hinet_4gtv_chnl_name ]\n\n"
                        Println "$info 解析 [ $hinet_4gtv_chnl_name ] 链接 ..."
                        stream_links=("https://embed.4gtv.tv/HiNet/$hinet_4gtv_chnl_name_enc.html")
                        headers="Referer: ${stream_links[0]}?ar=0&as=1&volume=0\r\n"
                        stream_link_data=$(CurlFake -s -Lm 10 \
            ${_4gtv_proxy_command[@]+"${_4gtv_proxy_command[@]}"} \
                            -H "$(StripSuffix "$headers" 4)" \
                            "https://app.4gtv.tv/Data/HiNet/GetURL.ashx?ChannelNamecallback=channelname&Type=LIVE&Content=$hinet_4gtv_chnl_id&HostURL=https%3A%2F%2Fwww.hinet.net%2Ftv%2F&_=$(DateMs)") || true
                        if [ -n "$stream_link_data" ] 
                        then
                            stream_link_data=$($JQ_FILE -r '.VideoURL' <<< "$(StripSuffix "${stream_link_data:12}" 1)")
                            if [ -z "$stream_link_data" ] 
                            then
                                Println "$error hinet 4gtv 或频道 [ $hinet_4gtv_chnl_name ] 不可用!\n"
                                continue
                            fi
                            hexkey=$(echo -n "VxzAfiseH0AbLShkQOPwdsssw5KyLeuv" | hexdump -v -e '/1 "%02x"')
                            hexiv=$(echo -n "${stream_link_data:0:16}" | hexdump -v -e '/1 "%02x"')
                            stream_link="${stream_links[0]}"
                            stream_link_url=$(echo "${stream_link_data:16}" | openssl enc -aes-256-cbc -d -iv "$hexiv" -K "$hexkey" -a)
                            stream_link_url_path=${stream_link_url%/*}
                            channel_name="$hinet_4gtv_chnl_name"
                            if ! Add4gtvLink
                            then
                                continue
                            fi
                            echo
                            inquirer list_input "是否 添加/替换 现有频道直播源" ny_options add_channel_yn

                            if [ "$add_channel_yn" == "$i18n_yes" ]
                            then
                                ListChannels
                                InputChannelsIndex

                                for((i=0;i<${#chnls_pid_chosen[@]};i++));
                                do
                                    chnl_pid=${chnls_pid_chosen[i]}
                                    chnls_index=${chnls_indices[i]}

                                    ListChannel

                                    echo
                                    change_options=( '添加' '替换' )
                                    inquirer list_input_index "如何修改频道 [ $chnl_channel_name ]" change_options change_options_index

                                    if [ "$change_options_index" -eq 0 ] 
                                    then
                                        jq_pre=true
                                        jq_path='["channels",'"$chnls_index"',"stream_link"]'
                                        JQ add "$CHANNELS_FILE" ["\"${stream_links[0]}\""]
                                    else
                                        echo
                                        inquirer list_input_index "选择替换的直播源" chnl_stream_links chnl_stream_links_index

                                        jq_path='["channels",'"$chnls_index"',"stream_link",'"$chnl_stream_links_index"']'
                                        JQ update "$CHANNELS_FILE" "${stream_links[0]}"
                                    fi

                                    jq_path='["channels",'"$chnls_index"',"proxy"]'
                                    JQ update "$CHANNELS_FILE" "$_4gtv_proxy"

                                    jq_path='["channels",'"$chnls_index"',"user_agent"]'
                                    JQ update "$CHANNELS_FILE" "$user_agent"

                                    jq_path='["channels",'"$chnls_index"',"headers"]'
                                    JQ update "$CHANNELS_FILE" "$headers"

                                    jq_path='["channels",'"$chnls_index"',"cookies"]'
                                    JQ update "$CHANNELS_FILE" "$cookies"

                                    Println "$info 频道 [ $chnl_channel_name ] 修改成功 !\n"
                                done
                            else
                                echo
                                inquirer list_input "是否推流 flv" ny_options add_channel_flv_yn
                                if [ "$add_channel_flv_yn" == "$i18n_yes" ] 
                                then
                                    kind="flv"
                                else
                                    kind=""
                                fi
                                AddChannel
                            fi
                        else
                            Println "$error hinet 4gtv 或频道 [ $hinet_4gtv_chnl_name ] 不可用!\n"
                        fi
                    else
                        _4gtv_chnl_index=$((chnl_num-hinet_4gtv_count-1))
                        _4gtv_chnl_id=${_4gtv_chnls_id[_4gtv_chnl_index]}
                        _4gtv_chnl_name=${_4gtv_chnls_name[_4gtv_chnl_index]}
                        _4gtv_chnl_aid=${_4gtv_chnls_aid[_4gtv_chnl_index]}
                        Println "$info 添加频道 [ $_4gtv_chnl_name ]\n\n"
                        Println "$info 解析 [ $_4gtv_chnl_name ] 链接 ..."
                        stream_links=("https://www.4gtv.tv/channel_sub.html?channelSet_id=$_4gtv_set_id&asset_id=$_4gtv_chnl_aid&channel_id=$_4gtv_chnl_id")
                        headers="Referer: ${stream_links[0]}\r\n"
                        key="ilyB29ZdruuQjC45JhBBR7o2Z8WJ26Vg"
                        iv="JUMxvVMmszqUTeKn"
                        hexkey=$(echo -n $key | hexdump -v -e '/1 "%02x"')
                        hexiv=$(echo -n $iv | hexdump -v -e '/1 "%02x"')
                        post_data='{"fnCHANNEL_ID":'"$_4gtv_chnl_id"',"fsASSET_ID":"'"$_4gtv_chnl_aid"'","fsDEVICE_TYPE":"pc","clsIDENTITY_VALIDATE_ARUS":{"fsVALUE":"'"$fsVALUE"'"}}'
                        post_data=$(echo -n "$post_data" | openssl enc -aes-256-cbc -iv "$hexiv" -K "$hexkey" -a)
                        if [ -n "$fsVALUE" ] 
                        then
                            value="$(UrlencodeUpper ${post_data//[[:space:]]/})"
                        else
                            value="$(Urlencode ${post_data//[[:space:]]/})"
                        fi

                        for((try_i=0;try_i<10;try_i++));
                        do
                            stream_link_data=$(CurlFake -s -Lm 10 \
                ${_4gtv_proxy_command[@]+"${_4gtv_proxy_command[@]}"} \
                                -H "$(StripSuffix "$headers" 4)" \
                                --data "value=$value" "https://api2.4gtv.tv/Channel/GetChannelUrl3") || true
                            if [ -n "$stream_link_data" ] 
                            then
                                break
                            fi
                        done

                        if [ -z "$stream_link_data" ] 
                        then
                            Println "$error 无法连接 4gtv !\n" && exit 1
                        fi

                        stream_link_data=$($JQ_FILE -r '.Data' <<< "$stream_link_data")

                        if [ "$stream_link_data" == null ] 
                        then
                            Println "$error 此服务器 ip 不支持或频道 [ $_4gtv_chnl_name ] 不可用!\n"
                        else
                            stream_link="${stream_links[0]}"
                            stream_link_url=$(echo "$stream_link_data" | openssl enc -aes-256-cbc -d -iv "$hexiv" -K "$hexkey" -a \
                                | $JQ_FILE -r '.flstURLs[0]')
                            stream_link_url_path=${stream_link_url%/*}
                            channel_name="$_4gtv_chnl_name"
                            if ! Add4gtvLink 
                            then
                                continue
                            fi

                            echo
                            inquirer list_input "是否 添加/替换 现有频道直播源" ny_options add_channel_yn

                            if [ "$add_channel_yn" == "$i18n_yes" ]
                            then
                                ListChannels
                                InputChannelsIndex

                                for((i=0;i<${#chnls_pid_chosen[@]};i++));
                                do
                                    chnl_pid=${chnls_pid_chosen[i]}
