                    do
                        chnl_id=${chnl%%:*}
                        singteltv_id=${chnl#*:}
                        chnl_name=${singteltv_id#*:}
                        singteltv_id=${singteltv_id%%:*}

                        schedule=""
                        for((singteltv_i=0;singteltv_i<${#channel_ids[@]};singteltv_i++));
                        do
                            if [ "${channel_ids[singteltv_i]}" == "$singteltv_id" ] 
