                    )

                    other_chnls=(
                        "disneyjr:迪士尼儿童频道(台湾)"
                        "foxmovies:fox movies (台湾)"
                        "amlh:澳门莲花"
                        "foxnews:FOX News"
                    )

                    providers=(
                        "jiushi:就是 节目表"
                        "niotv:niotv 节目表"
                        "nowtv:nowtv 节目表"
                        "icable:i-cable 节目表"
                        "hboasia:hbo 亚洲 节目表"
                        "hbous:hbo 美国 节目表"
                        "ontvtonight:ontvtonight 节目表"
                        "tvbhk:TVB 香港 节目表"
                        "singteltv:singteltv 节目表"
