        if [ "$sockopt_tfo_options_index" -eq 0 ] 
        then
            sockopt_tfo=""
        elif [ "$sockopt_tfo_options_index" -eq 1 ] 
        then
            if [ "$v2ray_name" == "xray" ] 
            then
                Println "$tip 表示待处理的 TFO 连接请求数上限"
                inquirer text_input "输入正整数" sockopt_tfo 256
                return 0
            fi
            sockopt_tfo=true
        else
            sockopt_tfo=false
        fi
    }

