    V2raySetWsHeaders()
    {
        ws_headers=""
        while true 
        do
            echo
            inquirer text_input "输入自定义 HTTP 头的名称: " ws_header_name "$i18n_blank"
            if [ -z "$ws_header_name" ] 
            then
                break
            fi
            echo
            inquirer text_input "输入自定义 HTTP 头 $ws_header_name 的值: " ws_header_value "$i18n_blank"
            if [ -z "$ws_header_value" ] 
            then
                break
            fi
            [ -n "$ws_headers" ] && ws_headers="$ws_headers, "
            ws_headers="$ws_headers\"$ws_header_name\":\"$ws_header_value\""
            echo
            inquirer list_input "是否继续添加" ny_options continue_yn
            if [ "$continue_yn" == "$i18n_no" ] 
            then
                break
            fi
        done
    }

