    V2raySetAlterId()
    {
        Println "请输入 alterId"
        while read -p "(默认: 0): " alter_id
        do
            case "$alter_id" in
                "")
                    alter_id=0
                    break
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_number [0-65535]\n"
                ;;
                *)
                    if [ "$alter_id" -ge 0 ] && [ "$alter_id" -le 65535 ]
                    then
                        break
                    else
                        Println "$error $i18n_input_correct_number [0-65535]\n"
                    fi
                ;;
            esac
        done
        Println "  alterId: ${green} $alter_id ${normal}"
    }

