        fi
        Println "  allowTransparent: ${green} $allow_transparent ${normal}"
    }

    V2raySetLevel()
    {
        V2rayListPolicy

        echo -e "选择等级"
        while read -p "(默认: 1): " level
        do
            case "$level" in
                "")
                    level=0
                    break
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$level" -gt 0 ] && [ "$level" -le $((policy_levels_count+1)) ]
                    then
                        level=$((level-1))
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
        Println "  等级: ${green} $level ${normal}\n"
    }

