    V2rayStreamUtlsSettings()
    {
        V2rayStreamUtlsTlsConfig
        V2rayStreamUtlsImitate
        V2rayStreamUtlsNoSNI
        V2rayStreamUtlsForceAlpn

        JQs merge_c stream_security_settings --argjson tlsConfig "$stream_utls_tls_config" \
        --arg imitate "$stream_utls_imitate" \
        --arg noSNI "$stream_utls_noSNI" \
        --arg forceAlpn "$stream_utls_force_alpn" '. * {
            "tlsConfig": $tlsConfig,
            "imitate": $imitate,
            "noSNI": ($noSNI | test("true")),
            "forceAlpn": $forceAlpn
        }'
    }

    V2rayStreamSocketMark()
    {
        V2raySetStreamSocketMark
    }

    V2rayStreamSocketTFO()
    {
        echo
        inquirer list_input_yn "socket TCP Fast Open 使用系统默认设置" tf_options stream_socket_tfo_system

        if [ "$stream_socket_tfo_system" = false ]
        then
            V2raySetStreamSocketTFO
        fi
    }

    V2rayStreamSocketTFOQL()
    {
        V2raySetStreamSocketTFOQL
    }

    V2rayStreamSocketTproxy()
    {
        V2raySetStreamSocketTproxy
    }

    V2rayStreamSocketTcpKeepAliveInterval()
    {
        V2raySetStreamSocketTcpKeepAliveInterval
    }

    V2rayStreamSocketBindToDevice()
    {
        V2raySetStreamSocketBindToDevice
    }

    V2rayStreamSocketMptcp()
    {
        echo
        inquirer list_input_yn "socket 多路径 TCP 使用系统默认设置" tf_options stream_socket_mptcp_system

        if [ "$stream_socket_mptcp_system" = false ]
        then
            V2raySetStreamSocketMptcp
        fi
    }

    V2rayStreamSocketSettings()
    {
        stream_socket_settings='{}'

        if [ "$dist" != "mac" ]
        then
            V2rayStreamSocketMark

            JQs merge_c stream_socket_settings --arg mark "$stream_socket_mark" '. * {
                "mark": ($mark | tonumber)
            }'
        fi

        V2rayStreamSocketTFO

        if [ "$stream_socket_tfo_system" = false ]
        then
            JQs merge_c stream_socket_settings --arg tcpFastOpen "$stream_socket_tfo" '. * {
                "tcpFastOpen": ($tcpFastOpen | test("true"))
            }'
        fi

        if [ "$dist" != "mac" ]
        then
            V2rayStreamSocketTFOQL
            V2rayStreamSocketTproxy
            V2rayStreamSocketTcpKeepAliveInterval

            JQs merge_c stream_socket_settings --arg tcpFastOpenQueueLength "$stream_socket_tfoql" \
            --arg tproxy "$stream_socket_tproxy" --arg tcpKeepAliveInterval "$stream_socket_tcp_keep_alive_interval" '. * {
                "tcpFastOpenQueueLength": ($tcpFastOpenQueueLength | tonumber),
                "tproxy": $tproxy,
                "tcpKeepAliveInterval": ($tcpKeepAliveInterval | tonumber)
            }'
        fi

        V2rayStreamSocketBindToDevice

        JQs merge_c stream_socket_settings --arg bindToDevice "$stream_socket_bind_to_device" '. * {
            "bindToDevice": $bindToDevice
        }'

        if [ "$dist" != "mac" ]
        then
            V2rayStreamSocketMptcp

            if [ "$stream_socket_mptcp_system" = false ]
            then
                JQs merge_c stream_socket_settings --arg mptcp "$stream_socket_mptcp" '. * {
                    "mptcp": ($mptcp | test("true"))
                }'
            fi
        fi
    }

    V2rayStream()
    {
        V2rayStreamTransport

        stream_transport_settings='{}'

        case $stream_transports_index in
            0) V2rayStreamTcpSettings "$@"
            ;;
            1) V2rayStreamWebSocketSettings "$@"
            ;;
            2) V2rayStreamMkcpSettings "$@"
            ;;
            3) V2rayStreamGrpcSettings "$@"
            ;;
            4) V2rayStreamQuicSettings "$@"
            ;;
            5) V2rayStreamMeekSettings "$@"
            ;;
            6) V2rayStreamHttpupgradeSettings "$@"
            ;;
            7) V2rayStreamHysteria2Settings "$@"
            ;;
            *) return
            ;;
        esac

        V2rayStreamSecurity

        stream_security_settings='{}'

        case $stream_security in
            tls) V2rayStreamTlsSettings
            ;;
            utls)
                if [ "$stream_transports_index" -gt 1 ]
                then
                    Println "$error 仅可以在 TCP, WebSocket 传输方式中使用 uTLS\n"
                fi
                V2rayStreamUtlsSettings
            ;;
            *)
            ;;
        esac

        V2rayStreamSocketSettings

        new_stream='{}'

        JQs merge_c new_stream --arg transport "$stream_transport" \
            --argjson transportSettings "$stream_transport_settings" \
            --arg security "$stream_security" \
            --argjson securitySettings "$stream_security_settings" \
            --argjson socketSettings "$stream_socket_settings" \
        '{
            "transport": $transport,
            "transportSettings": $transportSettings,
            "security": $security,
            "securitySettings": $securitySettings,
            "socketSettings": $socketSettings
        }'
    }

    V2rayInboundProxyProtocol()
    {
        echo
        inbound_proxy_protocols=( 
            vmess
            vless
            vliteu
            http
            socks
            shadowsocks
            dokodemo-door
            trojan
        )
        inbound_proxy_protocol_options=(
            VMess
            VLESS
            VLite
            HTTP
            SOCKS
            Shadowsocks
            Dokodemo
            Trojan
        )
        inquirer list_input_index "选择入站代理协议" inbound_proxy_protocol_options inbound_proxy_protocols_index
        inbound_proxy_protocol="${inbound_proxy_protocols[$inbound_proxy_protocols_index]}"
    }

    V2rayInboundPortValidator()
    {
        if [ "$1" == "$i18n_random" ] || [[ "$1" =~ ^[1-9][0-9]*$ ]] || [[ "$1" =~ ^([1-9][0-9]*)-([1-9][0-9]*)$ ]]
        then
            return 0
        fi

        return 1
    }

    V2rayInboundPort()
    {
        Println "$tip 数值或范围,比如 1234、5-10"
        inquirer text_input "输入入站端口" inbound_port "$i18n_random" V2rayInboundPortValidator

        if [ "$inbound_port" == "$i18n_random" ] 
        then
            inbound_port=$(GetFreePort)
            Println "  入站端口: ${green}$inbound_port${normal}"
        fi
    }

    V2rayInboundListen()
    {
        Println "$tip 填写 Unix domain socket 时, 入站端口将被忽略"
        inquirer text_input "输入入站监听地址" inbound_listen 0.0.0.0
    }

    V2rayInboundTag()
    {
        echo
        inquirer text_input "输入入站标识" inbound_tag "$i18n_random"

        if [ "$inbound_tag" == "$i18n_random" ] 
        then
            local free_tag
            while true 
            do
                free_tag=$(RandStr)
                if ! grep -q '"tag": "'"$free_tag"'"' < "$V2_CONFIG"
                then
                    inbound_tag="$free_tag"
                    break
                fi
            done
            Println "  入站标识: ${green}$inbound_tag${normal}"
        fi
    }

    V2rayInboundSniffingEnabled()
    {
        echo
        inquirer list_input_index "是否开启流量探测" ny_options ny_index

        if [ "$ny_index" -eq 0 ] 
        then
            inbound_sniffing_enabled=false
        else
            inbound_sniffing_enabled=true
        fi
    }

    V2rayInboundSniffingDestOverride()
    {
        inbound_sniffing_dest_override_options=( 'http' 'tls' 'quic' 'fakedns' 'fakedns+others' )

        Println "$tip 当流量为指定类型时，按其中包括的目标地址重置当前连接的目标"
        inquirer checkbox_input "指定流量类型: " inbound_sniffing_dest_override_options inbound_sniffing_dest_override_options_selected

        inbound_sniffing_dest_override=$(JoinByChar , "${inbound_sniffing_dest_override_options_selected[@]}")
    }

    V2rayInboundSniffingMetadataOnly()
    {
        echo
        inquirer list_input_index "仅使用元数据推断目标地址而不截取流量内容" ny_options ny_index

        if [ "$ny_index" -eq 0 ] 
        then
            inbound_sniffing_metadata_only=false
        else
            inbound_sniffing_metadata_only=true
        fi
    }

    V2rayInboundSniffing()
    {
        V2rayInboundSniffingEnabled

        if [ "$inbound_sniffing_enabled" = false ] 
        then
            inbound_sniffing_dest_override=""
            inbound_sniffing_metadata_only=false
            return
        fi

        V2rayInboundSniffingDestOverride
        V2rayInboundSniffingMetadataOnly

        new_sniffing=$(
        $JQ_FILE -n --arg enabled "$sniffing_enabled" \
            --argjson destOverride "[$sniffing_dest_override]" \
            --arg metadataOnly "$sniffing_metadata_only" \
        '{
            "enabled": $enabled | test("true"),
            "destOverride": $destOverride,
            "metadataOnly": $metadataOnly | test("true")
        }')
    }

    V2rayAllocateStrategy()
    {
        echo
        allocate_strategy_options=( 'always' 'random' )
        inquirer list_input "端口分配策略" allocate_strategy_options allocate_strategy
    }

    V2rayAllocateRefresh()
    {
        Println "随机端口刷新间隔(分钟)"
        while read -p "(默认: 5): " allocate_refresh
        do
            case "$allocate_refresh" in
                "")
                    allocate_refresh=5
                    break
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_number [>1]\n"
                ;;
                *)
                    if [ "$allocate_refresh" -ge 2 ]
                    then
                        break
                    else
                        Println "$error $i18n_input_correct_number [>1]\n"
                    fi
                ;;
            esac
        done
        Println "  刷新间隔: ${green} $allocate_refresh ${normal}"
    }

    V2rayAllocateConcurrency()
    {
        Println "随机端口数量, 最大值为端口范围的三分之一"
        while read -p "(默认: 3): " allocate_concurrency
        do
            case "$allocate_concurrency" in
                "")
                    allocate_concurrency=3
                    break
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_number [>0]\n"
                ;;
                *)
                    if [ "$allocate_concurrency" -ge 1 ]
                    then
                        break
                    else
                        Println "$error $i18n_input_correct_number [>0]\n"
                    fi
                ;;
            esac
        done
        Println "  随机端口数量: ${green} $allocate_concurrency ${normal}"
    }

    V2rayInbound()
    {
        V2rayInboundProxyProtocol

        proxy_protocol_settings='{}'

        case $inbound_proxy_protocols_index in
            0) V2rayProxyVmessSettings inbound
            ;;
            1) V2rayProxyVlessSettings inbound
            ;;
            2) V2rayProxyVliteSettings inbound
            ;;
            3) V2rayProxyHttpSettings inbound
            ;;
            4) V2rayProxySocksSettings inbound
            ;;
            5) V2rayProxyShadowsocksSettings inbound
            ;;
            6) V2rayProxyDokodemoSettings inbound
            ;;
            7) V2rayProxyTrojanSettings inbound
            ;;
            *) return
        esac

        V2rayInboundPort
        V2rayInboundListen
        V2rayInboundTag
        V2rayInboundSniffing
        V2rayStream

        new_inbound=$(
        $JQ_FILE -n --arg listen "$inbound_listen" \
            --arg port "$inbound_port" \
            --arg protocol "$inbound_proxy_protocol" \
            --argjson settings "$inbound_settings" \
            --argjson streamSettings "$new_stream" \
            --argjson sniffing "$new_sniffing" \
            --arg tag "$inbound_tag" \
        '{
            "listen": $listen,
            "port": $port | tonumber,
            "protocol": $protocol,
            "settings": $settings,
            "streamSettings": $streamSettings,
            "sniffing": $sniffing,
            "tag": $tag
        }')

        if [[ ! "$port" =~ ^[0-9]+$ ]] && [ "$v2ray_v4" = true ]
        then
            V2rayAllocateStrategy
            if [ "$allocate_strategy" == "random" ] 
            then
                V2rayAllocateRefresh
                V2rayAllocateConcurrency
                JQs merge_c new_inbound --arg strategy "$allocate_strategy" --arg refresh "$allocate_refresh" \
                --arg concurrency "$allocate_concurrency" '. * {
                    "allocate": {
                        "strategy": $strategy,
                        "refresh": $refresh | tonumber,
                        "concurrency": $concurrency | tonumber
                    }
                }'
            fi
        fi

        if [ "$protocol" == "vless" ] || [ "$protocol" == "trojan" ]
        then
            new_inbound=$(
            $JQ_FILE \
            '. * 
            {
                "settings": {
                    "clients": []
                }
            }' <<< "$new_inbound")

            if [ "$protocol" == "vless" ] 
            then
                new_inbound=$(
                $JQ_FILE \
                '. * 
                {
                    "settings": {
                        "decryption":"none"
                    }
                }' <<< "$new_inbound")
            fi

            if { [ "$security" == "tls" ] || [ "$security" == "xtls" ]; } && [ "$network" == "tcp" ] && [[ $tls_alpn == *"http/1.1"* ]]
            then
                V2rayFallbacks

                if [ "$v2ray_fallbacks" != "[]" ] 
                then
                    new_inbound=$(
                    $JQ_FILE --argjson fallbacks "$v2ray_fallbacks" \
                    '. * 
                    {
                        "settings": {
                            "fallbacks":$fallbacks
                        }
                    }' <<< "$new_inbound")
                fi
            fi
        elif [ "$protocol" == "http" ] 
        then
            V2rayTimeout
            V2rayAllowTransparent
            V2rayLevel

            new_inbound=$(
            $JQ_FILE --arg timeout "$timeout" --arg allowTransparent "$allow_transparent" \
            --arg userLevel "$level" \
            '. * 
            {
                "settings": {
                    "timeout": $timeout | tonumber,
                    "accounts": [],
                    "allowTransparent": $allowTransparent | test("true"),
                    "userLevel": $userLevel | tonumber
                }
            }' <<< "$new_inbound")
        elif [ "$protocol" == "socks" ] 
        then
            V2rayLevel
            V2rayAuth
            V2rayUdp

            new_inbound=$(
            $JQ_FILE --arg auth "$auth" --arg udp "$udp" \
            --arg userLevel "$level" \
            '. * 
            {
                "settings": {
                    "auth": $auth,
                    "udp": $udp | test("true"),
                    "userLevel": $userLevel | tonumber
                }
            }' <<< "$new_inbound")

            if [ "$udp" = true ] 
            then
                V2rayIp
                new_inbound=$(
                $JQ_FILE --arg ip "$ip" \
                '. * 
                {
                    "settings": {
                        "ip": $ip
                    }
                }' <<< "$new_inbound")
            fi
        elif [ "$protocol" == "shadowsocks" ] 
        then
            if [ "$v2ray_name" == "xray" ] && [[ $($V2CTL_FILE version | head -1 | cut -d' ' -f2) =~ ([^.]+).([^.]+).([^.]+) ]] && \
            [ "${BASH_REMATCH[1]}" -ge 1 ] && [ "${BASH_REMATCH[2]}" -ge 2 ] && [ "${BASH_REMATCH[3]}" -ge 3 ]
            then
                V2raySettingsNetwork

                new_inbound=$(
                $JQ_FILE --arg network "$settings_network" \
                '. * 
                {
                    "settings": {
                        "clients": [],
                        "network": $network
                    }
                }' <<< "$new_inbound")
            else
                V2rayEmail
                V2rayShadowsocksMethod
                V2rayPassword
                V2rayLevel
                V2raySettingsNetwork

                new_inbound=$(
                $JQ_FILE --arg email "$email" --arg method "$shadowsocks_method" \
                --arg password "$password" --arg level "$level" \
                --arg network "$settings_network" \
                '. * 
                {
                    "settings": {
                        "email": $email,
                        "method": $method,
                        "password": $password,
                        "level": $level | tonumber,
                        "network": $network
                    }
                }' <<< "$new_inbound")

                if [ "$v2ray_name" == "v2ray" ] 
                then
                    V2rayIvCheck

                    new_inbound=$(
                    $JQ_FILE --arg ivCheck "$iv_check" \
                    '. * 
                    {
                        "settings": {
                            "ivCheck": $ivCheck | test("true")
                        }
                    }' <<< "$new_inbound")
                fi
            fi
        elif [ "$protocol" == "dokodemo-door" ] 
        then
            echo
            inquirer list_input "是否用于 api 查询" ny_options yn_option

            if [ "$yn_option" == "$i18n_yes" ] 
            then
                new_inbound=$(
                $JQ_FILE \
                '. * 
                {
                    "settings": {
                        "address": "127.0.0.1",
                    }
                }' <<< "$new_inbound")
            else
                V2raySettingsNetwork
                V2rayTimeout
                V2rayLevel
                V2rayFollowRedirect

                if [ "$follow_redirect" = true ] 
                then
                    new_inbound=$(
                    $JQ_FILE --arg network "$settings_network" --arg timeout "$timeout" \
                    --arg followRedirect "$follow_redirect" --arg userLevel "$level" \
                    '. * 
                    {
                        "settings": {
                            "network": $network,
                            "timeout": $timeout | tonumber,
                            "followRedirect": $followRedirect | test("true"),
                            "userLevel": $userLevel | tonumber
                        }
                    }' <<< "$new_inbound")
                else
                    V2rayAddress
                    V2rayAddressPort

                    new_inbound=$(
                    $JQ_FILE --arg address "$address" --arg port "$address_port" \
                    --arg network "$settings_network" --arg timeout "$timeout" \
                    --arg followRedirect "$follow_redirect" --arg userLevel "$level" \
                    '. * 
                    {
                        "settings": {
                            "address": $address,
                            "port": $port | tonumber,
                            "network": $network,
                            "timeout": $timeout | tonumber,
                            "followRedirect": $followRedirect | test("true"),
                            "userLevel": $userLevel | tonumber
                        }
                    }' <<< "$new_inbound")
                fi
            fi
        fi

        if [ "$network" == "ws" ] 
        then
            V2rayAcceptProxyProtocol
            V2rayPath
            V2rayWsHeaders

            new_inbound=$(
            $JQ_FILE --arg acceptProxyProtocol "$accept_proxy_protocol" \
                --arg path "$path" --argjson headers "{$ws_headers}" \
            '. * 
            {
                "streamSettings": {
                    "wsSettings": {
                        "acceptProxyProtocol": $acceptProxyProtocol | test("true"),
                        "path": $path,
                        "headers": $headers
                    }
                }
            }' <<< "$new_inbound")

            if [ "$v2ray_name" == "v2ray" ] 
            then
                V2rayInboundMaxEarlyData

                if [ "$max_early_data" -gt 0 ] 
                then
                    V2rayEarlyDataHeaderName

                    if [ -n "$early_data_header_name" ] && [ "$early_data_header_name" != "Sec-WebSocket-Protocol" ]
                    then
                        use_browser_forwarding=false
                    else
                        V2rayUseBrowserForwarding
                    fi
                else
                    early_data_header_name=""
                    use_browser_forwarding=false
                fi

                new_inbound=$(
                $JQ_FILE --arg maxEarlyData "$max_early_data" \
                    --arg earlyDataHeaderName "$early_data_header_name" \
                    --arg useBrowserForwarding "$use_browser_forwarding" \
                '. * 
                {
                    "streamSettings": {
                        "wsSettings": {
                            "maxEarlyData": $maxEarlyData | tonumber,
                            "earlyDataHeaderName": $earlyDataHeaderName,
                            "useBrowserForwarding": $useBrowserForwarding | test("true")
                        }
                    }
                }' <<< "$new_inbound")
            fi
        elif [ "$network" == "tcp" ] 
        then
            V2rayAcceptProxyProtocol
            V2rayHeaderType

            new_inbound=$(
            $JQ_FILE --arg acceptProxyProtocol "$accept_proxy_protocol" \
                --arg header_type "$header_type" --argjson request "$header_http_request" \
                --argjson response "$header_http_response" \
            '. * 
            {
                "streamSettings": {
                    "tcpSettings": {
                        "acceptProxyProtocol": $acceptProxyProtocol | test("true"),
                        "header": {
                            "type": $header_type,
                            "request": $request,
                            "response": $response
                        }
                    }
                }
            }' <<< "$new_inbound")
        elif [ "$network" == "kcp" ] 
        then
            V2rayHeaderType
            V2rayKcpMtu
            V2rayKcpTti
            V2rayKcpUplinkCapacity
            V2rayKcpDownlinkCapacity
            V2rayKcpCongestion
            V2rayKcpReadBufferSize
            V2rayKcpWriteBufferSize
            V2rayKcpSeed

            new_inbound=$(
            $JQ_FILE --arg mtu "$kcp_mtu" --arg tti "$kcp_tti" \
                --arg uplinkCapacity "$kcp_uplink_capacity" --arg downlinkCapacity "$kcp_downlink_capacity" \
                --arg congestion "$kcp_congestion" --arg readBufferSize "$kcp_read_buffer_size" \
                --arg writeBufferSize "$kcp_write_buffer_size"  --arg header_type "$header_type" \
                --arg seed "$kcp_seed" \
            '. * 
            {
                "streamSettings": {
                    "kcpSettings": {
                        "mtu": $mtu | tonumber,
                        "tti": $tti | tonumber,
                        "uplinkCapacity": $uplinkCapacity | tonumber,
                        "downlinkCapacity": $downlinkCapacity | tonumber,
                        "congestion": $congestion | test("true"),
                        "readBufferSize": $readBufferSize | tonumber,
                        "writeBufferSize": $writeBufferSize | tonumber,
                        "header": {
                            "type": $header_type
                        },
                        "seed": $seed
                    }
                }
            }' <<< "$new_inbound")
        elif [ "$network" == "http" ] 
        then
            V2rayHttpHost
            V2rayPath
            V2rayHttpHeaders

            new_inbound=$(
            $JQ_FILE --argjson host "[$http_host]" --arg path "$path" \
                --argjson headers "{$http_headers}" \
            '. * 
            {
                "streamSettings": {
                    "httpSettings": {
                        "host": $host,
                        "path": $path,
                        "headers": $headers
                    }
                }
            }' <<< "$new_inbound")

            if [ "$v2ray_name" == "v2ray" ] 
            then
                V2rayHttpMethod

                new_inbound=$(
                $JQ_FILE --arg method "$http_method" \
                '. * 
                {
                    "streamSettings": {
                        "httpSettings": {
                            "method": $method
                        }
                    }
                }' <<< "$new_inbound")
            fi
        elif [ "$network" == "quic" ] 
        then
            V2rayQuicSecurity
            V2rayQuicKey
            V2rayHeaderType

            new_inbound=$(
            $JQ_FILE --arg security "$quic_security" \
                --arg key "$quic_key" --arg header_type "$header_type" \
            '. * 
            {
                "streamSettings": {
                    "quicSettings": {
                        "security": $security,
                        "key": $key,
                        "header": {
                            "type": $header_type
                        }
                    }
                }
            }' <<< "$new_inbound")
        elif [ "$network" == "domainsocket" ] 
        then
            V2rayDsPath
            V2rayDsAbstract
            V2rayDsPadding

            new_inbound=$(
            $JQ_FILE --arg path "$ds_path" \
                --arg abstract "$ds_abstract" --arg padding "$ds_padding" \
            '. * 
            {
                "streamSettings": {
                    "dsSettings": {
                        "path": $ds_path,
                        "abstract": $abstract | test("true"),
                        "padding": $padding | test("true")
                    }
                }
            }' <<< "$new_inbound")
        else
            V2rayGrpcServiceName

            new_inbound=$(
            $JQ_FILE --arg grpcSettings "$grpc_service_name" \
            '. * 
            {
                "streamSettings": {
                    "grpcSettings": {
                        "serviceName": $serviceName
                    }
                }
            }' <<< "$new_inbound")

            if [ "$v2ray_name" == "xray" ] 
            then
                V2rayGrpcMultiMode

                new_inbound=$(
                $JQ_FILE --arg multiMode "$grpc_multi_mode" \
                '. * 
                {
                    "streamSettings": {
                        "grpcSettings": {
                            "multiMode": $multiMode | test("true")
                        }
                    }
                }' <<< "$new_inbound")
            fi
        fi

        jq_path='["inbounds"]'
        JQ add "$V2_CONFIG" "[$new_inbound]"

        Println "$info 入站 $tag 添加成功\n"
    }
    V2rayGetInbounds()
    {
        ProxyLoadInboundsIndex "$V2_CONFIG"

        inbounds_stream_network=()
        inbounds_stream_path=()
        inbounds_stream_tls_server_name=()
        inbounds_stream_tls_certificates_usage=()
        inbounds_stream_tls_certificates_certificate_file=()
        inbounds_stream_tls_certificates_key_file=()
        inbounds_stream_tls_certificates_certificate=()

        if [ ! -s "$V2_CONFIG" ]
        then
            return 0
        fi

        SetDelimiters
        local s_net s_path s_sni s_usage s_cert_file s_key_file s_cert _sentinel
        while IFS="$field_sep" read -r s_net s_path s_sni s_usage s_cert_file s_key_file s_cert _sentinel
        do
            inbounds_stream_network+=("$s_net")
            inbounds_stream_path+=("$s_path")
            inbounds_stream_tls_server_name+=("$s_sni")
            inbounds_stream_tls_certificates_usage+=("$s_usage")
            inbounds_stream_tls_certificates_certificate_file+=("$s_cert_file")
            inbounds_stream_tls_certificates_key_file+=("$s_key_file")
            inbounds_stream_tls_certificates_certificate+=("$s_cert")
        done < <($JQ_FILE -r --arg sep "$field_sep" '
            def obj($x): if ($x | type) == "object" then $x else {} end;
            def arr_objs($x): if ($x | type) == "array" then ($x | map(select(type == "object"))) else [] end;
            (if (.inbounds | type) == "array" then .inbounds else [] end)[]
            | select(type == "object")
            | obj(.streamSettings) as $st
            | obj($st.tlsSettings) as $tls
            | arr_objs($tls.certificates) as $certs
            | [
                ($st.network // "tcp" | tostring),
                (
                    obj($st.wsSettings).path
                    // obj($st.httpSettings).path
                    // obj($st.httpupgradeSettings).path
                    // obj($st.dsSettings).path
                    // ""
                    | tostring
                ),
                ($tls.serverName // "" | tostring),
                ($certs | map(.usage // "encipherment" | tostring) | join("|")),
                ($certs | map(.certificateFile // "" | tostring) | join("|")),
                ($certs | map(.keyFile // "" | tostring) | join("|")),
                ($certs | map(
                    if (.certificate | type) == "array" and (.certificate | length) > 0 then
                        "inline"
                    elif (.certificate | type) == "string" and .certificate != "" then
                        .certificate
                    else
                        ""
                    end
                ) | join("|")),
                "1"
              ]
            | join($sep)
        ' "$V2_CONFIG")
    }
    V2rayListInbounds()
    {
        V2rayGetInbounds

        local list_inbounds_options=( '全部入站' '本地 nginx 入站' '直连 v2ray 入站' )
        local filter_mode="all"
        count=0

        if [ "${1:-}" == "nginx" ]
        then
            list_inbounds_options_index=1
            filter_mode="nginx"
            count=$inbounds_nginx_count
        elif [ "${1:-}" == "direct" ]
        then
            list_inbounds_options_index=2
            filter_mode="direct"
            count=$inbounds_other_count
        else
            echo
            inquirer list_input_index "选择显示的范围" list_inbounds_options list_inbounds_options_index

            if [ "$list_inbounds_options_index" -eq 0 ]
            then
                filter_mode="all"
                count=$inbounds_count
            elif [ "$list_inbounds_options_index" -eq 1 ]
            then
                filter_mode="nginx"
                count=$inbounds_nginx_count
            else
                filter_mode="direct"
                count=$inbounds_other_count
            fi
        fi

        if [ "$count" -eq 0 ]
        then
            if [ "$list_inbounds_options_index" -eq 0 ]
            then
                Println "$error 请先添加入站\n"
            else
                Println "$error 请先添加 ${list_inbounds_options[list_inbounds_options_index]}\n"
            fi
            return 1
        fi

        Println "\n=== ${list_inbounds_options[list_inbounds_options_index]}数 ${green} $count ${normal}"
        inbounds_list=$(ProxyRenderInbounds "$V2_CONFIG" v2ray "$filter_mode")
        Println "$inbounds_list"
    }
    V2raySelectInbound()
    {
        echo "选择入站"
        while read -p "$i18n_default_cancel" inbound_num
        do
            case "$inbound_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$inbound_num" -gt 0 ] && [ "$inbound_num" -le $count ]
                    then
                        inbound_num=$((inbound_num-1))
                        if [ "$list_inbounds_options_index" -eq 0 ] 
                        then
                            inbounds_index=$inbound_num
                        elif [ "$list_inbounds_options_index" -eq 1 ] 
                        then
                            inbounds_index=${inbounds_nginx_index[inbound_num]}
                        else
                            inbounds_index=${inbounds_other_index[inbound_num]}
                        fi
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    }
    V2raySelectAccount()
    {
        echo "选择账号"
        while read -p "$i18n_default_cancel" account_num
        do
            case "$account_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$account_num" -gt 0 ] && [ "$account_num" -le $accounts_count ]
                    then
                        accounts_index=$((account_num-1))
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    }
    V2rayDeleteInbound()
    {
        ProxySelectBound "$V2_CONFIG" inbounds "选择要删除的入站" || return 1
        local target_tag="${inbounds_tag[selected_bound_index]}"
        ProxyDeleteBound "$V2_CONFIG" inbounds "$selected_bound_index"
        ProxyRestartIfActive v2ray
        Println "$info 已删除入站 ${green}${target_tag}${normal}\n"
    }
    V2rayAddInboundAccount()
    {
        ProxySelectBound "$V2_CONFIG" inbounds "选择要添加账号的入站" || return 1
        local idx="$selected_bound_index"
        local protocol="${inbounds_protocol[idx]}"
        local item_json=""

        case "$protocol" in
            vmess)
                local uuid alter_id email level
                inquirer text_input "输入用户 UUID" uuid ""
                inquirer text_input "输入 alterId" alter_id "0"
                inquirer text_input "输入 email (可留空)" email ""
                inquirer text_input "输入 level" level "0"
                JQs build item_json '{"id": $id, "alterId": ($aid | tonumber), "email": $email, "level": ($lvl | tonumber)}' \
                    --arg id "$uuid" --arg aid "$alter_id" --arg email "$email" --arg lvl "$level"
                jq_path='["inbounds",'"$idx"',"settings","clients"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            vless)
                local uuid email level
                inquirer text_input "输入用户 UUID" uuid ""
                inquirer text_input "输入 email (可留空)" email ""
                inquirer text_input "输入 level" level "0"
                JQs build item_json '{"id": $id, "email": $email, "level": ($lvl | tonumber)}' \
                    --arg id "$uuid" --arg email "$email" --arg lvl "$level"
                jq_path='["inbounds",'"$idx"',"settings","clients"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            trojan)
                local pw email level
                inquirer text_input "输入密码" pw ""
                inquirer text_input "输入 email (可留空)" email ""
                inquirer text_input "输入 level" level "0"
                JQs build item_json '{"password": $pw, "email": $email, "level": ($lvl | tonumber)}' \
                    --arg pw "$pw" --arg email "$email" --arg lvl "$level"
                jq_path='["inbounds",'"$idx"',"settings","clients"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            socks|http)
                local user pass
                inquirer text_input "输入用户名" user ""
                inquirer text_input "输入密码" pass ""
                JQs build item_json '{"user": $u, "pass": $p}' --arg u "$user" --arg p "$pass"
                if [ "$protocol" == "socks" ]
                then
                    JQ mutate "$V2_CONFIG" '
                        .inbounds[$i].settings.auth = "password"
                        | .inbounds[$i].settings.accounts = ((.inbounds[$i].settings.accounts // []) + [$item])
                    ' --argjson i "$idx" --argjson item "$item_json"
                else
                    jq_path='["inbounds",'"$idx"',"settings","accounts"]'
                    JQ add "$V2_CONFIG" "[$item_json]"
                fi
            ;;
            *)
                Println "$error 协议 ${protocol} 不支持多账号管理\n"
                return 1
            ;;
        esac

        ProxyRestartIfActive v2ray
        Println "$info 已向入站 ${green}${inbounds_tag[idx]}${normal} 添加账号\n"
    }
    V2rayListInboundAccounts()
    {
        V2rayListInbounds "${1:-}" || return 1

        ProxySelectBound "$V2_CONFIG" inbounds "选择查看账号明细的入站" || return 0
        local idx="$selected_bound_index"
        inbounds_index="$idx"
        local accounts_out
        accounts_out=$(ProxyRenderInboundAccounts "$V2_CONFIG" "$idx")

        if [ -z "$accounts_out" ]
        then
            Println "$info 入站 ${green}${inbounds_tag[idx]}${normal} 没有多账号配置\n"
            return 0
        fi

        Println "\n=== 入站 ${green}${inbounds_tag[idx]}${normal} 账号明细 ===\n$accounts_out\n"
    }
    V2rayListInboundShare()
    {
        local host="${1:-}"
        local only_idx="${2:-${inbounds_index:-}}"
        if [ "$only_idx" == "all" ]
        then
            only_idx=""
        fi

        local links
        links=$(ProxyRenderShareLinks "$V2_CONFIG" "$host" "$only_idx" "v2ray")

        if [ -n "$links" ]
        then
            Println "\n=== V2Ray 分享链接 ===\n$links\n"
            if [ "${3:-}" == "qr" ]
            then
                local first_link
                first_link=$(printf '%s\n' "$links" | head -n 1)
                ProxyPrintQrCode "$first_link"
            fi
        fi
    }
    V2rayDeleteInboundAccount()
    {
        ProxySelectBound "$V2_CONFIG" inbounds "选择要删除账号的入站" || return 1
        local idx="$selected_bound_index"
        local protocol="${inbounds_protocol[idx]}"
        local field="clients"
        if [ "$protocol" == "socks" ] || [ "$protocol" == "http" ]
        then
            field="accounts"
        fi

        local opts=()
        local line
        while IFS= read -r line
        do
            [ -n "$line" ] && opts+=("$line")
        done < <(JQs query "$V2_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].settings | type) == "object"
                and (.inbounds[$i].settings[$f] | type) == "array"
             then .inbounds[$i].settings[$f]
             else [] end)
            | to_entries[]
            | select(.value | type == "object")
            | "\(.key + 1). \(.value.email // .value.id // .value.user // .value.password // "account")"
        ' --argjson i "$idx" --arg f "$field")

        if [ "${#opts[@]}" -eq 0 ]
        then
            Println "$error 该入站没有可删除的账号\n"
            return 1
        fi

        local acc_idx=0
        echo
        inquirer list_input_index "选择要删除的账号" opts acc_idx
        jq_path='["inbounds",'"$idx"',"settings","'"$field"'",'"$acc_idx"']'
        JQ delete "$V2_CONFIG"
        ProxyRestartIfActive v2ray
        Println "$info 已删除账号 ${green}${opts[acc_idx]}${normal}\n"
    }
    V2rayAddOutbound()
    {
        V2raySetOutboundProtocol
        V2raySetTag

        new_outbound=$(
        $JQ_FILE -n --arg protocol "$protocol" --arg tag "$tag" \
        '{
            "protocol": $protocol,
            "tag": $tag
        }')

        if [ "$protocol" != "blackhole" ]
        then
            V2raySetSendThrough
            new_outbound=$(
            $JQ_FILE --arg sendThrough "$send_through" \
            '. * 
            {
                "sendThrough": $sendThrough,
            }' <<< "$new_outbound")
        fi

        if [ "$protocol" != "blackhole" ] && [ "$protocol" != "dns" ]
        then
            V2raySetMuxEnabled
            V2raySetMuxConcurrency
            new_outbound=$(
            $JQ_FILE --arg enabled "$mux_enabled" --arg concurrency "$mux_concurrency" \
            '. * 
            {
                "mux": {
                    "enabled": $enabled | test("true"),
                    "concurrency": $concurrency | tonumber
                }
            }' <<< "$new_outbound")
        fi

        if [ "$protocol" == "vmess" ] || [ "$protocol" == "vless" ]
        then
            V2raySetAddress
            V2raySetAddressPort
            new_outbound=$(
            $JQ_FILE --arg address "$address" --arg port "$address_port" \
            '. * 
            {
                "settings": {
                    "vnext" : [
                        {
                            "address": $address,
                            "port": $port | tonumber,
                            "users": []
                        }
                    ]
                }
            }' <<< "$new_outbound")
        elif [ "$protocol" == "http" ] || [ "$protocol" == "socks" ]
        then
            V2raySetAddress
            V2raySetAddressPort

            new_outbound=$(
            $JQ_FILE --arg address "$address" --arg port "$address_port" \
            '. * 
            {
                "settings": {
                    "servers" : [
                        {
                            "address": $address,
                            "port": $port | tonumber,
                            "users": []
                        }
                    ]
                }
            }' <<< "$new_outbound")

            if [ "$v2ray_name" == "v2ray" ] && [ "$protocol" == "socks" ]
            then
                V2raySetSocksVersion

                new_outbound=$(
                $JQ_FILE --arg version "$socks_version" \
                '. * 
                {
                    "settings": {
                        "version" : $version
                    }
                }' <<< "$new_outbound")
            fi
        elif [ "$protocol" == "shadowsocks" ] 
        then
            V2raySetEmail
            V2raySetAddress
            V2raySetAddressPort
            V2raySetShadowsocksMethod
            V2raySetPassword
            V2raySetLevel

            if [ "$v2ray_name" == "v2ray" ] 
            then
                V2raySetIvCheck

                new_outbound=$(
                $JQ_FILE --arg email "$email" --arg address "$address" \
                --arg port "$address_port" --arg method "$shadowsocks_method" \
                --arg password "$password" --arg level "$level" \
                --arg ivCheck "$iv_check" \
                '. * 
                {
                    "settings": {
                        "servers": [
                            {
                                "email": $email,
                                "address": $address,
                                "port": $port | tonumber,
                                "method": $method,
                                "password": $password,
                                "level": $level | tonumber,
                                "ivCheck": $ivCheck | test("true")
                            }
                        ]
                    }
                }' <<< "$new_outbound")
            else
                new_outbound=$(
                $JQ_FILE --arg email "$email" --arg address "$address" \
                --arg port "$address_port" --arg method "$shadowsocks_method" \
                --arg password "$password" --arg level "$level" \
                '. * 
                {
                    "settings": {
                        "servers": [
                            {
                                "email": $email,
                                "address": $address,
                                "port": $port | tonumber,
                                "method": $method,
                                "password": $password,
                                "level": $level | tonumber
                            }
                        ]
                    }
                }' <<< "$new_outbound")
            fi
        elif [ "$protocol" == "trojan" ] 
        then
            new_outbound=$(
            $JQ_FILE \
            '. * 
            {
                "settings": {
                    "servers" : []
                }
            }' <<< "$new_outbound")
        elif [ "$protocol" == "blackhole" ] 
        then
            V2raySetResponseType
            new_outbound=$(
            $JQ_FILE --arg response_type "$response_type" \
            '. * 
            {
                "settings": {
                    "type": $response_type
                }
            }' <<< "$new_outbound")
        elif [ "$protocol" == "dns" ] 
        then
            V2raySetDnsNetwork
            V2raySetDnsAddress
            V2raySetDnsPort
            if [ -n "$dns_network" ] 
            then
                new_outbound=$(
                $JQ_FILE --arg network "$dns_network" \
                '. * 
                {
                    "settings": {
                        "network": $network
                    }
                }' <<< "$new_outbound")
            fi
            if [ -n "$dns_address" ] 
            then
                new_outbound=$(
                $JQ_FILE --arg address "$dns_address" \
                '. * 
                {
                    "settings": {
                        "address": $address
                    }
                }' <<< "$new_outbound")
            fi
            if [ -n "$dns_port" ] 
            then
                new_outbound=$(
                $JQ_FILE --arg port "$dns_port" \
                '. * 
                {
                    "settings": {
                        "port": $port | tonumber
                    }
                }' <<< "$new_outbound")
            fi
        elif [ "$protocol" == "freedom" ] 
        then
            V2raySetFreedomDomainStrategy
            V2raySetFreedomRedirect
            V2raySetLevel
            new_outbound=$(
            $JQ_FILE --arg domainStrategy "$freedom_domain_strategy" --arg userLevel "$level" \
            '. * 
            {
                "settings": {
                    "domainStrategy": $domainStrategy,
                    "userLevel": $userLevel | tonumber
                }
            }' <<< "$new_outbound")
            if [ -n "$freedom_redirect" ] 
            then
                new_outbound=$(
                $JQ_FILE --arg redirect "$freedom_redirect" \
                '. * 
                {
                    "settings": {
                        "redirect": ${red}irect
                    }
                }' <<< "$new_outbound")
            fi
        fi

        if [ "$v2ray_name" == "xray" ] 
        then
            V2raySetSockoptDialerProxy

            if [ -z "$sockopt_dialer_proxy" ] 
            then
                V2raySetProxyTag
            fi
        else
            V2raySetProxyTag
        fi

        if [ -n "${sockopt_dialer_proxy:-}" ] 
        then
            new_outbound=$(
            $JQ_FILE --arg dialerProxy "$sockopt_dialer_proxy" \
            '. * 
            {
                "streamSettings": {
                    "sockopt": {
                        "dialerProxy": $dialerProxy
                    }
                }
            }' <<< "$new_outbound")
        elif [ -n "${proxy_tag:-}" ] 
        then
            new_outbound=$(
            $JQ_FILE --arg tag "$proxy_tag" \
            '. * 
            {
                "proxySettings": {
                    "tag": $tag
                }
            }' <<< "$new_outbound")

            if [ "$v2ray_name" == "v2ray" ] 
            then
                V2raySetProxyTransportLayer

                new_outbound=$(
                $JQ_FILE --arg transportLayer "$transport_layer" \
                '. * 
                {
                    "proxySettings": {
                        "transportLayer": $transportLayer | test("true")
                    }
                }' <<< "$new_outbound")
            fi
        elif [ "$protocol" != "blackhole" ] && [ "$protocol" != "dns" ] && [ "$protocol" != "freedom" ]
        then
            V2raySetSockoptMark
            V2raySetOutboundSockoptTcpFastOpen

            if [ "$v2ray_name" == "xray" ] 
            then
                V2raySetSockoptDomainStrategy

                new_outbound=$(
                $JQ_FILE --arg mark "$sockopt_mark" --arg tcpFastOpen "$sockopt_tfo" \
                    --arg domainStrategy "$sockopt_domain_strategy" \
                '. * 
                {
                    "streamSettings": {
                        "sockopt": {
                            "mark": $mark | tonumber,
                            "tcpFastOpen": $tcpFastOpen | test("true"),
                            "domainStrategy": $domainStrategy
                        }
                    }
                }' <<< "$new_outbound")
            else
                V2raySetSockoptTcpKeepAliveInterval

                new_outbound=$(
                $JQ_FILE --arg mark "$sockopt_mark" --arg tcpFastOpen "$sockopt_tfo" \
                    --arg tcpKeepAliveInterval "$sockopt_tcp_keep_alive_interval" \
                '. * 
                {
                    "streamSettings": {
                        "sockopt": {
                            "mark": $mark | tonumber,
                            "tcpFastOpen": $tcpFastOpen | test("true"),
                            "tcpKeepAliveInterval": $tcpKeepAliveInterval | tonumber
                        }
                    }
                }' <<< "$new_outbound")
            fi

            V2raySetOutboundNetwork
            V2raySetSecurity

            new_outbound=$(
            $JQ_FILE --arg network "$network" --arg security "$security" \
            '. * 
            {
                "streamSettings": {
                    "network": $network,
                    "security": $security
                }
            }' <<< "$new_outbound")

            if [ "$network" == "ws" ] 
            then
                V2raySetPath
                V2raySetWsHeaders

                new_outbound=$(
                $JQ_FILE --arg path "$path" --argjson headers "{$ws_headers}" \
                '. * 
                {
                    "streamSettings": {
                        "wsSettings": {
                            "path": $path,
                            "headers": $headers
                        }
                    }
                }' <<< "$new_outbound")

                if [ "$v2ray_name" == "v2ray" ] 
                then
                    V2raySetOutboundMaxEarlyData

                    if [ "$max_early_data" -gt 0 ] 
                    then
                        V2raySetEarlyDataHeaderName

                        if [ -n "$early_data_header_name" ] && [ "$early_data_header_name" != "Sec-WebSocket-Protocol" ]
                        then
                            use_browser_forwarding=false
                        else
                            V2raySetUseBrowserForwarding
                        fi
                    else
                        early_data_header_name=""
                        use_browser_forwarding=false
                    fi

                    new_outbound=$(
                    $JQ_FILE --arg maxEarlyData "$max_early_data" \
                        --arg earlyDataHeaderName "$early_data_header_name" \
                        --arg useBrowserForwarding "$use_browser_forwarding" \
                    '. * 
                    {
                        "streamSettings": {
                            "wsSettings": {
                                "maxEarlyData": $maxEarlyData | tonumber,
                                "earlyDataHeaderName": $earlyDataHeaderName,
                                "useBrowserForwarding": $useBrowserForwarding | test("true")
                            }
                        }
                    }' <<< "$new_outbound")
                fi
            elif [ "$network" == "tcp" ] 
            then
                V2raySetHeaderType

                new_outbound=$(
                $JQ_FILE --arg header_type "$header_type" --argjson request "$header_http_request" \
                --argjson response "$header_http_response" \
                '. * 
                {
                    "streamSettings": {
                        "tcpSettings": {
                            "header": {
                                "type": $header_type,
                                "request": $request,
                                "response": $response
                            }
                        }
                    }
                }' <<< "$new_outbound")
            elif [ "$network" == "kcp" ] 
            then
                V2raySetHeaderType
                V2raySetKcpMtu
                V2raySetKcpTti
                V2raySetKcpUplinkCapacity
                V2raySetKcpDownlinkCapacity
                V2raySetKcpCongestion
                V2raySetKcpReadBufferSize
                V2raySetKcpWriteBufferSize
                V2raySetKcpSeed

                new_outbound=$(
                $JQ_FILE --arg mtu "$kcp_mtu" --arg tti "$kcp_tti" \
                    --arg uplinkCapacity "$kcp_uplink_capacity" --arg downlinkCapacity "$kcp_downlink_capacity" \
                    --arg congestion "$kcp_congestion" --arg readBufferSize "$kcp_read_buffer_size" \
                    --arg writeBufferSize "$kcp_write_buffer_size"  --arg header_type "$header_type" \
                    --arg seed "$kcp_seed" \
                '. * 
                {
                    "streamSettings": {
                        "kcpSettings": {
                            "mtu": $mtu | tonumber,
                            "tti": $tti | tonumber,
                            "uplinkCapacity": $uplinkCapacity | tonumber,
                            "downlinkCapacity": $downlinkCapacity | tonumber,
                            "congestion": $congestion | test("true"),
                            "readBufferSize": $readBufferSize | tonumber,
                            "writeBufferSize": $writeBufferSize | tonumber,
                            "header": {
                                "type": $header_type
                            },
                            "seed": $seed
                        }
                    }
                }' <<< "$new_outbound")
            elif [ "$network" == "http" ] 
            then
                V2raySetHttpHost
                V2raySetPath
                V2raySetHttpHeaders

                new_outbound=$(
                $JQ_FILE --argjson host "[$http_host]" --arg path "$path" \
                    --argjson headers "{$http_headers}" \
                '. * 
                {
                    "streamSettings": {
                        "httpSettings": {
                            "host": $host,
                            "path": $path,
                            "headers": $headers
                        }
                    }
                }' <<< "$new_outbound")

                if [ "$v2ray_name" == "v2ray" ] 
                then
                    V2raySetHttpMethod

                    new_outbound=$(
                    $JQ_FILE --arg method "$http_method" \
                    '. * 
                    {
                        "streamSettings": {
                            "httpSettings": {
                                "method": $method
                            }
                        }
                    }' <<< "$new_outbound")
                fi
            elif [ "$network" == "quic" ] 
            then
                V2raySetQuicSecurity
                V2raySetQuicKey
                V2raySetHeaderType

                new_outbound=$(
                $JQ_FILE --arg security "$quic_security" \
                    --arg key "$quic_key" --arg header_type "$header_type" \
                '. * 
                {
                    "streamSettings": {
                        "quicSettings": {
                            "security": $security,
                            "key": $key,
                            "header": {
                                "type": $header_type
                            }
                        }
                    }
                }' <<< "$new_outbound")
            else
                V2raySetGrpcServiceName

                new_outbound=$(
                $JQ_FILE --arg grpcSettings "$grpc_service_name" \
                '. * 
                {
                    "streamSettings": {
                        "grpcSettings": {
                            "serviceName": $serviceName
                        }
                    }
                }' <<< "$new_outbound")

                if [ "$v2ray_name" == "xray" ] 
                then
                    V2raySetGrpcMultiMode

                    new_outbound=$(
                    $JQ_FILE --arg multiMode "$grpc_multi_mode" \
                    '. * 
                    {
                        "streamSettings": {
                            "grpcSettings": {
                                "multiMode": $multiMode | test("true")
                            }
                        }
                    }' <<< "$new_outbound")
                fi
            fi

            if [ "$security" == "tls" ] 
            then
                V2raySetTlsServerName

                if [ -n "$tls_server_name" ] 
                then
                    new_outbound=$(
                    $JQ_FILE --arg serverName "$tls_server_name" \
                    '. * 
                    {
                        "streamSettings": {
                            "tlsSettings": {
                                "serverName": $serverName
                            }
                        }
                    }' <<< "$new_outbound")
                fi

                V2raySetTlsAllowInsecure
                V2raySetTlsAlpn
                V2raySetTlsDisableSystemRoot

                new_outbound=$(
                $JQ_FILE --arg allowInsecure "$tls_allow_insecure" --argjson alpn "[$tls_alpn]" \
                    --arg disableSystemRoot "$tls_disable_system_root" \
                '. * 
                {
                    "streamSettings": {
                        "tlsSettings": {
                            "allowInsecure": $allowInsecure | test("true"),
                            "alpn": $alpn,
                            "disableSystemRoot": $disableSystemRoot | test("true")
                        }
                    }
                }' <<< "$new_outbound")

                V2raySetTlsPinnedPeerCertificateChainSha256

                if [ -n "$tls_pinned_peer_certificate_chain_sha256" ] 
                then
                    new_outbound=$(
                    $JQ_FILE --arg pinnedPeerCertificateChainSha256 "$tls_pinned_peer_certificate_chain_sha256" \
                    '. * 
                    {
                        "streamSettings": {
                            "tlsSettings": {
                                "pinnedPeerCertificateChainSha256": $pinnedPeerCertificateChainSha256
                            }
                        }
                    }' <<< "$new_outbound")
                fi

                while true 
                do
                    if [ "$tls_disable_system_root" = false ] 
                    then
                        echo
                        inquirer list_input "是否继续添加证书" ny_options continue_yn
                        if [ "$continue_yn" == "$i18n_no" ] 
                        then
                            break
                        fi
                    fi
                    Println "$info 设置证书"
                    V2raySetCertificates
                    merge=$(
                    $JQ_FILE -n --argjson certificates "[$certificate]" \
                    '{
                        "streamSettings": {
                            "tlsSettings": {
                                "certificates": $certificates
                            }
                        }
                    }')
                    JQs merge new_outbound "$merge"
                    if [ "$tls_disable_system_root" = true ] 
                    then
                        echo
                        inquirer list_input "是否继续添加证书" ny_options continue_yn
                        if [ "$continue_yn" == "$i18n_no" ] 
                        then
                            break
                        fi
                    fi
                done
            elif [ "$security" == "xtls" ] 
            then
                V2raySetTlsServerName

                if [ -n "$tls_server_name" ] 
                then
                    new_outbound=$(
                    $JQ_FILE --arg serverName "$tls_server_name" \
                    '. * 
                    {
                        "streamSettings": {
                            "xtlsSettings": {
                                "serverName": $serverName
                            }
                        }
                    }' <<< "$new_outbound")
                fi

                V2raySetTlsAllowInsecure
                V2raySetTlsAlpn
                V2raySetTlsDisableSystemRoot
                V2raySetTlsEnableSessionResumption
                V2raySetTlsFingerprint

                new_outbound=$(
                $JQ_FILE --arg allowInsecure "$tls_allow_insecure" \
                --argjson alpn "[$tls_alpn]" --arg disableSystemRoot "$tls_disable_system_root" \
                --arg enableSessionResumption "[$tls_enable_session_resumption]" --arg fingerprint "$tls_fingerprint" \
                '. * 
                {
                    "streamSettings": {
                        "xtlsSettings": {
                            "allowInsecure": $allowInsecure | test("true"),
                            "alpn": $alpn,
                            "disableSystemRoot": $disableSystemRoot | test("true"),
                            "enableSessionResumption": $enableSessionResumption | test("true"),
                            "fingerprint": $fingerprint
                        }
                    }
                }' <<< "$new_outbound")

                while true 
                do
                    if [ "$tls_disable_system_root" = false ] 
                    then
                        echo
                        inquirer list_input "是否继续添加证书" ny_options continue_yn
                        if [ "$continue_yn" == "$i18n_no" ] 
                        then
                            break
                        fi
                    fi
                    Println "$info 设置证书"
                    V2raySetCertificates
                    merge=$(
                    $JQ_FILE -n --argjson certificates "[$certificate]" \
                    '{
                        "streamSettings": {
                            "xtlsSettings": {
                                "certificates": $certificates
                            }
                        }
                    }')
                    JQs merge new_outbound "$merge"
                    if [ "$tls_disable_system_root" = true ] 
                    then
                        echo
                        inquirer list_input "是否继续添加证书" ny_options continue_yn
                        if [ "$continue_yn" == "$i18n_no" ] 
                        then
                            break
                        fi
                    fi
                done
            fi
        fi

        jq_path='["outbounds"]'
        JQ add "$V2_CONFIG" "[$new_outbound]"

        Println "$info 出站 $tag 添加成功\n"
    }
    V2rayGetOutbounds()
    {
        ProxyLoadOutboundsIndex "$V2_CONFIG"
    }
    V2rayListOutbounds()
    {
        V2rayGetOutbounds

        if [ "$outbounds_count" -eq 0 ]
        then
            Println "$error 没有出站\n"
            return 1
        fi

        Println "\n=== 出站数 ${green} $outbounds_count ${normal}"
        outbounds_list=$(ProxyRenderOutbounds "$V2_CONFIG" v2ray)
        Println "$outbounds_list"
    }
    V2raySelectOutbound()
    {
        echo -e "选择出站"
        while read -p "$i18n_default_cancel" outbound_num
        do
            case "$outbound_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$outbound_num" -gt 0 ] && [ "$outbound_num" -le $outbounds_count ]
                    then
                        outbounds_index=$((outbound_num-1))
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    }
    V2rayDeleteOutbound()
    {
        ProxySelectBound "$V2_CONFIG" outbounds "选择要删除的出站" || return 1
        local target_tag="${outbounds_tag[selected_bound_index]}"
        ProxyDeleteBound "$V2_CONFIG" outbounds "$selected_bound_index"
        ProxyRestartIfActive v2ray
        Println "$info 已删除出站 ${green}${target_tag}${normal}\n"
    }
    V2rayAddOutboundAccount()
    {
        ProxySelectBound "$V2_CONFIG" outbounds "选择要添加服务端/用户的出站" || return 1
        local idx="$selected_bound_index"
        local protocol="${outbounds_protocol[idx]}"
        local item_json=""

        case "$protocol" in
            vmess)
                local addr port uuid alter_id sec
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                inquirer text_input "用户 UUID" uuid ""
                inquirer text_input "alterId" alter_id "0"
                inquirer text_input "加密方式 security" sec "auto"
                JQs build item_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "users": [{"id": $id, "alterId": ($aid | tonumber), "security": $sec}]
                }' --arg addr "$addr" --arg port "$port" --arg id "$uuid" --arg aid "$alter_id" --arg sec "$sec"
                jq_path='["outbounds",'"$idx"',"settings","vnext"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            vless)
                local addr port uuid enc
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                inquirer text_input "用户 UUID" uuid ""
                inquirer text_input "encryption" enc "none"
                JQs build item_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "users": [{"id": $id, "encryption": $enc}]
                }' --arg addr "$addr" --arg port "$port" --arg id "$uuid" --arg enc "$enc"
                jq_path='["outbounds",'"$idx"',"settings","vnext"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            trojan)
                local addr port pw email
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                inquirer text_input "密码 password" pw ""
                inquirer text_input "email (可留空)" email ""
                JQs build item_json '{"address": $addr, "port": ($port | tonumber), "password": $pw, "email": $email}' \
                    --arg addr "$addr" --arg port "$port" --arg pw "$pw" --arg email "$email"
                jq_path='["outbounds",'"$idx"',"settings","servers"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            shadowsocks)
                local addr port method pw email
                local iv_opts=( '默认(不设置)' '关闭' '开启' )
                local iv_idx=0
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "8388"
                inquirer text_input "加密方式 method" method "aes-256-gcm"
                inquirer text_input "密码 password" pw ""
                inquirer text_input "email (可留空)" email ""
                inquirer list_input_index "启用 IV 检查 ivCheck (可选)" iv_opts iv_idx
                JQs build item_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "method": $m,
                    "password": $pw,
                    "email": $email,
                    "ivCheck": (if $iv == "2" then true elif $iv == "1" then false else null end)
                }' --arg addr "$addr" --arg port "$port" --arg m "$method" --arg pw "$pw" --arg email "$email" --arg iv "$iv_idx"
                jq_path='["outbounds",'"$idx"',"settings","servers"]'
                JQ add "$V2_CONFIG" "[$item_json]"
            ;;
            *)
                Println "$error 出站协议 ${protocol} 不支持添加服务端账号\n"
                return 1
            ;;
        esac

        ProxyRestartIfActive v2ray
        Println "$info 已向出站 ${green}${outbounds_tag[idx]}${normal} 添加服务端/账号\n"
    }
    V2rayListOutboundAccounts()
    {
        V2rayListOutbounds || return 1

        ProxySelectBound "$V2_CONFIG" outbounds "选择查看账号/服务端明细的出站" || return 0
        local idx="$selected_bound_index"
        outbounds_index="$idx"
        local accounts_out
        accounts_out=$(ProxyRenderOutboundAccounts "$V2_CONFIG" "$idx")

        if [ -z "$accounts_out" ]
        then
            Println "$info 出站 ${green}${outbounds_tag[idx]}${normal} 没有账号/服务端明细\n"
            return 0
        fi

        Println "\n=== 出站 ${green}${outbounds_tag[idx]}${normal} 账号/服务端明细 ===\n$accounts_out\n"
    }
    V2rayDeleteOutboundAccount()
    {
        ProxySelectBound "$V2_CONFIG" outbounds "选择要删除服务端/账号的出站" || return 1
        local idx="$selected_bound_index"
        local protocol="${outbounds_protocol[idx]}"
        local field="servers"
        if [ "$protocol" == "vmess" ] || [ "$protocol" == "vless" ]
        then
            field="vnext"
        fi

        local opts=()
        local line
        while IFS= read -r line
        do
            [ -n "$line" ] && opts+=("$line")
        done < <(JQs query "$V2_CONFIG" '
            (if (.outbounds | type) == "array" and (.outbounds[$i] | type) == "object"
                and (.outbounds[$i].settings | type) == "object"
                and (.outbounds[$i].settings[$f] | type) == "array"
             then .outbounds[$i].settings[$f]
             else [] end)
            | to_entries[]
            | select(.value | type == "object")
            | "\(.key + 1). \(.value.address // ""):\(.value.port // "")"
        ' --argjson i "$idx" --arg f "$field")

        if [ "${#opts[@]}" -eq 0 ]
        then
            Println "$error 该出站没有可删除的服务端/账号\n"
            return 1
        fi

        local srv_idx=0
        echo
        inquirer list_input_index "选择要删除的服务端/账号" opts srv_idx
        jq_path='["outbounds",'"$idx"',"settings","'"$field"'",'"$srv_idx"']'
        JQ delete "$V2_CONFIG"
        ProxyRestartIfActive v2ray
        Println "$info 已删除服务端 ${green}${opts[srv_idx]}${normal}\n"
    }
    V2rayGetRouting()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$V2_CONFIG" '.routing')

        jq_path='[
            ["domainStrategy"],
            ["domainMatcher"],
            ["rules","domainMatcher"],
            ["rules","type"],
            ["rules","domains"],
            ["rules","ip"],
            ["rules","port"],
            ["rules","sourcePort"],
            ["rules","network"],
            ["rules","source"],
            ["rules","user"],
            ["rules","inboundTag"],
            ["rules","protocol"],
            ["rules","attrs"],
            ["rules","outboundTag"],
            ["rules","balancerTag"],
            ["balancers","tag"],
            ["balancers","selector"],
            ["balancers","strategy","type"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="jq_routing_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        routing_domainStrategy="${jq_routing_domainStrategy:-AsIs}"
        routing_domainMatcher="${jq_routing_domainMatcher:-mph}"

        if [ -z "${jq_routing_balancers_tag:-}" ]
        then
            routing_balancers_count=0
        else
            IFS="${delimiters[2]}" read -r -a routing_balancers_tag <<< "$jq_routing_balancers_tag"
            IFS="${delimiters[2]}" read -r -a routing_balancers_selector <<< "$jq_routing_balancers_selector"
            IFS="${delimiters[3]}" read -r -a routing_balancers_strategy_type <<< "$jq_routing_balancers_strategy_type"

            routing_balancers_count=${#routing_balancers_tag[@]}
        fi

        if [ -z "${jq_routing_rules_type:-}" ]
        then
            routing_rules_count=0
            return 0
        fi

        IFS="${delimiters[1]}" read -r -a routing_domainStrategy <<< "$jq_routing_domainStrategy"
        IFS="${delimiters[1]}" read -r -a routing_domainMatcher <<< "$jq_routing_domainMatcher"
        IFS="${delimiters[2]}" read -r -a routing_rules_domainMatcher <<< "$jq_routing_rules_domainMatcher"
        IFS="${delimiters[2]}" read -r -a routing_rules_type <<< "$jq_routing_rules_type"
        IFS="${delimiters[2]}" read -r -a routing_rules_domains <<< "$jq_routing_rules_domains"
        IFS="${delimiters[2]}" read -r -a routing_rules_ip <<< "$jq_routing_rules_ip"
        IFS="${delimiters[2]}" read -r -a routing_rules_port <<< "$jq_routing_rules_port"
        IFS="${delimiters[2]}" read -r -a routing_rules_sourcePort <<< "$jq_routing_rules_sourcePort"
        IFS="${delimiters[2]}" read -r -a routing_rules_network <<< "$jq_routing_rules_network"
        IFS="${delimiters[2]}" read -r -a routing_rules_source <<< "$jq_routing_rules_source"
        IFS="${delimiters[2]}" read -r -a routing_rules_user <<< "$jq_routing_rules_user"
        IFS="${delimiters[2]}" read -r -a routing_rules_inboundTag <<< "$jq_routing_rules_inboundTag"
        IFS="${delimiters[2]}" read -r -a routing_rules_protocol <<< "$jq_routing_rules_protocol"
        IFS="${delimiters[2]}" read -r -a routing_rules_attrs <<< "$jq_routing_rules_attrs"
        IFS="${delimiters[2]}" read -r -a routing_rules_outboundTag <<< "$jq_routing_rules_outboundTag"
        IFS="${delimiters[2]}" read -r -a routing_rules_balancerTag <<< "$jq_routing_rules_balancerTag"

        routing_rules_count=${#routing_rules_type[@]}

    }
    V2rayListRouting()
    {
        local out
        out=$(ProxyRenderRouting "$V2_CONFIG" v2ray)
        if [ -z "$out" ]
        then
            Println "$error 未配置路由\n"
            return 1
        fi
        Println "\n=== V2Ray 路由配置 ===\n$out\n"
    }
    V2raySetRouting()
    {
        local actions=(
            '添加路由规则'
            '添加负载均衡器'
            '设置 domainStrategy/domainMatcher'
            '删除路由规则'
            '删除负载均衡器'
            '设置规则级 domainMatcher'
        )
        local action_idx=0
        echo
        inquirer list_input_index "选择 V2Ray 路由操作" actions action_idx

        case "$action_idx" in
            0)
                local mode_opts=( '快捷路由 (选择入站 -> 出站)' '自定义路由规则' )
                local mode_idx=0
                inquirer list_input_index "选择添加路由方式" mode_opts mode_idx

                if [ "$mode_idx" -eq 0 ]
                then
                    ProxySelectBound "$V2_CONFIG" inbounds "选择匹配的入站" || return 1
                    local in_tag="${inbounds_tag[selected_bound_index]}"
                    if [ -z "$in_tag" ]
                    then
                        Println "$error 此入站没有标签\n"
                        return 1
                    fi
                    ProxySelectBound "$V2_CONFIG" outbounds "选择转发目标出站" || return 1
                    local out_tag="${outbounds_tag[selected_bound_index]}"
                    if [ -z "$out_tag" ]
                    then
                        Println "$error 此出站没有标签\n"
                        return 1
                    fi
                    local rule_json=""
                    JQs build rule_json '{"type": "field", "inboundTag": [$it], "outboundTag": $ot}' --arg it "$in_tag" --arg ot "$out_tag"
                    jq_path='["routing","rules"]'
                    JQ add "$V2_CONFIG" "[$rule_json]"
                    Println "$info 快捷路由添加成功: ${green}${in_tag} => ${out_tag}${normal}\n"
                else
                    local net_opts=( 'tcp,udp' 'tcp' 'udp' '不限' )
                    local net_choice=""
                    inquirer list_input "选择匹配的连接方式 network" net_opts net_choice
                    [ "$net_choice" == "不限" ] && net_choice=""

                    local domains ips port src_port source users attrs inb_tag out_tag bal_tag
                    inquirer text_input "匹配 domains (逗号分隔, 可留空)" domains ""
                    inquirer text_input "匹配 ip (逗号分隔, 可留空)" ips ""
                    inquirer text_input "匹配目标 port (可留空)" port ""
                    inquirer text_input "匹配来源 sourcePort (可留空)" src_port ""
                    inquirer text_input "匹配来源 source (逗号分隔, 可留空)" source ""
                    inquirer text_input "匹配用户 user (逗号分隔, 可留空)" users ""

                    local proto_opts=( 'http' 'tls' 'bittorrent' )
                    local proto_sel=()
                    inquirer checkbox_input "选择匹配的流量协议 protocol (可留空)" proto_opts proto_sel
                    local proto_csv=""
                    if [ "${#proto_sel[@]}" -gt 0 ] && [ -n "${proto_sel[0]:-}" ]
                    then
                        proto_csv=$(JoinByChar , "${proto_sel[@]}")
                    fi

                    inquirer text_input "匹配属性 attrs (可留空)" attrs ""
                    inquirer text_input "匹配 inboundTag (逗号分隔, 可留空)" inb_tag ""
                    inquirer text_input "目标 outboundTag (与 balancerTag 二选一)" out_tag ""
                    inquirer text_input "目标 balancerTag (可留空)" bal_tag ""

                    if [ -z "$out_tag" ] && [ -z "$bal_tag" ]
                    then
                        Println "$error outboundTag 与 balancerTag 不能同时为空\n"
                        return 1
                    fi

                    local rule_dm="${rule_domain_matcher:-}"
                    if [ -n "$rule_dm" ] && [ "$rule_dm" != "linear" ] && [ "$rule_dm" != "mph" ]
                    then
                        Println "$error 规则级 domainMatcher 仅支持 linear 或 mph: ${rule_dm}\n"
                        return 1
                    fi

                    local rule_json=""
                    JQs build rule_json '
                        def csv: split(",") | map(gsub("^[ \t]+|[ \t]+$"; "")) | map(select(. != ""));
                        {
                            "type": "field",
                            "domainMatcher": $rdm,
                            "network": $net,
                            "domains": (if $dom != "" then ($dom | csv) else null end),
                            "ip": (if $ip != "" then ($ip | csv) else null end),
                            "port": $port,
                            "sourcePort": $sport,
                            "source": (if $src != "" then ($src | csv) else null end),
                            "user": (if $usr != "" then ($usr | csv) else null end),
                            "protocol": (if $proto != "" then ($proto | csv) else null end),
                            "attrs": $attrs,
                            "inboundTag": (if $itag != "" then ($itag | csv) else null end),
                            "outboundTag": $otag,
                            "balancerTag": $btag
                        }' --arg rdm "$rule_dm" --arg net "$net_choice" --arg dom "$domains" --arg ip "$ips" \
                        --arg port "$port" --arg sport "$src_port" --arg src "$source" \
                        --arg usr "$users" --arg proto "$proto_csv" --arg attrs "$attrs" \
                        --arg itag "$inb_tag" --arg otag "$out_tag" --arg btag "$bal_tag"

                    jq_path='["routing","rules"]'
                    JQ add "$V2_CONFIG" "[$rule_json]"
                    Println "$info 已添加 V2Ray 路由规则\n"
                fi
            ;;
            1)
                local strat_opts=( 'random' 'leastPing' )
                local b_tag b_sel b_strat
                inquirer text_input "Balancer tag" b_tag ""
                inquirer text_input "selector (逗号分隔)" b_sel ""
                inquirer list_input "选择策略 strategy.type" strat_opts b_strat

                local bal_json=""
                JQs build bal_json '
                    def csv: split(",") | map(gsub("^[ \t]+|[ \t]+$"; "")) | map(select(. != ""));
                    {
                        "tag": $tag,
                        "selector": ($sel | csv),
                        "strategy": {"type": $st}
                    }' --arg tag "$b_tag" --arg sel "$b_sel" --arg st "$b_strat"

                jq_path='["routing","balancers"]'
                JQ add "$V2_CONFIG" "[$bal_json]"
                Println "$info 已添加 V2Ray 负载均衡 ${green}${b_tag}${normal}\n"
            ;;
            2)
                local ds_opts=( 'AsIs' 'IPIfNonMatch' 'IPOnDemand' )
                local dm_opts=( 'linear' 'mph' )
                local ds="" dm="" strat_json=""
                inquirer list_input "选择域名解析策略 domainStrategy" ds_opts ds
                inquirer list_input "选择域名匹配算法 domainMatcher" dm_opts dm
                JQs build strat_json '{"domainStrategy": $ds, "domainMatcher": $dm}' --arg ds "$ds" --arg dm "$dm"
                jq_merge=true
                jq_path='["routing"]'
                JQ update "$V2_CONFIG" "$strat_json"
                Println "$info 已更新 V2Ray 路由策略\n"
            ;;
            3)
                local rule_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && rule_opts+=("$line")
                done < <(JQs query "$V2_CONFIG" 'if (.routing | type) == "object" and (.routing.rules | type) == "array" then (.routing.rules | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.outboundTag // .value.balancerTag // "rule")") else empty end')
                if [ "${#rule_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的路由规则\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的路由规则" rule_opts del_idx
                jq_path='["routing","rules",'"$del_idx"']'
                JQ delete "$V2_CONFIG"
                Println "$info 已删除路由规则: ${green}${rule_opts[$del_idx]}${normal}\n"
            ;;
            4)
                local bal_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && bal_opts+=("$line")
                done < <(JQs query "$V2_CONFIG" 'if (.routing | type) == "object" and (.routing.balancers | type) == "array" then (.routing.balancers | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.tag // "balancer")") else empty end')
                if [ "${#bal_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的负载均衡器\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的负载均衡器" bal_opts del_idx
                jq_path='["routing","balancers",'"$del_idx"']'
                JQ delete "$V2_CONFIG"
                Println "$info 已删除负载均衡器: ${green}${bal_opts[$del_idx]}${normal}\n"
            ;;
            5)
                local rule_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && rule_opts+=("$line")
                done < <(JQs query "$V2_CONFIG" 'if (.routing | type) == "object" and (.routing.rules | type) == "array" then (.routing.rules | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.outboundTag // .value.balancerTag // "rule")") else empty end')
                if [ "${#rule_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可设置的路由规则\n"
                    return 1
                fi
                local rule_idx=0
                inquirer list_input_index "选择要设置 domainMatcher 的路由规则" rule_opts rule_idx
                local rdm_opts=( 'linear' 'mph' '清除' )
                local rdm_choice=""
                inquirer list_input "选择规则级 domainMatcher" rdm_opts rdm_choice
                if [ "$rdm_choice" == "清除" ]
                then
                    JQ mutate "$V2_CONFIG" 'del(.routing.rules[$i].domainMatcher)' --argjson i "$rule_idx"
                else
                    JQ mutate "$V2_CONFIG" '.routing.rules[$i].domainMatcher = $dm' --argjson i "$rule_idx" --arg dm "$rdm_choice"
                fi
                Println "$info 已更新规则级 domainMatcher: ${green}${rdm_choice}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive v2ray
    }
    V2raySetPolicy()
    {
        local actions=(
            '添加/修改用户等级策略'
            '删除用户等级策略'
            '设置入站上行流量统计'
            '设置入站下行流量统计'
            '设置出站上行流量统计'
            '设置出站下行流量统计'
        )
        local action_idx=0
        echo
        inquirer list_input_index "选择 V2Ray 策略操作" actions action_idx

        local sw_opts=( '关闭' '开启' )

        case "$action_idx" in
            0)
                local lvl hs ci uo do_s buf
                local up_idx=1 dn_idx=1
                inquirer text_input "用户等级 level (留空自动分配)" lvl ""
                if [ -z "$lvl" ]
                then
                    lvl=$(JQs query "$V2_CONFIG" '((if (.policy | type) == "object" then (if (.policy.levels | type) == "object" then .policy.levels elif (.policy.level | type) == "object" then .policy.level else {} end) else {} end) | keys | map(tonumber?) | max // -1) + 1')
                    lvl="${lvl:-0}"
                fi
                inquirer text_input "handshake (秒)" hs "4"
                inquirer text_input "connIdle (秒)" ci "300"
                inquirer text_input "uplinkOnly (秒)" uo "2"
                inquirer text_input "downlinkOnly (秒)" do_s "5"
                inquirer text_input "bufferSize (KB)" buf "512"
                inquirer list_input_index "用户上行流量统计 statsUserUplink" sw_opts up_idx
                inquirer list_input_index "用户下行流量统计 statsUserDownlink" sw_opts dn_idx

                local num_val
                for num_val in "$lvl" "$hs" "$ci" "$uo" "$do_s" "$buf"
                do
                    if ! [[ "$num_val" =~ ^[0-9]+$ ]]
                    then
                        Println "$error 策略数值参数必须为非负整数: ${num_val}\n"
                        return 1
                    fi
                done

                if ! JQ mutate "$V2_CONFIG" '.policy.levels = ((.policy.levels // .policy.level // {}) * {
                    ($lvl): {
                        "handshake": ($hs | tonumber),
                        "connIdle": ($ci | tonumber),
                        "uplinkOnly": ($uo | tonumber),
                        "downlinkOnly": ($do_s | tonumber),
                        "bufferSize": ($buf | tonumber),
                        "statsUserUplink": ($up == "1"),
                        "statsUserDownlink": ($dn == "1")
                    }
                }) | del(.policy.level)' \
                    --arg lvl "$lvl" --arg hs "$hs" --arg ci "$ci" --arg uo "$uo" --arg do_s "$do_s" \
                    --arg buf "$buf" --arg up "$up_idx" --arg dn "$dn_idx"
                then
                    Println "$error 更新等级 ${lvl} 策略失败\n"
                    return 1
                fi
                Println "$info 已更新等级 ${green}${lvl}${normal} 策略\n"
            ;;
            1)
                local lvls=()
                local k
                while IFS= read -r k
                do
                    [ -n "$k" ] && lvls+=("$k")
                done < <(JQs query "$V2_CONFIG" '(if (.policy | type) == "object" then (if (.policy.levels | type) == "object" then .policy.levels elif (.policy.level | type) == "object" then .policy.level else {} end) else {} end) | keys[]')
                if [ "${#lvls[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的用户等级策略\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的用户等级" lvls del_idx
                local del_lvl="${lvls[$del_idx]}"
                if ! JQ mutate "$V2_CONFIG" 'del(.policy.level[$k], .policy.levels[$k])' --arg k "$del_lvl"
                then
                    Println "$error 删除等级 ${del_lvl} 策略失败\n"
                    return 1
                fi
                Println "$info 已删除等级 ${green}${del_lvl}${normal} 策略\n"
            ;;
            2|3|4|5)
                local sys_keys=( '' '' 'statsInboundUplink' 'statsInboundDownlink' 'statsOutboundUplink' 'statsOutboundDownlink' )
                local sys_key="${sys_keys[$action_idx]}"
                local sw_idx=1 sw_bool=false
                inquirer list_input_index "设置 ${sys_key}" sw_opts sw_idx
                [ "$sw_idx" -eq 1 ] && sw_bool=true
                jq_bool=true
                jq_path='["policy","system","'"$sys_key"'"]'
                if ! JQ update "$V2_CONFIG" "$sw_bool"
                then
                    Println "$error 更新系统策略 ${sys_key} 失败\n"
                    return 1
                fi
                Println "$info 已更新系统策略 ${green}${sys_key}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive v2ray
    }
    V2rayGetReverse()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$V2_CONFIG" '.reverse')

        jq_path='[
            ["bridges","tag"],
            ["bridges","domain"],
            ["portals","tag"],
            ["portals","domain"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="jq_reverse_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        if [ -z "${jq_reverse_bridges_tag:-}" ]
        then
            reverse_bridges_count=0
        else
            IFS="${delimiters[2]}" read -r -a reverse_bridges_tag <<< "$jq_reverse_bridges_tag"
            IFS="${delimiters[2]}" read -r -a reverse_bridges_domain <<< "$jq_reverse_bridges_domain"
            reverse_bridges_count=${#reverse_bridges_tag[@]}
        fi

        if [ -z "${jq_reverse_portals_tag:-}" ]
        then
            reverse_portals_count=0
        else
            IFS="${delimiters[2]}" read -r -a reverse_portals_tag <<< "$jq_reverse_portals_tag"
            IFS="${delimiters[2]}" read -r -a reverse_portals_domain <<< "$jq_reverse_portals_domain"
            reverse_portals_count=${#reverse_portals_tag[@]}
        fi
    }
    V2rayListReverse()
    {
        local out
        out=$(ProxyRenderReverse "$V2_CONFIG" v2ray)
        if [ -z "$out" ]
        then
            Println "$error 未配置反向代理\n"
            return 1
        fi
        Println "\n=== V2Ray 反向代理配置 ===\n$out\n"
    }
    V2raySetReverse()
    {
        local actions=( '添加 Bridge' '添加 Portal' '删除 Bridge' '删除 Portal' )
        local action_idx=0
        echo
        inquirer list_input_index "选择 V2Ray 反向代理操作" actions action_idx

        case "$action_idx" in
            0|1)
                local r_tag r_domain item_json=""
                inquirer text_input "输入 tag" r_tag ""
                inquirer text_input "输入 domain" r_domain ""
                JQs build item_json '{"tag": $t, "domain": $d}' --arg t "$r_tag" --arg d "$r_domain"
                if [ "$action_idx" -eq 0 ]
                then
                    jq_path='["reverse","bridges"]'
                    JQ add "$V2_CONFIG" "[$item_json]"
                    Println "$info 已添加 Bridge ${green}${r_tag}${normal}\n"
                else
                    jq_path='["reverse","portals"]'
                    JQ add "$V2_CONFIG" "[$item_json]"
                    Println "$info 已添加 Portal ${green}${r_tag}${normal}\n"
                fi
            ;;
            2|3)
                local r_key="bridges"
                [ "$action_idx" -eq 3 ] && r_key="portals"
                local r_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && r_opts+=("$line")
                done < <(JQs query "$V2_CONFIG" 'if (.reverse | type) == "object" and (.reverse[$k] | type) == "array" then (.reverse[$k] | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.tag // "") (\(.value.domain // ""))") else empty end' --arg k "$r_key")
                if [ "${#r_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的 ${r_key}\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的 ${r_key}" r_opts del_idx
                jq_path='["reverse","'"$r_key"'",'"$del_idx"']'
                JQ delete "$V2_CONFIG"
                Println "$info 已删除 ${r_key}: ${green}${r_opts[$del_idx]}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive v2ray
    }
    V2rayGetDns()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$V2_CONFIG" '.dns')

        jq_path='["hosts"]'

        dns_hosts_domain=()
        dns_hosts_address=()

        while IFS="^" read -r dns_host_domain dns_host_address; do
            dns_hosts_domain+=("$dns_host_domain")
            dns_hosts_address+=("$dns_host_address")
        done < <(JQs get jq_payload '. // {} | to_entries[] | "\(.key)^\(.value)"')

        dns_hosts_count="${#dns_hosts_domain[@]}"

        jq_path='[
            ["servers"],
            ["clientIp"],
            ["queryStrategy"],
            ["disableCache"],
            ["disableFallback"],
            ["disableFallbackIfMatch"],
            ["tag"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="jq_dns_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        dns_clientIp="${jq_dns_clientIp:-}"
        dns_queryStrategy="${jq_dns_queryStrategy:-UseIP}"
        dns_disableCache="${jq_dns_disableCache:-false}"
        dns_disableFallback="${jq_dns_disableFallback:-false}"
        dns_disableFallbackIfMatch="${jq_dns_disableFallbackIfMatch:-false}"
        dns_tag="${jq_dns_tag:-dns_inbound}"

        if [ -z "${jq_dns_servers:-}" ]
        then
            dns_servers_count=0
            return 0
        fi

        IFS="${delimiters[1]}" read -r -a dns_servers <<< "$jq_dns_servers"

        dns_servers_count=${#dns_servers[@]}
    }
    V2rayListDns()
    {
        local out
        out=$(ProxyRenderDns "$V2_CONFIG" v2ray)
        if [ -z "$out" ]
        then
            Println "$error 未配置 DNS\n"
            return 1
        fi
        Println "\n=== V2Ray DNS 配置 ===\n$out\n"
    }
    V2raySetDns()
    {
        local actions=(
            '添加静态 IP (hosts)'
            '添加 DNS 服务器'
            '设置 clientIp'
            '设置 DNS 标识 tag'
            '设置 queryStrategy'
            '设置缓存与回退开关'
            '删除静态 IP (hosts)'
            '删除 DNS 服务器'
        )
        local action_idx=0
        echo
        inquirer list_input_index "选择 V2Ray DNS 操作" actions action_idx

        case "$action_idx" in
            0)
                local domain ips
                Println "$tip 格式如 v2fly.org, domain:v2fly.org, geosite:cn"
                inquirer text_input "输入域名或规则" domain ""
                inquirer text_input "输入目标 IP/域名 (逗号分隔)" ips ""
                JQ mutate "$V2_CONFIG" '
                    def trim: gsub("^[ \t]+|[ \t]+$"; "");
                    .dns.hosts = ((.dns.hosts // {}) + {
                        ($d | trim): (
                            if ($v | contains(",")) then
                                ($v | split(",") | map(trim) | map(select(. != "")))
                            else
                                ($v | trim)
                            end
                        )
                    })' --arg d "$domain" --arg v "$ips"
                Println "$info 静态 IP 添加成功: ${green}${domain}${normal}\n"
            ;;
            1)
                local addr port client_ip domains expect_ips
                local skip_fb_opts=( '否' '是' )
                local skip_fb_idx=0
                inquirer text_input "输入 DNS 地址 (如 1.1.1.1, https://...)" addr "1.1.1.1"
                inquirer text_input "输入端口 (留空默认)" port ""
                inquirer text_input "输入服务器级 clientIp (可留空)" client_ip ""
                inquirer text_input "输入匹配 domains (逗号分隔, 可留空)" domains ""
                inquirer text_input "输入 expectIPs (逗号分隔, 可留空)" expect_ips ""
                inquirer list_input_index "跳过回退 skipFallback" skip_fb_opts skip_fb_idx

                if [ -n "$port" ] && { ! [[ "$port" =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]; }
                then
                    Println "$error DNS 端口必须为 1-65535 的整数: ${port}\n"
                    return 1
                fi

                local srv_json=""
                if [ -z "$port" ] && [ -z "$client_ip" ] && [ -z "$domains" ] && [ -z "$expect_ips" ] && [ "$skip_fb_idx" -eq 0 ]
                then
                    JQs build srv_json '$addr' --arg addr "$addr"
                else
                    JQs build srv_json '
                        def csv: split(",") | map(gsub("^[ \t]+|[ \t]+$"; "")) | map(select(. != ""));
                        {
                            "address": $addr,
                            "port": (if $port != "" then ($port | tonumber) else null end),
                            "clientIp": $cip,
                            "domains": (if $dom != "" then ($dom | csv) else null end),
                            "expectIPs": (if $eip != "" then ($eip | csv) else null end),
                            "skipFallback": (if $sf == "1" then true else null end)
                        }' --arg addr "$addr" --arg port "$port" --arg cip "$client_ip" --arg dom "$domains" \
                        --arg eip "$expect_ips" --arg sf "$skip_fb_idx"
                fi
                jq_path='["dns","servers"]'
                JQ add "$V2_CONFIG" "[$srv_json]"
                Println "$info DNS 服务器添加成功: ${green}${addr}${normal}\n"
            ;;
            2)
                local cip
                inquirer text_input "输入全局 clientIp (留空清除)" cip ""
                jq_path='["dns","clientIp"]'
                if [ -z "$cip" ]
                then
                    JQ delete "$V2_CONFIG"
                else
                    JQ update "$V2_CONFIG" "$cip"
                fi
                Println "$info DNS clientIp 设置成功\n"
            ;;
            3)
                local dtag
                inquirer text_input "输入 DNS 标识 tag" dtag "dns_inbound"
                jq_path='["dns","tag"]'
                JQ update "$V2_CONFIG" "$dtag"
                Println "$info DNS tag 设置成功: ${green}${dtag}${normal}\n"
            ;;
            4)
                local qs_options=( 'UseIP' 'UseIPv4' 'UseIPv6' )
                local qs=""
                inquirer list_input "选择 DNS 查询策略 queryStrategy" qs_options qs
                jq_path='["dns","queryStrategy"]'
                JQ update "$V2_CONFIG" "$qs"
                Println "$info queryStrategy 已设置为 ${green}${qs}${normal}\n"
            ;;
            5)
                local yn_opts=( '否' '是' )
                local dc_idx=0 df_idx=0 dfm_idx=0
                inquirer list_input_index "禁用缓存 disableCache" yn_opts dc_idx
                inquirer list_input_index "禁用回退 disableFallback" yn_opts df_idx
                inquirer list_input_index "匹配时不回退 disableFallbackIfMatch" yn_opts dfm_idx

                JQ mutate "$V2_CONFIG" '.dns = ((.dns // {}) * {
                    "disableCache": ($dc == "1"),
                    "disableFallback": ($df == "1"),
                    "disableFallbackIfMatch": ($dfm == "1")
                })' --arg dc "$dc_idx" --arg df "$df_idx" --arg dfm "$dfm_idx"
                Println "$info V2Ray DNS 全局开关已更新\n"
            ;;
            6)
                local host_keys=()
                local k
                while IFS= read -r k
                do
                    [ -n "$k" ] && host_keys+=("$k")
                done < <(JQs query "$V2_CONFIG" 'if (.dns | type) == "object" and (.dns.hosts | type) == "object" then (.dns.hosts | keys[]) else empty end')
                if [ "${#host_keys[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的静态 IP\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的静态 IP" host_keys del_idx
                local del_key="${host_keys[$del_idx]}"
                JQ mutate "$V2_CONFIG" 'del(.dns.hosts[$k])' --arg k "$del_key"
                Println "$info 已删除静态 IP: ${green}${del_key}${normal}\n"
            ;;
            7)
                local srv_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && srv_opts+=("$line")
                done < <(JQs query "$V2_CONFIG" 'if (.dns | type) == "object" and (.dns.servers | type) == "array" then (.dns.servers | to_entries[] | "\(.key + 1). \(if (.value | type) == "string" then .value elif (.value | type) == "object" then (.value.address // "server") else "server" end)") else empty end')
                if [ "${#srv_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的 DNS 服务器\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的 DNS 服务器" srv_opts del_idx
                jq_path='["dns","servers",'"$del_idx"']'
                JQ delete "$V2_CONFIG"
                Println "$info 已删除 DNS 服务器: ${green}${srv_opts[$del_idx]}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive v2ray
    }
    V2rayGetStats()
    {
        local api_tag="" m_api_services=""
        SetDelimiters
        IFS="$field_sep" read -r api_tag m_api_services < <(JQs query "$V2_CONFIG" '
            (if type == "object" and (.api | type) == "object" then .api else {} end) as $a
            | [
                ($a.tag // "" | tostring),
                (if ($a.services | type) == "array" then ($a.services | map(tostring) | join("|")) else "" end)
              ]
            | join($sep)
        ' --arg sep "$field_sep")

        if [ -z "$api_tag" ] || [ -z "$m_api_services" ]
        then
            JQ mutate "$V2_CONFIG" '
                .stats = (.stats // {})
                | .api = ((if (.api | type) == "object" then .api else {} end) * {
                    "tag": (.api.tag // "api"),
                    "services": ((if (.api.services | type) == "array" then .api.services else [] end) + ["StatsService"] | unique)
                  })'
            api_tag="${api_tag:-api}"
        elif [[ "|${m_api_services}|" != *"|StatsService|"* ]]
        then
            JQ mutate "$V2_CONFIG" '.api.services = ((if (.api.services | type) == "array" then .api.services else [] end) + ["StatsService"] | unique)'
        fi

        V2rayGetRouting

        if [ "$routing_rules_count" -eq 0 ]
        then
            Println "$error 请先添加一个路由: 入站协议为 dokodemo-door (需要创建此协议的入站), 出站标签是 $api_tag (不用创建出站)\n"
            exit 1
        fi

        local routing_rule_found=0
        local i
        api_inbound_tag=""
        for((i=0;i<routing_rules_count;i++));
        do
            if [ "${routing_rules_outboundTag[i]:-}" == "$api_tag" ]
            then
                routing_rule_found=1
                api_inbound_tag="${routing_rules_inboundTag[i]%%${delimiters[3]}*}"
                break
            fi
        done

        if [ "$routing_rule_found" -eq 0 ] || [ -z "${api_inbound_tag:-}" ]
        then
            Println "$error 请先添加协议为 dokodemo-door 的入站路由到标签是 $api_tag 的出站\n"
            exit 1
        fi

        V2rayListPolicy
        V2rayGetInbounds

        api_inbound_listen=""
        api_inbound_port=""
        for((i=0;i<inbounds_count;i++));
        do
            if [ "${inbounds_tag[i]}" == "$api_inbound_tag" ]
            then
                if [ "${inbounds_listen[i]}" == "0.0.0.0" ]
                then
                    api_inbound_listen="127.0.0.1"
                else
                    api_inbound_listen="${inbounds_listen[i]}"
                fi
                api_inbound_port="${inbounds_port[i]}"
                break
            fi
        done

        if [ -z "${api_inbound_listen:-}" ]
        then
            Println "$error 标签为 $api_inbound_tag 的入站不存在?\n"
            exit 1
        fi
    }
    V2rayGetTraffic()
    {
        local raw_out=""
        if [ -x "${V2CTL_FILE:-}" ]
        then
            raw_out=$("$V2CTL_FILE" api --server="$api_inbound_listen:$api_inbound_port" StatsService.GetStats 'name: "'"$1"'>>>'"$2"'>>>traffic>>>'"$3"'" reset: false' 2> /dev/null)
        elif [ -x "${V2_FILE:-}" ]
        then
            raw_out=$("$V2_FILE" api stats --server="$api_inbound_listen:$api_inbound_port" --name="$1>>>$2>>>traffic>>>$3" 2> /dev/null)
        else
            Println "$error 未找到 v2ctl 或 v2ray 可执行文件\n" >&2
            return 1
        fi

        local line val=""
        while IFS= read -r line
        do
            if [[ "$line" =~ value:[[:space:]]*([0-9]+) ]]
            then
                val="${BASH_REMATCH[1]}"
                break
            elif [[ "$line" =~ \"value\":[[:space:]]*\"?([0-9]+)\"? ]]
            then
                val="${BASH_REMATCH[1]}"
                break
            fi
        done <<< "$raw_out"

        if [ -n "$val" ]
        then
            echo "$val" | numfmt --to=iec --suffix=B
        fi
        return 0
    }
    V2rayListStats()
    {
        V2rayGetStats

        stats_list=""

        for((i=0;i<inbounds_count;i++));
        do
            stats_list="$stats_list入站标签: ${green}${inbounds_tag[i]}${normal} "
            if [ "$policy_system_stats_inbound_uplink" = true ] 
            then
                stats_list="$stats_list上行流量: ${green}$(V2rayGetTraffic inbound ${inbounds_tag[i]} uplink)${normal} "
            else
                stats_list="$stats_list上行流量: ${red}关闭${normal} "
            fi
            if [ "$policy_system_stats_inbound_downlink" = true ] 
            then
                stats_list="$stats_list下行流量: ${green}$(V2rayGetTraffic inbound ${inbounds_tag[i]} downlink)${normal}\n\n"
            else
                stats_list="$stats_list下行流量: ${red}关闭${normal}\n\n"
            fi
        done

        V2rayGetOutbounds
        for((i=0;i<outbounds_count;i++));
        do
            if [ -n "${outbounds_tag[i]}" ] 
            then
                stats_list="$stats_list出站标签: ${green}${outbounds_tag[i]}${normal} "
                if [ "$policy_system_stats_outbound_uplink" = true ] 
                then
                    stats_list="$stats_list上行流量: ${green}$(V2rayGetTraffic outbound ${outbounds_tag[i]} uplink)${normal} "
                else
                    stats_list="$stats_list上行流量: ${red}关闭${normal} "
                fi
                if [ "$policy_system_stats_outbound_downlink" = true ] 
                then
                    stats_list="$stats_list下行流量: ${green}$(V2rayGetTraffic outbound ${outbounds_tag[i]} downlink)${normal}\n\n"
                else
                    stats_list="$stats_list下行流量: ${red}关闭${normal}\n\n"
                fi
            fi
        done

        Println "$stats_list"

        echo
        inquirer list_input "查看特定用户的流量" ny_options continue_yn
        if [ "$continue_yn" == "$i18n_no" ] 
        then
            echo
        else
            V2rayListInboundAccounts

            if [ "${inbounds_protocol[inbounds_index]}" == "http" ] 
            then
                Println "$error 用户没有邮箱, 不会开启统计\n"
                exit 1
            elif [ "${inbounds_protocol[inbounds_index]}" == "shadowsocks" ] 
            then
                for((i=0;i<policy_levels_count;i++));
                do
                    if [ "${policy_levels_id[i]}" == "${inbounds_settings_user_level[inbounds_index]}" ] 
                    then
                        if [ "${policy_levels_stats_user_uplink[i]}" = false ] 
                        then
                            Println "上行流量: ${red}关闭${normal}"
                        else
                            Println "上行流量: ${green}$(V2rayGetTraffic user ${inbounds_settings_email[inbounds_index]} uplink)${normal}"
                        fi
                        if [ "${policy_levels_stats_user_downlink[i]}" = false ] 
                        then
                            Println "下行流量: ${red}关闭${normal}\n"
                        else
                            Println "下行流量: ${green}$(V2rayGetTraffic user ${inbounds_settings_email[inbounds_index]} downlink)${normal}\n"
                        fi
                        break
                    fi
                done
                exit 0
            fi

            V2raySelectAccount

            for((i=0;i<policy_levels_count;i++));
            do
                if [ "${policy_levels_id[i]}" == "${accounts_level[accounts_index]}" ] 
                then
                    if [ "${policy_levels_stats_user_uplink[i]}" = false ] 
                    then
                        Println "上行流量: ${red}关闭${normal}"
                    else
                        Println "上行流量: ${green}$(V2rayGetTraffic user ${accounts_email[accounts_index]} uplink)${normal}"
                    fi
                    if [ "${policy_levels_stats_user_downlink[i]}" = false ] 
                    then
                        Println "下行流量: ${red}关闭${normal}\n"
                    else
                        Println "下行流量: ${green}$(V2rayGetTraffic user ${accounts_email[accounts_index]} downlink)${normal}\n"
                    fi
                    break
                fi
            done
        fi
    }
    V2rayResetStats()
    {
        V2rayGetStats
        ExitOnList n "`gettext \"将重置所有的流量统计\"`"
        if [ -x "${V2CTL_FILE:-}" ]
        then
            "$V2CTL_FILE" api --server="$api_inbound_listen:$api_inbound_port" StatsService.QueryStats 'pattern: "" reset: true'
        elif [ -x "${V2_FILE:-}" ]
        then
            "$V2_FILE" api statsquery --server="$api_inbound_listen:$api_inbound_port" --pattern="" --reset
        else
            Println "$error 未找到 v2ctl 或 v2ray 可执行文件\n"
            return 1
        fi
    }
    V2rayListInboundDomains()
    {
        v2ray_domains_inbound_list=""
        v2ray_domains_inbound_count=0
        v2ray_domains_inbound=()
        v2ray_domains_inbound_https_port=()

        if ls -A "$nginx_prefix/conf/sites_available/"* > /dev/null 2>&1
        then
            for f in "$nginx_prefix/conf/sites_available/"*
            do
                domain=${f##*/}
                domain=${domain%.conf}
                if [ -e "$nginx_prefix/conf/sites_enabled/$domain.conf" ] 
                then
                    v2ray_status_text="${green}开启${normal}"
                else
                    v2ray_status_text="${red}关闭${normal}"
                fi
                if [[ $domain =~ ^([a-zA-Z0-9](([a-zA-Z0-9-]){0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$ ]] || grep -q "proxy_pass http://127.0.0.1:${inbounds_port[inbounds_index]}" < "$nginx_prefix/conf/sites_available/$domain.conf" 
                then
                    server_found=0
                    server_flag=0
                    while IFS= read -r line 
                    do
                        if [[ $line == *"server {"* ]] 
                        then
                            server_found=1
                            server_ports=""
                            is_inbound=0
                        fi

                        if [[ $server_found -eq 1 ]] && [[ $line == *"{"* ]]
                        then
                            server_flag=$((server_flag+1))
                        fi

                        if [[ $server_found -eq 1 ]] && [[ $line == *"}"* ]]
                        then
                            server_flag=$((server_flag-1))
                            if [[ $server_flag -eq 0 ]] 
                            then
                                server_found=0
                                if [[ $is_inbound -eq 1 ]]
                                then
                                    v2ray_domains_inbound_count=$((v2ray_domains_inbound_count+1))
                                    v2ray_domains_inbound+=("$domain")
                                    v2ray_domains_inbound_https_port+=("$server_ports")
                                    v2ray_domains_inbound_list="$v2ray_domains_inbound_list${green}$v2ray_domains_inbound_count.${normal}${indent_6}域名: ${green}$domain${normal} nginx 端口: ${green}$server_ports${normal} nginx 路径: ${green}${inbounds_stream_path[inbounds_index]}${normal} 状态: $v2ray_status_text\n\n"
                                fi
                            fi
                        fi

                        if [[ $server_found -eq 1 ]] && [[ $line == *"listen "* ]]
                        then
                            line=${line#*listen }
                            line=${line% ssl;*}
                            Trim line
                            [ -n "$server_ports" ] && server_ports="$server_ports, "
                            server_ports="$server_ports${line:0:-1}"
                        fi

                        if [[ $server_found -eq 1 ]] && [[ $line == *"proxy_pass http://127.0.0.1:${inbounds_port[inbounds_index]}"* ]]
                        then
                            is_inbound=1
                        fi
                    done < "$nginx_prefix/conf/sites_available/$domain.conf"
                else
                    continue
                fi
            done
        fi
        Println "绑定的${green}域名列表:${normal}\n\n${v2ray_domains_inbound_list:-无}\n"
    }
    V2rayDomainUpdateCert()
    {
        local domain=$1

        if [ "$ca_server" == "letsencrypt" ] && [ -f /etc/systemd/system/mmproxy-acme.service ] && [[ $(systemctl is-active mmproxy-acme) == "active" ]]
        then
            if [ -z "${tls_port:-}" ] 
            then
                tls_port=$(grep ^ExecStart= < /etc/systemd/system/mmproxy-acme.service)
                if [[ $tls_port =~ -4\ 127.0.0.1:([^ ]+) ]] 
                then
                    tls_port=${BASH_REMATCH[1]}
                else
                    tls_port=${tls_port#*-4 }
                    tls_port=${tls_port#*:}
                    tls_port=${tls_port%% *}
                fi
            fi

            ~/.acme.sh/acme.sh --force --issue --alpn --tlsport "$tls_port" -d "$domain" --standalone -k ec-256 --server "$ca_server" > /dev/null
            ~/.acme.sh/acme.sh --force --installcert -d "$domain" --fullchainpath "/usr/local/share/$v2ray_name/$domain.crt" --keypath "/usr/local/share/$v2ray_name/$domain.key" --ecc > /dev/null
        else
            stopped=0

            if [ -d "$nginx_prefix" ] 
            then
                if [[ $(systemctl is-active $nginx_name) == "active" ]]
                then
                    if [[ $(echo $SSH_CONNECTION | cut -d' ' -f3) == "127.0.0.1" ]] 
                    then
                        Println "$error 请使用非 $nginx_name 监听端口连接 ssh 后重试\n"
                        exit 1
                    fi
                    systemctl stop $nginx_name
                    stopped=1
                fi

                sleep 1
            fi

            ~/.acme.sh/acme.sh --force --issue -d "$domain" --standalone -k ec-256 --server "$ca_server" > /dev/null
            ~/.acme.sh/acme.sh --force --installcert -d "$domain" --fullchainpath "/usr/local/share/$v2ray_name/$domain.crt" --keypath "/usr/local/share/$v2ray_name/$domain.key" --ecc > /dev/null

            [ "$stopped" -eq 1 ] && systemctl start $nginx_name
        fi

        if [ -e "/usr/local/nginx/conf/sites_crt/$domain.crt" ] 
        then
            cp -f "/usr/local/share/$v2ray_name/$domain.crt" "/usr/local/nginx/conf/sites_crt/$domain.crt"
            cp -f "/usr/local/share/$v2ray_name/$domain.key" "/usr/local/nginx/conf/sites_crt/$domain.key"
        fi

        if [ -e "/usr/local/openresty/nginx/conf/sites_crt/$domain.crt" ] 
        then
            cp -f "/usr/local/share/$v2ray_name/$domain.crt" "/usr/local/openresty/nginx/conf/sites_crt/$domain.crt"
            cp -f "/usr/local/share/$v2ray_name/$domain.key" "/usr/local/openresty/nginx/conf/sites_crt/$domain.key"
        fi

        return 0
    }
    V2rayNginxListDomains()
    {
        v2ray_nginx_domains_list=""
        v2ray_nginx_domains_count=0
        v2ray_nginx_domains=()

        if ls -A "$nginx_prefix/conf/sites_available/"* > /dev/null 2>&1
        then
            for f in "$nginx_prefix/conf/sites_available/"*
            do
                domain=${f##*/}
                domain=${domain%.conf}
                v2ray_nginx_domains_count=$((v2ray_nginx_domains_count+1))
                v2ray_nginx_domains+=("$domain")
                if [ -e "$nginx_prefix/conf/sites_enabled/$domain.conf" ] 
                then
                    v2ray_nginx_domain_status_text="${green} [开启] ${normal}"
                else
                    v2ray_nginx_domain_status_text="${red} [关闭] ${normal}"
                fi
                v2ray_nginx_domains_list="$v2ray_nginx_domains_list ${green}$v2ray_nginx_domains_count.${normal}${indent_6}$domain $v2ray_nginx_domain_status_text\n\n"
            done
        fi

        Println "${green}域名列表:${normal}\n\n${v2ray_nginx_domains_list:-无}"
    }
    V2rayNginxSelectDomain()
    {
        echo "`gettext \"输入序号\"`"
        while read -p "$i18n_default_cancel" v2ray_nginx_domains_index
        do
            case "$v2ray_nginx_domains_index" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$v2ray_nginx_domains_index" -gt 0 ] && [ "$v2ray_nginx_domains_index" -le "$v2ray_nginx_domains_count" ]
                    then
                        v2ray_nginx_domains_index=$((v2ray_nginx_domains_index-1))
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    }
    V2rayNginxSelectDomainServer()
    {
        echo "`gettext \"输入序号\"`"
        while read -p "$i18n_default_cancel" v2ray_nginx_domain_servers_num
        do
            case "$v2ray_nginx_domain_servers_num" in
                "")
                    Println "$i18n_canceled...\n"
                    exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$v2ray_nginx_domain_servers_num" -gt 0 ] && [ "$v2ray_nginx_domain_servers_num" -le "$v2ray_nginx_domain_servers_count" ]
                    then
                        v2ray_nginx_domain_servers_index=$((v2ray_nginx_domain_servers_num-1))
                        level_2_add_indices=( "${v2ray_nginx_domain_servers_indices[v2ray_nginx_domain_servers_index]}" )
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    }
    V2rayNginxDomainServerUpdateCert()
    {
        v2ray_name="${v2ray_name:-v2ray}"
        v2ray_nginx_domain_server_name=${v2ray_nginx_domain_servers_name[v2ray_nginx_domain_servers_index]}

        AcmeCheck

        if [[ $v2ray_nginx_domain_server_name =~ , ]]
        then
            IFS="," read -r -a domains <<< "$v2ray_nginx_domain_server_name"

            echo
            inquirer checkbox_input "选择域名: " domains domains_selected

            for domain in "${domains_selected[@]}"
            do
                V2rayDomainUpdateCert "$domain"
                if [ -d "$nginx_prefix/conf/sites_crt" ]
                then
                    cp -f "/usr/local/share/$v2ray_name/$domain.crt" "$nginx_prefix/conf/sites_crt/$domain.crt"
                    cp -f "/usr/local/share/$v2ray_name/$domain.key" "$nginx_prefix/conf/sites_crt/$domain.key"
                fi
                chown "$v2ray_name:$v2ray_name" "/usr/local/share/$v2ray_name/$domain.crt" "/usr/local/share/$v2ray_name/$domain.key"
            done

            return 0
        fi

        V2rayDomainUpdateCert "$v2ray_nginx_domain_server_name"
        if [ -d "$nginx_prefix/conf/sites_crt" ]
        then
            cp -f "/usr/local/share/$v2ray_name/$v2ray_nginx_domain_server_name.crt" "$nginx_prefix/conf/sites_crt/$v2ray_nginx_domain_server_name.crt"
            cp -f "/usr/local/share/$v2ray_name/$v2ray_nginx_domain_server_name.key" "$nginx_prefix/conf/sites_crt/$v2ray_nginx_domain_server_name.key"
        fi
        chown "$v2ray_name:$v2ray_name" "/usr/local/share/$v2ray_name/$v2ray_nginx_domain_server_name.crt" "/usr/local/share/$v2ray_name/$v2ray_nginx_domain_server_name.key"
    }
    V2rayNginxDomainServerAddProxy()
    {
        V2rayListInbounds nginx
        V2raySelectInbound

        if [ "${inbounds_stream_network[inbounds_index]}" == "domainsocket" ] 
        then
            Println "$error 不能使用此入站\n"
            exit 1
        fi

        if [ -z "${inbounds_stream_path[inbounds_index]}" ] 
        then
            Println "$error 此入站没有路径\n"
            exit 1
        fi

        proxy_path=${inbounds_stream_path[inbounds_index]}
        proxy_port=${inbounds_port[inbounds_index]}

        if [ "${inbounds_stream_network[inbounds_index]}" == "ws" ] 
        then
            new_proxy='
            {"directive":"location","args":["=","'"$proxy_path"'"],"block":[
                {"directive":"proxy_redirect","args":["off"]},
                {"directive":"proxy_pass","args":["http://127.0.0.1:'"$proxy_port"'"]},
                {"directive":"proxy_http_version","args":["1.1"]},
                {"directive":"proxy_set_header","args":["Upgrade","$http_upgrade"]},
                {"directive":"proxy_set_header","args":["Connection","upgrade"]}
            ]}'
        else
            new_proxy='
            {"directive":"location","args":["=","'"$proxy_path"'"],"block":[
                {"directive":"proxy_redirect","args":["off"]},
                {"directive":"proxy_pass","args":["http://127.0.0.1:'"$proxy_port"'"]},
                {"directive":"proxy_http_version","args":["1.1"]}
            ]}'
        fi

        jq_path='["config",0,"parsed",0,"block",'"$v2ray_nginx_domain_servers_index"',"block"]'
        JQs add parse_out "[$new_proxy]"

        NginxBuildConf parse_out

        Println "$info 代理添加成功\n"
    }
    V2rayNginxSelectDomainServerProxy()
    {
        echo "`gettext \"输入序号\"`"
        while read -p "$i18n_default_cancel" v2ray_nginx_domain_server_proxies_num
        do
            case "$v2ray_nginx_domain_server_proxies_num" in
                "")
                    Println "$i18n_canceled...\n"
                    exit 1
                ;;
                $v2ray_nginx_domain_server_update_crt_number)
                    AcmeCheck
                    V2rayNginxDomainServerUpdateCert
                    exit 0
                ;;
                $v2ray_nginx_domain_server_add_proxy_number)
                    V2rayNginxDomainServerAddProxy
                    exit 0
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$v2ray_nginx_domain_server_proxies_num" -gt 0 ] && [ "$v2ray_nginx_domain_server_proxies_num" -le "$v2ray_nginx_domain_server_proxies_count" ]
                    then
                        v2ray_nginx_domain_server_proxies_index=$((v2ray_nginx_domain_server_proxies_num-1))
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    }
    V2rayNginxListDomain()
    {
        if [ "$v2ray_nginx_domains_count" -eq 0 ]
        then
            Println "$error 请先使用 $nginx_name 管理面板添加域名\n"
            exit 1
        fi

        level_1_add_indices=( 0 )

        V2rayNginxSelectDomain
        NginxParseConfig ${v2ray_nginx_domains[v2ray_nginx_domains_index]}
        NginxGetConfig

        if [ "$level_3_d1_count" -eq 0 ]
        then
            Println "$error 请先添加 ${v2ray_nginx_domains[v2ray_nginx_domains_index]} 配置\n"
            exit 1
        fi

        v2ray_nginx_domain_servers_list=""
        v2ray_nginx_domain_servers_count=0
        v2ray_nginx_domain_servers_indices=()
        v2ray_nginx_domain_servers_name=()
        v2ray_nginx_domain_servers_proxy=()

        level_1_index=0

        level_2_directive_d1=${level_2_directive_arr[level_1_index]}
        level_3_directive_d1=${level_3_directive_arr[level_1_index]}
        level_3_args_d1=${level_3_args_arr[level_1_index]}

        IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "$level_2_directive_d1"
        IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "$level_3_directive_d1"
        IFS="${delimiters[5]}" read -r -a level_3_args_d1_arr <<< "$level_3_args_d1"

        if [ "$level_4_d1_count" -gt 0 ]
        then
            level_4_directive_d1=${level_4_directive_arr[level_1_index]}
            level_4_args_d1=${level_4_args_arr[level_1_index]}
            IFS="${delimiters[6]}" read -r -a level_4_directive_d1_arr <<< "$level_4_directive_d1"
            IFS="${delimiters[6]}" read -r -a level_4_args_d1_arr <<< "$level_4_args_d1"
        fi

        for((level_2_index=0;level_2_index<${#level_2_directive_d1_arr[@]};level_2_index++));
        do
            if [ "${level_2_directive_d1_arr[level_2_index]}" == "server" ]
            then
                level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}
                level_3_args_d2=${level_3_args_d1_arr[level_2_index]}

                IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "$level_3_directive_d2"
                IFS="${delimiters[6]}" read -r -a level_3_args_d2_arr <<< "$level_3_args_d2"

                if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ]
                then
                    level_4_directive_d2=${level_4_directive_d1_arr[level_2_index]}
                    level_4_args_d2=${level_4_args_d1_arr[level_2_index]}
                    IFS="${delimiters[7]}" read -r -a level_4_directive_d2_arr <<< "$level_4_directive_d2"
                    IFS="${delimiters[7]}" read -r -a level_4_args_d2_arr <<< "$level_4_args_d2"
                fi

                v2ray_nginx_domain_servers_count=$((v2ray_nginx_domain_servers_count+1))
                v2ray_nginx_domain_servers_indices+=("$level_2_index")
                v2ray_nginx_domain_server_listen_list=""
                v2ray_nginx_domain_server_name_list=""
                v2ray_nginx_domain_server_proxies=""
                v2ray_nginx_domain_server_proxies_list=""

                for((level_3_index=0;level_3_index<${#level_3_directive_d2_arr[@]};level_3_index++));
                do
                    level_3_directive=${level_3_directive_d2_arr[level_3_index]}
                    level_3_args=${level_3_args_d2_arr[level_3_index]}

                    if [ "$level_3_directive" == "listen" ]
                    then
                        [ -n "$v2ray_nginx_domain_server_listen_list" ] && v2ray_nginx_domain_server_listen_list="$v2ray_nginx_domain_server_listen_list, "
                        v2ray_nginx_domain_server_listen_list="$v2ray_nginx_domain_server_listen_list${level_3_args//${delimiters[7]}/ }"
                    elif [ "$level_3_directive" == "server_name" ]
                    then
                        [ -n "$v2ray_nginx_domain_server_name_list" ] && v2ray_nginx_domain_server_name_list="$v2ray_nginx_domain_server_name_list, "
                        v2ray_nginx_domain_server_name_list="$v2ray_nginx_domain_server_name_list${level_3_args//${delimiters[7]}/, }"
                    elif [ "$level_3_directive" == "location" ]
                    then
                        if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ] && [ -n "${level_4_directive_d2_arr[level_3_index]}" ]
                        then
                            level_4_directive_d3=${level_4_directive_d2_arr[level_3_index]}
                            level_4_args_d3=${level_4_args_d2_arr[level_3_index]}
                            IFS="${delimiters[8]}" read -r -a level_4_directive_d3_arr <<< "$level_4_directive_d3"
                            IFS="${delimiters[8]}" read -r -a level_4_args_d3_arr <<< "$level_4_args_d3"

                            if [[ ${level_3_args} =~ ^=${delimiters[7]}(.+) ]]
                            then
                                v2ray_nginx_domain_server_proxy_path=${BASH_REMATCH[1]}
                                for((level_4_index=0;level_4_index<${#level_4_directive_d3_arr[@]};level_4_index++));
                                do
                                    if [ "${level_4_directive_d3_arr[level_4_index]}" == "proxy_pass" ]
                                    then
                                        if [[ ${level_4_args_d3_arr[level_4_index]} =~ ^http://127.0.0.1:(.+) ]]
                                        then
                                            v2ray_nginx_domain_server_proxies="$v2ray_nginx_domain_server_proxies$level_3_index|$level_4_index|${BASH_REMATCH[1]}|$v2ray_nginx_domain_server_proxy_path "
                                            v2ray_nginx_domain_server_proxies_list="$v2ray_nginx_domain_server_proxies_list${indent_6}路径: ${green}$v2ray_nginx_domain_server_proxy_path${normal} => ${v2ray_name:-v2ray} 端口: ${green}${BASH_REMATCH[1]}${normal}\n"
                                        fi
                                        break
                                    fi
                                done
                            fi
                        fi
                    fi
                done

                if [ -z "$v2ray_nginx_domain_server_proxies_list" ]
                then
                    v2ray_nginx_domain_server_proxies_list="${red}未配置${normal}"
                fi

                v2ray_nginx_domain_servers_name+=("${v2ray_nginx_domain_server_name_list//, /,}")
                v2ray_nginx_domain_servers_proxy+=("$v2ray_nginx_domain_server_proxies")

                v2ray_nginx_domain_servers_list="$v2ray_nginx_domain_servers_list $v2ray_nginx_domain_servers_count.${indent_6}域名: ${green}${v2ray_nginx_domain_server_name_list:-未设置}${normal}\n${indent_6}端口: ${green}${v2ray_nginx_domain_server_listen_list:-未设置}${normal}\n${indent_6}代理: $v2ray_nginx_domain_server_proxies_list\n\n"
            fi
        done

        Println "域名 ${green}${v2ray_nginx_domains[v2ray_nginx_domains_index]}${normal} 配置:\n\n$v2ray_nginx_domain_servers_list"
    }
    V2rayConfigDomain()
    {
        v2ray_name="${v2ray_name:-v2ray}"
        tls_name="${tls_name:-tls}"

        if [ -d "$nginx_prefix" ]
        then
            echo
            v2ray_config_domain_options=( "$v2ray_name" nginx openresty )
            inquirer list_input "选择修改的配置" v2ray_config_domain_options v2ray_config_domain_option

            if [ "$v2ray_config_domain_option" != "$v2ray_name" ] 
            then
                if [ ! -d "/usr/local/$v2ray_config_domain_option" ] 
                then
                    Println "$error 请先安装 $v2ray_config_domain_option\n"
                    exit 1
                fi

                if [ "$v2ray_config_domain_option" == "nginx" ] 
                then
                    nginx_prefix="/usr/local/nginx"
                    nginx_name="nginx"
                    nginx_ctl="nx"
                else
                    nginx_prefix="/usr/local/openresty/nginx"
                    nginx_name="openresty"
                    nginx_ctl="or"
                fi

                NGINX_FILE="$nginx_prefix/sbin/nginx"

                V2rayNginxListDomains
                V2rayNginxListDomain

                V2rayNginxSelectDomainServer

                v2ray_nginx_domain_server_proxies_list=""
                v2ray_nginx_domain_server_proxies_count=0

                v2ray_nginx_domain_server_proxy=${v2ray_nginx_domain_servers_proxy[v2ray_nginx_domain_servers_index]}

                if [ -n "$v2ray_nginx_domain_server_proxy" ] 
                then
                    v2ray_nginx_domain_server_location_indices=()
                    v2ray_nginx_domain_server_proxy_indices=()
                    v2ray_nginx_domain_server_proxies_port=()
                    v2ray_nginx_domain_server_proxies_path=()
                    v2ray_nginx_domain_server_proxies_list=""

                    IFS=" " read -r -a v2ray_nginx_domain_server_proxies <<< "$v2ray_nginx_domain_server_proxy"

                    for((i=0;i<${#v2ray_nginx_domain_server_proxies[@]};i++));
                    do
                        if [[ ${v2ray_nginx_domain_server_proxies[i]} =~ ^([^|]+)\|([^|]+)\|([^|]+)\|(.+)$ ]] 
                        then
                            v2ray_nginx_domain_server_location_indices+=("${BASH_REMATCH[1]}")
                            v2ray_nginx_domain_server_proxy_indices+=("${BASH_REMATCH[2]}")
                            v2ray_nginx_domain_server_proxies_port+=("${BASH_REMATCH[3]}")
                            v2ray_nginx_domain_server_proxies_path+=("${BASH_REMATCH[4]}")
                            v2ray_nginx_domain_server_proxies_list="$v2ray_nginx_domain_server_proxies_list $((i+1)).${indent_6}路径: ${green}${BASH_REMATCH[4]}${normal} => 端口: ${green}${BASH_REMATCH[3]}${normal}\n\n"
                        fi
                    done

                    v2ray_nginx_domain_server_proxies_count=${#v2ray_nginx_domain_server_proxies_path[@]}
                fi

                v2ray_nginx_domain_server_update_crt_number=$((v2ray_nginx_domain_server_proxies_count+1))
                v2ray_nginx_domain_server_add_proxy_number=$((v2ray_nginx_domain_server_proxies_count+2))
                v2ray_nginx_domain_server_proxies_list="$v2ray_nginx_domain_server_proxies_list $v2ray_nginx_domain_server_update_crt_number.${indent_6}${green}更新证书${normal}\n\n"
                v2ray_nginx_domain_server_proxies_list="$v2ray_nginx_domain_server_proxies_list $v2ray_nginx_domain_server_add_proxy_number.${indent_6}${green}添加代理${normal}\n"

                Println "代理配置:\n\n$v2ray_nginx_domain_server_proxies_list"

                V2rayNginxSelectDomainServerProxy

                v2ray_nginx_domain_server_location_index=${v2ray_nginx_domain_server_location_indices[v2ray_nginx_domain_server_proxies_index]}
                v2ray_nginx_domain_server_proxy_index=${v2ray_nginx_domain_server_proxy_indices[v2ray_nginx_domain_server_proxies_index]}
                v2ray_nginx_domain_server_proxy_port=${v2ray_nginx_domain_server_proxies_port[v2ray_nginx_domain_server_proxies_index]}
                v2ray_nginx_domain_server_proxy_path=${v2ray_nginx_domain_server_proxies_path[v2ray_nginx_domain_server_proxies_index]}

                echo
                v2ray_nginx_domain_server_proxy_options=( '修改代理路径' '修改代理端口' '删除此代理' )
                inquirer list_input_index "选择操作" v2ray_nginx_domain_server_proxy_options v2ray_nginx_domain_server_proxy_options_index

                if [ "$v2ray_nginx_domain_server_proxy_options_index" -eq 0 ] 
                then
                    echo
                    inquirer text_input "输入新的代理路径: " new_path "$v2ray_nginx_domain_server_proxy_path"
                    jq_path='["config",0,"parsed",0,"block",'"$v2ray_nginx_domain_servers_index"',"block",'"$v2ray_nginx_domain_server_location_index"',"args"]'
                    JQs replace parse_out "$new_path"
                elif [ "$v2ray_nginx_domain_server_proxy_options_index" -eq 1 ] 
                then
                    echo
                    new_proxy_port_options=( '输入新的代理端口' '浏览并选择端口' )
                    inquirer list_input_index "选择操作" new_proxy_port_options new_proxy_port_options_index

                    if [ "$new_proxy_port_options_index" -eq 0 ] 
                    then
                        echo
                        inquirer text_input "输入新的代理端口: " new_proxy_port "$v2ray_nginx_domain_server_proxy_port"
                    else
                        V2rayListInbounds nginx
                        V2raySelectInbound

                        if [ "${inbounds_stream_network[inbounds_index]}" == "domainsocket" ] 
                        then
                            Println "$error 选择错误\n"
                            exit 1
                        fi

                        new_proxy_port=${inbounds_port[inbounds_index]}
                    fi

                    jq_path='["config",0,"parsed",0,"block",'"$v2ray_nginx_domain_servers_index"',"block",'"$v2ray_nginx_domain_server_location_index"',"block",'"$v2ray_nginx_domain_server_proxy_index"',"args"]'
                    JQs replace parse_out "$new_proxy_port"
                else
                    jq_path='["config",0,"parsed",0,"block",'"$v2ray_nginx_domain_servers_index"',"block"]'
                    JQs delete parse_out "$v2ray_nginx_domain_server_location_index"
                fi

                NginxBuildConf parse_out

                Println "$info 操作成功\n"
                exit 0
            fi
        fi

        V2rayListInbounds direct

        V2raySelectInbound

        if [ -z "${inbounds_stream_tls_certificates_usage[inbounds_index]}" ] 
        then
            Println "$error 没有证书\n"
            exit 1
        fi

        certificates_list="${green}证书:${normal}\n${indent_6}"
        certificates_indices=()

        IFS="|" read -r -a usages <<< "${inbounds_stream_tls_certificates_usage[inbounds_index]}"
        IFS="|" read -r -a certificate_files <<< "${inbounds_stream_tls_certificates_certificate_file[inbounds_index]}"
        IFS="|" read -r -a key_files <<< "${inbounds_stream_tls_certificates_key_file[inbounds_index]}"
        IFS="|" read -r -a certificates <<< "${inbounds_stream_tls_certificates_certificate[inbounds_index]}"

        for((certificate_i=0;certificate_i<${#usages[@]};certificate_i++));
        do
            if [ -z "${certificate_files[certificate_i]}" ] || [ -z "${key_files[certificate_i]}" ]
            then
                continue
            fi

            certificates_indices+=("$certificate_i")

            if [ "${usages[certificate_i]}" == "encipherment" ] 
            then
                certificate_usage="$tls_name 认证和加密"
            elif [ "${usages[certificate_i]}" == "verify" ] 
            then
                certificate_usage="验证远端 $tls_name"
            elif [ "${usages[certificate_i]}" == "issue" ] 
            then
                certificate_usage="签发其它证书"
            else
                certificate_usage="验证客户端身份"
            fi

            if [ -n "${certificates:-}" ] && [ -n "${certificates[certificate_i]}" ] 
            then
                certificates_list="$certificates_list${#certificates_indices[@]}.${indent_6}用途: ${green}$certificate_usage [自签名]${normal}\n"
            else
                certificates_list="$certificates_list${#certificates_indices[@]}.${indent_6}用途: ${green}$certificate_usage${normal}\n"
            fi

            certificates_list="${certificates_list}${indent_6}证书路径: ${green}${certificate_files[certificate_i]}${normal}\n"

            certificates_list="${certificates_list}${indent_6}密钥路径: ${green}${key_files[certificate_i]}${normal}\n\n"
        done

        if [ -z "$certificates_list" ] 
        then
            Println "$error 没有可管理证书\n"
            exit 1
        fi

        Println "$certificates_list"

        certificates_count=${#certificates_indices[@]}

        echo "选择证书"
        while read -p "$i18n_default_cancel" certificates_num
        do
            case "$certificates_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$certificates_num" -gt 0 ] && [ "$certificates_num" -le $certificates_count ]
                    then
                        certificates_index=${certificates_indices[certificates_num-1]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        certificate_file=${certificate_files[certificates_index]}
        tls_settings_name=$(tr '[:upper:]' '[:lower:]' <<< "$tls_name")"Settings"

        echo
        certificates_options=( '更新证书' '修改证书路径' '修改密钥路径' )
        inquirer list_input_index "选择操作" certificates_options certificates_options_index

        if [ "$certificates_options_index" -eq 0 ] 
        then
            if [ -n "${certificates:-}" ] && [ -n "${certificates[certificates_index]}" ] 
            then
                if [ "$v2ray_name" == "xray" ]
                then
                    crt=$("$V2CTL_FILE" tls cert)
                elif [ "${usages[certificates_index]}" == "encipherment" ]
                then
                    echo
                    inquirer list_input "是否是 CA 证书" yn_options ca_yn
                    if [ "$ca_yn" == "$i18n_yes" ]
                    then
                        if [ -x "${V2CTL_FILE:-}" ]
                        then
                            crt=$("$V2CTL_FILE" cert -ca)
                        else
                            crt=$("$V2_FILE" tls cert --ca)
                        fi
                    else
                        if [ -x "${V2CTL_FILE:-}" ]
                        then
                            crt=$("$V2CTL_FILE" cert)
                        else
                            crt=$("$V2_FILE" tls cert)
                        fi
                    fi
                else
                    if [ -x "${V2CTL_FILE:-}" ]
                    then
                        crt=$("$V2CTL_FILE" cert -ca)
                    else
                        crt=$("$V2_FILE" tls cert --ca)
                    fi
                fi

                certificate=$($JQ_FILE "{\"usage\":\"${usages[certificates_index]}\"} * ." <<< "$crt")

                jq_json=true
                jq_path='["inbounds",'"$inbounds_index"',"streamSettings","'"$tls_settings_name"'","certificates",'"$certificates_index"']'
                JQ update "$V2_CONFIG" "$certificate"

                Println "$info 证书更新成功\n"
            else
                if [ -n "${inbounds_stream_tls_server_name[inbounds_index]}" ] 
                then
                    certificate_name=${inbounds_stream_tls_server_name[inbounds_index]}
                else
                    certificate_name=${certificate_file##*/}
                    certificate_name=${certificate_name%.*}
                fi

                echo
                inquirer text_input "请输入证书域名: " certificate_domain "$certificate_name"

                AcmeCheck

                Println "$info 更新 $certificate_domain 证书..."

                V2rayDomainUpdateCert "$certificate_domain"

                local cert_patch=""
                JQs build cert_patch '{"certificateFile": $crt, "keyFile": $key}' \
                    --arg crt "$AIOS_PREFIX/share/$v2ray_name/$certificate_domain.crt" \
                    --arg key "$AIOS_PREFIX/share/$v2ray_name/$certificate_domain.key"
                jq_merge=true
                jq_path='["inbounds",'"$inbounds_index"',"streamSettings","'"$tls_settings_name"'","certificates",'"$certificates_index"']'
                JQ update "$V2_CONFIG" "$cert_patch"

                Println "$info $certificate_domain 证书更新成功\n"
            fi
        elif [ "$certificates_options_index" -eq 1 ] 
        then
            V2raySetCertificateFile

            jq_path='["inbounds",'"$inbounds_index"',"streamSettings","'"$tls_settings_name"'","certificates",'"$certificates_index"',"certificateFile"]'
            JQ update "$V2_CONFIG" "$certificate_file"

            Println "$info 证书路径修改成功\n"
        else
            V2raySetKeyFile

            jq_path='["inbounds",'"$inbounds_index"',"streamSettings","'"$tls_settings_name"'","certificates",'"$certificates_index"',"keyFile"]'
            JQ update "$V2_CONFIG" "$key_file"

            Println "$info 密钥路径修改成功\n"
        fi
    }
    V2rayInstall()
    {
        if [ -s "$V2_CONFIG" ]
        then
            Println "$error v2ray 已存在...\n"
            ExitOnList n "`gettext \"是否覆盖原安装\"`"
        fi

        DepsCheck
        JQInstall

        if ! grep -q 'v2ray:' < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser v2ray --system --group --no-create-home > /dev/null
            else
                adduser v2ray --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin v2ray
        fi

        Println "$info 安装 v2ray..."

        { curl -s -m 10 "$V2_LINK" || curl -s -m 30 "$V2_LINK_FALLBACK"; } \
        | sed "s+nobody+v2ray+g" \
        | sed "s+ 'sha1'++g" \
        | sed "s+ 'sha256'++g" \
        | sed "s+ 'sha512'++g" \
        | sed "s+https://api.github.com/repos/v2fly/v2ray-core/releases/latest+$FFMPEG_MIRROR_LINK/v2ray.json+g" \
        | sed "s+https://github.com/v2fly/v2ray-core/releases/download+$FFMPEG_MIRROR_LINK/v2ray+g" | bash

        sed -i "s+nobody+v2ray+g" "/etc/systemd/system/v2ray.service"
        sed -i "s+nobody+v2ray+g" "/etc/systemd/system/v2ray@.service"

        mkdir -p /var/log/v2ray/
        [ ! -e "/var/log/v2ray/error.log" ] && printf '%s' "" > /var/log/v2ray/error.log
        chown -R v2ray:v2ray /var/log/v2ray/
        chown -R v2ray:v2ray /usr/local/share/v2ray/

        ServiceControl start v2ray

        Println "$info v2ray 安装完成\n"
    }

    V2rayUpdate()
    {
        DepsCheck
        JQInstall
        ShFileUpdate v2ray

        if ! grep -q "v2ray:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser v2ray --system --group --no-create-home > /dev/null
            else
                adduser v2ray --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin v2ray
        fi

        { curl -s -m 10 "$V2_LINK" || curl -s -m 30 "$V2_LINK_FALLBACK"; } \
        | sed "s+nobody+v2ray+g" \
        | sed "s+ 'sha1'++g" \
        | sed "s+ 'sha256'++g" \
        | sed "s+ 'sha512'++g" \
        | sed "s+https://api.github.com/repos/v2fly/v2ray-core/releases/latest+$FFMPEG_MIRROR_LINK/v2ray.json+g" \
        | sed "s+https://github.com/v2fly/v2ray-core/releases/download+$FFMPEG_MIRROR_LINK/v2ray+g" | bash

        sed -i "s+nobody+v2ray+g" "/etc/systemd/system/v2ray.service"
        sed -i "s+nobody+v2ray+g" "/etc/systemd/system/v2ray@.service"

        mkdir -p /var/log/v2ray/
        [ ! -e "/var/log/v2ray/error.log" ] && printf '%s' "" > /var/log/v2ray/error.log
        chown -R v2ray:v2ray /var/log/v2ray/
        chown -R v2ray:v2ray /usr/local/share/v2ray/

        ServiceControl restart v2ray

        Println "$info v2ray 升级完成\n"
    }

    ShFileCheck

    if [ "$dist" != "mac" ] && [ -d /etc/v2ray/ ] && [ ! -d /usr/local/etc/v2ray/ ]
    then
        ServiceControl disable v2ray
        rm -rf /usr/bin/v2ray/
        mv /etc/v2ray/ /usr/local/etc/
        if ! grep -q "v2ray:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser v2ray --system --group --no-create-home > /dev/null
            else
                adduser v2ray --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin v2ray
        fi
        mkdir -p /var/log/v2ray/
        [ ! -e "/var/log/v2ray/error.log" ] && printf '%s' "" > /var/log/v2ray/error.log
        chown -R v2ray:v2ray /var/log/v2ray/
        chown -R v2ray:v2ray /usr/local/share/v2ray/
        V2rayUpdate
    fi

    case $* in
        "e")
            [ ! -e "$V2_CONFIG" ] && Println "$error 尚未安装, 请检查 !\n" && exit 1
            editor "$V2_CONFIG" && exit 0
        ;;
        *)
        ;;
    esac

    ProxyDetectNginx

    Println "  v2ray 管理面板 ${normal}${red}[v$sh_ver]${normal}

  ${green}1.${normal} 安装
  ${green}2.${normal} 升级
  ${green}3.${normal} 配置域名
  ${green}4.${normal} 查看状态
————————————
  ${green}5.${normal} 查看入站
  ${green}6.${normal} 添加入站
  ${green}7.${normal} 添加入站账号
————————————
  ${green}8.${normal} 查看出站
  ${green}9.${normal} 添加出站
 ${green}10.${normal} 添加出站账号
————————————
 ${green}11.${normal} 查看DNS
 ${green}12.${normal} 设置DNS
————————————
 ${green}13.${normal} 查看路由
 ${green}14.${normal} 设置路由
————————————
 ${green}15.${normal} 查看策略
 ${green}16.${normal} 设置策略
————————————
 ${green}17.${normal} 查看流量
 ${green}18.${normal} 重置流量
————————————
 ${green}19.${normal} 查看反向代理
 ${green}20.${normal} 设置反向代理
————————————
 ${green}21.${normal} 删除入站
 ${green}22.${normal} 删除入站账号
 ${green}23.${normal} 删除出站
 ${green}24.${normal} 删除出站账号
————————————
 ${green}25.${normal} 开关
 ${green}26.${normal} 重启

 ${tip} 输入: v2 打开面板
    "
    read -p "`gettext \"输入序号\"` [1-26]: " v2ray_num
    case $v2ray_num in
        1)
            V2rayInstall
        ;;
        2)
            V2rayUpdate
        ;;
        3)
            V2rayConfigDomain
        ;;
        4)
            ServiceControl status v2ray
        ;;
        5)
            V2rayListInboundAccounts && V2rayListInboundShare
        ;;
        6)
            V2rayAddInbound
        ;;
        7)
            V2rayAddInboundAccount
        ;;
        8)
            V2rayListOutboundAccounts
        ;;
        9)
            V2rayAddOutbound
        ;;
        10)
            V2rayAddOutboundAccount
        ;;
        11)
            V2rayListDns
        ;;
        12)
            V2raySetDns
        ;;
        13)
            V2rayListRouting
        ;;
        14)
            V2raySetRouting
        ;;
        15)
            V2rayListPolicy
        ;;
        16)
            V2raySetPolicy
        ;;
        17)
            V2rayListStats
        ;;
        18)
            V2rayResetStats
        ;;
        19)
            V2rayListReverse
        ;;
        20)
            V2raySetReverse
        ;;
        21)
            V2rayDeleteInbound
        ;;
        22)
            V2rayDeleteInboundAccount
        ;;
        23)
            V2rayDeleteOutbound
        ;;
        24)
            V2rayDeleteOutboundAccount
        ;;
        25)
            ProxyToggleService v2ray "$V2_CONFIG"
        ;;
        26)
            ProxyRestartService v2ray "$V2_CONFIG"
        ;;
        *) Println "$error $i18n_input_correct_number [1-26]\n"
        ;;
    esac

    exit 0
elif [ "$self" == "x" ]
then
    XrayInstall()
    {
        if [ -s "$X_CONFIG" ]
        then
            Println "$error xray 已存在...\n"
            ExitOnList n "`gettext \"是否覆盖原安装\"`"
        fi

        DepsCheck
        JQInstall

        if ! grep -q "xray:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser xray --system --group --no-create-home > /dev/null
            else
                adduser xray --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin xray
        fi

        Println "$info 安装 xray..."

        { curl -s -m 10 "$X_LINK" || curl -s -m 30 "$X_LINK_FALLBACK"; } \
        | sed "s+nobody+xray+g" \
        | sed "s+ 'sha1'++g" \
        | sed "s+ 'sha256'++g" \
        | sed "s+ 'sha512'++g" \
        | sed "s+https://api.github.com/repos/XTLS/Xray-core/releases/latest+$FFMPEG_MIRROR_LINK/xray.json+g" \
        | sed "s+https://github.com/XTLS/Xray-core/releases/download+$FFMPEG_MIRROR_LINK/xray+g" | bash

        sed -i "s+nobody+xray+g" "/etc/systemd/system/xray.service"
        sed -i "s+nobody+xray+g" "/etc/systemd/system/xray@.service"

        mkdir -p /var/log/xray/
        [ ! -e "/var/log/xray/error.log" ] && printf '%s' "" > /var/log/xray/error.log
        chown -R xray:xray /var/log/xray/
        chown -R xray:xray /usr/local/share/xray/

        ServiceControl start xray

        Println "$info xray 安装完成\n"
    }

    XrayUpdate()
    {
        DepsCheck
        JQInstall
        ShFileUpdate xray

        if ! grep -q "xray:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser xray --system --group --no-create-home > /dev/null
            else
                adduser xray --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin xray
        fi

        { curl -s -m 10 "$X_LINK" || curl -s -m 30 "$X_LINK_FALLBACK"; } \
        | sed "s+nobody+xray+g" \
        | sed "s+ 'sha1'++g" \
        | sed "s+ 'sha256'++g" \
        | sed "s+ 'sha512'++g" \
        | sed "s+https://api.github.com/repos/XTLS/Xray-core/releases/latest+$FFMPEG_MIRROR_LINK/xray.json+g" \
        | sed "s+https://github.com/XTLS/Xray-core/releases/download+$FFMPEG_MIRROR_LINK/xray+g" | bash

        sed -i "s+nobody+xray+g" "/etc/systemd/system/xray.service"
        sed -i "s+nobody+xray+g" "/etc/systemd/system/xray@.service"

        mkdir -p /var/log/xray/
        [ ! -e "/var/log/xray/error.log" ] && printf '%s' "" > /var/log/xray/error.log
        chown -R xray:xray /var/log/xray/
        chown -R xray:xray /usr/local/share/xray/

        ServiceControl restart xray

        Println "$info xray 升级完成\n"
    }
    XrayConfigDomain()
    {
        if [ ! -e "$X_CONFIG" ]
        then
            Println "$error 尚未安装 xray, 请检查 !\n"
            return 1
        fi

        ProxyDetectNginx

        local target_mode="xray"
        if [ -x "$NGINX_FILE" ]
        then
            echo
            local target_opts=( "xray 直连 TLS 证书" "${nginx_name} 反代站点管理" )
            local target_idx=""
            inquirer list_input_index "选择配置目标" target_opts target_idx
            if [ "$target_idx" -eq 1 ]
            then
                target_mode="nginx"
            fi
        fi

        if [ "$target_mode" == "nginx" ]
        then
            Println "$info 检测到 ${green}${nginx_name}${normal}, 可通过 ${green}${nginx_ctl}${normal} 管理站点反代与 TLS 证书\n"
            return 0
        fi

        if ! ProxySelectBound "$X_CONFIG" "inbounds" "选择要管理证书的直连入站"
        then
            return 1
        fi

        local ib_idx="$selected_bound_index"
        local ib_tag="${inbounds_tag[$ib_idx]}"
        local sec_type
        sec_type=$(JQs query "$X_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object" and (.inbounds[$i].streamSettings | type) == "object"
             then .inbounds[$i].streamSettings.security
             else null end) // "none"
        ' --argjson i "$ib_idx")
        sec_type="${sec_type:-none}"

        if [ "$sec_type" != "tls" ]
        then
            Println "$error 入站 ${green}${ib_tag}${normal} 当前安全类型为 ${green}${sec_type}${normal} (非 tls), 无需配置 TLS 证书\n"
            return 1
        fi

        local certs_info
        certs_info=$(JQs query "$X_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].streamSettings | type) == "object"
                and (.inbounds[$i].streamSettings.tlsSettings | type) == "object"
                and (.inbounds[$i].streamSettings.tlsSettings.certificates | type) == "array"
             then .inbounds[$i].streamSettings.tlsSettings.certificates
             else [] end)
            | to_entries[]
            | select(.value | type == "object")
            | "\(.key)\t\(.value.usage // "encipherment")\t\(.value.certificateFile // "")\t\(.value.keyFile // "")\t\(.value.ocspStapling // "")"
        ' --argjson i "$ib_idx")

        local action_opts=( "修改证书文件路径" "修改密钥文件路径" "修改证书用途 / OCSP" "添加新证书条目" "删除证书条目" )
        local cert_indices=()
        local cert_labels=()

        if [ -n "$certs_info" ]
        then
            Println "${green}入站 ${ib_tag} 当前 TLS 证书:${normal}\n"
            local line c_idx c_usage c_file k_file c_ocsp
            while IFS=$'\t' read -r c_idx c_usage c_file k_file c_ocsp
            do
                [ -z "$c_idx" ] && continue
                cert_indices+=("$c_idx")
                cert_labels+=("#$((c_idx + 1)) [${c_usage}] ${c_file:-<inline>}")
                Println "  $((c_idx + 1)). 用途: ${green}${c_usage}${normal}  证书: ${green}${c_file:-<inline>}${normal}  密钥: ${green}${k_file:-<inline>}${normal}"
                if [ -n "$c_ocsp" ]
                then
                    Println "     OCSP Stapling: ${green}${c_ocsp}s${normal}"
                fi
            done <<< "$certs_info"
            echo
        else
            Println "$tip 当前入站尚未配置证书条目\n"
        fi

        local action_idx=""
        inquirer list_input_index "选择证书操作" action_opts action_idx

        case "$action_idx" in
            0)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$error 没有可修改的证书条目\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "选择证书条目" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                local new_crt=""
                inquirer text_input "输入新的证书文件路径 (certificateFile): " new_crt
                [ -z "$new_crt" ] && return 1
                jq_path='["inbounds",'"$ib_idx"',"streamSettings","tlsSettings","certificates",'"$target_c"',"certificateFile"]'
                if ! JQ update "$X_CONFIG" "$new_crt"
                then
                    Println "$error 证书路径修改失败\n"
                    return 1
                fi
                Println "$info 证书路径修改成功\n"
            ;;
            1)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$error 没有可修改的证书条目\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "选择证书条目" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                local new_key=""
                inquirer text_input "输入新的密钥文件路径 (keyFile): " new_key
                [ -z "$new_key" ] && return 1
                jq_path='["inbounds",'"$ib_idx"',"streamSettings","tlsSettings","certificates",'"$target_c"',"keyFile"]'
                if ! JQ update "$X_CONFIG" "$new_key"
                then
                    Println "$error 密钥路径修改失败\n"
                    return 1
                fi
                Println "$info 密钥路径修改成功\n"
            ;;
            2)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$error 没有可修改的证书条目\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "选择证书条目" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                local usage_opts=( "encipherment" "verify" "issue" )
                local usage_idx=""
                inquirer list_input_index "选择证书用途 (usage)" usage_opts usage_idx
                local new_usage="${usage_opts[$usage_idx]}"
                local new_ocsp="" cert_patch=""
                inquirer text_input "OCSP Stapling 间隔秒数 (默认 0 不启用, 留空不修改): " new_ocsp
                if [ -n "$new_ocsp" ] && [[ ! $new_ocsp =~ ^[0-9]+$ ]]
                then
                    Println "$error ocspStapling 必须为非负整数\n"
                    return 1
                fi
                JQs build cert_patch '{"usage": $u, "ocspStapling": (if $o != "" then ($o | tonumber) else null end)}' \
                    --arg u "$new_usage" --arg o "$new_ocsp"
                jq_merge=true
                jq_path='["inbounds",'"$ib_idx"',"streamSettings","tlsSettings","certificates",'"$target_c"']'
                if ! JQ update "$X_CONFIG" "$cert_patch"
                then
                    Println "$error 证书用途 / OCSP 更新失败\n"
                    return 1
                fi
                Println "$info 证书用途 / OCSP 更新成功\n"
            ;;
            3)
                local usage_opts=( "encipherment" "verify" "issue" )
                local usage_idx=""
                inquirer list_input_index "选择证书用途 (usage)" usage_opts usage_idx
                local new_usage="${usage_opts[$usage_idx]}"
                local new_crt="" new_key="" new_ocsp="" cert_json=""
                inquirer text_input "证书文件路径 (certificateFile): " new_crt
                inquirer text_input "密钥文件路径 (keyFile, verify 用途可留空): " new_key
                inquirer text_input "OCSP Stapling 间隔秒数 (默认 0 不启用, 留空跳过): " new_ocsp
                if [ -z "$new_crt" ]
                then
                    Println "$error 证书文件路径不能为空\n"
                    return 1
                fi
                if [ "$new_usage" != "verify" ] && [ -z "$new_key" ]
                then
                    Println "$error 非 verify 用途必须填写密钥文件路径 (keyFile)\n"
                    return 1
                fi
                if [ -n "$new_ocsp" ] && [[ ! $new_ocsp =~ ^[0-9]+$ ]]
                then
                    Println "$error ocspStapling 必须为非负整数\n"
                    return 1
                fi
                JQs build cert_json '{
                    "usage": $u,
                    "certificateFile": $c,
                    "keyFile": $k,
                    "ocspStapling": (if $o != "" then ($o | tonumber) else null end)
                }' --arg u "$new_usage" --arg c "$new_crt" --arg k "$new_key" --arg o "$new_ocsp"
                jq_path='["inbounds",'"$ib_idx"',"streamSettings","tlsSettings","certificates"]'
                if ! JQ add "$X_CONFIG" "[$cert_json]"
                then
                    Println "$error 添加证书条目失败\n"
                    return 1
                fi
                Println "$info 已添加证书条目\n"
            ;;
            4)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$error 没有可删除的证书条目\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "选择要删除的证书条目" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                jq_path='["inbounds",'"$ib_idx"',"streamSettings","tlsSettings","certificates",'"$target_c"']'
                if ! JQ delete "$X_CONFIG"
                then
                    Println "$error 删除证书条目失败\n"
                    return 1
                fi
                Println "$info 已删除证书条目\n"
            ;;
        esac

        ProxyRestartIfActive xray
    }
    XrayGetInbounds()
    {
        ProxyLoadInboundsIndex "$X_CONFIG"
    }
    XrayListInbounds()
    {
        XrayGetInbounds

        local list_inbounds_options=( '全部入站' '本地 nginx 入站' '直连 xray 入站' )
        local filter_mode="all"
        local count=0

        if [ "${1:-}" == "nginx" ]
        then
            list_inbounds_options_index=1
            filter_mode="nginx"
            count=$inbounds_nginx_count
        elif [ "${1:-}" == "direct" ]
        then
            list_inbounds_options_index=2
            filter_mode="direct"
            count=$inbounds_other_count
        else
            echo
            inquirer list_input_index "选择显示的范围" list_inbounds_options list_inbounds_options_index

            if [ "$list_inbounds_options_index" -eq 0 ]
            then
                filter_mode="all"
                count=$inbounds_count
            elif [ "$list_inbounds_options_index" -eq 1 ]
            then
                filter_mode="nginx"
                count=$inbounds_nginx_count
            else
                filter_mode="direct"
                count=$inbounds_other_count
            fi
        fi

        if [ "$count" -eq 0 ]
        then
            if [ "$list_inbounds_options_index" -eq 0 ]
            then
                Println "$error 请先添加入站\n"
            else
                Println "$error 请先添加 ${list_inbounds_options[list_inbounds_options_index]}\n"
            fi
            return 1
        fi

        Println "\n=== ${list_inbounds_options[list_inbounds_options_index]}数 ${green} $count ${normal}"
        inbounds_list=$(ProxyRenderInbounds "$X_CONFIG" xray "$filter_mode")
        Println "$inbounds_list"
    }
    XrayListInboundAccounts()
    {
        XrayListInbounds "${1:-}" || return 1

        if ! ProxySelectBound "$X_CONFIG" inbounds "选择查看账号明细的入站"
        then
            inbounds_index=""
            return 1
        fi

        local idx="$selected_bound_index"
        inbounds_index="$idx"
        local accounts_out
        accounts_out=$(ProxyRenderInboundAccounts "$X_CONFIG" "$idx")

        if [ -z "$accounts_out" ]
        then
            Println "$info 入站 ${green}${inbounds_tag[idx]}${normal} 没有多账号配置\n"
            return 0
        fi

        Println "\n=== 入站 ${green}${inbounds_tag[idx]}${normal} 账号明细 ===\n$accounts_out\n"
    }
    XrayListInboundShare()
    {
        local host="${1:-}"
        local only_idx="${2:-${inbounds_index:-}}"
        if [ "$only_idx" == "all" ]
        then
            only_idx=""
        fi

        local links
        links=$(ProxyRenderShareLinks "$X_CONFIG" "$host" "$only_idx" "xray")

        if [ -n "$links" ]
        then
            Println "\n=== Xray 分享链接 ===\n$links\n"
            if [ "${3:-}" == "qr" ]
            then
                local first_link
                first_link=$(printf '%s\n' "$links" | head -n 1)
                ProxyPrintQrCode "$first_link"
            fi
        fi
    }
    XrayGetBin()
    {
        if [ -n "${XRAY_FILE:-}" ] && [ -x "$XRAY_FILE" ]
        then
            printf '%s' "$XRAY_FILE"
        elif [ -n "${XCTL_FILE:-}" ] && [ -x "$XCTL_FILE" ]
        then
            printf '%s' "$XCTL_FILE"
        elif command -v xray > /dev/null 2>&1
        then
            command -v xray
        fi
    }

    XrayAddInbound()
    {
        local mode_options=( '直连 xray 入站' '本地 nginx 反代入站' )
        local mode_idx=0
        echo
        inquirer list_input_index "选择入站模式" mode_options mode_idx

        local proto_options=( 'vless' 'vmess' 'trojan' 'shadowsocks' 'socks' 'http' 'tunnel' 'hysteria' 'wireguard' 'tun' 'masque' )
        local proto_idx=0
        inquirer list_input_index "选择入站协议" proto_options proto_idx
        local protocol="${proto_options[$proto_idx]}"

        local default_listen="0.0.0.0"
        local tag_prefix="${protocol}-"
        if [ "$mode_idx" -eq 1 ]
        then
            default_listen="127.0.0.1"
            tag_prefix="nginx-${protocol}-"
        fi

        local listen port tag
        inquirer text_input "输入监听地址" listen "$default_listen"
        inquirer text_input "输入监听端口 (留空随机)" port ""
        if [ -z "$port" ]
        then
            port=$(GetFreePort)
        fi
        if [[ $port =~ ^[0-9]+$ ]]
        then
            if [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
            then
                Println "$error 监听端口必须在 1-65535 之间\n"
                return 1
            fi
        elif [[ ! $port =~ ^[0-9]+-[0-9]+$ ]]
        then
            Println "$error 监听端口格式无效 (应为端口或端口范围, 如 443 或 10000-20000)\n"
            return 1
        fi
        inquirer text_input "输入入站标识 (留空随机)" tag ""
        if [ -z "$tag" ]
        then
            tag=$(ProxyGetFreeTag "$X_CONFIG" "$tag_prefix")
        elif [ "$mode_idx" -eq 1 ] && [ "${tag:0:6}" != "nginx-" ]
        then
            tag="nginx-${tag}"
        fi

        local xray_bin
        xray_bin=$(XrayGetBin)

        local settings_json='{}'
        case "$protocol" in
            vless)
                local uuid flow email decryption
                inquirer text_input "输入用户 UUID (留空自动生成)" uuid ""
                if [ -z "$uuid" ]
                then
                    if [ -n "$xray_bin" ]
                    then
                        uuid=$("$xray_bin" uuid 2> /dev/null | head -n 1 | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && command -v uuidgen > /dev/null 2>&1
                    then
                        uuid=$(uuidgen 2> /dev/null | tr '[:upper:]' '[:lower:]' | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && [ -r /proc/sys/kernel/random/uuid ]
                    then
                        uuid=$(cat /proc/sys/kernel/random/uuid | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ]
                    then
                        Println "$error 自动生成 UUID 失败, 请手动输入\n"
                        return 1
                    fi
                    Println "$info 已自动生成 UUID: ${green}${uuid}${normal}\n"
                fi
                inquirer text_input "输入流控 flow (如 xtls-rprx-vision, 可留空)" flow ""
                inquirer text_input "输入用户 email (可留空)" email ""
                inquirer text_input "输入 decryption" decryption "none"
                JQs build settings_json '{
                    "decryption": $decryption,
                    "users": [{"id": $id, "flow": $flow, "email": $email, "level": 0}]
                }' --arg decryption "$decryption" --arg id "$uuid" --arg flow "$flow" --arg email "$email"
            ;;
            vmess)
                local uuid email
                inquirer text_input "输入用户 UUID (留空自动生成)" uuid ""
                if [ -z "$uuid" ]
                then
                    if [ -n "$xray_bin" ]
                    then
                        uuid=$("$xray_bin" uuid 2> /dev/null | head -n 1 | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && command -v uuidgen > /dev/null 2>&1
                    then
                        uuid=$(uuidgen 2> /dev/null | tr '[:upper:]' '[:lower:]' | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && [ -r /proc/sys/kernel/random/uuid ]
                    then
                        uuid=$(cat /proc/sys/kernel/random/uuid | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ]
                    then
                        Println "$error 自动生成 UUID 失败, 请手动输入\n"
                        return 1
                    fi
                    Println "$info 已自动生成 UUID: ${green}${uuid}${normal}\n"
                fi
                inquirer text_input "输入用户 email (可留空)" email ""
                JQs build settings_json '{
                    "users": [{"id": $id, "email": $email, "level": 0}]
                }' --arg id "$uuid" --arg email "$email"
            ;;
            trojan)
                local password email
                inquirer text_input "输入密码" password ""
                inquirer text_input "输入用户 email (可留空)" email ""
                JQs build settings_json '{
                    "users": [{"password": $password, "email": $email, "level": 0}]
                }' --arg password "$password" --arg email "$email"
            ;;
            shadowsocks)
                local method password network email
                inquirer text_input "输入加密方式" method "2022-blake3-aes-256-gcm"
                inquirer text_input "输入密钥 (SS2022 留空自动生成)" password ""
                if [ -z "$password" ] && [[ "$method" == 2022-* ]]
                then
                    local ss_bytes=32
                    if [[ "$method" == *aes-128* ]]
                    then
                        ss_bytes=16
                    fi
                    password=$(openssl rand -base64 "$ss_bytes" 2> /dev/null | tr -d '\r\n')
                    if [ -z "$password" ]
                    then
                        Println "$error 自动生成 SS2022 密钥失败, 请手动输入\n"
                        return 1
                    fi
                    Println "$info 已自动生成 SS2022 密钥: ${green}${password}${normal}\n"
                fi
                inquirer text_input "输入监听网络 (tcp/udp/tcp,udp)" network "tcp,udp"
                inquirer text_input "输入用户 email (可留空)" email ""
                JQs build settings_json '{
                    "method": $method,
                    "password": $password,
                    "network": $network,
                    "email": $email
                }' --arg method "$method" --arg password "$password" --arg network "$network" --arg email "$email"
            ;;
            socks)
                local auth_opts=( 'noauth' 'password' )
                local auth="" udp_idx=1 user="" pass=""
                local yn_opts=( '否' '是' )
                inquirer list_input "选择认证方式 auth" auth_opts auth
                inquirer list_input_index "开启 UDP 转发" yn_opts udp_idx
                if [ "$auth" == "password" ]
                then
                    inquirer text_input "输入用户名" user ""
                    inquirer text_input "输入密码" pass ""
                    JQs build settings_json '{
                        "auth": $auth,
                        "udp": ($udp == "1"),
                        "users": [{"user": $user, "pass": $pass}]
                    }' --arg auth "$auth" --arg udp "$udp_idx" --arg user "$user" --arg pass "$pass"
                else
                    JQs build settings_json '{
                        "auth": $auth,
                        "udp": ($udp == "1")
                    }' --arg auth "$auth" --arg udp "$udp_idx"
                fi
            ;;
            http)
                local user pass
                inquirer text_input "输入用户名 (留空无认证)" user ""
                if [ -n "$user" ]
                then
                    inquirer text_input "输入密码" pass ""
                    JQs build settings_json '{
                        "users": [{"user": $user, "pass": $pass}]
                    }' --arg user "$user" --arg pass "$pass"
                fi
            ;;
            tunnel)
                local rw_addr rw_port allowed_net fr_idx=0
                local yn_opts=( '否' '是' )
                inquirer text_input "输入目标转发地址" rw_addr "127.0.0.1"
                inquirer text_input "输入目标转发端口" rw_port "8080"
                if [[ ! $rw_port =~ ^[0-9]+$ ]] || [ "$rw_port" -lt 1 ] || [ "$rw_port" -gt 65535 ]
                then
                    Println "$error 目标转发端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "输入允许网络 (tcp/udp/tcp,udp)" allowed_net "tcp"
                inquirer list_input_index "启用 followRedirect" yn_opts fr_idx
                JQs build settings_json '{
                    "rewriteAddress": $addr,
                    "rewritePort": ($port | tonumber),
                    "allowedNetwork": $net,
                    "followRedirect": ($fr == "1")
                }' --arg addr "$rw_addr" --arg port "$rw_port" --arg net "$allowed_net" --arg fr "$fr_idx"
            ;;
            hysteria)
                local auth email
                inquirer text_input "输入认证密钥 auth" auth ""
                inquirer text_input "输入用户 email (可留空)" email ""
                JQs build settings_json '{
                    "version": 2,
                    "users": [{"auth": $auth, "email": $email, "level": 0}]
                }' --arg auth "$auth" --arg email "$email"
            ;;
            wireguard)
                local secret_key peer_pub allowed_ip mtu
                inquirer text_input "输入服务端 secretKey (留空自动生成)" secret_key ""
                if [ -z "$secret_key" ]
                then
                    if [ -n "$xray_bin" ]
                    then
                        local wg_out wg_pub=""
                        wg_out=$("$xray_bin" wg 2> /dev/null)
                        secret_key=$(printf '%s\n' "$wg_out" | awk -F': ' '/^Private[ ]?[Kk]ey:/ {print $2; exit}' | tr -d '\r\n ')
                        wg_pub=$(printf '%s\n' "$wg_out" | awk -F': ' '/^Public[ ]?[Kk]ey:/ {print $2; exit}' | tr -d '\r\n ')
                        if [ -n "$secret_key" ]
                        then
                            Println "$info 已自动生成 WireGuard secretKey: ${green}${secret_key}${normal}\n"
                            if [ -n "$wg_pub" ]
                            then
                                Println "$info 对应服务端 publicKey: ${green}${wg_pub}${normal}\n"
                            fi
                        fi
                    fi
                    if [ -z "$secret_key" ]
                    then
                        Println "$error 自动生成 WireGuard secretKey 失败, 请手动输入\n"
                        return 1
                    fi
                fi
                inquirer text_input "输入对端 publicKey" peer_pub ""
                inquirer text_input "输入 allowedIPs (逗号分隔)" allowed_ip "10.0.0.2/32"
                inquirer text_input "输入 MTU" mtu "1420"
                if [[ ! $mtu =~ ^[0-9]+$ ]]
                then
                    Println "$error MTU 必须为正整数\n"
                    return 1
                fi
                JQs build settings_json '{
                    "secretKey": $sk,
                    "mtu": ($mtu | tonumber),
                    "peers": [{"publicKey": $pk, "allowedIPs": ($ips | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0)))}]
                }' --arg sk "$secret_key" --arg mtu "$mtu" --arg pk "$peer_pub" --arg ips "$allowed_ip"
            ;;
            tun)
                local tun_name tun_mtu tun_gw tun_dns
                inquirer text_input "TUN 网卡名称" tun_name "xray0"
                inquirer text_input "MTU" tun_mtu "1500"
                if [[ ! $tun_mtu =~ ^[0-9]+$ ]]
                then
                    Println "$error MTU 必须为正整数\n"
                    return 1
                fi
                inquirer text_input "gateway (逗号分隔, 可留空)" tun_gw ""
                inquirer text_input "dns (逗号分隔, 可留空)" tun_dns ""
                JQs build settings_json '{
                    "name": $name,
                    "mtu": ($mtu | tonumber),
                    "gateway": (if $gw != "" then ($gw | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                    "dns": (if $dns != "" then ($dns | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end)
                }' --arg name "$tun_name" --arg mtu "$tun_mtu" --arg gw "$tun_gw" --arg dns "$tun_dns"
            ;;
            masque)
                local m_addr m_mtu m_pass m_email
                inquirer text_input "MASQUE address (逗号分隔)" m_addr "10.0.0.1/24"
                inquirer text_input "MTU" m_mtu "1280"
                if [[ ! $m_mtu =~ ^[0-9]+$ ]]
                then
                    Println "$error MTU 必须为正整数\n"
                    return 1
                fi
                inquirer text_input "用户 pass" m_pass ""
                inquirer text_input "用户 email (必填, 不能包含 :)" m_email ""
                if [ -z "$m_email" ] || [[ "$m_email" == *:* ]]
                then
                    Println "$error MASQUE 用户 email 必填且不能包含 :\n"
                    return 1
                fi
                JQs build settings_json '{
                    "address": ($addr | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "mtu": ($mtu | tonumber),
                    "users": [{"pass": $pass, "email": $email, "level": 0}]
                }' --arg addr "$m_addr" --arg mtu "$m_mtu" --arg pass "$m_pass" --arg email "$m_email"
            ;;
        esac

        local network="" security=""
        if [ "$protocol" == "masque" ]
        then
            network="masque"
            security="tls"
        elif [ "$protocol" == "hysteria" ]
        then
            network="hysteria"
            security="tls"
        else
            local net_options=( 'raw' 'xhttp' 'ws' 'grpc' 'httpupgrade' 'kcp' 'hysteria' )
            local net_idx=0
            inquirer list_input_index "选择传输方式" net_options net_idx
            network="${net_options[$net_idx]}"

            if [ "$network" == "hysteria" ]
            then
                security="tls"
            elif [ "$network" == "raw" ] || [ "$network" == "xhttp" ] || [ "$network" == "grpc" ]
            then
                local sec_options=( 'none' 'tls' 'reality' )
                local sec_idx=0
                inquirer list_input_index "选择传输安全" sec_options sec_idx
                security="${sec_options[$sec_idx]}"
            else
                local sec_options=( 'none' 'tls' )
                local sec_idx=0
                inquirer list_input_index "选择传输安全" sec_options sec_idx
                security="${sec_options[$sec_idx]}"
            fi
        fi

        if [ "$security" == "reality" ] && [ "$network" != "raw" ] && [ "$network" != "xhttp" ] && [ "$network" != "grpc" ]
        then
            Println "$tip REALITY 仅支持 raw/xhttp/grpc, 已自动回退为 tls\n"
            security="tls"
        fi

        local xhttp_host="" xhttp_path="" xhttp_mode=""
        local ws_path="" ws_host="" grpc_svc="" hu_path="" hu_host=""
        local tls_sni="" tls_cert="" tls_key=""
        local r_target="" r_sni="" r_pk="" r_sid=""

        case "$network" in
            xhttp)
                inquirer text_input "XHTTP host (可留空)" xhttp_host ""
                inquirer text_input "XHTTP path" xhttp_path "/"
                local xm_opts=( 'auto' 'packet-up' 'stream-up' 'stream-one' )
                inquirer list_input "选择 XHTTP mode" xm_opts xhttp_mode
            ;;
            ws)
                inquirer text_input "WebSocket path" ws_path "/"
                inquirer text_input "WebSocket host (可留空)" ws_host ""
            ;;
            grpc)
                inquirer text_input "gRPC serviceName" grpc_svc ""
            ;;
            httpupgrade)
                inquirer text_input "HTTPUpgrade path" hu_path "/"
                inquirer text_input "HTTPUpgrade host (可留空)" hu_host ""
            ;;
        esac

        if [ "$security" == "tls" ]
        then
            inquirer text_input "TLS serverName (可留空)" tls_sni ""
            inquirer text_input "证书文件路径 certificateFile" tls_cert ""
            inquirer text_input "私钥文件路径 keyFile" tls_key ""
        elif [ "$security" == "reality" ]
        then
            inquirer text_input "REALITY target (如 www.example.com:443)" r_target ""
            inquirer text_input "REALITY serverNames (逗号分隔)" r_sni ""
            inquirer text_input "REALITY privateKey (留空自动生成)" r_pk ""
            if [ -z "$r_pk" ]
            then
                if [ -n "$xray_bin" ]
                then
                    local x25519_out r_pub=""
                    x25519_out=$("$xray_bin" x25519 2> /dev/null)
                    r_pk=$(printf '%s\n' "$x25519_out" | awk -F': ' '/^Private[ ]?[Kk]ey:/ {print $2; exit}' | tr -d '\r\n ')
                    r_pub=$(printf '%s\n' "$x25519_out" | awk -F': ' '/^(Password|Public[ ]?[Kk]ey):/ {print $2; exit}' | tr -d '\r\n ')
                    if [ -n "$r_pk" ]
                    then
                        Println "$info 已自动生成 REALITY privateKey: ${green}${r_pk}${normal}\n"
                        if [ -n "$r_pub" ]
                        then
                            Println "$info 对应客户端公钥 (Password/PublicKey): ${green}${r_pub}${normal}\n"
                        fi
                    fi
                fi
                if [ -z "$r_pk" ]
                then
                    Println "$error 自动生成 REALITY privateKey 失败, 请手动输入\n"
                    return 1
                fi
            fi
            inquirer text_input "REALITY shortIds (逗号分隔, 留空默认为 [\"\"])" r_sid ""
        fi

        local yn_opts=( '否' '是' )
        local sniff_idx=1 route_only_idx=0
        inquirer list_input_index "开启流量探测 sniffing" yn_opts sniff_idx
        if [ "$sniff_idx" -eq 1 ]
        then
            inquirer list_input_index "嗅探域名仅用于路由 routeOnly" yn_opts route_only_idx
        fi

        local inbound_json=""
        JQs build inbound_json '{
            "listen": $listen,
            "port": (if ($port | test("^[0-9]+$")) then ($port | tonumber) else $port end),
            "protocol": $protocol,
            "tag": $tag,
            "settings": $settings,
            "streamSettings": {
                "network": $network,
                "security": $security,
                "xhttpSettings": (if $network == "xhttp" then {"host": $xh_host, "path": $xh_path, "mode": $xh_mode} else null end),
                "wsSettings": (if $network == "ws" then {"path": $ws_path, "host": $ws_host} else null end),
                "grpcSettings": (if $network == "grpc" then {"serviceName": $grpc_svc} else null end),
                "httpupgradeSettings": (if $network == "httpupgrade" then {"path": $hu_path, "host": $hu_host} else null end),
                "hysteriaSettings": (if $network == "hysteria" then {"version": 2} else null end),
                "tlsSettings": (if $security == "tls" then {
                    "serverName": $tls_sni,
                    "certificates": (if $tls_cert != "" then [{"certificateFile": $tls_cert, "keyFile": $tls_key}] else [] end)
                } else null end),
                "realitySettings": (if $security == "reality" then {
                    "target": $r_target,
                    "serverNames": (if $r_sni != "" then ($r_sni | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else [] end),
                    "privateKey": $r_pk
                } else null end)
            },
            "sniffing": {
                "enabled": ($sniff == "1"),
                "destOverride": (if $sniff == "1" then ["http", "tls", "quic"] else [] end),
                "routeOnly": ($route_only == "1")
            }
        }' \
            --arg listen "$listen" \
            --arg port "$port" \
            --arg protocol "$protocol" \
            --arg tag "$tag" \
            --argjson settings "$settings_json" \
            --arg network "$network" \
            --arg security "$security" \
            --arg xh_host "$xhttp_host" \
            --arg xh_path "$xhttp_path" \
            --arg xh_mode "$xhttp_mode" \
            --arg ws_path "$ws_path" \
            --arg ws_host "$ws_host" \
            --arg grpc_svc "$grpc_svc" \
            --arg hu_path "$hu_path" \
            --arg hu_host "$hu_host" \
            --arg tls_sni "$tls_sni" \
            --arg tls_cert "$tls_cert" \
            --arg tls_key "$tls_key" \
            --arg r_target "$r_target" \
            --arg r_sni "$r_sni" \
            --arg r_pk "$r_pk" \
            --arg sniff "$sniff_idx" \
            --arg route_only "$route_only_idx"

        if [ "$security" == "reality" ]
        then
            inbound_json=$($JQ_FILE -c --arg r_sid "$r_sid" '
                .streamSettings.realitySettings = (.streamSettings.realitySettings // {})
                | .streamSettings.realitySettings.shortIds = (
                    if $r_sid == "" then
                        [""]
                    else
                        ($r_sid | split(",") | map(gsub("^\\s+|\\s+$"; "")))
                    end
                )
            ' <<< "$inbound_json")
        fi

        if [ "$network" == "masque" ]
        then
            inbound_json=$($JQ_FILE -c '
                .streamSettings.masqueSettings = (.streamSettings.masqueSettings // {})
            ' <<< "$inbound_json")
        fi

        if ! ProxyAddBound "$X_CONFIG" inbounds "$inbound_json"
        then
            Println "$error 添加 Xray 入站 ${tag} 失败\n"
            return 1
        fi
        ProxyRestartIfActive xray
        Println "$info 已添加 Xray 入站 ${green}${tag}${normal} (${protocol})\n"
    }
    XrayDeleteInbound()
    {
        ProxySelectBound "$X_CONFIG" inbounds "选择要删除的入站" || return 1
        local target_tag="${inbounds_tag[selected_bound_index]}"
        ProxyDeleteBound "$X_CONFIG" inbounds "$selected_bound_index"
        ProxyRestartIfActive xray
        Println "$info 已删除入站 ${green}${target_tag}${normal}\n"
    }
    XrayGenUuid()
    {
        local xray_bin=""
        if [ -n "${XRAY_FILE:-}" ] && [ -x "$XRAY_FILE" ]
        then
            xray_bin="$XRAY_FILE"
        elif [ -n "${XCTL_FILE:-}" ] && [ -x "$XCTL_FILE" ]
        then
            xray_bin="$XCTL_FILE"
        elif command -v xray > /dev/null 2>&1
        then
            xray_bin=$(command -v xray)
        fi

        local gen=""
        if [ -n "$xray_bin" ]
        then
            gen=$("$xray_bin" uuid 2> /dev/null | head -n 1 | tr -d '\r\n')
        fi
        if [ -z "$gen" ] && command -v uuidgen > /dev/null 2>&1
        then
            gen=$(uuidgen 2> /dev/null | tr '[:upper:]' '[:lower:]' | tr -d '\r\n')
        fi
        if [ -z "$gen" ] && [ -r /proc/sys/kernel/random/uuid ]
        then
            gen=$(cat /proc/sys/kernel/random/uuid | tr -d '\r\n')
        fi
        printf '%s' "$gen"
    }

    XrayGenSs2022Key()
    {
        local method="$1"
        local bytes=32
        if [[ "$method" == *aes-128* ]]
        then
            bytes=16
        fi
        openssl rand -base64 "$bytes" 2> /dev/null | tr -d '\r\n'
    }

    XrayAddInboundAccount()
    {
        ProxySelectBound "$X_CONFIG" inbounds "选择要添加账号的入站" || return 1
        local idx="$selected_bound_index"
        local protocol="${inbounds_protocol[idx]}"
        local user_json=""
        local acc_key="users"

        if [ "$protocol" == "wireguard" ]
        then
            acc_key="peers"
        else
            acc_key=$(JQs query "$X_CONFIG" '
                if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                    and (.inbounds[$i].settings | type) == "object"
                then
                    if (.inbounds[$i].settings.users | type) == "array" then "users"
                    elif (.inbounds[$i].settings.clients | type) == "array" then "clients"
                    elif (.inbounds[$i].settings.accounts | type) == "array" then "accounts"
                    else "users" end
                else "users" end
            ' --argjson i "$idx")
            acc_key="${acc_key:-users}"
        fi

        case "$protocol" in
            vless)
                local uuid flow email
                inquirer text_input "输入用户 UUID (留空自动生成)" uuid ""
                if [ -z "$uuid" ]
                then
                    uuid=$(XrayGenUuid)
                    if [ -z "$uuid" ]
                    then
                        Println "$error 自动生成 UUID 失败, 请手动输入\n"
                        return 1
                    fi
                    Println "$info 已自动生成 UUID: ${green}${uuid}${normal}\n"
                fi
                inquirer text_input "输入 flow (可留空)" flow ""
                inquirer text_input "输入 email (可留空)" email ""
                JQs build user_json '{"id": $id, "flow": $flow, "email": $email, "level": 0}' \
                    --arg id "$uuid" --arg flow "$flow" --arg email "$email"
            ;;
            vmess)
                local uuid email
                inquirer text_input "输入用户 UUID (留空自动生成)" uuid ""
                if [ -z "$uuid" ]
                then
                    uuid=$(XrayGenUuid)
                    if [ -z "$uuid" ]
                    then
                        Println "$error 自动生成 UUID 失败, 请手动输入\n"
                        return 1
                    fi
                    Println "$info 已自动生成 UUID: ${green}${uuid}${normal}\n"
                fi
                inquirer text_input "输入 email (可留空)" email ""
                JQs build user_json '{"id": $id, "email": $email, "level": 0}' \
                    --arg id "$uuid" --arg email "$email"
            ;;
            trojan)
                local password email
                inquirer text_input "输入密码" password ""
                inquirer text_input "输入 email (可留空)" email ""
                JQs build user_json '{"password": $pw, "email": $email, "level": 0}' \
                    --arg pw "$password" --arg email "$email"
            ;;
            shadowsocks)
                local inb_method
                inb_method=$(JQs query "$X_CONFIG" '
                    if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                        and (.inbounds[$i].settings | type) == "object"
                    then (.inbounds[$i].settings.method // "")
                    else "" end
                ' --argjson i "$idx")
                local password email user_method=""
                if [[ "$inb_method" == 2022-* ]]
                then
                    inquirer text_input "输入密钥 (SS2022 留空自动生成)" password ""
                    if [ -z "$password" ]
                    then
                        password=$(XrayGenSs2022Key "$inb_method")
                        if [ -z "$password" ]
                        then
                            Println "$error 自动生成 SS2022 密钥失败, 请手动输入\n"
                            return 1
                        fi
                        Println "$info 已自动生成 SS2022 密钥: ${green}${password}${normal}\n"
                    fi
                    inquirer text_input "输入 email (可留空)" email ""
                    JQs build user_json '{"password": $pw, "email": $email, "level": 0}' \
                        --arg pw "$password" --arg email "$email"
                else
                    inquirer text_input "输入用户加密方式 method" user_method "${inb_method:-aes-256-gcm}"
                    inquirer text_input "输入密码" password ""
                    inquirer text_input "输入 email (可留空)" email ""
                    JQs build user_json '{"method": $method, "password": $pw, "email": $email, "level": 0}' \
                        --arg method "$user_method" --arg pw "$password" --arg email "$email"
                fi
            ;;
            socks|http)
                local user pass
                inquirer text_input "输入用户名" user ""
                inquirer text_input "输入密码" pass ""
                JQs build user_json '{"user": $user, "pass": $pass}' \
                    --arg user "$user" --arg pass "$pass"
            ;;
            hysteria)
                local auth email
                inquirer text_input "输入认证密钥 auth" auth ""
                inquirer text_input "输入 email (可留空)" email ""
                JQs build user_json '{"auth": $auth, "email": $email, "level": 0}' \
                    --arg auth "$auth" --arg email "$email"
            ;;
            masque)
                local pass email
                inquirer text_input "输入用户 pass" pass ""
                inquirer text_input "输入用户 email (必填, 不能包含 :)" email ""
                if [ -z "$email" ] || [[ "$email" == *:* ]]
                then
                    Println "$error MASQUE 用户 email 必填且不能包含 :\n"
                    return 1
                fi
                JQs build user_json '{"pass": $pass, "email": $email, "level": 0}' \
                    --arg pass "$pass" --arg email "$email"
            ;;
            wireguard)
                local pk allowed_ips psk
                inquirer text_input "输入对端 publicKey" pk ""
                inquirer text_input "输入 allowedIPs (逗号分隔)" allowed_ips "10.0.0.2/32"
                inquirer text_input "输入 preSharedKey (可留空)" psk ""
                JQs build user_json '{
                    "publicKey": $pk,
                    "allowedIPs": ($ips | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "preSharedKey": $psk
                }' --arg pk "$pk" --arg ips "$allowed_ips" --arg psk "$psk"
            ;;
            *)
                Println "$error 协议 ${protocol} 不支持多账号管理\n"
                return 1
            ;;
        esac

        jq_path='["inbounds",'"$idx"',"settings","'"$acc_key"'"]'
        if ! JQ add "$X_CONFIG" "[$user_json]"
        then
            Println "$error 向入站 ${inbounds_tag[idx]} 添加账号失败\n"
            return 1
        fi
        ProxyRestartIfActive xray
        Println "$info 已向入站 ${green}${inbounds_tag[idx]}${normal} 添加账号\n"
    }

    XrayDeleteInboundAccount()
    {
        ProxySelectBound "$X_CONFIG" inbounds "选择要删除账号的入站" || return 1
        local idx="$selected_bound_index"
        local acc_key
        acc_key=$(JQs query "$X_CONFIG" '
            if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].settings | type) == "object"
            then
                if (.inbounds[$i].settings.peers | type) == "array" and (.inbounds[$i].settings.peers | length) > 0 then "peers"
                elif (.inbounds[$i].settings.users | type) == "array" and (.inbounds[$i].settings.users | length) > 0 then "users"
                elif (.inbounds[$i].settings.clients | type) == "array" and (.inbounds[$i].settings.clients | length) > 0 then "clients"
                elif (.inbounds[$i].settings.accounts | type) == "array" and (.inbounds[$i].settings.accounts | length) > 0 then "accounts"
                else "" end
            else "" end
        ' --argjson i "$idx")

        if [ -z "$acc_key" ]
        then
            Println "$error 该入站没有可删除的账号\n"
            return 1
        fi

        local user_options=()
        local line
        while IFS= read -r line
        do
            [ -n "$line" ] && user_options+=("$line")
        done < <(JQs query "$X_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].settings | type) == "object"
                and (.inbounds[$i].settings[$k] | type) == "array"
             then .inbounds[$i].settings[$k]
             else [] end)
            | to_entries[]
            | select(.value | type == "object")
            | "\(.key + 1). \(.value.email // .value.id // .value.user // .value.publicKey // .value.password // .value.pass // .value.auth // "user")"
        ' --argjson i "$idx" --arg k "$acc_key")

        if [ "${#user_options[@]}" -eq 0 ]
        then
            Println "$error 该入站没有可删除的账号\n"
            return 1
        fi

        local user_idx=0
        echo
        inquirer list_input_index "选择要删除的账号" user_options user_idx
        jq_path='["inbounds",'"$idx"',"settings","'"$acc_key"'",'"$user_idx"']'
        if ! JQ delete "$X_CONFIG"
        then
            Println "$error 删除账号失败\n"
            return 1
        fi
        ProxyRestartIfActive xray
        Println "$info 已删除账号 ${green}${user_options[user_idx]}${normal}\n"
    }
    XrayGetOutbounds()
    {
        ProxyLoadOutboundsIndex "$X_CONFIG"
    }
    XrayListOutbounds()
    {
        XrayGetOutbounds

        if [ "$outbounds_count" -eq 0 ]
        then
            Println "$error 没有出站\n"
            return 1
        fi

        Println "\n=== 出站数 ${green} $outbounds_count ${normal}"
        outbounds_list=$(ProxyRenderOutbounds "$X_CONFIG" xray)
        Println "$outbounds_list"
    }
    XrayListOutboundAccounts()
    {
        XrayListOutbounds || return 1

        ProxySelectBound "$X_CONFIG" outbounds "选择查看账号/服务端明细的出站" || return 0
        local idx="$selected_bound_index"
        local accounts_out
        accounts_out=$(ProxyRenderOutboundAccounts "$X_CONFIG" "$idx")

        if [ -z "$accounts_out" ]
        then
            Println "$info 出站 ${green}${outbounds_tag[idx]}${normal} 没有账号/服务端明细\n"
            return 0
        fi

        Println "\n=== 出站 ${green}${outbounds_tag[idx]}${normal} 账号/服务端明细 ===\n$accounts_out\n"
    }
    XrayAddOutbound()
    {
        local proto_options=( 'freedom' 'blackhole' 'dns' 'vless' 'vmess' 'trojan' 'shadowsocks' 'socks' 'http' 'loopback' 'hysteria' 'wireguard' 'masque' )
        local proto_idx=0
        echo
        inquirer list_input_index "选择出站协议" proto_options proto_idx
        local protocol="${proto_options[$proto_idx]}"

        local tag send_through target_strategy="" dialer_proxy
        inquirer text_input "输入出站标识 (留空随机)" tag ""
        if [ -z "$tag" ]
        then
            tag=$(ProxyGetFreeTag "$X_CONFIG" "${protocol}-out-")
        fi
        inquirer text_input "输入 sendThrough (可留空)" send_through ""
        if [ "$protocol" != "freedom" ]
        then
            inquirer text_input "输入 targetStrategy (AsIs/UseIP/UseIPv4/UseIPv6, 可留空)" target_strategy ""
        fi
        inquirer text_input "输入前置代理 sockopt.dialerProxy (可留空)" dialer_proxy ""

        local settings_json='{}'
        local hy_auth=""
        case "$protocol" in
            freedom)
                local redirect proxy_proto
                inquirer text_input "输入 redirect (可留空)" redirect ""
                inquirer text_input "输入 proxyProtocol (0/1/2, 可留空)" proxy_proto ""
                if [ -n "$proxy_proto" ] && [[ ! $proxy_proto =~ ^[0-2]$ ]]
                then
                    Println "$error proxyProtocol 必须为 0、1 或 2\n"
                    return 1
                fi
                JQs build settings_json '{
                    "redirect": $redirect,
                    "proxyProtocol": (if $pp != "" then ($pp | tonumber) else null end)
                }' --arg redirect "$redirect" --arg pp "$proxy_proto"
            ;;
            blackhole)
                local resp_type
                inquirer text_input "响应类型 (none/http)" resp_type "none"
                JQs build settings_json '{"response": {"type": $rt}}' --arg rt "$resp_type"
            ;;
            dns)
                local rw_net rw_addr rw_port
                inquirer text_input "rewriteNetwork (tcp/udp, 可留空)" rw_net ""
                inquirer text_input "rewriteAddress (可留空)" rw_addr ""
                inquirer text_input "rewritePort (可留空)" rw_port ""
                if [ -n "$rw_port" ] && ([[ ! $rw_port =~ ^[0-9]+$ ]] || [ "$rw_port" -lt 1 ] || [ "$rw_port" -gt 65535 ])
                then
                    Println "$error rewritePort 必须为 1-65535 的整数\n"
                    return 1
                fi
                JQs build settings_json '{
                    "rewriteNetwork": $net,
                    "rewriteAddress": $addr,
                    "rewritePort": (if $port != "" then ($port | tonumber) else null end)
                }' --arg net "$rw_net" --arg addr "$rw_addr" --arg port "$rw_port"
            ;;
            vless)
                local addr port uuid encryption flow
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "用户 UUID" uuid ""
                inquirer text_input "encryption" encryption "none"
                inquirer text_input "flow (可留空)" flow ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "id": $id,
                    "encryption": $enc,
                    "flow": $flow
                }' --arg addr "$addr" --arg port "$port" --arg id "$uuid" --arg enc "$encryption" --arg flow "$flow"
            ;;
            vmess)
                local addr port uuid sec
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "用户 UUID" uuid ""
                inquirer text_input "security (auto/aes-128-gcm/chacha20-poly1305)" sec "auto"
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "id": $id,
                    "security": $sec
                }' --arg addr "$addr" --arg port "$port" --arg id "$uuid" --arg sec "$sec"
            ;;
            trojan)
                local addr port password
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "密码 password" password ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "password": $pw
                }' --arg addr "$addr" --arg port "$port" --arg pw "$password"
            ;;
            shadowsocks)
                local addr port method password
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "8388"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "加密方式 method" method "2022-blake3-aes-256-gcm"
                inquirer text_input "密钥 password" password ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "method": $method,
                    "password": $pw
                }' --arg addr "$addr" --arg port "$port" --arg method "$method" --arg pw "$password"
            ;;
            socks|http)
                local addr port user pass
                inquirer text_input "服务端地址 address" addr "127.0.0.1"
                inquirer text_input "服务端端口 port" port "1080"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "用户名 (可留空)" user ""
                inquirer text_input "密码 (可留空)" pass ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "user": $user,
                    "pass": $pass
                }' --arg addr "$addr" --arg port "$port" --arg user "$user" --arg pass "$pass"
            ;;
            loopback)
                local inb_tag
                inquirer text_input "目标 inboundTag" inb_tag ""
                JQs build settings_json '{"inboundTag": $t}' --arg t "$inb_tag"
            ;;
            hysteria)
                local addr port
                inquirer text_input "服务端地址 address" addr ""
                inquirer text_input "服务端端口 port" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "认证密钥 auth" hy_auth ""
                JQs build settings_json '{"version": 2, "address": $addr, "port": ($port | tonumber)}' --arg addr "$addr" --arg port "$port"
            ;;
            wireguard)
                local sk addr endpoint pk
                inquirer text_input "本地 secretKey" sk ""
                inquirer text_input "本地接口地址 (逗号分隔)" addr "10.0.0.2/32"
                inquirer text_input "对端 endpoint" endpoint ""
                inquirer text_input "对端 publicKey" pk ""
                JQs build settings_json '{
                    "secretKey": $sk,
                    "address": ($addr | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "peers": [{"endpoint": $ep, "publicKey": $pk}]
                }' --arg sk "$sk" --arg addr "$addr" --arg ep "$endpoint" --arg pk "$pk"
            ;;
            masque)
                local m_addr m_port m_user m_pass m_mtu
                inquirer text_input "服务端地址 address" m_addr ""
                inquirer text_input "服务端端口 port" m_port "443"
                if [[ ! $m_port =~ ^[0-9]+$ ]] || [ "$m_port" -lt 1 ] || [ "$m_port" -gt 65535 ]
                then
                    Println "$error 服务端端口必须为 1-65535 的整数\n"
                    return 1
                fi
                inquirer text_input "用户 email (可留空)" m_user ""
                inquirer text_input "用户 pass (可留空)" m_pass ""
                inquirer text_input "MTU" m_mtu "1280"
                if [[ ! $m_mtu =~ ^[0-9]+$ ]]
                then
                    Println "$error MTU 必须为正整数\n"
                    return 1
                fi
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "email": $email,
                    "pass": $pass,
                    "mtu": ($mtu | tonumber)
                }' --arg addr "$m_addr" --arg port "$m_port" --arg email "$m_user" --arg pass "$m_pass" --arg mtu "$m_mtu"
            ;;
        esac

        local network="" security=""
        local xhttp_host="" xhttp_path="" xhttp_mode=""
        local ws_path="" ws_host="" grpc_svc="" hu_path="" hu_host=""
        local tls_sni="" tls_fp=""
        local r_sni="" r_fp="" r_pw="" r_sid="" r_spx=""

        case "$protocol" in
            hysteria)
                network="hysteria"
                security="tls"
                inquirer text_input "TLS serverName (可留空)" tls_sni ""
                inquirer text_input "TLS fingerprint (如 chrome, 可留空)" tls_fp ""
            ;;
            masque)
                network="masque"
                security="tls"
                inquirer text_input "TLS serverName (可留空)" tls_sni ""
                inquirer text_input "TLS fingerprint (如 chrome, 可留空)" tls_fp ""
            ;;
            vless|vmess|trojan|shadowsocks)
                local net_options=( 'raw' 'xhttp' 'ws' 'grpc' 'httpupgrade' 'kcp' )
                local net_idx=0
                inquirer list_input_index "选择传输方式" net_options net_idx
                network="${net_options[$net_idx]}"

                if [ "$network" == "raw" ] || [ "$network" == "xhttp" ] || [ "$network" == "grpc" ]
                then
                    local sec_options=( 'none' 'tls' 'reality' )
                    local sec_idx=0
                    inquirer list_input_index "选择传输安全" sec_options sec_idx
                    security="${sec_options[$sec_idx]}"
                else
                    local sec_options=( 'none' 'tls' )
                    local sec_idx=0
                    inquirer list_input_index "选择传输安全" sec_options sec_idx
                    security="${sec_options[$sec_idx]}"
                fi

                case "$network" in
                    xhttp)
                        inquirer text_input "XHTTP host (可留空)" xhttp_host ""
                        inquirer text_input "XHTTP path" xhttp_path "/"
                        local xm_opts=( 'auto' 'packet-up' 'stream-up' 'stream-one' )
                        inquirer list_input "选择 XHTTP mode" xm_opts xhttp_mode
                    ;;
                    ws)
                        inquirer text_input "WebSocket path" ws_path "/"
                        inquirer text_input "WebSocket host (可留空)" ws_host ""
                    ;;
                    grpc)
                        inquirer text_input "gRPC serviceName" grpc_svc ""
                    ;;
                    httpupgrade)
                        inquirer text_input "HTTPUpgrade path" hu_path "/"
                        inquirer text_input "HTTPUpgrade host (可留空)" hu_host ""
                    ;;
                esac

                if [ "$security" == "tls" ]
                then
                    inquirer text_input "TLS serverName (可留空)" tls_sni ""
                    inquirer text_input "TLS fingerprint (如 chrome, 可留空)" tls_fp ""
                elif [ "$security" == "reality" ]
                then
                    inquirer text_input "REALITY serverName" r_sni ""
                    inquirer text_input "REALITY fingerprint" r_fp "chrome"
                    inquirer text_input "REALITY 公钥 password" r_pw ""
                    inquirer text_input "REALITY shortId (可留空)" r_sid ""
                    inquirer text_input "REALITY spiderX (可留空)" r_spx ""
                fi
            ;;
        esac

        local outbound_json=""
        JQs build outbound_json '{
            "sendThrough": $st,
            "protocol": $protocol,
            "tag": $tag,
            "targetStrategy": $ts,
            "settings": $settings,
            "streamSettings": (
                if $network != "" or $dp != "" then {
                    "network": $network,
                    "security": $security,
                    "xhttpSettings": (if $network == "xhttp" then {"host": $xh_host, "path": $xh_path, "mode": $xh_mode} else null end),
                    "wsSettings": (if $network == "ws" then {"path": $ws_path, "host": $ws_host} else null end),
                    "grpcSettings": (if $network == "grpc" then {"serviceName": $grpc_svc} else null end),
                    "httpupgradeSettings": (if $network == "httpupgrade" then {"path": $hu_path, "host": $hu_host} else null end),
                    "hysteriaSettings": (if $network == "hysteria" then {"version": 2, "auth": $hy_auth} else null end),
                    "tlsSettings": (if $security == "tls" then {"serverName": $tls_sni, "fingerprint": $tls_fp} else null end),
                    "realitySettings": (if $security == "reality" then {
                        "serverName": $r_sni,
                        "fingerprint": $r_fp,
                        "password": $r_pw,
                        "shortId": $r_sid,
                        "spiderX": $r_spx
                    } else null end),
                    "sockopt": (if $dp != "" then {"dialerProxy": $dp} else null end)
                } else null end
            )
        }' \
            --arg st "$send_through" \
            --arg protocol "$protocol" \
            --arg tag "$tag" \
            --arg ts "$target_strategy" \
            --argjson settings "$settings_json" \
            --arg network "$network" \
            --arg security "$security" \
            --arg xh_host "$xhttp_host" \
            --arg xh_path "$xhttp_path" \
            --arg xh_mode "$xhttp_mode" \
            --arg ws_path "$ws_path" \
            --arg ws_host "$ws_host" \
            --arg grpc_svc "$grpc_svc" \
            --arg hu_path "$hu_path" \
            --arg hu_host "$hu_host" \
            --arg hy_auth "$hy_auth" \
            --arg tls_sni "$tls_sni" \
            --arg tls_fp "$tls_fp" \
            --arg r_sni "$r_sni" \
            --arg r_fp "$r_fp" \
            --arg r_pw "$r_pw" \
            --arg r_sid "$r_sid" \
            --arg r_spx "$r_spx" \
            --arg dp "$dialer_proxy"

        if [ "$network" == "masque" ]
        then
            outbound_json=$($JQ_FILE -c '
                .streamSettings = (.streamSettings // {})
                | .streamSettings.masqueSettings = (.streamSettings.masqueSettings // {})
            ' <<< "$outbound_json")
        fi

        if ! ProxyAddBound "$X_CONFIG" outbounds "$outbound_json"
        then
            Println "$error 添加 Xray 出站 ${tag} 失败\n"
            return 1
        fi
        ProxyRestartIfActive xray
        Println "$info 已添加 Xray 出站 ${green}${tag}${normal} (${protocol})\n"
    }
    XrayDeleteOutbound()
    {
        ProxySelectBound "$X_CONFIG" outbounds "选择要删除的出站" || return 1
        local target_tag="${outbounds_tag[selected_bound_index]}"
        ProxyDeleteBound "$X_CONFIG" outbounds "$selected_bound_index"
        ProxyRestartIfActive xray
        Println "$info 已删除出站 ${green}${target_tag}${normal}\n"
    }
    XrayAddOutboundAccount()
    {
        ProxySelectBound "$X_CONFIG" outbounds "选择要更新凭据/对端的出站" || return 1
        local idx="$selected_bound_index"
        local protocol="${outbounds_protocol[idx]}"

        case "$protocol" in
            wireguard)
                local ep pk psk ka
                inquirer text_input "输入对端 endpoint" ep ""
                inquirer text_input "输入对端 publicKey" pk ""
                inquirer text_input "输入 preSharedKey (可留空)" psk ""
                inquirer text_input "输入 keepAlive (可留空)" ka ""
                if [ -n "$ka" ] && [[ ! $ka =~ ^[0-9]+$ ]]
                then
                    Println "$error keepAlive 必须为非负整数\n"
                    return 1
                fi
                local peer_json=""
                JQs build peer_json '{
                    "endpoint": $ep,
                    "publicKey": $pk,
                    "preSharedKey": $psk,
                    "keepAlive": (if $ka != "" then ($ka | tonumber) else null end)
                }' --arg ep "$ep" --arg pk "$pk" --arg psk "$psk" --arg ka "$ka"
                jq_path='["outbounds",'"$idx"',"settings","peers"]'
                if ! JQ add "$X_CONFIG" "[$peer_json]"
                then
                    Println "$error 添加 WireGuard peer 失败\n"
                    return 1
                fi
                Println "$info 已向出站 ${green}${outbounds_tag[idx]}${normal} 添加 WireGuard peer\n"
            ;;
            vless|vmess)
                local uuid has_vnext
                inquirer text_input "输入新的用户 UUID" uuid ""
                has_vnext=$(JQs query "$X_CONFIG" '
                    if (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.vnext | type) == "array"
                        and (.outbounds[$i].settings.vnext | length) > 0
                    then "1" else "0" end
                ' --argjson i "$idx")
                if [ "$has_vnext" == "1" ]
                then
                    if ! JQ mutate "$X_CONFIG" '.outbounds[$i].settings.vnext[0].users = (if (.outbounds[$i].settings.vnext[0].users | type) == "array" and (.outbounds[$i].settings.vnext[0].users | length) > 0 then (.outbounds[$i].settings.vnext[0].users | .[0].id = $id) else [{"id": $id}] end)' --argjson i "$idx" --arg id "$uuid"
                    then
                        Println "$error 更新出站 ${outbounds_tag[idx]} 的 UUID 失败\n"
                        return 1
                    fi
                else
                    jq_path='["outbounds",'"$idx"',"settings","id"]'
                    if ! JQ update "$X_CONFIG" "$uuid"
                    then
                        Println "$error 更新出站 ${outbounds_tag[idx]} 的 UUID 失败\n"
                        return 1
                    fi
                fi
                Println "$info 已更新出站 ${green}${outbounds_tag[idx]}${normal} 的 UUID\n"
            ;;
            trojan|shadowsocks)
                local pw has_servers
                inquirer text_input "输入新的密码" pw ""
                has_servers=$(JQs query "$X_CONFIG" '
                    if (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.servers | type) == "array"
                        and (.outbounds[$i].settings.servers | length) > 0
                    then "1" else "0" end
                ' --argjson i "$idx")
                if [ "$has_servers" == "1" ]
                then
                    if ! JQ mutate "$X_CONFIG" '.outbounds[$i].settings.servers[0].password = $pw' --argjson i "$idx" --arg pw "$pw"
                    then
                        Println "$error 更新出站 ${outbounds_tag[idx]} 的密码失败\n"
                        return 1
                    fi
                else
                    jq_path='["outbounds",'"$idx"',"settings","password"]'
                    if ! JQ update "$X_CONFIG" "$pw"
                    then
                        Println "$error 更新出站 ${outbounds_tag[idx]} 的密码失败\n"
                        return 1
                    fi
                fi
                Println "$info 已更新出站 ${green}${outbounds_tag[idx]}${normal} 的密码\n"
            ;;
            socks|http)
                local user pass has_servers auth_json=""
                inquirer text_input "输入用户名" user ""
                inquirer text_input "输入密码" pass ""
                has_servers=$(JQs query "$X_CONFIG" '
                    if (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.servers | type) == "array"
                        and (.outbounds[$i].settings.servers | length) > 0
                    then "1" else "0" end
                ' --argjson i "$idx")
                if [ "$has_servers" == "1" ]
                then
                    if ! JQ mutate "$X_CONFIG" '.outbounds[$i].settings.servers[0].users = [{"user": $u, "pass": $p}]' --argjson i "$idx" --arg u "$user" --arg p "$pass"
                    then
                        Println "$error 更新出站 ${outbounds_tag[idx]} 的账号密码失败\n"
                        return 1
                    fi
                else
                    JQs build auth_json '{"user": $u, "pass": $p}' --arg u "$user" --arg p "$pass"
                    jq_merge=true
                    jq_path='["outbounds",'"$idx"',"settings"]'
                    if ! JQ update "$X_CONFIG" "$auth_json"
                    then
                        Println "$error 更新出站 ${outbounds_tag[idx]} 的账号密码失败\n"
                        return 1
                    fi
                fi
                Println "$info 已更新出站 ${green}${outbounds_tag[idx]}${normal} 的账号密码\n"
            ;;
            *)
                Println "$error 出站协议 ${protocol} 不支持账号/凭据更新\n"
                return 1
            ;;
        esac

        ProxyRestartIfActive xray
    }

    XrayDeleteOutboundAccount()
    {
        ProxySelectBound "$X_CONFIG" outbounds "选择要清理凭据/对端的出站" || return 1
        local idx="$selected_bound_index"
        local protocol="${outbounds_protocol[idx]}"

        case "$protocol" in
            wireguard)
                local peer_options=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && peer_options+=("$line")
                done < <(JQs query "$X_CONFIG" '
                    (if (.outbounds | type) == "array" and (.outbounds[$i] | type) == "object"
                        and (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.peers | type) == "array"
                     then .outbounds[$i].settings.peers
                     else [] end)
                    | to_entries[]
                    | select(.value | type == "object")
                    | "\(.key + 1). \(.value.endpoint // .value.publicKey // "peer")"
                ' --argjson i "$idx")
                if [ "${#peer_options[@]}" -eq 0 ]
                then
                    Println "$error 该出站没有可删除的 peer\n"
                    return 1
                fi
                local peer_idx=0
                inquirer list_input_index "选择要删除的 peer" peer_options peer_idx
                jq_path='["outbounds",'"$idx"',"settings","peers",'"$peer_idx"']'
                if ! JQ delete "$X_CONFIG"
                then
                    Println "$error 删除 peer 失败\n"
                    return 1
                fi
                Println "$info 已删除 peer ${green}${peer_options[peer_idx]}${normal}\n"
            ;;
            socks|http)
                if ! JQ mutate "$X_CONFIG" '
                    del(.outbounds[$i].settings.user, .outbounds[$i].settings.pass)
                    | if (.outbounds[$i].settings.servers | type) == "array" and (.outbounds[$i].settings.servers | length) > 0 then
                        del(.outbounds[$i].settings.servers[0].users)
                      else . end
                ' --argjson i "$idx"
                then
                    Println "$error 清除出站 ${outbounds_tag[idx]} 的认证账号失败\n"
                    return 1
                fi
                Println "$info 已清除出站 ${green}${outbounds_tag[idx]}${normal} 的认证账号\n"
            ;;
            *)
                Println "$error 出站协议 ${protocol} 请直接删除或重建出站\n"
                return 1
            ;;
        esac

        ProxyRestartIfActive xray
    }
    XrayGetDns()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.dns')

        jq_path='["hosts"]'

        dns_hosts_domain=()
        dns_hosts_address=()

        while IFS="^" read -r dns_host_domain dns_host_address; do
            dns_hosts_domain+=("$dns_host_domain")
            dns_hosts_address+=("$dns_host_address")
        done < <(JQs get jq_payload '. // {} | to_entries[] | "\(.key)^\(.value)"')

        dns_hosts_count="${#dns_hosts_domain[@]}"

        jq_path='[
            ["servers"],
            ["clientIp"],
            ["queryStrategy"],
            ["disableCache"],
            ["serveStale"],
            ["serveExpiredTTL"],
            ["disableFallback"],
            ["disableFallbackIfMatch"],
            ["enableParallelQuery"],
            ["useSystemHosts"],
            ["tag"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="jq_dns_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        dns_clientIp="${jq_dns_clientIp:-}"
        dns_queryStrategy="${jq_dns_queryStrategy:-UseIP}"
        dns_disableCache="${jq_dns_disableCache:-false}"
        dns_serveStale="${jq_dns_serveStale:-false}"
        dns_serveExpiredTTL="${jq_dns_serveExpiredTTL:-0}"
        dns_disableFallback="${jq_dns_disableFallback:-false}"
        dns_disableFallbackIfMatch="${jq_dns_disableFallbackIfMatch:-false}"
        dns_enableParallelQuery="${jq_dns_enableParallelQuery:-false}"
        dns_useSystemHosts="${jq_dns_useSystemHosts:-false}"
        dns_tag="${jq_dns_tag:-dns_inbound}"

        if [ -z "${jq_dns_servers:-}" ]
        then
            dns_servers_count=0
            return 0
        fi

        IFS="${delimiters[1]}" read -r -a dns_servers <<< "$jq_dns_servers"

        dns_servers_count=${#dns_servers[@]}
    }
    XrayListDns()
    {
        local out
        out=$(ProxyRenderDns "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$error 未配置 DNS\n"
            return 1
        fi
        Println "\n=== Xray DNS 配置 ===\n$out\n"
    }
    XraySetDns()
    {
        local actions=(
            '添加静态 IP (hosts)'
            '添加 DNS 服务器'
            '设置 clientIp'
            '设置 DNS 标识 tag'
            '设置 queryStrategy'
            '设置缓存与回退开关'
            '删除静态 IP (hosts)'
            '删除 DNS 服务器'
        )
        local action_idx=0
        echo
        inquirer list_input_index "选择 Xray DNS 操作" actions action_idx

        case "$action_idx" in
            0)
                local domain ips
                Println "$tip 格式如 example.com, domain:example.com, geosite:cn"
                inquirer text_input "输入域名或规则" domain ""
                inquirer text_input "输入目标 IP/域名 (逗号分隔)" ips ""
                if [ -z "$domain" ] || [ -z "$ips" ]
                then
                    Println "$error 域名和目标 IP/域名不能为空\n"
                    return 1
                fi
                if ! JQ mutate "$X_CONFIG" '.dns.hosts = ((.dns.hosts // {}) + {($d): (if ($v | contains(",")) then ($v | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else ($v | gsub("^\\s+|\\s+$"; "")) end)})' \
                    --arg d "$domain" --arg v "$ips"
                then
                    Println "$error 添加静态 IP 失败\n"
                    return 1
                fi
                Println "$info 静态 IP 添加成功: ${green}${domain}${normal}\n"
            ;;
            1)
                local addr port client_ip domains expected_ips unexpected_ips timeout_ms
                local skip_fb_opts=( '否' '是' )
                local skip_fb_idx=0 final_q_idx=0
                inquirer text_input "输入 DNS 地址 (如 1.1.1.1, https://...)" addr "1.1.1.1"
                inquirer text_input "输入端口 (留空默认)" port ""
                if [ -n "$port" ] && [[ ! $port =~ ^[0-9]+$ ]]
                then
                    Println "$error DNS 端口必须为非负整数\n"
                    return 1
                fi
                inquirer text_input "输入服务器级 clientIP (可留空)" client_ip ""
                inquirer text_input "输入匹配 domains (逗号分隔, 可留空)" domains ""
                inquirer text_input "输入 expectedIPs (逗号分隔, 可留空)" expected_ips ""
                inquirer text_input "输入 unexpectedIPs (逗号分隔, 可留空)" unexpected_ips ""
                inquirer text_input "输入 timeoutMs (可留空)" timeout_ms ""
                if [ -n "$timeout_ms" ] && [[ ! $timeout_ms =~ ^[0-9]+$ ]]
                then
                    Println "$error timeoutMs 必须为非负整数\n"
                    return 1
                fi
                inquirer list_input_index "跳过回退 skipFallback" skip_fb_opts skip_fb_idx
                inquirer list_input_index "终止后续查询 finalQuery" skip_fb_opts final_q_idx

                local srv_json=""
                if [ -z "$port" ] && [ -z "$client_ip" ] && [ -z "$domains" ] && [ -z "$expected_ips" ] && [ -z "$unexpected_ips" ] && [ -z "$timeout_ms" ] && [ "$skip_fb_idx" -eq 0 ] && [ "$final_q_idx" -eq 0 ]
                then
                    JQs build srv_json '$addr' --arg addr "$addr"
                else
                    JQs build srv_json '{
                        "address": $addr,
                        "port": (if $port != "" then ($port | tonumber) else null end),
                        "clientIP": (if $cip != "" then $cip else null end),
                        "domains": (if $dom != "" then ($dom | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                        "expectedIPs": (if $eip != "" then ($eip | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                        "unexpectedIPs": (if $uip != "" then ($uip | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                        "timeoutMs": (if $tms != "" then ($tms | tonumber) else null end),
                        "skipFallback": (if $sf == "1" then true else null end),
                        "finalQuery": (if $fq == "1" then true else null end)
                    }' --arg addr "$addr" --arg port "$port" --arg cip "$client_ip" --arg dom "$domains" \
                        --arg eip "$expected_ips" --arg uip "$unexpected_ips" --arg tms "$timeout_ms" \
                        --arg sf "$skip_fb_idx" --arg fq "$final_q_idx"
                fi
                jq_path='["dns","servers"]'
                if ! JQ add "$X_CONFIG" "[$srv_json]"
                then
                    Println "$error 添加 DNS 服务器失败\n"
                    return 1
                fi
                Println "$info DNS 服务器添加成功: ${green}${addr}${normal}\n"
            ;;
            2)
                local cip
                inquirer text_input "输入全局 clientIp (留空清除)" cip ""
                jq_path='["dns","clientIp"]'
                if [ -z "$cip" ]
                then
                    if ! JQ delete "$X_CONFIG"
                    then
                        Println "$error 清除 DNS clientIp 失败\n"
                        return 1
                    fi
                else
                    if ! JQ update "$X_CONFIG" "$cip"
                    then
                        Println "$error 设置 DNS clientIp 失败\n"
                        return 1
                    fi
                fi
                Println "$info DNS clientIp 设置成功\n"
            ;;
            3)
                local dtag
                inquirer text_input "输入 DNS 标识 tag" dtag "dns_inbound"
                jq_path='["dns","tag"]'
                if ! JQ update "$X_CONFIG" "$dtag"
                then
                    Println "$error 设置 DNS tag 失败\n"
                    return 1
                fi
                Println "$info DNS tag 设置成功: ${green}${dtag}${normal}\n"
            ;;
            4)
                local qs_options=( 'UseIP' 'UseIPv4' 'UseIPv6' 'UseSystem' )
                local qs=""
                inquirer list_input "选择 DNS 查询策略 queryStrategy" qs_options qs
                jq_path='["dns","queryStrategy"]'
                if ! JQ update "$X_CONFIG" "$qs"
                then
                    Println "$error 设置 queryStrategy 失败\n"
                    return 1
                fi
                Println "$info queryStrategy 已设置为 ${green}${qs}${normal}\n"
            ;;
            5)
                local yn_opts=( '否' '是' )
                local dc_idx=0 df_idx=0 dfm_idx=0 ss_idx=0 pq_idx=0 sh_idx=0 ttl=""
                inquirer list_input_index "禁用缓存 disableCache" yn_opts dc_idx
                inquirer list_input_index "禁用回退 disableFallback" yn_opts df_idx
                inquirer list_input_index "匹配时不回退 disableFallbackIfMatch" yn_opts dfm_idx
                inquirer list_input_index "启用过期缓存 serveStale" yn_opts ss_idx
                if [ "$ss_idx" -eq 1 ]
                then
                    inquirer text_input "过期缓存 TTL (秒, 0 不限)" ttl "0"
                    if [ -n "$ttl" ] && [[ ! $ttl =~ ^[0-9]+$ ]]
                    then
                        Println "$error serveExpiredTTL 必须为非负整数\n"
                        return 1
                    fi
                fi
                inquirer list_input_index "启用并行查询 enableParallelQuery" yn_opts pq_idx
                inquirer list_input_index "使用系统 Hosts useSystemHosts" yn_opts sh_idx

                if ! JQ mutate "$X_CONFIG" '.dns = ((.dns // {}) * {
                    "disableCache": ($dc == "1"),
                    "disableFallback": ($df == "1"),
                    "disableFallbackIfMatch": ($dfm == "1"),
                    "serveStale": ($ss == "1"),
                    "enableParallelQuery": ($pq == "1"),
                    "useSystemHosts": ($sh == "1")
                } + (if $ttl != "" then {"serveExpiredTTL": ($ttl | tonumber)} else {} end))' \
                    --arg dc "$dc_idx" --arg df "$df_idx" --arg dfm "$dfm_idx" \
                    --arg ss "$ss_idx" --arg pq "$pq_idx" --arg sh "$sh_idx" --arg ttl "$ttl"
                then
                    Println "$error 更新 Xray DNS 全局开关失败\n"
                    return 1
                fi
                Println "$info Xray DNS 全局开关已更新\n"
            ;;
            6)
                local host_keys=()
                local k
                while IFS= read -r k
                do
                    [ -n "$k" ] && host_keys+=("$k")
                done < <(JQs query "$X_CONFIG" 'if (.dns | type) == "object" and (.dns.hosts | type) == "object" then (.dns.hosts | keys[]) else empty end')
                if [ "${#host_keys[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的静态 IP\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的静态 IP" host_keys del_idx
                local del_key="${host_keys[$del_idx]}"
                jq_path='["dns","hosts","'"$del_key"'"]'
                if ! JQ delete "$X_CONFIG"
                then
                    Println "$error 删除静态 IP 失败\n"
                    return 1
                fi
                Println "$info 已删除静态 IP: ${green}${del_key}${normal}\n"
            ;;
            7)
                local srv_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && srv_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.dns | type) == "object" and (.dns.servers | type) == "array" then (.dns.servers | to_entries[] | "\(.key + 1). \(if (.value | type) == "string" then .value elif (.value | type) == "object" then (.value.address // "server") else "server" end)") else empty end')
                if [ "${#srv_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的 DNS 服务器\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的 DNS 服务器" srv_opts del_idx
                jq_path='["dns","servers",'"$del_idx"']'
                if ! JQ delete "$X_CONFIG"
                then
                    Println "$error 删除 DNS 服务器失败\n"
                    return 1
                fi
                Println "$info 已删除 DNS 服务器: ${green}${srv_opts[$del_idx]}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive xray
    }
    XrayGetRouting()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.routing')

        jq_path='[
            ["domainStrategy"],
            ["rules","domain"],
            ["rules","ip"],
            ["rules","port"],
            ["rules","sourcePort"],
            ["rules","localPort"],
            ["rules","network"],
            ["rules","sourceIP"],
            ["rules","localIP"],
            ["rules","user"],
            ["rules","vlessRoute"],
            ["rules","inboundTag"],
            ["rules","protocol"],
            ["rules","attrs"],
            ["rules","process"],
            ["rules","outboundTag"],
            ["rules","balancerTag"],
            ["rules","ruleTag"],
            ["rules","webhook","url"],
            ["rules","webhook","deduplication"],
            ["rules","webhook","headers"],
            ["balancers","tag"],
            ["balancers","selector"],
            ["balancers","fallbackTag"],
            ["balancers","strategy","type"],
            ["balancers","strategy","settings","expected"],
            ["balancers","strategy","settings","maxRTT"],
            ["balancers","strategy","settings","tolerance"],
            ["balancers","strategy","settings","baselines"],
            ["balancers","strategy","settings","costs","regexp"],
            ["balancers","strategy","settings","costs","match"],
            ["balancers","strategy","settings","costs","value"]
        ]'

        while IFS=": " read -r path_name value
        do
            var_name="jq_routing_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        routing_domainStrategy="${jq_routing_domainStrategy:-AsIs}"

        if [ -z "${jq_routing_balancers_tag:-}" ]
        then
            routing_balancers_count=0
        else
            IFS="${delimiters[2]}" read -r -a routing_balancers_tag <<< "$jq_routing_balancers_tag"
            IFS="${delimiters[2]}" read -r -a routing_balancers_selector <<< "$jq_routing_balancers_selector"
            IFS="${delimiters[2]}" read -r -a routing_balancers_fallbackTag <<< "$jq_routing_balancers_fallbackTag"
            IFS="${delimiters[3]}" read -r -a routing_balancers_strategy_type <<< "$jq_routing_balancers_strategy_type"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_expected <<< "$jq_routing_balancers_strategy_settings_expected"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_maxRTT <<< "$jq_routing_balancers_strategy_settings_maxRTT"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_tolerance <<< "$jq_routing_balancers_strategy_settings_tolerance"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_baselines <<< "$jq_routing_balancers_strategy_settings_baselines"
            IFS="${delimiters[5]}" read -r -a routing_balancers_strategy_settings_costs_regexp <<< "$jq_routing_balancers_strategy_settings_costs_regexp"
            IFS="${delimiters[5]}" read -r -a routing_balancers_strategy_settings_costs_match <<< "$jq_routing_balancers_strategy_settings_costs_match"
            IFS="${delimiters[5]}" read -r -a routing_balancers_strategy_settings_costs_value <<< "$jq_routing_balancers_strategy_settings_costs_value"

            routing_balancers_count=${#routing_balancers_tag[@]}
        fi

        routing_rules_count=0
        if [ -s "$X_CONFIG" ]
        then
            routing_rules_count=$($JQ_FILE -r '(.routing.rules // []) | length' "$X_CONFIG" 2> /dev/null)
            routing_rules_count="${routing_rules_count:-0}"
        fi

        if [ "$routing_rules_count" -eq 0 ]
        then
            return 0
        fi

        IFS="${delimiters[2]}" read -r -a routing_rules_domain <<< "${jq_routing_rules_domain:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_ip <<< "${jq_routing_rules_ip:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_port <<< "${jq_routing_rules_port:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_sourcePort <<< "${jq_routing_rules_sourcePort:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_localPort <<< "${jq_routing_rules_localPort:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_network <<< "${jq_routing_rules_network:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_sourceIP <<< "${jq_routing_rules_sourceIP:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_localIP <<< "${jq_routing_rules_localIP:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_user <<< "${jq_routing_rules_user:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_vlessRoute <<< "${jq_routing_rules_vlessRoute:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_inboundTag <<< "${jq_routing_rules_inboundTag:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_protocol <<< "${jq_routing_rules_protocol:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_attrs <<< "${jq_routing_rules_attrs:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_process <<< "${jq_routing_rules_process:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_outboundTag <<< "${jq_routing_rules_outboundTag:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_balancerTag <<< "${jq_routing_rules_balancerTag:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_ruleTag <<< "${jq_routing_rules_ruleTag:-}"
        IFS="${delimiters[3]}" read -r -a routing_rules_webhook_url <<< "${jq_routing_rules_webhook_url:-}"
        IFS="${delimiters[3]}" read -r -a routing_rules_webhook_deduplication <<< "${jq_routing_rules_webhook_deduplication:-}"
        IFS="${delimiters[3]}" read -r -a routing_rules_webhook_headers <<< "${jq_routing_rules_webhook_headers:-}"
    }
    XrayListRouting()
    {
        local out
        out=$(ProxyRenderRouting "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$error 未配置路由\n"
            return 1
        fi
        Println "\n=== Xray 路由配置 ===\n$out\n"
    }
    XraySetRouting()
    {
        local actions=(
            '添加路由规则'
            '添加负载均衡器'
            '设置 domainStrategy'
            '删除路由规则'
            '删除负载均衡器'
        )
        local action_idx=0
        echo
        inquirer list_input_index "选择 Xray 路由操作" actions action_idx

        case "$action_idx" in
            0)
                local mode_opts=( '快捷路由 (选择入站 -> 出站)' '自定义路由规则' )
                local mode_idx=0
                inquirer list_input_index "选择添加路由方式" mode_opts mode_idx

                if [ "$mode_idx" -eq 0 ]
                then
                    ProxySelectBound "$X_CONFIG" inbounds "选择匹配的入站" || return 1
                    local in_tag="${inbounds_tag[selected_bound_index]}"
                    if [ -z "$in_tag" ]
                    then
                        Println "$error 此入站没有标签\n"
                        return 1
                    fi
                    ProxySelectBound "$X_CONFIG" outbounds "选择转发目标出站" || return 1
                    local out_tag="${outbounds_tag[selected_bound_index]}"
                    if [ -z "$out_tag" ]
                    then
                        Println "$error 此出站没有标签\n"
                        return 1
                    fi
                    local rule_json=""
                    JQs build rule_json '{"inboundTag": [$it], "outboundTag": $ot}' --arg it "$in_tag" --arg ot "$out_tag"
                    jq_path='["routing","rules"]'
                    JQ add "$X_CONFIG" "[$rule_json]"
                    Println "$info 快捷路由添加成功: ${green}${in_tag} => ${out_tag}${normal}\n"
                else
                    local net_opts=( 'tcp,udp' 'tcp' 'udp' '不限' )
                    local net_choice=""
                    inquirer list_input "选择匹配的连接方式 network" net_opts net_choice
                    [ "$net_choice" == "不限" ] && net_choice=""

                    local rule_tag domains ips port src_port local_port src_ip local_ip users inb_tag procs vless_route webhook_url out_tag bal_tag
                    inquirer text_input "规则标识 ruleTag (可留空)" rule_tag ""
                    inquirer text_input "匹配 domain (逗号分隔, 可留空)" domains ""
                    inquirer text_input "匹配 ip (逗号分隔, 可留空)" ips ""
                    inquirer text_input "匹配目标 port (可留空)" port ""
                    inquirer text_input "匹配来源 sourcePort (可留空)" src_port ""
                    inquirer text_input "匹配本地 localPort (可留空)" local_port ""
                    inquirer text_input "匹配 sourceIP (逗号分隔, 可留空)" src_ip ""
                    inquirer text_input "匹配 localIP (逗号分隔, 可留空)" local_ip ""
                    inquirer text_input "匹配用户 user (逗号分隔, 可留空)" users ""

                    local proto_opts=( 'http' 'tls' 'quic' 'bittorrent' )
                    local proto_sel=()
                    inquirer checkbox_input "选择匹配的流量协议 protocol (可留空)" proto_opts proto_sel
                    local proto_csv=""
                    if [ "${#proto_sel[@]}" -gt 0 ] && [ -n "${proto_sel[0]:-}" ]
                    then
                        proto_csv=$(JoinByChar , "${proto_sel[@]}")
                    fi

                    inquirer text_input "匹配 inboundTag (逗号分隔, 可留空)" inb_tag ""
                    inquirer text_input "匹配进程 process (逗号分隔, 可留空)" procs ""
                    inquirer text_input "匹配 vlessRoute (可留空)" vless_route ""
                    inquirer text_input "Webhook URL (可留空)" webhook_url ""
                    inquirer text_input "目标 outboundTag (与 balancerTag 二选一)" out_tag ""
                    inquirer text_input "目标 balancerTag (可留空)" bal_tag ""

                    local rule_json=""
                    JQs build rule_json '{
                        "ruleTag": $rtag,
                        "network": $net,
                        "domain": (if $dom != "" then ($dom | split(",")) else null end),
                        "ip": (if $ip != "" then ($ip | split(",")) else null end),
                        "port": $port,
                        "sourcePort": $sport,
                        "localPort": $lport,
                        "sourceIP": (if $sip != "" then ($sip | split(",")) else null end),
                        "localIP": (if $lip != "" then ($lip | split(",")) else null end),
                        "user": (if $usr != "" then ($usr | split(",")) else null end),
                        "protocol": (if $proto != "" then ($proto | split(",")) else null end),
                        "inboundTag": (if $itag != "" then ($itag | split(",")) else null end),
                        "process": (if $proc != "" then ($proc | split(",")) else null end),
                        "vlessRoute": $vr,
                        "webhook": (if $wh != "" then {"url": $wh} else null end),
                        "outboundTag": $otag,
                        "balancerTag": $btag
                    }' --arg rtag "$rule_tag" --arg net "$net_choice" --arg dom "$domains" --arg ip "$ips" \
                        --arg port "$port" --arg sport "$src_port" --arg lport "$local_port" \
                        --arg sip "$src_ip" --arg lip "$local_ip" --arg usr "$users" --arg proto "$proto_csv" \
                        --arg itag "$inb_tag" --arg proc "$procs" --arg vr "$vless_route" --arg wh "$webhook_url" \
                        --arg otag "$out_tag" --arg btag "$bal_tag"

                    jq_path='["routing","rules"]'
                    JQ add "$X_CONFIG" "[$rule_json]"
                    Println "$info 已添加 Xray 路由规则\n"
                fi
            ;;
            1)
                local strat_opts=( 'random' 'roundRobin' 'leastPing' 'leastLoad' )
                local b_tag b_sel b_strat b_fb
                inquirer text_input "Balancer tag" b_tag ""
                inquirer text_input "selector (逗号分隔)" b_sel ""
                inquirer list_input "选择策略 strategy.type" strat_opts b_strat
                inquirer text_input "fallbackTag (可留空)" b_fb ""

                local bal_json=""
                JQs build bal_json '{
                    "tag": $tag,
                    "selector": ($sel | split(",")),
                    "fallbackTag": $fb,
                    "strategy": {"type": $st}
                }' --arg tag "$b_tag" --arg sel "$b_sel" --arg fb "$b_fb" --arg st "$b_strat"

                jq_path='["routing","balancers"]'
                JQ add "$X_CONFIG" "[$bal_json]"
                Println "$info 已添加 Xray 负载均衡 ${green}${b_tag}${normal}\n"
            ;;
            2)
                local ds_opts=( 'AsIs' 'IPIfNonMatch' 'IPOnDemand' )
                local ds=""
                inquirer list_input "选择域名解析策略 domainStrategy" ds_opts ds
                jq_path='["routing","domainStrategy"]'
                JQ update "$X_CONFIG" "$ds"
                Println "$info 已设置 domainStrategy 为 ${green}${ds}${normal}\n"
            ;;
            3)
                local rule_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && rule_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.routing | type) == "object" and (.routing.rules | type) == "array" then (.routing.rules | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.ruleTag // "rule") => \(.value.outboundTag // .value.balancerTag // "")") else empty end')
                if [ "${#rule_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的路由规则\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的路由规则" rule_opts del_idx
                jq_path='["routing","rules",'"$del_idx"']'
                JQ delete "$X_CONFIG"
                Println "$info 已删除路由规则: ${green}${rule_opts[$del_idx]}${normal}\n"
            ;;
            4)
                local bal_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && bal_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.routing | type) == "object" and (.routing.balancers | type) == "array" then (.routing.balancers | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.tag // "balancer")") else empty end')
                if [ "${#bal_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的负载均衡器\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的负载均衡器" bal_opts del_idx
                jq_path='["routing","balancers",'"$del_idx"']'
                JQ delete "$X_CONFIG"
                Println "$info 已删除负载均衡器: ${green}${bal_opts[$del_idx]}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive xray
    }
    XrayGetPolicy()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.policy')

        jq_path='["levels"]'

        policy_levels_id=()
        policy_levels_handshake=()
        policy_levels_connIdle=()
        policy_levels_uplinkOnly=()
        policy_levels_downlinkOnly=()
        policy_levels_statsUserUplink=()
        policy_levels_statsUserDownlink=()
        policy_levels_bufferSize=()

        while IFS="^" read -r policy_levels_id policy_levels_handshake policy_levels_connIdle policy_levels_uplinkOnly \
        policy_levels_downlinkOnly policy_levels_statsUserUplink policy_levels_statsUserDownlink policy_levels_bufferSize; do
            policy_levels_id+=("$policy_levels_id^")
            policy_levels_handshake+=("$policy_levels_handshake^")
            policy_levels_connIdle+=("$policy_levels_connIdle^")
            policy_levels_uplinkOnly+=("$policy_levels_uplinkOnly^")
            policy_levels_downlinkOnly+=("$policy_levels_downlinkOnly^")
            policy_levels_statsUserUplink+=("$policy_levels_statsUserUplink^")
            policy_levels_statsUserDownlink+=("$policy_levels_statsUserDownlink^")
            policy_levels_bufferSize+=("$policy_levels_bufferSize^")
        done < <(JQs get jq_payload '. // {} | to_entries[] | "\(.key)^\(.value.handshake // 4)^\(.value.connIdle // 300)^\(.value.uplinkOnly // 2)^\(.value.downlinkOnly // 5)^\(.value.statsUserUplink // false)^\(.value.statsUserDownlink // false)^\(.value.bufferSize // 4)"')

        jq_path='[
            ["system","statsInboundUplink"],
            ["system","statsInboundDownlink"],
            ["system","statsOutboundUplink"],
            ["system","statsOutboundDownlink"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="jq_policy_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        policy_system_stats_inbound_uplink=${jq_policy_system_stats_inbound_uplink:-false}
        policy_system_stats_inbound_downlink=${jq_policy_system_stats_inbound_downlink:-false}
        policy_system_stats_outbound_uplink=${jq_policy_system_stats_outbound_uplink:-false}
        policy_system_stats_outbound_downlink=${jq_policy_system_stats_outbound_downlink:-false}

        policy_levels_count="${#policy_levels_id[@]}"

    }
    XrayListPolicy()
    {
        local out
        out=$(ProxyRenderPolicy "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$error 未配置策略\n"
            return 1
        fi
        Println "\n=== Xray 策略配置 ===\n$out\n"
    }
    XraySetPolicy()
    {
        local actions=(
            '添加/修改用户等级策略'
            '删除用户等级策略'
            '设置入站上行流量统计'
            '设置入站下行流量统计'
            '设置出站上行流量统计'
            '设置出站下行流量统计'
        )
        local action_idx=0
        echo
        inquirer list_input_index "选择 Xray 策略操作" actions action_idx

        local sw_opts=( '关闭' '开启' )

        case "$action_idx" in
            0)
                local lvl hs ci uo do_s buf
                local up_idx=1 dn_idx=1 online_idx=1
                inquirer text_input "用户等级 level (留空自动分配)" lvl ""
                if [ -z "$lvl" ]
                then
                    lvl=$(JQs query "$X_CONFIG" '((if (.policy | type) == "object" then (if (.policy.levels | type) == "object" then .policy.levels elif (.policy.level | type) == "object" then .policy.level else {} end) else {} end) | keys | map(tonumber?) | max // -1) + 1')
                    lvl="${lvl:-0}"
                fi
                if [[ ! $lvl =~ ^[0-9]+$ ]]
                then
                    Println "$error 用户等级 level 必须为非负整数\n"
                    return 1
                fi
                inquirer text_input "handshake (秒)" hs "60"
                inquirer text_input "connIdle (秒)" ci "300"
                inquirer text_input "uplinkOnly (秒)" uo "1"
                inquirer text_input "downlinkOnly (秒)" do_s "1"
                inquirer text_input "bufferSize (KB)" buf "0"
                if [[ ! $hs =~ ^[0-9]+$ ]] || [[ ! $ci =~ ^[0-9]+$ ]] || [[ ! $uo =~ ^[0-9]+$ ]] || [[ ! $do_s =~ ^[0-9]+$ ]] || [[ ! $buf =~ ^[0-9]+$ ]]
                then
                    Println "$error handshake / connIdle / uplinkOnly / downlinkOnly / bufferSize 必须为非负整数\n"
                    return 1
                fi
                inquirer list_input_index "用户上行流量统计 statsUserUplink" sw_opts up_idx
                inquirer list_input_index "用户下行流量统计 statsUserDownlink" sw_opts dn_idx
                inquirer list_input_index "用户在线统计 statsUserOnline" sw_opts online_idx

                if ! JQ mutate "$X_CONFIG" '.policy.levels = ((.policy.levels // .policy.level // {}) * {
                    ($lvl): {
                        "handshake": ($hs | tonumber),
                        "connIdle": ($ci | tonumber),
                        "uplinkOnly": ($uo | tonumber),
                        "downlinkOnly": ($do_s | tonumber),
                        "bufferSize": ($buf | tonumber),
                        "statsUserUplink": ($up == "1"),
                        "statsUserDownlink": ($dn == "1"),
                        "statsUserOnline": ($online == "1")
                    }
                }) | del(.policy.level)' \
                    --arg lvl "$lvl" --arg hs "$hs" --arg ci "$ci" --arg uo "$uo" --arg do_s "$do_s" \
                    --arg buf "$buf" --arg up "$up_idx" --arg dn "$dn_idx" --arg online "$online_idx"
                then
                    Println "$error 更新等级 ${lvl} 策略失败\n"
                    return 1
                fi
                Println "$info 已更新等级 ${green}${lvl}${normal} 策略\n"
            ;;
            1)
                local lvls=()
                local k
                while IFS= read -r k
                do
                    [ -n "$k" ] && lvls+=("$k")
                done < <(JQs query "$X_CONFIG" '(if (.policy | type) == "object" then (if (.policy.levels | type) == "object" then .policy.levels elif (.policy.level | type) == "object" then .policy.level else {} end) else {} end) | keys[]')
                if [ "${#lvls[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的用户等级策略\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的用户等级" lvls del_idx
                local del_lvl="${lvls[$del_idx]}"
                if ! JQ mutate "$X_CONFIG" 'del(.policy.level[$k], .policy.levels[$k])' --arg k "$del_lvl"
                then
                    Println "$error 删除等级 ${del_lvl} 策略失败\n"
                    return 1
                fi
                Println "$info 已删除等级 ${green}${del_lvl}${normal} 策略\n"
            ;;
            2|3|4|5)
                local sys_keys=( '' '' 'statsInboundUplink' 'statsInboundDownlink' 'statsOutboundUplink' 'statsOutboundDownlink' )
                local sys_key="${sys_keys[$action_idx]}"
                local sw_idx=1 sw_bool=false
                inquirer list_input_index "设置 ${sys_key}" sw_opts sw_idx
                [ "$sw_idx" -eq 1 ] && sw_bool=true
                jq_bool=true
                jq_path='["policy","system","'"$sys_key"'"]'
                if ! JQ update "$X_CONFIG" "$sw_bool"
                then
                    Println "$error 更新系统策略 ${sys_key} 失败\n"
                    return 1
                fi
                Println "$info 已更新系统策略 ${green}${sys_key}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive xray
    }
    XrayGetApiServer()
    {
        local api_server
        api_server=$(JQs query "$X_CONFIG" '
            def normalize_host($h):
                if $h == "" or $h == "0.0.0.0" or $h == "::" or $h == "[::]" then "127.0.0.1" else $h end;
            if (.api | type) == "object" and (.api.listen | type) == "string" and .api.listen != "" then
                (.api.listen | sub("^(0\\.0\\.0\\.0|\\[::\\]|::):"; "127.0.0.1:"))
            else
                ((if (.api | type) == "object" and (.api.tag | type) == "string" then .api.tag else "api" end) as $api_tag
                | first(
                    (if (.inbounds | type) == "array" then .inbounds else [] end)[]
                    | select(type == "object" and .tag == $api_tag)
                    | "\(normalize_host(.listen // "127.0.0.1")):\(.port // 10085)"
                ) // $def_api)
            end
        ' --arg def_api "$XRAY_DEFAULT_API" | head -n 1)
        printf '%s' "${api_server:-$XRAY_DEFAULT_API}"
    }

    XrayListStats()
    {
        local api_server
        api_server=$(XrayGetApiServer)

        local raw_stats
        if ! raw_stats=$("$XCTL_FILE" api statsquery --server="$api_server" 2>&1)
        then
            Println "$error 无法连接 Xray API ($api_server), 请确认已开启 api 与 stats: ${raw_stats}\n"
            return 1
        fi

        if ! printf '%s' "$raw_stats" | $JQ_FILE -e . > /dev/null 2>&1
        then
            Println "$error Xray API 返回非合法 JSON ($api_server): ${raw_stats}\n"
            return 1
        fi

        local formatted
        formatted=$(ProxyFormatStatsJson "$raw_stats")

        if [ -z "$formatted" ]
        then
            Println "$info 暂无流量统计数据\n"
            return 0
        fi

        Println "\n=== Xray 流量统计 ===\n$formatted\n"
    }

    XrayResetStats()
    {
        if [ "${1:-}" != "-y" ] && [ "${1:-}" != "--yes" ] && [ -t 0 ]
        then
            local confirm_opts=( '否' '是' )
            local confirm_idx=0
            echo
            inquirer list_input_index "确认重置 Xray 所有流量统计?" confirm_opts confirm_idx
            if [ "$confirm_idx" -ne 1 ]
            then
                Println "$info 已取消重置流量统计\n"
                return 0
            fi
        fi

        local api_server
        api_server=$(XrayGetApiServer)

        local err_msg=""
        if err_msg=$("$XCTL_FILE" api statsquery --server="$api_server" --reset 2>&1)
        then
            Println "$info 已重置 Xray 流量统计\n"
        else
            Println "$error 重置 Xray 流量统计失败 ($api_server): ${err_msg}\n"
            return 1
        fi
    }
    XrayListReverse()
    {
        Println "$tip 注意: Xray 顶层 reverse 配置已废弃，推荐使用 VLESS 反向代理\n"

        local out
        out=$(ProxyRenderReverse "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$error 未配置反向代理\n"
            return 1
        fi
        Println "\n=== Xray 反向代理配置 ===\n$out\n"
    }
    XraySetReverse()
    {
        Println "$tip 注意: Xray 顶层 reverse 配置已废弃，推荐使用 VLESS 反向代理\n"

        local actions=( '添加 Bridge' '添加 Portal' '删除 Bridge' '删除 Portal' )
        local action_idx=0
        echo
        inquirer list_input_index "选择 Xray 反向代理操作" actions action_idx

        case "$action_idx" in
            0|1)
                local r_tag r_domain item_json=""
                inquirer text_input "输入 tag" r_tag ""
                inquirer text_input "输入 domain" r_domain ""
                JQs build item_json '{"tag": $t, "domain": $d}' --arg t "$r_tag" --arg d "$r_domain"
                if [ "$action_idx" -eq 0 ]
                then
                    jq_path='["reverse","bridges"]'
                    if ! JQ add "$X_CONFIG" "[$item_json]"
                    then
                        Println "$error 添加 Bridge 失败\n"
                        return 1
                    fi
                    Println "$info 已添加 Bridge ${green}${r_tag}${normal}\n"
                else
                    jq_path='["reverse","portals"]'
                    if ! JQ add "$X_CONFIG" "[$item_json]"
                    then
                        Println "$error 添加 Portal 失败\n"
                        return 1
                    fi
                    Println "$info 已添加 Portal ${green}${r_tag}${normal}\n"
                fi
            ;;
            2|3)
                local r_key="bridges"
                [ "$action_idx" -eq 3 ] && r_key="portals"
                local r_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && r_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.reverse | type) == "object" and (.reverse[$k] | type) == "array" then (.reverse[$k] | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.tag // "") (\(.value.domain // ""))") else empty end' --arg k "$r_key")
                if [ "${#r_opts[@]}" -eq 0 ]
                then
                    Println "$error 没有可删除的 ${r_key}\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "选择要删除的 ${r_key}" r_opts del_idx
                jq_path='["reverse","'"$r_key"'",'"$del_idx"']'
                if ! JQ delete "$X_CONFIG"
                then
                    Println "$error 删除 ${r_key} 失败\n"
                    return 1
                fi
                Println "$info 已删除 ${r_key}: ${green}${r_opts[$del_idx]}${normal}\n"
            ;;
        esac

        ProxyRestartIfActive xray
    }
    XrayGetLog()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.log')

        jq_path='[
            ["access"],
            ["error"],
            ["loglevel"],
            ["logLevel"],
            ["dnsLog"],
            ["maskAddress"]
        ]'

        while IFS=": " read -r path_name value
        do
            var_name="$path_name"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        log_access="${jq_access:-stdout}"
        log_error="${jq_error:-stdout}"
        log_loglevel="${jq_loglevel:-${jq_logLevel:-warning}}"
        log_dnsLog="${jq_dnsLog:-false}"
        log_maskAddress="${jq_maskAddress:-}"

        return 0
    }
