            dnscrypt_version_old=${DNSCRYPT_ROOT#*-}

            if [[ $dnscrypt_version_old == "*" ]] 
            then
                Println "$error 请先安装 dnscrypt proxy\n"
                exit 1
            fi

            if [ -d /opt/AdGuardHome ] 
            then
