then
    [ ! -d "$IPTV_ROOT" ] && Println "$error 尚未安装, 请检查 !\n" && exit 1

    XtreamCodesDomainFilter()
    {
        local domain=$1

        if [ ! -e "$XTREAM_CODES"_domain_filter ]
        then
            ShFallback
            if ! curl -s -Lm 10 "$SH_FALLBACK/xtream_codes_domain_filter" -o "$XTREAM_CODES"_domain_filter
            then
                echo "$domain"
                return 0
            fi
        fi

        local domain_match domain_replace

        while IFS= read -r line
        do
            domain_match=${line% *}
            domain_replace=${line#* }
            if [[ $domain_match =~ : ]]
            then
                if [ "$domain" == "$domain_match" ]
                then
                    domain="$domain_replace"
                    break
                fi
            elif [[ $domain_replace =~ : ]]
            then
                if [ "${domain%:*}" == "$domain_match" ]
                then
                    domain="$domain_replace"
                    break
                fi
            elif [[ $domain =~ : ]]
            then
                if [ "${domain%:*}" == "$domain_match" ]
                then
                    domain="$domain_replace:${domain#*:}"
                    break
                fi
            elif [ "$domain" == "$domain_match" ]
            then
                domain="$domain_replace"
                break
            fi
        done < "$XTREAM_CODES"_domain_filter

        echo "$domain"
    }












    Println "  Xtream Codes 面板 ${normal}

${green}1.${normal} 查看账号
${green}2.${normal} 添加账号
${green}3.${normal} 批量检测
${green}4.${normal} 测试账号
${green}5.${normal} 获取账号
————————————
${green}6.${normal} 查看 mac 地址
${green}7.${normal} 添加 mac 地址
${green}8.${normal} 浏览频道

    "
