                    "cdn": "",
                    "jwt_secret": "",
                    "token_expires_in": 48,
                    "database": {
                        "type": "sqlite3",
                        "host": "",
                        "port": 0,
                        "user": "",
                        "password": "",
                        "name": "",
                        "db_file": $db_file,
                        "table_prefix": "x_",
                        "ssl_mode": "",
                        "dsn": ""
                    },
                    "meilisearch": {
                        "host": "http://localhost:7700",
                        "api_key": "",
                        "index_prefix": ""
                    },
                    "scheme": {
                        "address": "127.0.0.1",
                        "http_port": 5244,
                        "https_port": -1,
                        "force_https": false,
                        "cert_file": "",
                        "key_file": "",
                        "unix_file": "",
                        "unix_file_perm": ""
                    },
                    "temp_dir": "/tmp/openlist",
                    "bleve_dir": $bleve_dir,
                    "dist_dir": "",
                    "log": {
                        "enable": true,
                        "name": $log,
                        "max_size": 10,
                        "max_backups": 5,
                        "max_age": 28,
                        "compress": false
                    },
                    "delayed_start": 0,
                    "max_connections": 0,
                    "tls_insecure_skip_verify": true,
                    "tasks": {
                        "download": {
                        "workers": 5,
                        "max_retry": 1
                        },
                        "transfer": {
                        "workers": 5,
                        "max_retry": 2
                        },
                        "upload": {
                        "workers": 5,
                        "max_retry": 0
                        },
                        "copy": {
                        "workers": 5,
                        "max_retry": 2
                        }
                    },
                    "cors": {
                        "allow_origins": [
                        "*"
                        ],
                        "allow_methods": [
                        "*"
                        ],
                        "allow_headers": [
                        "*"
                        ]
                    },
                    "s3": {
                        "enable": false,
                        "port": 5246,
                        "ssl": false
                    }
                }'
            )

            echo "$openlist_config" > "$OPENLIST_ROOT"/data/config.json
            cd "$OPENLIST_ROOT"
            ./openlist admin set "$openlist_pass"
        fi

        service_name="openlist"

        service_commands=( "$OPENLIST_ROOT"/openlist server --data "$OPENLIST_ROOT"/data )

        if ! err_msg=$(ServiceControl start "$service_name" service_commands)
        then
            Println "$error $service_name 启动失败, $err_msg\n"
            return 1
        fi

        rm -rf "${TMP_DIR:-notfound}"
        trap - EXIT

        Println "$info OpenList 安装成功\n"
