    OpenList.auth.login()
    {
        openlist_payload=$(
        $JQ_FILE -c -n --arg username "$openlist_acc_username" --arg password "$openlist_acc_password" \
            '{
                username: $username,
                password: $password,
                otp_code: ""
            }'
        )

        response=$(
            curl -s -Lm 20 "${openlists_url[openlists_index]}"/api/auth/login \
            -H "Content-Type: application/json" \
            -H "User-Agent: $USER_AGENT_BROWSER" \
            --data "$openlist_payload"
        )

        jq_payload=$(JQs flat "$response")

        jq_path='[
            ["code"],
            ["message"],
            ["data","token"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        auth_login_code="$jq_code"
        auth_login_message="$jq_message"
        openlist_acc_token="$jq_data_token"

        if [ "$auth_login_code" -eq 200 ] 
        then
            jq_path='["openlist",'"$openlists_index"',"accs",'"$openlist_accs_index"',"token"]'
            JQ update "$SERVICES_CONFIG" "$openlist_acc_token"
            Println "$info 账号 $openlist_acc_username 登陆成功\n"
        else
            Println "$error 账号 $openlist_acc_username 登陆失败: $auth_login_message\n"
            return 1
        fi
    }

    OpenList.me()
    {
        response=$(
            curl -s -Lm 20 "${openlists_url[openlists_index]}"/api/me \
            -H "Content-Type: application/json" \
            -H "User-Agent: $USER_AGENT_BROWSER" \
            -H "Authorization: $openlist_acc_token"
        )

        jq_payload=$(JQs flat "$response")

        jq_path='[
            ["code"],
            ["message"],
            ["data","id"],
            ["data","base_path"],
            ["data","role"],
            ["data","disabled"],
            ["data","permission"],
            ["data","github_id"],
            ["data","otp"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        me_code="$jq_code"
        me_message="$jq_message"
        id="$jq_data_id"
        base_path="$jq_data_base_path"
        role="$jq_data_role"
        disabled="$jq_data_disabled"
        permission="$jq_data_permission"
        github_id="$jq_data_github_id"
        otp="$jq_data_otp"

        return 0
    }

    OpenList.fs.get()
    {
        response=$(
            curl -s -Lm 20 "${openlists_url[openlists_index]}"/api/fs/get \
            -H "Content-Type: application/json" \
            -H "User-Agent: $USER_AGENT_BROWSER" \
            -H "Authorization: $openlist_acc_token" \
            --data '{"path":"/","password":""}'
        )

        jq_payload=$(JQs flat "$response")

        jq_path='[
            ["code"],
            ["message"],
            ["data","name"],
            ["data","size"],
            ["data","is_dir"],
            ["data","modified"],
            ["data","sign"],
            ["data","thumb"],
            ["data","type"],
            ["data","raw_url"],
            ["data","readme"],
            ["data","provider"],
            ["data","related"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        fs_get_code="$jq_code"
        fs_get_message="$jq_message"
        name="$jq_data_name"
        size="$jq_data_size"
        is_dir="$jq_data_is_dir"
        modified="$jq_data_modified"
        sign="$jq_data_sign"
        thumb="$jq_data_thumb"
        type="$jq_data_type"
        raw_url="$jq_data_raw_url"
        readme="$jq_data_readme"
        provider="$jq_data_provider"
        related="$jq_data_related"

        return 0
    }

