    OpenList.fs.list()
    {
        openlist_payload=$(
        $JQ_FILE -c -n --arg path "$1" --arg password "" \
        --arg page 1 --arg per_page 0 --arg refresh "false" \
            '{
                path: $path,
                password: $password,
                page: $page | tonumber,
                per_page: $per_page | tonumber,
                refresh: $refresh | test("true")
            }'
        )

        response=$(
            curl -s -Lm 20 "${openlists_url[openlists_index]}"/api/fs/list \
            -H "Content-Type: application/json" \
            -H "User-Agent: $USER_AGENT_BROWSER" \
            -H "Authorization: $openlist_acc_token" \
            --data "$openlist_payload"
        )

        jq_payload=$(JQs flat "$response")

        jq_path='[
            ["code"],
            ["message"],
            ["data","total"],
            ["data","readme"],
            ["data","write"],
            ["data","provider"],
            ["data","content","name"],
            ["data","content","size"],
            ["data","content","is_dir"],
            ["data","content","modified"],
            ["data","content","sign"],
            ["data","content","thumb"],
            ["data","content","type"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        fs_list_code="$jq_code"
        fs_list_message="$jq_message"
        total="$jq_data_total"
        readme="$jq_data_readme"
        write="$jq_data_write"
        provider="$jq_data_provider"
        content_name="$jq_data_content_name"
        content_size="$jq_data_content_size"
        content_is_dir="$jq_data_content_is_dir"
        content_modified="$jq_data_content_modified"
        content_sign="$jq_data_content_sign"
        content_thumb="$jq_data_content_thumb"
        content_type="$jq_data_content_type"

        if [ "$fs_list_code" -ne 200 ] 
        then
            return 1
        fi

        return 0
    }

