    OpenListAct()
    {
        ServiceGet openlist

        if [ "$openlists_count" -eq 0 ] 
        then
            Println "$error 请先添加 OpenList\n"
            exit 1
        fi

        openlists_txt=""
        openlists_options=()
        for((openlists_index=0;openlists_index<openlists_count;openlists_index++));
        do
            openlists_options+=("OpenList $((openlists_index+1))")
            if [ -z "${openlists_acc_username[openlists_index]:-}" ] 
            then
                openlist_accs_count=0
            else
                IFS="${delimiters[4]}" read -ra openlist_accs_username <<< "${openlists_acc_username[openlists_index]}"
                openlist_accs_count=${#openlist_accs_username[@]}
            fi
            openlists_txt="$openlists_txt\n${green}$((openlists_index+1)).${normal}${indent_6}名称: ${openlists_name[openlists_index]:-无}\n${indent_6}地址: ${openlists_url[openlists_index]}\n${indent_6}账号: ${openlist_accs_count}个\n"
        done

        Println "$openlists_txt\n"

        echo
        inquirer list_input_index "选择 OpenList" openlists_options openlists_index

        if [ -z "${openlists_acc_username[openlists_index]:-}" ] 
        then
            Println "$error 请先添加账号\n"
            exit 1
        fi

        IFS="${delimiters[4]}" read -ra openlist_accs_username <<< "${openlists_acc_username[openlists_index]}"
        IFS="${delimiters[4]}" read -ra openlist_accs_password <<< "${openlists_acc_password[openlists_index]}"
        IFS="${delimiters[4]}" read -ra openlist_accs_token <<< "${openlists_acc_token[openlists_index]}"

        openlist_accs_count=${#openlist_accs_username[@]}

        openlist_txt="${green}账号:${normal}\n"

        for((i=0;i<openlist_accs_count;i++));
        do
            openlist_txt="$openlist_txt${green}$((i+1)).${normal}${indent_6}用户名: ${openlist_accs_username[i]}\n${indent_6}密码: ${openlist_accs_password[i]:-无}\n${indent_6}Token: ${openlist_accs_token[i]:-无}\n\n"
        done

        Println "$openlist_txt"

        inquirer list_input_index "选择账号" openlist_accs_username openlist_accs_index

        openlist_acc_username="${openlist_accs_username[openlist_accs_index]}"
        openlist_acc_password="${openlist_accs_password[openlist_accs_index]}"

        if [ -n "${openlist_accs_token[openlist_accs_index]}" ] 
        then
            echo
            inquirer list_input_index "是否重新登陆账号" ny_options ny_index

            if [ "$ny_index" -eq 0 ] 
            then
                openlist_acc_token="${openlist_accs_token[openlist_accs_index]}"
            else
                OpenList.auth.login
            fi
        else
            OpenList.auth.login
        fi

        echo
        inquirer text_input "输入访问路径" openlist_path "/" SetOpenListPathValidate "必须是 / 开始的路径"

        while true 
        do
            openlist_files_count=0

            if ! OpenList.fs.list "$openlist_path" 
            then
                Println "$error 发生错误: $fs_list_message\n"
                if [ "$openlist_path" == "/" ] 
                then
                    exit 1
                fi
            elif [ -n "$content_name" ] 
            then
                IFS="${delimiters[3]}" read -ra openlist_files_name <<< "$content_name"
                IFS="${delimiters[3]}" read -ra openlist_files_is_dir <<< "$content_is_dir"

                openlist_files_count=${#openlist_files_name[@]}
            else
                Println "$error 没有文件\n"
                if [ "$openlist_path" == "/" ] 
                then
                    exit 1
                fi
            fi

            openlist_files_root=true
            openlist_files_options=()

            if [ "$openlist_path" != "/" ] 
            then
                openlist_files_options+=("..")
                openlist_files_root=false
            fi

            openlist_not_dir_indices=()
            openlist_dir_indices=()
            openlist_checkbox_options=()

            for((openlist_files_index=0;openlist_files_index<openlist_files_count;openlist_files_index++));
            do
                if [ "${openlist_files_is_dir[openlist_files_index]}" = true ] 
                then
                    openlist_files_options+=("${openlist_files_name[openlist_files_index]}/")
                    openlist_dir_indices+=("$openlist_files_index")
                    openlist_checkbox_options+=("${openlist_files_name[openlist_files_index]}/")
                else
                    openlist_files_options+=("${openlist_files_name[openlist_files_index]}")
                    openlist_not_dir_indices+=("$openlist_files_index")
                    openlist_checkbox_options+=("${openlist_files_name[openlist_files_index]}")
                fi
            done

            if [ -n "${openlist_not_dir_indices:-}" ] || [ -n "${openlist_dir_indices:-}" ]
            then
                openlist_files_options+=("${red}修改${normal}")
            fi

            echo
            inquirer list_input_index "请选择" openlist_files_options openlist_files_index

            if [ "$openlist_files_root" = false ] && [ "$openlist_files_index" -eq 0 ]
            then
                openlist_path="${openlist_path%/*}"
                continue
            fi

            if { [ "$openlist_files_root" = false ] && [ "$openlist_files_index" -eq $((openlist_files_count+1)) ]; } || { [ "$openlist_files_root" = true ] && [ "$openlist_files_index" -eq $((openlist_files_count)) ]; }
            then
                openlist_files_options=("多选")

                if [ -n "${openlist_dir_indices:-}" ] 
                then
                    openlist_files_options+=("选择所有目录文件")
                fi
                if [ -n "${openlist_not_dir_indices:-}" ] 
                then
                    openlist_files_options+=("选择所有非目录文件")
                fi

                echo
                inquirer list_input_index "请选择" openlist_files_options openlist_files_options_index

                if [ "$openlist_files_options_index" -eq 0 ] 
                then
                    echo
                    openlist_files_indices=()
                    inquirer checkbox_input_indices "多选" openlist_checkbox_options openlist_files_indices 20
                elif [ "${openlist_files_options[openlist_files_options_index]}" == "选择所有目录文件" ] 
                then
                    openlist_files_indices=("${openlist_dir_indices[@]}")
                else
                    openlist_files_indices=("${openlist_not_dir_indices[@]}")
                fi
            else
                if [ "$openlist_files_root" = false ] 
                then
                    openlist_files_index=$((openlist_files_index-1))
                fi

                if [ "${openlist_files_is_dir[openlist_files_index]}" = true ] 
                then
                    openlist_path="$openlist_path/${openlist_files_name[openlist_files_index]}"
                    continue
                fi

                openlist_files_indices=("$openlist_files_index")
            fi

            openlist_files_edit_count=${#openlist_files_indices[@]}

            openlist_files_edit_options=()

            if [ "$openlist_files_edit_count" -eq 1 ] 
            then
                openlist_files_edit_options+=("重命名")
            else
                openlist_files_edit_options+=( '逐个重命名' '批量重命名')
            fi

            openlist_files_edit_options+=( '删除' )

            echo
            inquirer list_input "选择操作" openlist_files_edit_options openlist_files_edit_option

            if [ "$openlist_files_edit_option" == "重命名" ] 
            then
                echo
                inquirer text_input "输入新的名称" openlist_file_name "$i18n_cancel"
                if [ "$openlist_file_name" == "$i18n_cancel" ] 
                then
                    continue
                fi
                OpenList.fs.rename
            elif [ "$openlist_files_edit_option" == "逐个重命名" ] 
            then
                for openlist_files_index in "${openlist_files_indices[@]}"
                do
                    echo
                    Println "$info 修改 ${openlist_files_name[openlist_files_index]}\n"
                    inquirer text_input "输入新的名称" openlist_file_name "$i18n_cancel"
                    if [ "$openlist_file_name" == "$i18n_cancel" ] 
                    then
                        continue
                    fi
                    OpenList.fs.rename
                done
            elif [ "$openlist_files_edit_option" == "批量重命名" ] 
            then
                echo
                inquirer text_input "输入 sed 命令(-e)" openlist_files_edit_sed "$i18n_cancel"
                if [ "$openlist_file_name" == "$i18n_cancel" ] 
                then
                    continue
                fi
                for openlist_files_index in "${openlist_files_indices[@]}"
                do
                    openlist_file_name=$(echo "${openlist_files_name[openlist_files_index]}" | sed -e "$openlist_files_edit_sed")
                    Println "$info 修改 ${openlist_files_name[openlist_files_index]} => $openlist_file_name\n"
                    OpenList.fs.rename
                done
            else
                echo
                openlist_files_txt=""
                openlist_files_delete_names=()
                for((openlist_files_edit_index=0;openlist_files_edit_index<openlist_files_edit_count;openlist_files_edit_index++));
                do
                    openlist_files_index="${openlist_files_indices[openlist_files_edit_index]}"
                    openlist_files_txt="$openlist_files_txt${green}$((openlist_files_edit_index+1)).${normal}${indent_6}${openlist_files_name[openlist_files_index]}\n"
                    openlist_files_delete_names+=("${openlist_files_name[openlist_files_index]}")
                done

                Println "$openlist_files_txt\n"
                inquirer list_input_index "确认删除以上文件" ny_options ny_index

                if [ "$ny_index" -eq 1 ] 
                then
                    for openlist_file_delete_name in "${openlist_files_delete_names[@]}"
                    do
                        if OpenList.fs.remove
                        then
                            Println "$info 文件 $openlist_file_delete_name 删除成功"
                        else
                            Println "$error 文件 $openlist_file_delete_name 删除失败: $fs_remove_message"
                        fi
                    done
                fi
            fi
        done

        return 0
    }

    SetOpenListPathValidate()
    {
        if [ "${1:0:1}" == "/" ] 
        then
            return 0
        fi

        return 1
    }

    echo
    openlist_options=( '文件管理' 'OpenList管理' '账号管理' '退出' )
    inquirer list_input_index "请选择" openlist_options openlist_options_index

    case $openlist_options_index in
        0) 
            OpenListAct
        ;;
        1) 
            echo
            openlist_app_options=( '查看' '添加' '修改' '删除' '本地安装/升级' )
            inquirer list_input_index "选择操作" openlist_app_options openlist_app_options_index

            case $openlist_app_options_index in
                0) OpenListAppView
                ;;
                1) OpenListAppAdd
                ;;
                2) OpenListAppEdit
                ;;
                3) OpenListAppDel
                ;;
                4) OpenListAppInstall
                ;;
            esac
        ;;
        2) 
            echo
            openlist_acc_options=( '查看' '添加' '登陆' '修改' '删除' )
            inquirer list_input_index "选择操作" openlist_acc_options openlist_acc_options_index

            case $openlist_acc_options_index in
                0) OpenListAccView
                ;;
                1) OpenListAccAdd
                ;;
                2) OpenListAccLogin
                ;;
                3) OpenListAccEdit
                ;;
                4) OpenListAccDel
                ;;
            esac
        ;;
        *) 
        ;;
    esac

    exit 0
elif [ "$self" == "lhh" ]
then
    CookiesGet()
    {
        local cookies cookie_commands=() url="$1" var_name="$2" data="${3:-}"
        local oIFS=$IFS

        if [ "${use_cookie_file:-false}" = true ] 
        then
            cookie_commands+=( -b "$COOKIE_FILE" )
        fi

        if [ "${save_cookie_file:-false}" = true ] 
        then
            cookie_commands+=( -c "$COOKIE_FILE" )
        fi

        if [ -n "${data:-}" ] 
        then
            cookie_commands+=( --data "$data" )
        fi

        IFS=$'\n'

        if [ "${save_return:-false}" = true ] 
        then
            if TMP_FILE=$(mktemp -q)
            then
                chmod +r "$TMP_FILE"
            else
                exit $?
            fi

            trap '
                rm -f "${TMP_FILE:-notfound}"
            ' EXIT

            if ! cookies=($(CurlFake -s -Lm 20 -D - ${cookie_commands[@]+"${cookie_commands[@]}"} -o "$TMP_FILE" "$url" | grep -i 'set-cookie'))
            then
                Println "$error 无法连接 $url, 请稍后再试\n"
                exit 1
            fi

            return_body="$(< $TMP_FILE)"

            rm -f "${TMP_FILE:-notfound}"
        elif ! cookies=($(CurlFake -s -Lm 20 -D - ${cookie_commands[@]+"${cookie_commands[@]}"} -o /dev/null "$url" | grep -i 'set-cookie'))
        then
            Println "$error 无法连接 $url, 请稍后再试\n"
            exit 1
        fi

        IFS="$oIFS"

        read -r -a ${var_name?} <<< "${cookies[@]#*set-cookie:}"

        use_cookie_file=false
        save_cookie_file=false
        save_return=false
    }

    CookiesToJson()
    {
        local domain="$1"
        shift
        local cookies=("$@") cookie new_cookie cookie_json
        cookies=("${cookies[@]%;}")

        for cookie in "${cookies[@]}"
        do
            new_cookie=$(
            $JQ_FILE -n --arg name "${cookie%=*}" --arg value "${cookie#*=}" \
            --arg domain "${domain}" --arg path / \
                '{
                    name: $name,
                    value: $value,
                    domain: $domain,
                    path: $path
                }'
            )

            [ -n "${cookie_json:-}" ] && cookie_json="${cookie_json},"
            cookie_json="${cookie_json}${new_cookie}"
        done

        echo "[$cookie_json]" | $JQ_FILE -c .
    }
    NodeInstallToutiao()
    {
        if [ -f "$NODE_ROOT"/toutiao/browser.js ] 
        then
            if ver=$(grep -oP 'const ver = "\K[^"]+' "$NODE_ROOT"/toutiao/browser.js) && [ "$NODE_TOUTIAO_VER" == "$ver" ] 
            then
                return
            fi
        fi

        mkdir -p "$NODE_ROOT"/toutiao/
        DepInstall curl
        if ! curl -Lm 20 -o "$NODE_ROOT"/toutiao/browser.js "$NODE_SCRIPTS_LINK"/browser.js
        then
            curl -L -o "$NODE_ROOT"/toutiao/browser.js "$FFMPEG_MIRROR_LINK"/browser.js
        fi
        cd "$NODE_ROOT"/toutiao/
        npm i playwright-chromium
        Println "$info 头条签名 node 安装成功"
    }

    if [ ! -f "$LIANHUANHUA_CONFIG" ] && [ -f "$HOME/ebooks/config.json" ] 
    then
        mkdir -p "$LIANHUANHUA_ROOT"
        cp  "$HOME/ebooks/config.json" "$LIANHUANHUA_CONFIG"
    fi

    LhhDownload()
    {
        CurlImpersonateInstall
        if [[ ! -x "${CURL_IMPERSONATE_FILE}-lhh" ]] 
        then
            cp -f "$CURL_IMPERSONATE_FILE" "${CURL_IMPERSONATE_FILE}-lhh"
            sed -i '/User-Agent:/d' "${CURL_IMPERSONATE_FILE}-lhh"
        fi
        if ! CurlFake lhh "$@"
        then
            if [ "${curl_retry:-true}" = true ] 
            then
                sleep 10
                if CurlFake lhh "$@" 
                then
                    return 0
                fi
            fi

            if [ "${curl_print_error:-true}" = true ] 
            then
                echo "$@"
                Println "$error \n发生错误请重试\n"
            fi
            return 1
        fi

        curl_retry=true
        curl_print_error=true
    }

    ZhLhhDownload()
    {
        local book_url="$1" title="$2" i j
        local book_path="$save_dir/${title//\//_}"

        i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        book_html=$(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: $book_url" $book_url)
        iframe_path=$(grep -oP '<iframe id="iframepage" src="\K[^"]+' <<< "$book_html" | sed 's/\&amp;/\&/g')

        if [ "${iframe_path:-}" == "#" ] 
        then
            printf '%s' '' > "$COOKIE_FILE"
            CurlFake -s -L -c "$COOKIE_FILE" http://www.zhlhh.com/ > /dev/null
            login_html=$(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/index.aspx" "http://www.zhlhh.com/user/login.aspx?libcode=$libcode")
            viewstate=$(grep -oP '<input(.+)name="__VIEWSTATE"(.+)value="\K[^"]+' <<< "$login_html")
            viewstate_generator=$(grep -oP '<input(.+)name="__VIEWSTATEGENERATOR"(.+)value="\K[^"]+' <<< "$login_html")
            event_validation=$(grep -oP '<input(.+)name="__EVENTVALIDATION"(.+)value="\K[^"]+' <<< "$login_html")
            CurlFake -s -b "$COOKIE_FILE" -c "$COOKIE_FILE" \
            --data "__VIEWSTATE=$viewstate&__VIEWSTATEGENERATOR=$viewstate_generator&__EVENTVALIDATION=$event_validation&txtusername=admin&txtpassword=21232f297a57a5a743894a0e4a801fc3&btnlogin=登 录&returnUrl=http://www.zhlhh.com/" "http://www.zhlhh.com/user/login.aspx?libcode=$libcode" > /dev/null
            book_html=$(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: $book_url" $book_url)
            iframe_path=$(grep -oP '<iframe id="iframepage" src="\K[^"]+' <<< "$book_html" | sed 's/\&amp;/\&/g')
        fi

        iframe_url="${book_url%/*}/$iframe_path"
        book_html=$(LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" -H "Referer: $book_url" "$iframe_url")
        source_src=$(grep -oP '<input id="sousrc"(.+)value="\K[^"]+' <<< "$book_html")
        book_images=($(grep -m1 -oE "var filenamefc=new Array\(.+\);" <<< "$book_html" | grep -oE "[0-9]+"))
        p_p=$(grep -oP '<div id="p_p"(.+)">\K[^<]+' <<< "$book_html")
        iii=( 5 6 7 1 3 8 101 88 66 77 44 55 33 22 4 84 65 42 )

        IFS="|" read -r -a pp <<< "${p_p}|"

        total=0
        for((i=0;i<${#pp[1]};i++));
        do
            c=${pp[1]:$i:1}
            if [[ $c =~ ^[0-9]+$ ]] 
            then
                total=$((total+c))
            else
                total=$((total+1))
            fi
        done

        mkdir -p "$book_path"

        if ! TMP_DIR=$(mktemp -q -d)
        then
            exit $?
        fi

        trap '
            rm -rf "${TMP_DIR:-notfound}"
        ' EXIT

        for((i=0;i<${#book_images[@]};i++));
        do
            book_image="${book_images[i]}"
            book_image_formated=$(printf '%04d' $((i+1)))

            echo -ne "\r"
            tput el
            echo -n "$title ${book_image_formated}.jpg"

            ffmpeg_inputs=()

            for((j=0;j<${pp[2]};j++));
            do
                ffmpeg_inputs+=( -i "$TMP_DIR/${j}.jpg" )

                if [ $j -gt "${#iii[@]}" ] 
                then
                    image_name="${book_image}$((total*j))"
                else
                    image_name="${book_image}$((total*iii[j]))"
                fi

                LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" -o "$TMP_DIR/${j}.jpg" "${source_src}${pp[0]}/${pp[1]}/${image_name}.jpg"
            done

            # https://stackoverflow.com/questions/10225403/how-can-i-extract-a-good-quality-jpeg-image-from-a-video-file-with-ffmpeg
            $FFMPEG_FILE ${ffmpeg_inputs[@]+"${ffmpeg_inputs[@]}"} -hide_banner -loglevel error -filter_complex hstack=inputs=$j -qmin 1 -q:v 1 -update true "$book_path/${book_image_formated}.jpg"
        done

        echo -ne "\r"
        tput el

        rm -rf "${TMP_DIR:-notfound}"

        trap - EXIT
    }

    ZhLhh()
    {
        local search_keys=( a b c d e f a )
        local search_means=( '书名' '原著' '改编' '绘画' '出版社' '颜色' '人物' )
        libcode=A7CCFF874E0E58868FF7FA84BF94B4C94E9F781AEF6E50E0359E12099735745F2B943218D8F245B2BD8EFA919770D399
        COOKIE_FILE="$LIANHUANHUA_ROOT/cookie_zhlhh"

        if [ ! -s "$LIANHUANHUA_CONFIG" ] 
        then
            mkdir -p "$LIANHUANHUA_ROOT/"
            printf '{"%s":{"%s":[]}}' "books" "zhlhh" > "$LIANHUANHUA_CONFIG"
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$LIANHUANHUA_CONFIG" 'del(.books.hdlz)')

        jq_path='[
            ["default","save_dir"],
            ["books","zhlhh","adapter"],
            ["books","zhlhh","addtime"],
            ["books","zhlhh","bookname"],
            ["books","zhlhh","category_id"],
            ["books","zhlhh","cover"],
            ["books","zhlhh","drawing"],
            ["books","zhlhh","m"],
            ["books","zhlhh","muludir"],
            ["books","zhlhh","original"],
            ["books","zhlhh","p"],
            ["books","zhlhh","publish"],
            ["books","zhlhh","yd"],
            ["books","zhlhh","downloaded"],
            ["books","zhlhh","fav"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        default_save_dir="$jq_default_save_dir"

        IFS="${delimiters[3]}" read -r -a books_adapter <<< "$jq_books_zhlhh_adapter"
        IFS="${delimiters[3]}" read -r -a books_addtime <<< "$jq_books_zhlhh_addtime"
        IFS="${delimiters[3]}" read -r -a books_bookname <<< "$jq_books_zhlhh_bookname"
        IFS="${delimiters[3]}" read -r -a books_category_id <<< "$jq_books_zhlhh_category_id"
        IFS="${delimiters[3]}" read -r -a books_cover <<< "$jq_books_zhlhh_cover"
        IFS="${delimiters[3]}" read -r -a books_drawing <<< "$jq_books_zhlhh_drawing"
        IFS="${delimiters[3]}" read -r -a books_m <<< "$jq_books_zhlhh_m"
        IFS="${delimiters[3]}" read -r -a books_muludir <<< "$jq_books_zhlhh_muludir"
        IFS="${delimiters[3]}" read -r -a books_original <<< "$jq_books_zhlhh_original"
        IFS="${delimiters[3]}" read -r -a books_p <<< "$jq_books_zhlhh_p"
        IFS="${delimiters[3]}" read -r -a books_publish <<< "$jq_books_zhlhh_publish"
        IFS="${delimiters[3]}" read -r -a books_yd <<< "$jq_books_zhlhh_yd"
        IFS="${delimiters[3]}" read -r -a books_downloaded <<< "$jq_books_zhlhh_downloaded"
        IFS="${delimiters[3]}" read -r -a books_fav <<< "$jq_books_zhlhh_fav"

        local books_total=${#books_adapter[@]}

        if [ "$books_total" -gt 0 ] 
        then
            search_means=( '不搜索' "${search_means[@]}" )
        fi

        Println "$tip 人物只能单独查询"
        inquirer checkbox_input_indices "选择查询选项" search_means search_keys_indices 20

        if [ "$books_total" -gt 0 ] && EleInArray 0 search_keys_indices
        then
            result_bookname=()
            for((i=0;i<books_total;i++));
            do
                bookname="${books_bookname[i]}"
                if [ "${books_downloaded[i]}" = true ] 
                then
                    bookname="$bookname ${green}[已下载]${normal}"
                fi
                if [ "${books_fav[i]}" = true ] 
                then
                    bookname="$bookname ${green}[已收藏]${normal}"
                fi
                result_bookname+=("$bookname")
            done
            result_m=("${books_m[@]}")
            result_yd=("${books_yd[@]}")
            result_p=("${books_p[@]}")
            iframe_paths=($(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/" "http://www.zhlhh.com/web/js/main.js" | grep -oP 'url = "\K[^"]+'))
            books_indices=("${!books_m[@]}")
        else
            if EleInArray $((${#search_means[@]}-1)) search_keys_indices
            then
                echo
                ExitOnText "输入查询的人物" search_text
                post_data="${search_keys[6]}=$search_text&p=1&s=1000"
                post_url="http://www.zhlhh.com/web/handler/main.ashx/G_P_B"
            else
                colors=( '全部' '黑白' '彩色' )
                for search_keys_index in "${search_keys_indices[@]}"
                do
                    if [ "$books_total" -gt 0 ] 
                    then
                        search_keys_index=$((search_keys_index-1))
                    fi
                    case $search_keys_index in
                        0) 
                            echo
                            ExitOnText "输入书名" book_name
                        ;;
                        1) 
                            echo
                            ExitOnText "输入原著" book_original
                        ;;
                        2) 
                            echo
                            ExitOnText "输入改编" book_adapter
                        ;;
                        3) 
                            echo
                            ExitOnText "输入绘画" book_drawing
                        ;;
                        4) 
                            echo
                            ExitOnText "输入出版社" book_publish
                        ;;
                        5) 
                            echo
                            inquirer list_input_index "选择颜色" colors colors_index
                        ;;
                    esac
                done

                post_data="a=${book_name:-}&b=${book_original:-}&c=${book_adapter:-}&d=${book_drawing:-}&e=${book_publish:-}&f=${colors[${colors_index:-0}]}&p=1&s=1000"
                post_url="http://www.zhlhh.com/web/handler/main.ashx/G_F_B"
            fi

            response=$(
                CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/" --data ''"$post_data"'' $post_url
            )

            jq_payload=$(JQs flat "$response")

            jq_path='[
                ["AllCount"],
                ["pageInfor","AllCount"],
                ["result","adapter"],
                ["result","addtime"],
                ["result","bookname"],
                ["result","category_id"],
                ["result","cover"],
                ["result","drawing"],
                ["result","m"],
                ["result","muludir"],
                ["result","original"],
                ["result","p"],
                ["result","publish"],
                ["result","yd"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            result_count="$jq_result_count"
            result_total="$jq_pageInfor_AllCount"

            if [ "$result_count" -eq 0 ] 
            then
                Println "$error 没有结果"
                exit 1
            fi

            iframe_paths=($(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/" "http://www.zhlhh.com/web/js/main.js" | grep -oP 'url = "\K[^"]+'))

            IFS="${delimiters[2]}" read -r -a result_adapter <<< "$jq_result_adapter"
            IFS="${delimiters[2]}" read -r -a result_addtime <<< "$jq_result_addtime"
            IFS="${delimiters[2]}" read -r -a result_bookname <<< "$jq_result_bookname"
            IFS="${delimiters[2]}" read -r -a result_category_id <<< "$jq_result_category_id"
            IFS="${delimiters[2]}" read -r -a result_cover <<< "$jq_result_cover"
            IFS="${delimiters[2]}" read -r -a result_drawing <<< "$jq_result_drawing"
            IFS="${delimiters[2]}" read -r -a result_m <<< "$jq_result_m"
            IFS="${delimiters[2]}" read -r -a result_muludir <<< "$jq_result_muludir"
            IFS="${delimiters[2]}" read -r -a result_original <<< "$jq_result_original"
            IFS="${delimiters[2]}" read -r -a result_p <<< "$jq_result_p"
            IFS="${delimiters[2]}" read -r -a result_publish <<< "$jq_result_publish"
            IFS="${delimiters[2]}" read -r -a result_yd <<< "$jq_result_yd"

            local i j books new_book books_indices=()

            for((i=0;i<result_count;i++));
            do
                if [ "$books_total" -gt 0 ] && EleInArray "${result_m[i]}" books_m 
                then
                    for((j=0;j<books_total;j++));
                    do
                        if [ "${books_m[j]}" -eq "${result_m[i]}" ] 
                        then
                            if [ "${books_downloaded[j]}" = true ] 
                            then
                                result_bookname[i]="${result_bookname[i]} ${green}[已下载]${normal}"
                            fi

                            if [ "${books_fav[j]}" = true ] 
                            then
                                result_bookname[i]="${result_bookname[i]} ${green}[已收藏]${normal}"
                            fi
                            books_indices+=("$j")
                            break
                        fi
                    done
                else
                    books_adapter+=("${result_adapter[i]}")
                    books_addtime+=("${result_addtime[i]}")
                    books_bookname+=("${result_bookname[i]}")
                    books_category_id+=("${result_category_id[i]}")
                    books_cover+=("${result_cover[i]}")
                    books_drawing+=("${result_drawing[i]}")
                    books_m+=("${result_m[i]}")
                    books_muludir+=("${result_muludir[i]}")
                    books_original+=("${result_original[i]}")
                    books_p+=("${result_p[i]}")
                    books_publish+=("${result_publish[i]}")
                    books_yd+=("${result_yd[i]}")
                    books_downloaded+=("false")
                    books_fav+=("false")
                    new_book=$(
                    $JQ_FILE -n --arg adapter "${result_adapter[i]}" --arg addtime "${result_addtime[i]}" \
                    --arg bookname "${result_bookname[i]}" --arg category_id "${result_category_id[i]}" \
                    --arg cover "${result_cover[i]}" --arg drawing "${result_drawing[i]}" \
                    --arg m "${result_m[i]}" --arg muludir "${result_muludir[i]}" \
                    --arg original "${result_original[i]}" --arg p "${result_p[i]}" \
                    --arg publish "${result_publish[i]}" --arg yd "${result_yd[i]}" \
                        '{
                            adapter: $adapter,
                            addtime: $addtime,
                            bookname: $bookname,
                            category_id: $category_id | tonumber,
                            cover: $cover,
                            drawing: $drawing,
                            m: $m | tonumber,
                            muludir: $muludir,
                            original: $original,
                            p: $p,
                            publish: $publish,
                            yd: $yd,
                            downloaded: false,
                            fav: false
                        }'
                    )

                    [ -n "${books:-}" ] && books="${books},"
                    books="${books}${new_book}"
                    books_indices+=("$books_total")
                    books_total=$((books_total+1))
                fi
            done

            if [ -n "${books:-}" ] 
            then
                jq_path='["books","zhlhh"]'
                JQ add "$LIANHUANHUA_CONFIG" "[$books]"
            fi
        fi

        echo
        inquirer checkbox_input_indices "选择连环画" result_bookname result_indices 20

        echo
        result_options=( '下载' '收藏' '取消收藏' )
        inquirer checkbox_input_indices "选择操作" result_options result_options_indices

        for result_options_index in "${result_options_indices[@]}"
        do
            if [ "$result_options_index" -eq 0 ] 
            then
                echo
                inquirer text_input "输入存储文件夹目录" save_dir "${default_save_dir}"
                RemoveQuotes save_dir
                if [ -z "$save_dir" ] 
                then
                    Println "已取消...\n"
                    exit 1
                fi

                if [ "$save_dir" != "$default_save_dir" ] 
                then
                    jq_path='["default","save_dir"]'
                    JQ update "$LIANHUANHUA_CONFIG" "$save_dir"
                fi

                FFmpegInstall

                for result_index in "${result_indices[@]}"
                do
                    books_index=${books_indices[result_index]}
                    book_url="http://www.zhlhh.com${iframe_paths[result_yd[result_index]]:-iframe_paths[0]}?libcode=$libcode&m=${result_m[result_index]}&p=${result_p[result_index]}&y_l_s="
                    ZhLhhDownload "${book_url}" "${books_bookname[books_index]}"
                    if [ "${books_downloaded[books_index]}" = false ] 
                    then
                        jq_bool=true
                        jq_path='["books","zhlhh",'"$books_index"',"downloaded"]'
                        JQ update "$LIANHUANHUA_CONFIG" true
                    fi
                done

                Println "$info 下载完成\n"
            elif [ "$result_options_index" -eq 1 ] 
            then
                for result_index in "${result_indices[@]}"
                do
                    books_index=${books_indices[result_index]}
                    if [ "${books_fav[books_index]}" = false ]
                    then
                        jq_bool=true
                        jq_path='["books","zhlhh",'"$books_index"',"fav"]'
                        JQ update "$LIANHUANHUA_CONFIG" true
                    fi
                done
                Println "$info 已添加到收藏\n"
            else
                for result_index in "${result_indices[@]}"
                do
                    books_index=${books_indices[result_index]}
                    if [ "${books_fav[books_index]}" = true ]
                    then
                        jq_bool=true
                        jq_path='["books","zhlhh",'"$books_index"',"fav"]'
                        JQ update "$LIANHUANHUA_CONFIG" false
                    fi
                done
                Println "$info 已取消收藏\n"
            fi
        done
    }

    HdlzZhihuDownload()
    {
        local id=$1 title=$2 i j
        local book_path="$save_dir/${title//\//_}"
        shift 2

        i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        if ! book_images=($(LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" "https://zhuanlan.zhihu.com/p/${id}" | grep -oP 'data-original-token="\K[^"]+' | uniq))
        then
            return 1
        fi

        if [ -z "${1:-}" ] 
        then
            mkdir -p "$book_path"

            for((i=0;i<${#book_images[@]};i++));
            do
                book_image="https://picx.zhimg.com/${book_images[i]}_r.jpg"
                book_image_formated=$(printf '%04d' $((i+1)))

                echo -ne "\r"
                tput el
                echo -n "还剩 $result_count 本, $title ${book_image_formated}.jpg"

                LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" -o "$book_path/${book_image_formated}.jpg" "$book_image"
            done

            echo -ne "\r"
            tput el
        else
            j=0

            while [ -n "${1:-}" ] 
            do
                book_images_count="${1%-*}"
                book_images_name="${1#*-}"

                i=2
                until [ ! -d "$book_path/${book_images_name}" ] 
                do
                    if [ "$i" -gt 2 ] 
                    then
                        book_images_name="${book_images_name%-*}"
                    fi
                    book_images_name="${book_images_name}-$i"
                    i=$((i+1))
                done

                mkdir -p "$book_path/${book_images_name}"

                for((i=j;i<book_images_count+j;i++));
                do
                    book_image="https://picx.zhimg.com/${book_images[i]}_r.jpg"
                    book_image_formated=$(printf '%04d' $((i-j+1)))

                    echo -ne "\r"
                    tput el
                    echo -n "还剩 $result_count 本, $title ${book_image_formated}.jpg"

                    LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" -o "$book_path/${book_images_name}/${book_image_formated}.jpg" "$book_image"
                done

                echo -ne "\r"
                tput el

                shift

                j=$((j+book_images_count))
            done
        fi
    }

    HdlzToutiaoDownload()
    {
        local id=$1 title=$2 i j
        local book_path="$save_dir/${title//\//_}"

        i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        if ! book_images=($(LhhDownload -s -L -A "$getinfo_useragent" -H "referer: $signed_url" -H "cookie: ${toutiao_cookies[*]}" "https://www.toutiao.com/article/${id}" | grep -oP '<article[^>]*>.*?</article>' | grep -oP '<img[^>]*src="\K[^"]*(?=")'))
        then
            return 1
        fi

        mkdir -p "$book_path"

        book_images_total=${#book_images[@]}

        for((i=0;i<book_images_total;i++));
        do
            book_image="${book_images[i]}"
            book_image_formated=$(printf '%04d' $((i+1)))

            echo -ne "\r"
            tput el
            echo -n "还剩 $result_count 本, $title ${book_image_formated}.jpg"

            while true 
            do
                curl_retry=false
                curl_print_error=false
                if ! LhhDownload -s -Lm 20 -A "$getinfo_useragent" -H "referer: https://www.toutiao.com/article/${id}" -H "cookie: ${toutiao_cookies[*]}" -o "$book_path/${book_image_formated}.jpg" "$book_image" 
                then
                    HdlzGetTouTiaoCookies
                    if ! book_images=($(LhhDownload -s -L -A "$getinfo_useragent" -H "referer: $signed_url" -H "cookie: ${toutiao_cookies[*]}" "https://www.toutiao.com/article/${id}" | grep -oP '<article[^>]*>.*?</article>' | grep -oP '<img[^>]*src="\K[^"]*(?=")'))
                    then
                        Println "$error 无法获取图片\n"
                        exit 1
                    fi
                    continue
                fi
                break
            done
        done

        echo -ne "\r"
        tput el
    }

    HdlzGetTouTiaoCookies()
    {
        if ! toutiao_init=$(node "$NODE_ROOT"/toutiao/browser.js)
        then
            Println "$error 无法使用 头条 node\n"
            exit 1
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$toutiao_init")

        jq_path='[
            ["data","getinfo","url"],
            ["data","feed","url"],
            ["data","feed","headers","cookie"],
            ["data","feed","headers","referer"],
            ["data","getinfo","headers","referer"],
            ["data","getinfo","headers","user-agent"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        getinfo_url="$jq_data_getinfo_url"
        signed_url="$jq_data_feed_url"
        feed_cookie="$jq_data_feed_headers_cookie"
        feed_referer="$jq_data_feed_headers_referer"
        getinfo_referer="$jq_data_getinfo_headers_referer"
        getinfo_useragent="$jq_data_getinfo_headers_user-agent"

        if [[ "${feed_cookie}" =~ (.*)tt_scid=([^\;]+)\;\ (.*) ]] || [[ "${feed_cookie}" =~ (.*)tt_scid=([^ ]+)(.*) ]] 
        then
            cookie_tt_scid="${BASH_REMATCH[2]}"
            toutiao_cookies=( ${feed_cookie} )
        else
            if [[ "${feed_cookie}" =~ (.*)ttcid=([^\;]+)\;\ (.*) ]] || [[ "${feed_cookie}" =~ (.*)ttcid=([^ ]+)(.*) ]]
            then
                feed_cookie="${BASH_REMATCH[1]}${BASH_REMATCH[3]:-}"
            fi

            cookie_tt_scid=($(CurlFake -s -Lm 20 -A "$getinfo_useragent" -H "cookie: $feed_cookie" -H "referer: $getinfo_referer" -D - -o /dev/null "$getinfo_url" | grep -i 'set-cookie' | awk '{print $2}'))
            toutiao_cookies=( ${cookie_tt_scid[@]} ${feed_cookie} )
        fi

        cookie_mstoken=$(RandStr 64)
        cookie_verify="verify_$(RandStr 8)_$(RandStr 8)_$(RandStr 4)_$(RandStr 4)_$(RandStr 4)_$(RandStr 12)"
        toutiao_cookies=( "msToken=${cookie_mstoken};" "s_v_web_id=${cookie_verify};" ${toutiao_cookies[@]} )
        toutiao_cookies_json="$(CookiesToJson www.toutiao.com ${toutiao_cookies[@]})"
    }

    HdlzLhh()
    {
        if [ ! -s "$LIANHUANHUA_CONFIG" ] 
        then
            mkdir -p "$LIANHUANHUA_ROOT/"
            printf '{"%s":{"%s":[]}}' "books" "hdlz" > "$LIANHUANHUA_CONFIG"
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$LIANHUANHUA_CONFIG")

        jq_path='[
            ["default","save_dir"],
            ["books","hdlz","source"],
            ["books","hdlz","id"],
            ["books","hdlz","title"],
            ["books","hdlz","cover"],
            ["books","hdlz","excerpt"],
            ["books","hdlz","behot_time"],
            ["books","hdlz","downloaded"],
            ["books","hdlz","fav"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        default_save_dir="$jq_default_save_dir"

        IFS="${delimiters[3]}" read -r -a books_source <<< "$jq_books_hdlz_source"
        IFS="${delimiters[3]}" read -r -a books_id <<< "$jq_books_hdlz_id"
        IFS="${delimiters[3]}" read -r -a books_title <<< "$jq_books_hdlz_title"
        IFS="${delimiters[3]}" read -r -a books_cover <<< "$jq_books_hdlz_cover"
        IFS="${delimiters[3]}" read -r -a books_excerpt <<< "$jq_books_hdlz_excerpt"
        IFS="${delimiters[3]}" read -r -a books_behot_time <<< "$jq_books_hdlz_behot_time"
        IFS="${delimiters[3]}" read -r -a books_downloaded <<< "$jq_books_hdlz_downloaded"
        IFS="${delimiters[3]}" read -r -a books_fav <<< "$jq_books_hdlz_fav"

        local books_total=${#books_source[@]} i j lookup_options_index=0

        if [ "$books_total" -gt 0 ] 
        then
            echo
            lookup_options=( '不查询' '查询知乎' '查询头条' '查询全部' )
            inquirer list_input_index "是否重新查询" lookup_options lookup_options_index
        fi

        COOKIE_FILE="$LIANHUANHUA_ROOT/cookie_hdlz"

        if [ "$books_total" -eq 0 ] || [ "$lookup_options_index" -eq 1 ] || [ "$lookup_options_index" -eq 3 ]
        then
            if ! CurlFake -s -L -b "$COOKIE_FILE" -c "$COOKIE_FILE" https://www.zhihu.com/column/c_1396234006309003264 > /dev/null
            then
                Println "$error 无法连接知乎, 请稍后再试"
                exit 1
            fi

            local loop=0 books new_book

            while true 
            do
                echo -ne "\r"
                tput el

                echo -n "搜索知乎 $((1+loop*20))~$((20+loop*20)), 共 2568 条"

                response=$(
                    CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: https://www.zhihu.com/column/c_1396234006309003264" ${paging_next:-'http://www.zhihu.com/api/v4/columns/c_1396234006309003264/items?limit=20&offset=0'}
                )

                jq_payload=$(JQs flat "$response")

                jq_path='[
                    ["paging","is_end"],
                    ["paging","next"],
                    ["paging","previous"],
                    ["data","excerpt"],
                    ["data","id"],
                    ["data","image_url"],
                    ["data","title"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                paging_is_end="$jq_paging_is_end"
                paging_next="$jq_paging_next"
                paging_previous="$jq_paging_previous"

                IFS="${delimiters[2]}" read -r -a result_excerpt <<< "$jq_data_excerpt"

                if [ -z "${result_excerpt:-}" ] 
                then
                    paging_next="$paging_previous"
                    continue
                fi

                IFS="${delimiters[2]}" read -r -a result_id <<< "$jq_data_id"
                IFS="${delimiters[2]}" read -r -a result_cover <<< "$jq_data_image_url"
                IFS="${delimiters[2]}" read -r -a result_title <<< "$jq_data_title"

                result_total=${#result_id[@]}
                books_total=$((books_total+result_total))
                books=""

                for((i=0;i<result_total;i++));
                do
                    if [ -z "${books_id:-}" ] || ! EleInArray "${result_id[i]}" books_id
                    then
                        books_id+=("${result_id[i]}")
                    else
                        books_total=$((books_total-1))
                        continue
                    fi

                    book_images_command=()
                    book_excerpts=(${result_excerpt[i]} end)
                    book_images_count=0
                    book_images_name=""

                    for((j=0;j<${#book_excerpts[@]};j++));
                    do
                        if [ "${book_excerpts[j]}" == "[图片]" ] 
                        then
                            book_images_count=$((book_images_count+1))
                        elif [ "${book_excerpts[j]}" == "end" ] 
                        then
                            if [ "${book_excerpts[j-1]}" == "[图片]" ] && [ -n "${book_images_command:-}" ] 
                            then
                                if [ "${#book_images_command[@]}" -eq 1 ] 
                                then
                                    if [ "$book_images_count" -eq 1 ] 
                                    then
                                        book_images_command=()
                                        break
                                    fi
                                else
                                    if [ "$book_images_count" -eq 1 ] 
                                    then
                                        book_images_command_count="${#book_images_command[@]}"
                                        book_images_command_last="${book_images_command[book_images_command_count-1]}"
                                        book_images_command_last_num=${book_images_command_last%-*}
                                        book_images_command_last_name=${book_images_command_last#*-}
                                        book_images_command[book_images_command_count-1]="$((book_images_command_last_num+1))-${book_images_command_last_name}"
                                        break
                                    fi
                                fi
                                book_images_command+=( "${book_images_count}-${book_images_name:-未分类}" )
                            else
                                book_images_command=()
                            fi
                        else
                            if [ "$book_images_count" -le 1 ] || [ "${#book_excerpts[j]}" -ge 10 ]
                            then
                                continue
                            fi

                            book_images_command+=( "${book_images_count}-${book_images_name:-未分类}" )
                            book_images_count=0

                            book_images_name="${book_excerpts[j]}"
                        fi
                    done

                    books_source+=("zhihu")
                    books_title+=("${result_title[i]}")
                    books_cover+=("${result_cover[i]}")
                    books_excerpt+=("${book_images_command[*]:-}")
                    books_downloaded+=("false")
                    books_fav+=("false")
                    new_book=$(
                    $JQ_FILE -n --arg source "zhihu" --arg id "${result_id[i]}" \
                    --arg title "${result_title[i]}" --arg cover "${result_cover[i]}" \
                    --arg excerpt "${book_images_command[*]:-}" \
                        '{
                            source: $source,
                            id: $id,
                            title: $title,
                            cover: $cover,
                            excerpt: $excerpt,
                            downloaded: false,
                            fav: false
                        }'
                    )

                    [ -n "${books:-}" ] && books="${books},"
                    books="${books}${new_book}"
                done

                loop=$((loop+1))

                if [ "$paging_is_end" = true ] 
                then
                    echo -ne "\r"
                    tput el
                    break
                fi

                if [ -z "${books:-}" ] 
                then
                    continue
                fi

                jq_path='["books","hdlz"]'
                JQ add "$LIANHUANHUA_CONFIG" "[$books]"
            done
        fi

        if [ "$books_total" -eq 0 ] || [ "$lookup_options_index" -eq 2 ] || [ "$lookup_options_index" -eq 3 ] 
        then
            NodejsInstall
            NodeInstallToutiao

            HdlzGetTouTiaoCookies

            # last_behot_time=$(date +%s)
            # for((i=0;i<books_total;i++));
            # do
            #     if [ "${books_source[i]}" = "toutiao" ] && [ "${books_behot_time[i]}" -lt "$last_behot_time" ]
            #     then
            #         last_behot_time="${books_behot_time[i]}"
            #     fi
            # done

            # if [[ "${feed_cookie}" =~ (.*)__ac_nonce=([^\;]+)\;\ (.*) ]] || [[ "${feed_cookie}" =~ (.*)__ac_nonce=([^ ]+)(.*) ]] 
            # then
            #    cookie_nonce="${BASH_REMATCH[2]}"
            # fi
            # cookie_signature=$(node "$NODE_ROOT"/toutiao/browser.js "$cookie_nonce" "$toutiao_cookies_json" | $JQ_FILE -r '.data.signature')

            signed_url="https://www.toutiao.com/api/pc/list/user/feed?category=profile_all&token=MS4wLjABAAAAB2ev2na9xNHI8py8dnKvLnSYGkxaFKDtOQTqbR7nsEzpNhwVqpCY8ZZz6s7qA8vt&max_behot_time=0&aid=24&app_name=toutiao_web"
            IFS= read -r a_bogus < <(node "$NODE_ROOT"/toutiao/browser.js "$signed_url" "$toutiao_cookies_json" | $JQ_FILE -r '.data."a-bogus"')
            signed_url="${signed_url}&a_bogus=${a_bogus}"

            local toutiao_total=0

            while true 
            do
                if ! jq_input=$(LhhDownload -s -Lm 20 -A "$getinfo_useragent" -H "referer: $feed_referer" -H "cookie: ${toutiao_cookies[*]}" "$signed_url" | $JQ_FILE -c '.data |= map({id, behot_time, title})' 2> /dev/null)
                then
                    result_total=0
                else
                    jq_payload=$(JQs flat "$jq_input")

                    jq_path='[
                        ["has_more"],
                        ["next","max_behot_time"],
                        ["data","id"],
                        ["data","behot_time"],
                        ["data","title"]
                    ]'

                    while IFS=": " read -r path_name value; do
                        var_name=${path_name}
                        read -r ${var_name?} <<< "$value"
                    done < <(JQs gets jq_payload)

                    has_more="$jq_has_more"
                    max_behot_time="$jq_next_max_behot_time"

                    IFS="${delimiters[2]}" read -r -a result_id <<< "$jq_data_id"
                    IFS="${delimiters[2]}" read -r -a result_behot_time <<< "$jq_data_behot_time"
                    IFS="${delimiters[2]}" read -r -a result_title <<< "$jq_data_title"

                    result_total=${#result_id[@]}
                fi

                while true 
                do
                    if [ "$result_total" -gt 0 ] 
                    then
                        max_behot_time=$m_max_behot_time
                    else
                        cookie_mstoken=$(RandStr 64)
                        cookie_verify="verify_$(RandStr 8)_$(RandStr 8)_$(RandStr 4)_$(RandStr 4)_$(RandStr 4)_$(RandStr 12)"
                        toutiao_cookies[0]="msToken=${cookie_mstoken};"
                        toutiao_cookies[1]="s_v_web_id=${cookie_verify};"
                        toutiao_cookies_json="$(CookiesToJson www.toutiao.com ${toutiao_cookies[@]})"
                    fi

                    if ! signed_response=$(node "$NODE_ROOT"/toutiao/browser.js "https://www.toutiao.com/api/pc/list/user/feed?category=profile_all&token=MS4wLjABAAAAB2ev2na9xNHI8py8dnKvLnSYGkxaFKDtOQTqbR7nsEzpNhwVqpCY8ZZz6s7qA8vt&max_behot_time=${max_behot_time:-0}&aid=24&app_name=toutiao_web" "$toutiao_cookies_json")
                    then
                        sleep 12
                        continue
                    fi

                    if ! a_bogus=$($JQ_FILE -r '.data."a-bogus"' <<< "$signed_response" 2> /dev/null) 
                    then
                        Println "$error $signed_response\n"
                        continue
                    fi

                    signed_url="${signed_url%&*}&a_bogus=${a_bogus}"

                    if [ "$result_total" -eq 0 ] 
                    then
                        continue 2
                    fi
                    break
                done

                echo -ne "\r"
                tput el

                echo -n "搜索头条 $((toutiao_total+1))~$((toutiao_total+result_total))"

                toutiao_total=$((toutiao_total+result_total))

                # if [ "${result_behot_time[result_total-1]}" -gt "$last_behot_time" ] 
                # then
                #     continue
                # fi

                books_total=$((books_total+result_total))
                books=""

                for((i=0;i<result_total;i++));
                do
                    if [ -n "${result_title[i]}" ] && { [ -z "${books_id:-}" ] || ! EleInArray "${result_id[i]}" books_id ;} 
                    then
                        books_id+=("${result_id[i]}")
                    else
                        books_total=$((books_total-1))
                        continue
                    fi

                    books_source+=("toutiao")
                    books_title+=("${result_title[i]}")
                    books_downloaded+=("false")
                    books_fav+=("false")

                    new_book=$(
                    $JQ_FILE -n --arg source "toutiao" --arg id "${result_id[i]}" \
                    --arg title "${result_title[i]}" --arg behot_time "${result_behot_time[i]}" \
                        '{
                            source: $source,
                            id: $id,
                            title: $title,
                            behot_time: $behot_time | tonumber,
                            downloaded: false,
                            fav: false
                        }'
                    )

                    [ -n "${books:-}" ] && books="${books},"
                    books="${books}${new_book}"
                done

                if [ "$has_more" = false ] 
                then
                    echo -ne "\r"
                    tput el
                    break
                fi

                if [ -z "${books:-}" ] 
                then
                    continue
                fi

                jq_path='["books","hdlz"]'
                JQ add "$LIANHUANHUA_CONFIG" "[$books]"
            done
        fi

        # dy_163_docid=($(CurlFake -s -L -b "$COOKIE_FILE" -c "$COOKIE_FILE" https://www.163.com/dy/media/T1624341866994.html | grep -oP '<a href="https://www.163.com/dy/article/\K[^.]+' | uniq))

        result_title=()

        for((i=0;i<books_total;i++));
        do
            result_title[i]="${books_title[i]#*｜}"
            if [ "${books_downloaded[i]}" = true ] 
            then
                result_title[i]="${result_title[i]} ${green}[已下载]${normal}"
            fi
            if [ "${books_fav[i]}" = true ] 
            then
                result_title[i]="${result_title[i]} ${green}[已收藏]${normal}"
            fi
        done

        echo
        inquirer checkbox_input_indices "选择连环画" result_title result_indices 20

        echo
        result_options=( '下载' '收藏' '取消收藏' )
        inquirer checkbox_input_indices "选择操作" result_options result_options_indices

        for result_options_index in "${result_options_indices[@]}"
        do
            if [ "$result_options_index" -eq 0 ] 
            then
                echo
                inquirer text_input "输入存储文件夹目录" save_dir "${default_save_dir}"
                RemoveQuotes save_dir
                if [ -z "$save_dir" ] 
                then
                    Println "已取消...\n"
                    exit 1
                fi

                if [ "$save_dir" != "$default_save_dir" ] 
                then
                    jq_path='["default","save_dir"]'
                    JQ update "$LIANHUANHUA_CONFIG" "$save_dir"
                fi

                local all_success=true all_failed=true
                result_count="${#result_indices[@]}"

                for result_index in "${result_indices[@]}"
                do
                    result_count=$((result_count-1))
                    if [ "${books_source[result_index]}" == "zhihu" ] 
                    then
                        if ! HdlzZhihuDownload "${books_id[result_index]}" "${books_title[result_index]#*｜}" ${books_excerpt[result_index]}
                        then
                            Println "$error ${books_title[result_index]#*｜} 下载失败, 请检查资源是否存在 https://zhuanlan.zhihu.com/p/${books_id[result_index]}\n"
                            all_success=false
                            continue
                        fi
                    else
                        if [ -z "${toutiao_init:-}" ] 
                        then
                            HdlzGetTouTiaoCookies
                        fi
                        if ! HdlzToutiaoDownload "${books_id[result_index]}" "${books_title[result_index]#*｜}"
                        then
                            Println "$error ${books_title[result_index]#*｜} 下载失败, 请检查资源是否存在 https://www.toutiao.com/article/${books_id[result_index]}\n"
                            all_success=false
                            continue
                        fi
                    fi

                    all_failed=false

                    if [ "${books_downloaded[result_index]}" = false ] 
                    then
                        jq_bool=true
                        jq_path='["books","hdlz",'"$result_index"',"downloaded"]'
                        JQ update "$LIANHUANHUA_CONFIG" true
                    fi
                done

                if [ "$all_failed" = true ] 
                then
                    Println "$error 所有资源下载失败\n"
                    exit 1
                elif [ "$all_success" = true ] 
                then
                    Println "$info 下载完成\n"
                else
                    Println "$info 部分下载完成\n"
                fi
            elif [ "$result_options_index" -eq 1 ] 
            then
                for result_index in "${result_indices[@]}"
                do
                    jq_bool=true
                    jq_path='["books","hdlz",'"$result_index"',"fav"]'
                    JQ update "$LIANHUANHUA_CONFIG" true
                done
                Println "$info 已添加到收藏\n"
            else
                for result_index in "${result_indices[@]}"
                do
                    jq_bool=true
                    jq_path='["books","hdlz",'"$result_index"',"fav"]'
                    JQ update "$LIANHUANHUA_CONFIG" false
                done
                Println "$info 已取消收藏\n"
            fi
        done
    }

    DangValidateId()
    {
        if [ "$1" == "$i18n_cancel" ]
        then
            return 0
        fi

        book_id=${1##*/}
        book_id=${book_id%%_*}

        if [ "$books_total" -gt 0 ] 
        then
            local id
            for id in "${books_id[@]}"
            do
                if [ "$id" == "$book_id" ] 
                then
                    return 1
                fi
            done
        fi

        return 0
    }

    DangValidateStartPage()
    {
        if [ "$1" == "$i18n_cancel" ] || [[ $1 =~ ^[0-9]+$ ]]
        then
            return 0
        fi

        return 1
    }

    DangValidateEndPage()
    {
        if [ "$1" == "$i18n_cancel" ] || { [[ $1 =~ ^[0-9]+$ ]] && [ "$1" -ge "$book_start" ]; }
        then
            return 0
        fi

        return 1
    }

    DangCloudDownload()
    {
        echo
        inquirer text_input "输入存储文件夹目录" save_dir "${default_save_dir}"
        RemoveQuotes save_dir

        if [ -z "$save_dir" ] 
        then
            Println "已取消...\n"
            return 1
        fi

        if [ "$save_dir" != "$default_save_dir" ] 
        then
            jq_path='["default","save_dir"]'
            JQ update "$LIANHUANHUA_CONFIG" "$save_dir"
        fi

        local book_path="$save_dir/${book_title//\//_}"
        local book_images_count=$((book_end-book_start+1))

        local i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        mkdir -p "$book_path"

        book_image_format_num=${#book_end}
        book_image_formated=$(printf "%0${book_image_format_num}d" $book_start)
        LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_formated}.jpg" "${book_img%/*}/${book_id}_cover_epub.jpg"

        book_image_formated=$(printf "%0${book_image_format_num}d" $((book_start+1)))
        LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_formated}.jpg" "${book_img%/*}/${book_id}_F001_epub.jpg"

        book_image_formated=$(printf "%0${book_image_format_num}d" $((book_start+2)))
        LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_formated}.jpg" "${book_img%/*}/${book_id}_F002_epub.jpg"

        for((i=0;i<book_images_count;i++));
        do
            book_image_formated=$(printf "%0${book_image_format_num}d" $((book_start+i)))
            book_image_save_formated=$(printf "%0${book_image_format_num}d" $((book_start+i+3)))

            echo -ne "\r"
            tput el
            echo -n "还剩 $((book_images_count-i)) 张, $book_title ${book_image_formated}.jpg"

            LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_save_formated}.jpg" "${book_img%/*}/${book_id}_P${book_image_formated}_epub.jpg"
        done

        echo -ne "\r"
        tput el
    }

    DangCloud()
    {
        if [ ! -s "$LIANHUANHUA_CONFIG" ] 
        then
            mkdir -p "$LIANHUANHUA_ROOT/"
            printf '{"%s":{"%s":[]}}' "books" "dang" > "$LIANHUANHUA_CONFIG"
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$LIANHUANHUA_CONFIG")

        jq_path='[
            ["default","save_dir"],
            ["books","dang","id"],
            ["books","dang","title"],
            ["books","dang","cover"],
            ["books","dang","start"],
            ["books","dang","end"],
            ["books","dang","downloaded"],
            ["books","dang","fav"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        default_save_dir="$jq_default_save_dir"

        IFS="${delimiters[3]}" read -r -a books_id <<< "$jq_books_dang_id"
        IFS="${delimiters[3]}" read -r -a books_title <<< "$jq_books_dang_title"
        IFS="${delimiters[3]}" read -r -a books_cover <<< "$jq_books_dang_cover"
        IFS="${delimiters[3]}" read -r -a books_start <<< "$jq_books_dang_start"
        IFS="${delimiters[3]}" read -r -a books_end <<< "$jq_books_dang_end"
        IFS="${delimiters[3]}" read -r -a books_downloaded <<< "$jq_books_dang_downloaded"
        IFS="${delimiters[3]}" read -r -a books_fav <<< "$jq_books_dang_fav"

        local books_total=${#books_id[@]}

        dang_options_index=0

        if [ "$books_total" -gt 0 ] 
        then
            echo
            dang_options=( '添加' '选择' )
            inquirer list_input_index "请选择操作" dang_options dang_options_index
        fi

        if [ "$dang_options_index" -eq 0 ] 
        then
            echo
            ExitOnText "输入书名" book_title

            Println "$tip 比如 https://img7x6.ddimg.cn/imgother10/xx/xx/xxxxxxxxxx_cover_epub.jpg"
            ExitOnText "输入图片链接" book_img DangValidateId "此书已经存在"

            book_id=${book_img##*/}
            book_id=${book_id%%_*}

            echo
            ExitOnText "输入起始页码" book_start DangValidateStartPage "请输入数字"

            echo
            ExitOnText "输入结束页码" book_end DangValidateEndPage "请输入数字且不能小于起始页码"

            echo
            inquirer list_input_index "收藏" ny_options ny_index

            if [ "$ny_index" -eq 0 ] 
            then
                book_fav=false
            else
                book_fav=true
            fi

            echo
            inquirer list_input_index "下载" ny_options ny_index

            if [ "$ny_index" -eq 0 ] 
            then
                book_downloaded=false
            else
                DangCloudDownload
                book_downloaded=true
            fi

            new_book=$(
