elif [ "$self" == "cw" ]
then
    CalibreWebPatch()
    {
        if [ ! -d "$CALIBRE_ROOT/web" ] 
        then
            Println "$error 请先安装 Calibre Web\n"
            return 1
        fi

        local d

        for d in "$CALIBRE_ROOT"/web/cps/translations/*
        do
            if TMP_FILE=$(mktemp -q) 
            then
                chmod +r "$TMP_FILE"
            else
                printf -v TMP_FILE '%(%m-%d-%H:%M:%S)T' -1
            fi

            trap '
                rm -f "$TMP_FILE"
            ' EXIT

            awk '
                BEGIN {
                    in_relevant_block = 0;
                }

                /#:/ {
                    in_relevant_block = ($0 ~ /helper\.py/) ? 1 : 0;
                }

                /^msgid/ && in_relevant_block {
                    gsub(/Calibre-Web/, "Epub.Fun");
                }

                /^msgstr/ && in_relevant_block {
                    gsub(/Calibre-Web/, "Epub.Fun");
                }

                { print }
            ' "$d"/LC_MESSAGES/messages.po > "$TMP_FILE"

            mv "$TMP_FILE" "$d"/LC_MESSAGES/messages.po

            trap - EXIT

            sed -i 's/please restart Calibre-Web/please restart/g' "$d"/LC_MESSAGES/messages.po
            sed -i 's/to hide it in Calibre-Web/to hide it/g' "$d"/LC_MESSAGES/messages.po
            sed -i 's/Calibre-Web Instance/Instance/g' "$d"/LC_MESSAGES/messages.po
            msgfmt -o "$d"/LC_MESSAGES/messages.mo "$d"/LC_MESSAGES/messages.po
        done

        sed -i '20,$s/Calibre-Web/Epub.Fun/g' "$CALIBRE_ROOT"/web/cps/helper.py
        sed -i '20,$s/ Calibre-Web//g' "$CALIBRE_ROOT"/web/cps/search.py
        sed -i 's/ in Calibre-Web//g' "$CALIBRE_ROOT"/web/cps/templates/detail.html
        sed -i 's/Calibre-Web //g' "$CALIBRE_ROOT"/web/cps/templates/http_error.html

        return 0
    }

    CalibreWebInstall()
    {
        if [ -d "$CALIBRE_ROOT/web" ] 
        then
            cd "$CALIBRE_ROOT/web"
            git stash
            git pull
            git stash pop
            Println "$info Calibre Web 更新成功\n"
            return
        fi

        GitInstall
        PythonInstall
        git clone https://github.com/janeczku/calibre-web.git "$CALIBRE_ROOT/web"
        cd "$CALIBRE_ROOT/web"
        if [ "$dist" == "ubu" ] || [ "$dist" == "deb" ]
        then
            python3 -m pip install virtualenv
            virtualenv venv
        else
            python3 -m venv venv
        fi
        ./venv/bin/python3 -m pip install -r requirements.txt
        Println "$info Calibre Web 安装成功\n"
    }

    CalibreWebStart()
    {
        service_name="calibre-web"

        if ServiceControl is-active "$service_name"
        then
            Println "$error $service_name 已运行\n"
            return 1
        fi

        service_commands=( "$CALIBRE_ROOT"/web/venv/bin/python3 "$CALIBRE_ROOT"/web/cps.py )

        if ! err_msg=$(ServiceControl start "$service_name" service_commands)
        then
            Println "$error $service_name 启动失败, $err_msg\n"
            return 1
        fi

        Println "$info $service_name 启动成功\n"
    }

    CalibreWebStop()
    {
        service_name="calibre-web"

        if ! ServiceControl is-active "$service_name"
        then
            Println "$error $service_name 未运行\n"
            return 1
        fi

        if ! err_msg=$(ServiceControl stop "$service_name")
        then
            Println "$error $service_name 关闭失败, $err_msg\n"
            return 1
        fi

        Println "$info $service_name 关闭成功\n"
    }

    CalibreWebRestart()
    {
        service_name="calibre-web"

        if ServiceControl is-active "$service_name" && ! err_msg=$(ServiceControl stop "$service_name")
        then
            Println "$error $service_name 关闭失败, $err_msg\n"
            return 1
        fi

        service_commands=( "$CALIBRE_ROOT"/web/venv/bin/python3 "$CALIBRE_ROOT"/web/cps.py )

        if ! err_msg=$(ServiceControl start "$service_name" service_commands)
        then
            Println "$error $service_name 重启失败, $err_msg\n"
            return 1
        fi

        Println "$info $service_name 重启成功\n"
    }

    CalibreWebView()
    {
        service_name="calibre-web"

        if ! ServiceControl is-active "$service_name"
        then
            Println "$error $service_name 未运行\n"
            return 1
        fi

        Println "$info 访问 Calibre Web: http://localhost:8083 , 用户名 admin 初始密码 admin123\n"

        if [ "$dist" == "mac" ] 
        then
            open "http://localhost:8083"
        fi
    }
    KccInstall()
    {
        if [[ -x "$KCC_FILE" ]] 
        then
            cd "$CALIBRE_ROOT/kcc"
            git pull
            Println "$info KCC 更新成功\n"
            return 0
        fi
        GitInstall
        PythonInstall
        git clone https://github.com/ciromattia/kcc.git "$KCC_ROOT"
        cd "$KCC_ROOT"
        python3 -m venv venv
        ./venv/bin/python3 -m pip install -r requirements.txt
        Println "$info KCC 安装成功\n"
    }

    KccView()
    {
        ServiceGet kcc

        if [ -z "${kcc_output:-}" ] 
        then
            Println "$error 请先设置 kcc\n"
            return 1
        fi

        local kcc_list="输出格式: $kcc_format\n"

        if [ "$kcc_process" = true ] 
        then
            kcc_list="${kcc_list}处理图片: 是\n"
        else
            kcc_list="${kcc_list}处理图片: 否\n"
        fi

        if [ -n "${kcc_sources:-}" ] 
        then
            kcc_source=$(JoinByString ', ' "${kcc_sources[@]}")
        fi

        kcc_list="${kcc_list}额外参数: ${kcc_args:-无}\n输出目录: $kcc_output\n源图片: ${kcc_source:-无}\n"

        Println "$kcc_list"
    }

    KccBrowse()
    {
        KccView

        kcc_view_options=( '输出目录' '源图片' )

        echo
        inquirer list_input_index "请选择" kcc_view_options kcc_view_options_index

        if [ "$kcc_view_options_index" -eq 0 ] 
        then
            ServiceBrowse "$kcc_output"
        elif [ "$kcc_view_options_index" -eq 1 ] 
        then
            if [ -z "${kcc_sources:-}" ] 
            then
                Println "$error 请先添加源图片目录\n"
                return 1
            fi
            echo
            inquirer list_input_index "请选择源图片目录" kcc_sources kcc_sources_index
            ServiceBrowse "${kcc_sources[kcc_sources_index]}"
        fi
    }

    KccConfig()
    {
        ServiceGet kcc

        kcc_format_options=( Auto MOBI EPUB CBZ KFX MOBI+EPUB )

        echo
        inquirer list_input "选择输出格式" kcc_format_options kcc_format

        echo
        inquirer list_input_index "是否处理图片" ny_options ny_index

        if [ "$ny_index" -eq 0 ] 
        then
            kcc_process=false
            kcc_args=""
        else
            kcc_process=true
            echo
            inquirer text_input "输入额外参数" kcc_args "$i18n_blank"
        fi

        echo
        ExitOnText "设置输出目录" kcc_output
        RemoveQuotes kcc_output

        kcc_sources=()

        while true 
        do
            echo
            inquirer text_input "输入源图片目录" kcc_source
            RemoveQuotes kcc_source
            if [ -z "$kcc_source" ] 
            then
                Println "$error 源图片目录不能为空"
            else
                kcc_sources+=("$kcc_source")
                echo
                inquirer list_input_index "继续添加源图片目录" ny_options ny_index
                if [ "$ny_index" -eq 0 ] 
                then
                    break
                fi
            fi
        done

        kcc_payload=$(
        $JQ_FILE -c -n --arg format "$kcc_format" --arg process "$kcc_process" \
        --arg args "$kcc_args" --arg output "$kcc_output" \
        --argjson source "$(ToJsonArray kcc_sources)" \
            '{
                format: $format,
                process: $process | test("true"),
                args: $args,
                output: $output,
                source: $source
            }'
        )

        jq_json=true
        jq_path='["kcc"]'
        JQ update "$SERVICES_CONFIG" "$kcc_payload"

        Println "$info kcc 设置成功\n"
    }

    KccConfigEdit()
    {
        KccView

        kcc_config_edit_options=( '输出格式' '是否处理图片' '额外参数' '输出目录' '添加源图片目录' '修改源图片目录' '删除源图片目录' )
        kcc_format_options=( Auto MOBI EPUB CBZ KFX MOBI+EPUB )

        echo
        inquirer checkbox_input_indices "请选择修改内容" kcc_config_edit_options kcc_config_edit_options_indices

        for kcc_config_edit_options_index in "${kcc_config_edit_options_indices[@]}"
        do
            case $kcc_config_edit_options_index in
                0) 
                    echo
                    inquirer list_input "选择输出格式" kcc_format_options new_kcc_format
                    if [ "$new_kcc_format" != "$kcc_format" ] 
                    then
                        jq_path='["kcc","format"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_format"
                        Println "$info 输出格式修改成功\n"
                    fi
                ;;
                1) 
                    echo
                    inquirer list_input_index "是否处理图片" ny_options ny_index
                    if [ "$ny_index" -eq 0 ] 
                    then
                        new_kcc_process=false
                    else
                        new_kcc_process=true
                    fi

                    if [ "$new_kcc_process" != "$kcc_process" ] 
                    then
                        jq_bool=true
                        jq_path='["kcc","process"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_process"
                        Println "$info 是否处理图片修改成功\n"
                    fi
                ;;
                2)
                    echo
                    inquirer text_input "输入额外参数" new_kcc_args "$i18n_blank"

                    if [ "$new_kcc_args" != "$kcc_args" ] 
                    then
                        jq_path='["kcc","args"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_args"
                        Println "$info 额外参数修改成功\n"
                    fi
                ;;
                3) 
                    echo
                    inquirer text_input "设置输出目录" new_kcc_output "$kcc_output"
                    RemoveQuotes new_kcc_output
                    if [ "$new_kcc_output" != "$kcc_output" ] 
                    then
                        jq_path='["kcc","output"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_output"
                        Println "$info 输出目录修改成功\n"
                    fi
                ;;
                4)
                    while true 
                    do
                        echo
                        inquirer text_input "输入源图片目录" new_kcc_source "$i18n_blank"
                        if [ -z "$new_kcc_source" ] 
                        then
                            break
                        fi
                        RemoveQuotes new_kcc_source
                        if [ -z "$new_kcc_source" ] 
                        then
                            Println "$error 源图片目录不能为空"
                        elif EleInArray "$new_kcc_source" kcc_sources
                        then
                            Println "$error 源图片目录已存在"
                        else
                            kcc_sources+=("$new_kcc_source")
                            echo
                            inquirer list_input_index "继续添加源图片目录" ny_options ny_index
                            if [ "$ny_index" -eq 0 ] 
                            then
                                break
                            fi
                        fi
                    done
                    jq_json=true
                    jq_path='["kcc","source"]'
                    JQ update "$SERVICES_CONFIG" "$(ToJsonArray kcc_sources)"
                    Println "$info 源图片目录添加成功\n"
                ;;
                5)
                    if [ -z "${kcc_sources:-}" ] 
                    then
                        Println "$error 请先添加源图片目录\n"
                        return 1
                    fi

                    echo
                    inquirer checkbox_input_indices "请选择源图片目录" kcc_sources kcc_sources_indices

                    kcc_source_update=false

                    for kcc_sources_index in "${kcc_sources_indices[@]}"
                    do
                        while true 
                        do
                            echo
                            inquirer text_input "修改源图片目录 ${kcc_sources[kcc_sources_index]}" new_kcc_source "$i18n_blank"
                            if [ -z "$new_kcc_source" ] 
                            then
                                continue 2
                            fi
                            RemoveQuotes new_kcc_source
                            if [ -z "$new_kcc_source" ] 
                            then
                                Println "$error 源图片目录不能为空"
                            elif EleInArray "$new_kcc_source" kcc_sources
                            then
                                Println "$error 源图片目录已存在"
                            else
                                kcc_sources[$kcc_sources_index]="$new_kcc_source"
                                kcc_source_update=true
                                break
                            fi
                        done
                    done

                    if [ "$kcc_source_update" = true ] 
                    then
                        jq_json=true
                        jq_path='["kcc","source"]'
                        JQ update "$SERVICES_CONFIG" "$(ToJsonArray kcc_sources)"
                        Println "$info 源图片目录修改成功\n"
                    fi
                ;;
                6)
                    if [ -z "${kcc_sources:-}" ] 
                    then
                        Println "$error 请先添加源图片目录\n"
                        return 1
                    fi

                    echo
                    inquirer checkbox_input_indices "请选择源图片目录" kcc_sources kcc_sources_indices

                    for kcc_sources_index in "${kcc_sources_indices[@]}"
                    do
                        unset kcc_sources[$kcc_sources_index]
                    done

                    jq_json=true
                    jq_path='["kcc","source"]'

                    if [ "${#kcc_sources[@]}" -eq 0 ]
                    then
                        JQ update "$SERVICES_CONFIG" "[]"
                    else
                        kcc_sources=("${kcc_sources[@]}")
                        JQ update "$SERVICES_CONFIG" "$(ToJsonArray kcc_sources)"
                    fi

                    Println "$info 源图片目录删除成功\n"
                ;;
            esac
        done

        return 0
    }

    KccConvert()
    {
        local source="$1"
        shift
        local files_indices=( "$@" ) files_index kcc_commands=() kcc_output_name
        shopt -s nullglob
        local files=("$source"/*)
        shopt -u nullglob

        local kcc_convert_formats=( Auto MOBI EPUB CBZ KFX MOBI+EPUB ) format

        if [ "${kcc_format:-Auto}" != "Auto" ] 
        then
            kcc_convert_formats=( "$kcc_format" )
            for format in Auto MOBI EPUB CBZ KFX MOBI+EPUB
            do
                if [ "$format" != "$kcc_format" ] 
                then
                    kcc_convert_formats+=( "$format" )
                fi
            done
        fi

        if [ "${kcc_format:-Auto}" != "KFX Output" ] 
        then
            kcc_convert_formats+=( 'KFX Output' )
        fi

        kcc_convert_outputs=( "$kcc_output" '当前目录' '输入新目录' )

        echo
        inquirer list_input_index "选择输出目录" kcc_convert_outputs kcc_convert_outputs_index

        case $kcc_convert_outputs_index in
            1) kcc_output="$source"
            ;;
            2) 
                echo
                inquirer text_input "输入转换输出的目录" kcc_output "$kcc_output"
                RemoveQuotes kcc_output
            ;;
        esac

        echo
        inquirer list_input "选择输出格式" kcc_convert_formats kcc_format

        if [ "$kcc_format" == "KFX Output" ] 
        then
            for files_index in "${files_indices[@]}"
            do
                if [ -d "${files[files_index]}" ] || [ "${files[files_index]##*.}" != "kpf" ]
                then
                    Println "$error 请只选择kpf文件\n"
                    return 1
                fi
            done

            CalibrePluginInstall 'KFX Output'

            for files_index in "${files_indices[@]}"
            do
                kcc_output_name="${files[files_index]##*/}"
                kcc_output_name="${kcc_output_name%.*}.kfx"
                "$CALIBRE_BIN_ROOT"/calibre-debug -r "KFX Output" -- "${files[files_index]}" "${kcc_output}/${kcc_output_name}"
                Println "$info ${files[files_index]##*/} 转换成功\n"
            done

            return 0
        fi

        for files_index in "${files_indices[@]}"
        do
            if [ ! -d "${files[files_index]}" ] 
            then
                Println "$error 请只选择图片目录\n"
                return 1
            fi
        done

        if [ "${kcc_process:-false}" = false ] 
        then
            kcc_commands+=( -n )
        elif [ -n "$kcc_args" ] 
        then
            kcc_commands+=($kcc_args)
        fi

        source "${KCC_ROOT}/venv/bin/activate"

        for files_index in "${files_indices[@]}"
        do
            python3 "$KCC_FILE" ${kcc_commands+"${kcc_commands[@]}"} -f "$kcc_format" -o "$kcc_output"/ "${files[files_index]}"
            Println "$info ${files[files_index]##*/} 转换成功\n"
        done

        return 0
    }

    KccMenu()
    {
        kcc_options=( '浏览' '转换' '设置' '修改设置' '更新/安装' )
        echo
        inquirer list_input_index "请选择" kcc_options kcc_options_index

        case $kcc_options_index in
            0) KccBrowse
            ;;
            1) 
                KccView

                if [ -z "${kcc_sources:-}" ] 
                then
                    Println "$error 请先添加源图片目录\n"
                    return 1
                fi

                if [[ ! -x "$KCC_FILE" ]] 
                then
                    Println "$error 请先安装 kcc\n"
                    return 1
                fi

                echo
                inquirer list_input_index "选择源图片目录" kcc_sources kcc_sources_index

                ServiceBrowse "${kcc_sources[$kcc_sources_index]}" "转换" KccConvert
            ;;
            2) KccConfig
            ;;
            3) KccConfigEdit
            ;;
            4) KccInstall
            ;;
        esac
    }
    CalibreInstall()
    {
        if [ "$dist" == "mac" ] 
        then
            brew install --cask calibre
        else
            DepInstall wget
            DepInstall xdg-utils
            if [ "$dist" == "rpm" ] 
            then
                DepInstall xz
                DepInstall libglvnd-opengl
                DepInstall libxcb-cursor-devel
                DepInstall nss
                DepInstall libxkbcommon
                DepInstall mesa-libEGL
            else
                DepInstall xz-utils
                DepInstall libopengl0
                DepInstall libxcb-cursor0
                DepInstall libnss3
                DepInstall libxkbcommon-x11-0
                DepInstall libglx0
                DepInstall libegl1
            fi
            ImageMagickInstall
            PythonInstall
            pip3 install pyqt6
            mkdir -p "$CALIBRE_ROOT"/bin
            sudo -v && wget -nv -O- https://download.calibre-ebook.com/linux-installer.sh | sudo sh /dev/stdin install_dir="$CALIBRE_ROOT"/bin version=7.16.0
        fi

        Println "$info calibre 安装/更新成功\n"
    }

    CalibrePluginInstall()
    {
        if { [ "$dist" == "mac" ] && [ ! -d /Applications/calibre.app ]; } || { [ "$dist" != "mac" ] && [ ! -d "$CALIBRE_ROOT"/bin ]; }
        then
            CalibreInstall
        fi

        if [ "$dist" == "mac" ] 
        then
            CALIBRE_BIN_ROOT="/Applications/calibre.app/Contents/MacOS"
        else
            CALIBRE_BIN_ROOT="$CALIBRE_ROOT"/bin/calibre
        fi

        local plugin_name="$1" plugin_grep=$("$CALIBRE_BIN_ROOT"/calibre-customize -l)
        if ! grep -q "$plugin_name" <<< "$plugin_grep"
        then
            DepInstall curl
            mkdir -p "$CALIBRE_ROOT"/plugins
            if ! curl -L -o "${CALIBRE_ROOT}/plugins/${plugin_name}.zip" "$FFMPEG_MIRROR_LINK/calibre/plugins/${plugin_name}.zip"
            then
                Println "$error $plugin_name 插件不存在\n"
                return 1
            fi
            "$CALIBRE_BIN_ROOT"/calibre-customize -a "${CALIBRE_ROOT}/plugins/${plugin_name}.zip"
            Println "$info $plugin_name 插件安装成功\n"
        fi
    }

    calibre_options=( 'kcc' '安装/更新 calibre' '开启 Calibre Web' '关闭 Calibre Web' '重启 Calibre Web' '查看 Calibre Web' '安装/更新 Calibre Web' 'Patch Calibre Web' )
    echo
    inquirer list_input_index "请选择" calibre_options calibre_options_index

    case $calibre_options_index in
        0) KccMenu
        ;;
        1) CalibreInstall
        ;;
        2) CalibreWebStart
        ;;
        3) CalibreWebStop
        ;;
        4) CalibreWebRestart
        ;;
        5) CalibreWebView
        ;;
        6) CalibreWebInstall
        ;;
        7) CalibreWebPatch
        ;;
    esac
elif [ "$self" == "dr" ]
then
    DockerInstall()
    {
        local install="更新"

        if [ -z "${1:-}" ]
        then
            if [[ -x $(command -v docker) ]]
            then
                return 0
            fi
            install="安装"
        elif [[ ! -x $(command -v docker) ]]
        then
            install="安装"
        fi

        if [ "$dist" == "mac" ]
        then
            brew install --cask docker
            Println "$info docker ${install}成功, 打开 docker app 完成最后设置!\n"
            return 0
        fi

        DepInstall curl
        DepInstall ca-certificates
        DepInstall gpg

        case $dist in
            ubu|deb)
                local docker_dist="ubuntu" docker_codename docker_repo_base docker_key_url
                if [ "$dist" == "deb" ]
                then
                    docker_dist="debian"
                fi

                docker_codename=$(AptGetCodename)

                if grep -q "docker-ce" < /etc/apt/sources.list
                then
                    sed -i '/docker-ce/d' /etc/apt/sources.list
                fi

                if [ ! -f "/etc/apt/sources.list.d/docker.list" ]
                then
                    docker_repo_base="${DOCKER_REPO_LINK}/${docker_dist}"
                    if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                    then
                        docker_key_url="http://${USTC_MIRROR_HOST}/docker-ce/linux/${docker_dist}/gpg"
                    else
                        docker_key_url="${DOCKER_REPO_LINK}/${docker_dist}/gpg"
                    fi

                    if ! AptRepoCheck "$docker_repo_base" "$docker_codename"
                    then
                        Println "$error Docker 官方源暂不支持当前系统 (${docker_codename:-unknown}), 未写入失效源\n"
                        return 1
                    fi

                    curl -fsSL "$docker_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] ${docker_repo_base} \
                ${docker_codename} stable" | tee /etc/apt/sources.list.d/docker.list
                    AptUpdate force
                fi

                for pkg in docker.io docker-doc docker-compose podman-docker containerd runc
                do
                    sudo apt-get -y remove $pkg || true
                done

                AptInstall docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
            ;;
            rpm)
                echo
                sudo yum install -y yum-utils
                sudo yum-config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo
                sudo yum remove docker \
                    docker-client \
                    docker-client-latest \
                    docker-common \
                    docker-latest \
                    docker-latest-logrotate \
                    docker-logrotate \
                    docker-engine || true
                sudo yum -y install docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
            ;;
            *)
                Println "$error 不支持的系统\n"
                return 1
            ;;
        esac

        if [ ! -f /etc/systemd/system/docker.service.d/clear_mount_propagation_flags.conf ]
        then
cat > /etc/systemd/system/docker.service.d/clear_mount_propagation_flags.conf <<EOF
[Service]
MountFlags=shared
EOF
            systemctl daemon-reload
            systemctl restart docker
        fi

        Println "$info docker 安装成功\n"
    }
    DockerCrtSelfSignValid()
    {
        local domain=$1

        if [ -e "$service_cert_root/$domain".crt ] && [ -e "$service_cert_root/$domain".key ]
        then
            return 1
        fi
    }

    DockerCrtManage()
    {
        if [ ! -d "$DOCKER_ROOT" ] 
        then
            if [ ! -d "$DEPENDS_ROOT"/aios ] 
            then
                mkdir -p "$DEPENDS_ROOT"
                GitInstall
                git clone "$AIOS_LINK" "$DEPENDS_ROOT"/aios
            else
                cd "$DEPENDS_ROOT"/aios
                git fetch --all && git reset --hard origin/main
            fi
            cp -r "$DEPENDS_ROOT"/aios/scripts/docker "$DOCKER_ROOT"
        fi

        echo
        crt_options=( '浏览证书' '安装自签名证书' )
        inquirer list_input_index "选择操作" crt_options crt_options_index

        case $crt_options_index in
            0) ServiceBrowse "$DOCKER_ROOT"/certs
            ;;
            1) 
                cd "$DOCKER_ROOT"/certs

                if [ ! -f "$DOCKER_ROOT"/certs/root.crt ] 
                then
                    echo
                    inquirer text_input "请输入你想设置的根证书公用名CN (Common Name)" root_cn root.yourdomain.com
                    openssl req -new -nodes -text -out root.csr -newkey rsa:4096 -keyout root.key -subj "/CN=$root_cn"
                    chmod og-rwx root.key
                    openssl x509 -req -in root.csr -text -days 3650 -extfile "$DOCKER_ROOT"/certs/openssl.cnf -extensions v3_ca -signkey root.key -out root.crt
                    Println "$info "$DOCKER_ROOT"/certs/root.crt 可以添加到用户端系统用来验证之后自签名的证书\n"
                fi

                docker_certs_services=( 'traefik' )
                echo
                inquirer list_input "选择安装证书的服务" docker_certs_services docker_certs_service

                service_cert_root="$DOCKER_ROOT/certs/$docker_certs_service"

                mkdir -p newcerts
                mkdir -p "$docker_certs_service"

                echo
                inquirer text_input "请输入自签名证书公用名CN (Common Name)" server_cn localhost DockerCrtSelfSignValid "证书已存在"

                ny_index=0

                if ! [[ "$server_cn" =~ \* ]] 
                then
                    echo
                    inquirer list_input_index "是否将子域名 *.$server_cn 加到 SAN" ny_options ny_index
                fi

                if [ "$ny_index" -eq 1 ] 
                then
                    root_domain="${server_cn#\*.}"
                    san="DNS:$root_domain,DNS:*.$root_domain,IP:127.0.0.1,IP:::1"
                else
                    san="DNS:$server_cn,IP:127.0.0.1,IP:::1"
                fi

                openssl req -new -nodes -text -out "$service_cert_root/${server_cn}".csr -newkey rsa:4096 -keyout "$service_cert_root/${server_cn}".key -subj "/CN=$server_cn" -addext "subjectAltName=$san"

                chmod og-rwx "$service_cert_root/${server_cn}".key

                if openssl help x509 2>&1 | grep -q "copy_extensions"
                then
                    openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$service_cert_root/${server_cn}".csr -text -days 365 -CA root.crt -CAkey root.key -CAcreateserial -out "$service_cert_root/${server_cn}".crt)
                else
                    openssl_cmds=(openssl ca -batch -config "$DOCKER_ROOT"/certs/openssl.cnf -policy signing_policy -extensions signing_req -out "$service_cert_root/${server_cn}".crt -infiles "$service_cert_root/${server_cn}".csr)
                fi

                if [ ! -f ./index.txt ] 
                then
                    touch index.txt
                fi

                if [ ! -f ./serial ] 
                then
                    echo 01 > serial
                fi

                "${openssl_cmds[@]}"

                openssl x509 -in "$service_cert_root/${server_cn}".crt -outform PEM -out "$service_cert_root/${server_cn}".pem

                if [ "$ny_index" -eq 1 ] 
                then
                    openssl req -new -nodes -text -out "$service_cert_root/*.${server_cn}".csr -newkey rsa:4096 -keyout "$service_cert_root/*.${server_cn}".key -subj "/CN=*.$server_cn" -addext "subjectAltName=$san"
                    chmod og-rwx "$service_cert_root/*.${server_cn}".key
                    if openssl help x509 2>&1 | grep -q "copy_extensions"
                    then
                        openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$service_cert_root/*.${server_cn}".csr -text -days 365 -CA ../root.crt -CAkey ../root.key -CAcreateserial -out "$service_cert_root/*.${server_cn}".crt)
                    else
                        openssl_cmds=(openssl ca -batch -config "$DOCKER_ROOT"/certs/openssl.cnf -policy signing_policy -extensions signing_req -out "$service_cert_root/*.${server_cn}".crt -infiles "$service_cert_root/*.${server_cn}".csr)
                    fi
                    "${openssl_cmds[@]}"
                    openssl x509 -in "$service_cert_root/*.${server_cn}".crt -outform PEM -out "$service_cert_root/*.${server_cn}".pem
                    cat "$service_cert_root/${server_cn}".pem "$service_cert_root/*.${server_cn}".pem > "$service_cert_root/${server_cn}".pem.tmp
                    mv "$service_cert_root/${server_cn}".pem.tmp "$service_cert_root/${server_cn}".pem
                fi

                Println "$info 自签名证书安装成功\n"
            ;;
        esac

        return 0
    }
    DockerServiceStart()
    {
        DockerInstall
        PostgresqlInstall
        YqInstall

        . "$DOCKER_ROOT"/.env

        if [ ! -f "$DOCKER_ROOT/certs/traefik/$TRAEFIK_DOMAIN".crt ] || [ ! -f "$DOCKER_ROOT/certs/traefik/$TRAEFIK_DOMAIN".key ]
        then
            Println "$error $TRAEFIK_DOMAIN 的证书不存在\n"
            return 1
        fi

        if [ ! -f "$DOCKER_ROOT"/certs/traefik/hub.docker.com.crt ] || [ ! -f "$DOCKER_ROOT"/certs/traefik/hub.docker.com.key ]
        then
            Println "$error hub.docker.com 的证书不存在\n"
            return 1
        fi

        traefik_local_plugins=($(yq '.experimental.localPlugins | map_values(.modulename) | to_entries | .[] | .value' "$DOCKER_ROOT"/data/traefik/config/traefik.yml))

        for traefik_local_plugin in "${traefik_local_plugins[@]}"
        do
            if [ ! -d "$DOCKER_ROOT/data/traefik/plugins-local/src/$traefik_local_plugin" ]
            then
                Println "$error traefik 本地插件 $traefik_local_plugin 不存在, 请先设置\n"
                return 1
            fi
        done

        JWT_SECRET=$(< "$DOCKER_ROOT"/data/authelia/secrets/JWT_SECRET)
        SESSION_REDIS_PASSWORD=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_REDIS_PASSWORD)
        SESSION_SECRET=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_SECRET)
        STORAGE_ENCRYPTION_KEY=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_ENCRYPTION_KEY)
        STORAGE_POSTGRES_PASSWORD=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)

        for var in JWT_SECRET SESSION_REDIS_PASSWORD SESSION_SECRET STORAGE_ENCRYPTION_KEY STORAGE_POSTGRES_PASSWORD
        do
            if [[ -z "${!var:-}" ]]
            then
                Println "$error $var 为空, 请先设置服务 secrets\n"
                return 1
            fi
        done

        if ! psql -c "\du" | grep -q authelia || ! psql -c "SELECT datname FROM pg_catalog.pg_database;" | grep -q authelia
        then
            Println "$error 请先设置服务 postgresql\n"
            return 1
        fi

        cd "$DOCKER_ROOT"

        mkdir -p "$DOCKER_ROOT/data/redis"
        mkdir -p "$DOCKER_ROOT/data/traefik/logs"
        mkdir -p "$DOCKER_ROOT/data/authelia/logs"

        docker compose up
    }

    DockerServiceStartClean()
    {
        cd "$DOCKER_ROOT"

        docker compose up
    }

    DockerServiceStop()
    {
        DockerInstall

        cd "$DOCKER_ROOT"

        docker compose stop
    }

    DockerServiceConfig()
    {
        echo
        docker_config_options=( 'Traefik' 'Authelia' 'Postgresql' )
        inquirer checkbox_input_indices "请选择" docker_config_options docker_config_options_indices

        for docker_config_options_index in "${docker_config_options_indices[@]}"
        do
            echo
            case $docker_config_options_index in
                0)
                    traefik_options=( '域名' '本地插件' )
                    inquirer checkbox_input_indices "选择 traefik 设置选项" traefik_options traefik_options_indices

                    for traefik_options_index in "${traefik_options_indices[@]}"
                    do
                        if [ $traefik_options_index -eq 0 ]
                        then
                            . "$DOCKER_ROOT"/.env
                            echo
                            inquirer text_input "请输入 traefik 使用的域名" traefik_domain "$TRAEFIK_DOMAIN"
                            if [ "$traefik_domain" != "$TRAEFIK_DOMAIN" ]
                            then
                                sed -i "/TRAEFIK_DOMAIN=/c\TRAEFIK_DOMAIN=$traefik_domain" "$DOCKER_ROOT"/.env
                                Println "$info traefik 域名已设置为 $traefik_domain\n"
                            fi
                        else
                            traefik_local_plugins=( cors-preflight )
                            traefik_plugins=( github.com/Medzoner/traefik-plugin-cors-preflight )
                            echo
                            inquirer checkbox_input_indices "选择 traefik 本地插件" traefik_local_plugins traefik_local_plugins_indices
                            for traefik_local_plugins_index in "${traefik_local_plugins_indices[@]}"
                            do
                                if [ -d "$DOCKER_ROOT/data/traefik/plugins-local/src/${traefik_plugins[$traefik_local_plugins_index]}" ]
                                then
                                    cd "$DOCKER_ROOT/data/traefik/plugins-local/src/${traefik_plugins[$traefik_local_plugins_index]}"
                                    git pull
                                    Println "$info ${traefik_local_plugins[$traefik_local_plugins_index]} 插件已更新\n"
                                    continue
                                fi
                                git clone "https://${traefik_plugins[$traefik_local_plugins_index]}" "$DOCKER_ROOT/data/traefik/plugins-local/src/${traefik_plugins[$traefik_local_plugins_index]}"
                                Println "$info ${traefik_local_plugins[$traefik_local_plugins_index]} 插件已安装\n"
                            done
                        fi
                    done
                ;;
                1)
                    authelia_options=( '域名' '用户名' '显示名' '密码' secrets )
                    inquirer checkbox_input_indices "选择 authelia 设置选项" authelia_options authelia_options_indices
                    for authelia_options_index in "${authelia_options_indices[@]}"
                    do
                        case $authelia_options_index in
                            0)
                                . "$DOCKER_ROOT"/.env
                                echo
                                inquirer text_input "请输入 authelia 使用的域名" authelia_domain "$AUTHELIA_DOMAIN"
                                if [ "$authelia_domain" != "$AUTHELIA_DOMAIN" ]
                                then
                                    sed -i "/AUTHELIA_DOMAIN=/c\AUTHELIA_DOMAIN=$traefik_domain" "$DOCKER_ROOT"/.env
                                    echo
                                    inquirer list_input_index "是否添加到 /etc/hosts" ny_options ny_index
                                    if [ $ny_index -eq 1 ]
                                    then
                                        Println "$tip 可能需要输入密码"
                                        echo "\
    127.0.0.1  hub.docker.com
    127.0.0.1  authelia.$DOMAIN
    127.0.0.1  public.$DOMAIN
    127.0.0.1  traefik.$DOMAIN
    127.0.0.1  secure.$DOMAIN" | sudo tee -a /etc/hosts > /dev/null
                                    fi
                                    Println "$info authelia 域名已设置为 $authelia_domain\n"
                                fi
                            ;;
                            1)
                                authelia_usernames=($(yq '.users | keys | join(" ")' "$DOCKER_ROOT"/data/authelia/config/users_database.yml))
                                authelia_default_username="${authelia_usernames[0]}"
                                echo
                                inquirer text_input "请输入 authelia 用户名" authelia_username "$authelia_default_username"
                                if [ "$authelia_username" != "$authelia_default_username" ]
                                then
                                    yq_path_new=".users.$authelia_username"
                                    yq_path_old=".users.$authelia_default_username"
                                    YQ update_key "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    authelia_user_email=$(yq ".users.$authelia_username.email" "$DOCKER_ROOT"/data/authelia/config/users_database.yml)
                                    if [[ "$authelia_user_email" =~ '<USERNAME>' ]]
                                    then
                                        yq_path='["users","'$authelia_username'","email"]'
                                        yq_replace="${authelia_username}@${authelia_user_email#*@}"
                                        YQ update "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    fi
                                    Println "$info authelia 用户名已改为 $authelia_username\n"
                                fi
                            ;;
                            2)
                                authelia_usernames=($(yq '.users | keys | join(" ")' "$DOCKER_ROOT"/data/authelia/config/users_database.yml))
                                authelia_default_username="${authelia_usernames[0]}"
                                authelia_default_displayname=$(yq ".users.$authelia_default_username.displayname" "$DOCKER_ROOT"/data/authelia/config/users_database.yml)
                                echo
                                inquirer text_input "请输入 authelia 用户 $authelia_default_username 的显示名" authelia_displayname "$authelia_default_displayname"
                                if [ "$authelia_displayname" != "$authelia_default_displayname" ]
                                then
                                    yq_path='["users","'$authelia_default_username'","displayname"]'
                                    yq_replace="$authelia_displayname"
                                    YQ update "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    Println "$info authelia 用户 $authelia_default_username 的显示名已改为 $authelia_displayname\n"
                                fi
                            ;;
                            3)
                                authelia_usernames=($(yq '.users | keys | join(" ")' "$DOCKER_ROOT"/data/authelia/config/users_database.yml))
                                authelia_default_username="${authelia_usernames[0]}"
                                authelia_default_password=$(yq ".users.$authelia_default_username.password" "$DOCKER_ROOT"/data/authelia/config/users_database.yml)
                                DockerInstall
                                if ! docker images | grep -q authelia/authelia
                                then
                                    Println "$info 下载 authelia 镜像..."
                                    docker pull authelia/authelia
                                fi
                                echo
                                inquirer text_input "请输入 authelia 用户 $authelia_default_username 的密码" authelia_password "$authelia_default_password"
                                authelia_password=$(docker run authelia/authelia authelia crypto hash generate argon2 --password $authelia_password | sed 's/Digest: //g')
                                if [ "$authelia_password" != "$authelia_default_password" ]
                                then
                                    yq_path='["users","'$authelia_default_username'","password"]'
                                    yq_replace="$authelia_password"
                                    YQ update "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    Println "$info authelia 用户 $authelia_default_username 的密码已改为 $authelia_password\n"
                                fi
                            ;;
                            4)
                                authelia_secrets=( JWT_SECRET SESSION_REDIS_PASSWORD SESSION_SECRET STORAGE_ENCRYPTION_KEY STORAGE_POSTGRES_PASSWORD )
                                echo
                                inquirer checkbox_input_indices "选择设置的 secret" authelia_secrets authelia_secrets_indices

                                for authelia_secret_index in "${authelia_secrets_indices[@]}"
                                do
                                    echo
                                    case $authelia_secret_index in
                                        0)
                                            default_jwt_secret=$(< "$DOCKER_ROOT"/data/authelia/secrets/JWT_SECRET)
                                            inquirer text_input "请输入 JWT_SECRET" JWT_SECRET "${default_jwt_secret:-$(openssl rand -hex 32)}"
                                        ;;
                                        1)
                                            default_session_redis_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_REDIS_PASSWORD)
                                            inquirer text_input "请输入 SESSION_REDIS_PASSWORD" SESSION_REDIS_PASSWORD "${default_session_redis_password:-$(openssl rand -hex 64)}"
                                        ;;
                                        2)
                                            default_session_secret=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_SECRET)
                                            inquirer text_input "请输入 SESSION_SECRET" SESSION_SECRET "${default_session_secret:-$(openssl rand -hex 64)}"
                                        ;;
                                        3)
                                            default_storage_encryption_key=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_ENCRYPTION_KEY)
                                            inquirer text_input "请输入 STORAGE_ENCRYPTION_KEY" STORAGE_ENCRYPTION_KEY "${default_storage_encryption_key:-$(openssl rand -hex 32)}"
                                        ;;
                                        4)
                                            default_storage_postgres_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)
                                            inquirer text_input "请输入 STORAGE_POSTGRES_PASSWORD" STORAGE_POSTGRES_PASSWORD "${default_storage_postgres_password:-$(RandStr 15)}"
                                        ;;
                                    esac
                                    echo -n "${!authelia_secrets[authelia_secret_index]}" > "$DOCKER_ROOT"/data/authelia/secrets/${authelia_secrets[authelia_secret_index]}
                                    Println "$info ${authelia_secrets[authelia_secret_index]} 设置成功\n"
                                done
                            ;;
                        esac
                    done
                ;;
                2)
                    postgresql_options=( '添加 role authelia' '添加 database authelia' '设置 role authelia 的密码' )
                    echo
                    inquirer checkbox_input_indices "选择 postgresql 设置选项" postgresql_options postgresql_options_indices
                    for postgresql_options_index in "${postgresql_options_indices[@]}"
                    do
                        case $postgresql_options_index in
                            0)
                                if psql -c "\du" | grep -q authelia
                                then
                                    Println "$error role authelia 已存在\n"
                                    continue
                                fi
                                default_storage_postgres_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)
                                echo
                                inquirer text_input "请输入 role authelia 的密码" storage_postgres_password "${default_storage_postgres_password:-$(RandStr 15)}"
                                psql -c "CREATE ROLE authelia PASSWORD '$storage_postgres_password' CREATEDB REPLICATION LOGIN;"
                                Println "$info role authelia 已添加\n"
                            ;;
                            1)
                                if ! psql -c "\du" | grep -q authelia
                                then
                                    Println "$error 请先添加 role authelia\n"
                                    continue
                                fi
                                if psql -c "SELECT datname FROM pg_catalog.pg_database;" | grep -q authelia
                                then
                                    Println "$error database authelia 已存在\n"
                                    continue
                                fi
                                psql -c "CREATE DATABASE authelia OWNER authelia;"
                                Println "$info database authelia 已添加\n"
                            ;;
                            2)
                                if ! psql -c "\du" | grep -q authelia
                                then
                                    Println "$error 请先添加 role authelia\n"
                                    continue
                                fi
                                default_storage_postgres_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)
                                echo
                                inquirer text_input "请输入 role authelia 的密码" storage_postgres_password "${default_storage_postgres_password:-$(RandStr 15)}"
                                psql -c "ALTER ROLE authelia PASSWORD '$storage_postgres_password';"
                                Println "$info role authelia 的密码已设置\n"
                            ;;
                        esac
                    done
                ;;
            esac
        done

        return 0
    }

    DockerService()
    {
        if [ ! -d "$DOCKER_ROOT" ]
        then
            if [ ! -d "$DEPENDS_ROOT"/aios ]
            then
                mkdir -p "$DEPENDS_ROOT"
                GitInstall
                git clone "$AIOS_LINK" "$DEPENDS_ROOT"/aios
            else
                cd "$DEPENDS_ROOT"/aios
                git fetch --all && git reset --hard origin/main
            fi
            cp -r "$DEPENDS_ROOT"/aios/scripts/docker "$DOCKER_ROOT"
        fi

        if [ "$dist" == "mac" ] && [[ ! -x $(command -v psql) ]] && [[ -x /Applications/Postgres.app/Contents/Versions/latest/bin/psql ]]
        then
            export PATH="${PATH}:/Applications/Postgres.app/Contents/Versions/latest/bin"
        fi

        docker_service_options=( '启动' '启动(原版)' '关闭' '重启' '重启(原版)' '设置' )
        echo
        inquirer list_input_index "请选择" docker_service_options docker_service_options_index

        case $docker_service_options_index in
            0) DockerServiceStart
            ;;
            1) DockerServiceStartClean
            ;;
            2) DockerServiceStop
            ;;
            3)
                DockerServiceStop
                DockerServiceStart
            ;;
            4)
                DockerServiceStop
                DockerServiceStartClean
            ;;
            5)
                YqInstall
                DockerServiceConfig
            ;;
        esac

        return 0
    }
    PostgresqlInstall()
    {
        local install="更新"

        if [ -z "${1:-}" ]
        then
            if [[ -x $(command -v psql) ]]
            then
                return 0
            fi
            install="安装"
        elif [[ ! -x $(command -v psql) ]]
        then
            install="安装"
        fi

        if [ "$dist" == "mac" ]
        then
            if [[ -x /Applications/Postgres.app/Contents/Versions/latest/bin/psql ]]
            then
                return 0
            fi

            brew install --cask postgres-unofficial
            open /Applications/Postgres.app
            if [ ! -f /etc/paths.d/postgresapp ]
            then
                Println "$info 输入密码配置命令行: "
                sudo mkdir -p /etc/paths.d && echo /Applications/Postgres.app/Contents/Versions/latest/bin | sudo tee /etc/paths.d/postgresapp
            fi
            Println "$info postgresql ${install}成功\n"
            return 0
        fi

        DepInstall curl
        DepInstall ca-certificates

        . /etc/os-release

        case $dist in
            ubu|deb)
                local pg_codename
                pg_codename=$(AptGetCodename)

                if [ ! -f /etc/apt/sources.list.d/pgdg.list ]
                then
                    local pg_repo_base="$PGDG_APT_LINK"
                    local pg_key_url="https://www.postgresql.org/media/keys/ACCC4CF8.asc"

                    if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                    then
                        pg_repo_base="https://${USTC_MIRROR_HOST}/postgresql/repos/apt"
                        pg_key_url="https://${USTC_MIRROR_HOST}/postgresql/repos/apt/ACCC4CF8.asc"
                    fi

                    if ! AptRepoCheck "$pg_repo_base" "${pg_codename}-pgdg"
                    then
                        if AptRepoCheck "$PGDG_ARCHIVE_APT_LINK" "${pg_codename}-pgdg"
                        then
                            pg_repo_base="$PGDG_ARCHIVE_APT_LINK"
                        else
                            Println "$tip PostgreSQL 官方源暂不支持当前系统 (${pg_codename:-unknown}), 改用系统默认源安装"
                            AptInstall postgresql
                            return $?
                        fi
                    fi

                    DepInstall gpg
                    curl -fsSL "$pg_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/postgresql-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/postgresql-archive-keyring.gpg] ${pg_repo_base} ${pg_codename}-pgdg main" | tee /etc/apt/sources.list.d/pgdg.list > /dev/null
                    AptUpdate force
                fi

                AptInstall postgresql
            ;;
            rpm)
                ArchCheck

                local repo_name=""
                if [ "$arch" == "arm64" ]
                then
                    repo_name="-aarch64"
                else
                    repo_name="-x86_64"
                fi
                if [ "${ID:-}" == "fedora" ]
                then
                    repo_name="F-${VERSION_ID%%.*}${repo_name}/pgdg-fedora-repo-latest.noarch.rpm"
                else
                    repo_name="EL-${VERSION_ID%%.*}${repo_name}/pgdg-redhat-repo-latest.noarch.rpm"
                fi
                if [[ -x $(command -v dnf) ]]
                then
                    sudo dnf install -y https://download.postgresql.org/pub/repos/yum/reporpms/${repo_name}
                    sudo dnf -qy module disable postgresql || true
                    sudo dnf install -y "postgresql${POSTGRESQL_VER}-server"
                    sudo "/usr/pgsql-${POSTGRESQL_VER}/bin/postgresql-${POSTGRESQL_VER}-setup" initdb
                    sudo systemctl enable "postgresql-${POSTGRESQL_VER}"
                    sudo systemctl start "postgresql-${POSTGRESQL_VER}"
                else
                    sudo yum install -y https://download.postgresql.org/pub/repos/yum/reporpms/${repo_name}/pgdg-redhat-repo-latest.noarch.rpm
                    sudo yum install -y "postgresql${POSTGRESQL_VER}-server"
                    if [ "${VERSION_ID%%.*}" -eq 7 ]
                    then
                        sudo "/usr/pgsql-${POSTGRESQL_VER}/bin/postgresql-${POSTGRESQL_VER}-setup" initdb
                        sudo systemctl enable "postgresql-${POSTGRESQL_VER}"
                        sudo systemctl start "postgresql-${POSTGRESQL_VER}"
                    else
                        sudo service "postgresql-${POSTGRESQL_VER}" initdb
                        sudo chkconfig "postgresql-${POSTGRESQL_VER}" on
                        sudo service "postgresql-${POSTGRESQL_VER}" start
                    fi
                fi
            ;;
            opensuse)
                zypper install -l -y "postgresql${POSTGRESQL_VER}-server"
                systemctl enable postgresql.service
                systemctl start postgresql.service
            ;;
            sles)
                if [ "${VERSION_ID%%.*}" -eq 12 ]
                then
                    SUSEConnect -p PackageHub/12/x86_64
                    SUSEConnect -p sle-sdk/12/x86_64
                    zypper addrepo "https://download.postgresql.org/pub/repos/zypp/repo/pgdg-sles-12-pg${POSTGRESQL_SLES12_VER}.repo"
                    zypper refresh
                    zypper install "postgresql${POSTGRESQL_SLES12_VER}-server"
                else
                    zypper addrepo https://download.opensuse.org/repositories/devel:/libraries:/c_c++/${VERSION_ID}/devel:libraries:c_c++.repo
                    zypper addrepo https://download.opensuse.org/repositories/science/${VERSION_ID}/science.repo
                    zypper addrepo https://download.opensuse.org/repositories/Application:/Geo/${VERSION_ID}/Application:Geo.repo
                    SUSEConnect -p sle-module-desktop-applications/${VERSION_ID}/x86_64
                    SUSEConnect -p PackageHub/${VERSION_ID}/x86_64
                    zypper --gpg-auto-import-keys install -y zypper install https://download.postgresql.org/pub/repos/zypp/reporpms/SLES-15-x86_64/pgdg-suse-repo-latest.noarch.rpm
                    zypper refresh
                    zypper install "postgresql${POSTGRESQL_VER}-server"
                fi

                systemctl enable postgresql.service
                systemctl start postgresql.service
            ;;
            *)
                Println "$error 不支持的系统\n"
                return 1
            ;;
        esac

        if ! su postgres -c 'psql -c "\du"' | grep -q "$USER"
        then
            su postgres -c "createuser --superuser $USER"
            createdb "$USER"
        fi

        Println "$info postgresql 安装成功\n"
    }
    YqInstall()
    {
        local install="更新"

        if [ -z "${1:-}" ] 
        then
            if [[ -x $(command -v yq) ]] 
            then
                return 0
            fi
            install="安装"
        elif [[ ! -x $(command -v yq) ]] 
        then
            install="安装"
        fi

        DepsCheck
        ArchCheck

        if [ "$dist" == "mac" ] 
        then
            echo
            inquirer list_input_index "是否编译(brew安装可能会很慢)" ny_options ny_index
            if [ "$ny_index" -eq 1 ] 
            then
                brew install yq
                Println "$info yq ${install}成功\n"
                return 0
            fi
            if [ "$arch" == "x86_64" ] 
            then
                yq_name=yq_darwin_amd64
            else
                yq_name=yq_darwin_arm64
            fi
        else
            case $arch in
                i386) yq_name=yq_linux_386
                ;;
                x86_64) yq_name=yq_linux_amd64
                ;;
                arm64|s390x) yq_name=yq_linux_$arch
                ;;
                arm*) yq_name=yq_linux_arm
                ;;
                *) Println "不支持的架构: $arch"; return 1
                ;;
            esac
        fi

        if curl -L "$FFMPEG_MIRROR_LINK/yq/$yq_name" -o "$YQ_FILE"_tmp
        then
            mv "$YQ_FILE"_tmp "$YQ_FILE"
            chmod +x "$YQ_FILE"
        else
            rm -f "$YQ_FILE"_tmp
            Println "`eval_gettext \"\\\$error 下载 yq 失败, 请重试 !\"`"
            return 1
        fi

        Println "$info yq ${install}成功\n"
    }

    YQ()
    {
        case $1 in
            update)
                local pattern replace
                pattern="${yq_path}" replace="${yq_replace}" yq -i 'setpath(env(pattern); env(replace))' "$2"
            ;;
            update_key)
                local pattern_new pattern_old
                pattern_new="${yq_path_new}" pattern_old="${yq_path_old}" yq -i 'eval(strenv(pattern_new)) = eval(strenv(pattern_old)) | del(eval(strenv(pattern_old)))' "$2"
            ;;
        esac

        return 0
    }

    DepInstall sudo

    docker_options=( '服务' '管理证书' '安装/更新 docker' '安装/更新 postgresql' '安装/更新 yq' )
    echo
    inquirer list_input_index "请选择" docker_options docker_options_index

    case $docker_options_index in
        0) DockerService
        ;;
        1) DockerCrtManage
        ;;
        2) DockerInstall update
        ;;
        3) PostgresqlInstall update
        ;;
        4) YqInstall update
        ;;
    esac
elif [ "$self" == "ha" ]
then
    HAProxyInstall()
    {
        local install="更新"

        if [ -z "${1:-}" ] 
        then
            if [[ -x $(command -v haproxy) ]] 
            then
                Println "$error haproxy 已安装 !\n"
                return 0
            fi
            install="安装"
        elif [[ ! -x $(command -v haproxy) ]] 
        then
            install="安装"
        fi

        DepsCheck

        args=()
        ldflags=()

        if [ "$dist" == "mac" ] 
        then
            if [ -d "$DEPENDS_ROOT"/haproxy ] 
            then
                Println "$info 已经存在 $DEPENDS_ROOT/haproxy !\n"
                return 1
            fi

            if [ ! -f /etc/paths.d/haproxy ] 
            then
                sudo mkdir -p /etc/paths.d
                echo "$DEPENDS_ROOT"/haproxy/bin | sudo tee /etc/paths.d/haproxy
            fi
        else
            echo
            inquirer list_input_index "开启 USE_GETADDRINFO" yn_options yn_index

            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_GETADDRINFO=1 )
            fi
        fi

        echo
        pcre_options=( pcre pcre2 )
        inquirer list_input_index "选择 pcre 版本" pcre_options pcre_options_index

        if [ "$pcre_options_index" -eq 0 ] 
        then
            pcre_args=( USE_STATIC_PCRE USE_PCRE )
            echo
            inquirer list_input_index "开启 USE_PCRE_JIT" yn_options yn_index
            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_PCRE_JIT=1 )
            fi
        else
            pcre_args=( USE_STATIC_PCRE2 USE_PCRE2 )
            echo
            inquirer list_input_index "开启 USE_PCRE2_JIT" yn_options yn_index
            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_PCRE2_JIT=1 )
            fi
        fi

        echo
        inquirer list_input_index "选择 ${pcre_options[pcre_options_index]} 编译选项" pcre_args pcre_args_index
        args+=( "${pcre_args[pcre_args_index]}=1" )

        if [ "$pcre_args_index" -eq 0 ] 
        then
            static_pcre=true
        else
            static_pcre=false
        fi

        Println "$tip 如果选择 openssl, haproxy 将不支持 QUIC 0-RTT"
        openssl_options=( openssl@1.1 openssl@3 quictls )
        inquirer list_input_index "选择 openssl 版本" openssl_options openssl_options_index

        args+=( USE_OPENSSL=1 )

        if [ "$openssl_options_index" -eq 2 ] 
        then
            args+=( USE_QUIC=1 )
        fi

        echo
        inquirer list_input_index "开启硬件加密加速 USE_ENGINE" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            args+=( USE_ENGINE=1 )
        fi

        if [ "$openssl_options_index" -eq 1 ] 
        then
            echo
            inquirer list_input_index "开启 USE_PTHREAD_EMULATION" yn_options yn_index

            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_PTHREAD_EMULATION=1 )
            fi
        fi

        echo
        inquirer list_input_index "静态链接 ${openssl_options[openssl_options_index]}" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            tls_install_args=(static)
            static_ssl=true
        else
            tls_install_args=()
            static_ssl=false
        fi

        echo
        inquirer list_input_index "静态链接 zlib" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            zlib_install_args=(static)
            args+=( USE_ZLIB=1 ZLIB_INC="$DEPENDS_ROOT"/zlib-static/include ZLIB_LIB="$DEPENDS_ROOT"/zlib-static/lib )
        else
            zlib_install_args=()
            ldflags+=("$DEPENDS_ROOT"/zlib/lib)
            args+=( USE_ZLIB=1 ZLIB_INC="$DEPENDS_ROOT"/zlib/include ZLIB_LIB="$DEPENDS_ROOT"/zlib/lib )
        fi

        echo
        inquirer list_input_index "静态链接 Lua" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            static_lua=true
            LuaInstall static
            args+=( USE_LUA=1 LUA_INC="$DEPENDS_ROOT"/lua-static/include LUA_LIB="$DEPENDS_ROOT"/lua-static/lib )
        else
            static_lua=false
            LuaInstall
            ldflags+=("$DEPENDS_ROOT"/lua/lib)
            args+=( USE_LUA=1 LUA_INC="$DEPENDS_ROOT"/lua/include LUA_LIB="$DEPENDS_ROOT"/lua/lib )
        fi

        ZlibInstall ${zlib_install_args[@]+"${zlib_install_args[@]}"}

        case $openssl_options_index in
            0)
                OpensslSourceInstall "${openssl_options[0]}" ${tls_install_args[@]+"${tls_install_args[@]}"}
                if [ "$static_ssl" = false ] 
                then
                    ldflags+=("$DEPENDS_ROOT"/openssl/lib)
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl/include SSL_LIB="$DEPENDS_ROOT"/openssl/lib )
                else
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl-static/include SSL_LIB="$DEPENDS_ROOT"/openssl-static/lib )
                fi
            ;;
            1)
                OpensslSourceInstall "${openssl_options[1]}" ${tls_install_args[@]+"${tls_install_args[@]}"}
                if [ "$static_ssl" = false ] 
                then
                    ldflags+=("$DEPENDS_ROOT"/openssl3/lib)
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl3/include SSL_LIB="$DEPENDS_ROOT"/openssl3/lib )
                else
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl3-static/include SSL_LIB="$DEPENDS_ROOT"/openssl3-static/lib )
                fi
            ;;
            2)
                QuictlsInstall ${tls_install_args[@]+"${tls_install_args[@]}"}
                if [ "$static_ssl" = false ] 
                then
                    ldflags+=("$DEPENDS_ROOT"/quictls/lib)
                    args+=( SSL_INC="$DEPENDS_ROOT"/quictls/include SSL_LIB="$DEPENDS_ROOT"/quictls/lib )
                else
                    args+=( SSL_INC="$DEPENDS_ROOT"/quictls-static/include SSL_LIB="$DEPENDS_ROOT"/quictls-static/lib )
                fi
            ;;
        esac

        mkdir -p "$DEPENDS_ROOT"
        cd "$DEPENDS_ROOT"

        haproxy_ver=$(curl -s -L https://www.haproxy.org/ | grep -oPm1 '<a href="/download/(?!.*dev).+.tar.gz">\K[^<]+' || true)

        if [ ! -d haproxy-"${haproxy_ver}" ] 
        then
            if ! curl -Lm 30 "https://www.haproxy.org/download/${haproxy_ver%.*}/src/haproxy-${haproxy_ver}.tar.gz" -o haproxy-"${haproxy_ver}".tar.gz
            then
                curl -Lm 30 "$FFMPEG_MIRROR_LINK/haproxy/haproxy-${haproxy_ver}.tar.gz" -o haproxy-"${haproxy_ver}".tar.gz
            fi
            Println "$info 解压 haproxy-${haproxy_ver} ..."
            tar xzf haproxy-"${haproxy_ver}".tar.gz
        fi

        cd haproxy-"${haproxy_ver}"

        if [ "$dist" == "mac" ] 
        then
            SourceInstallReady "${pcre_options[pcre_options_index]}"

            if [ "$static_pcre" = false ] 
            then
                ldflags+=("$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib")
            fi

            args+=( PCRE_INC="$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/include" PCRE_LIB="$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib" )

            args+=( USE_PROMEX=1 )

            if [ -n "${ldflags:-}" ] 
            then
                args+=( LDFLAGS="-Wl,-rpath,$(JoinByString : "${ldflags[@]}")" )
            fi

            make TARGET=osx ${args[@]+"${args[@]}"}
        else
            if [ "$dist" == "rpm" ] 
            then
                if [ "$pcre_options_index" -eq 0 ] 
                then
                    SourceInstallReady pcre-devel
                else
                    SourceInstallReady pcre2-devel
                fi
            else
                if [ "$pcre_options_index" -eq 0 ] 
                then
                    SourceInstallReady libpcre3-dev
                else
                    SourceInstallReady libpcre2-dev
                fi
            fi

            args+=( USE_SYSTEMD=1 USE_PROMEX=1 )

            if [ -n "${ldflags:-}" ] 
            then
                args+=( LDFLAGS="-Wl,-rpath,$(JoinByString : "${ldflags[@]}")" )
            fi

            make TARGET=linux-glibc ${args[@]+"${args[@]}"}
        fi

        Println "$info haproxy ${install}成功\n"
    }

    HAProxyUninstall()
    {


        Println "$info haproxy 卸载完成\n"
    }

    HAProxyUpdate()
    {
        HAProxyInstall update
    }
    LuaInstall()
    {
        local build_dir=build lua_path="$DEPENDS_ROOT"/lua static=false patch=https://raw.githubusercontent.com/Homebrew/formula-patches/0dcd11880c7d63eb395105a5cdddc1ca05b40f4a/lua/lua-so.patch

        lua_package=$(curl -s -L https://www.lua.org/download.html | grep -oPm1 '<A HREF="ftp/\K[^"]+' || true)
        lua_name=${lua_package%.tar*}
        lua_ver=${lua_name#lua-}

        if [ -n "${1:-}" ] 
        then
            lua_install_options=("$@")

            if EleInArray static lua_install_options
            then
                build_dir+=-static
                lua_path+=-static
                static=true
            fi
        fi

        if [ ! -d "$DEPENDS_ROOT/$lua_name/$build_dir" ] 
        then
            mkdir -p "$DEPENDS_ROOT"
            cd "$DEPENDS_ROOT"

            if [ "$dist" == "mac" ] 
            then
                DepInstall readline
                DepInstall lua

                mkdir "$lua_name/$build_dir"/{bin,lib,include}
                cp "$HOMEBREW_PREFIX"/opt/lua/bin/{lua,luac} "$lua_name/$build_dir"/bin/
                cp "$HOMEBREW_PREFIX"/opt/lua/include/lua/* "$lua_name/$build_dir"/include/
                cp "$HOMEBREW_PREFIX"/opt/lua/lib/liblua.a "$lua_name/$build_dir"/lib/
                if ! $static 
                then
                    cp "$HOMEBREW_PREFIX"/opt/lua/lib/liblua.dylib "$lua_name/$build_dir"/lib/
                fi
            else
                if [ "$dist" == "rpm" ] 
                then
                    DepInstall readline-devel
                else
                    DepInstall libreadline-dev
                fi

                curl -L "https://www.lua.org/ftp/$lua_package" -o "$lua_package"
                Println "$info 解压 $lua_name ..."
                tar xzf "$lua_package"
                cd "$lua_name"

                if ! $static 
                then
                    curl -Lm 20 "$FFMPEG_MIRROR_LINK/${patch##*/}" -o "${patch##*/}"
                    patch -p1 < "${patch##*/}"
                fi

                make linux-readline INSTALL_TOP="$DEPENDS_ROOT/$lua_name/$build_dir"
                make install INSTALL_TOP="$DEPENDS_ROOT/$lua_name/$build_dir"

                mkdir "$build_dir"/lib/pkgconfig
            cat > "$build_dir"/lib/pkgconfig/lua.pc << EOF
V= ${lua_ver%.*}
R= ${lua_ver}
prefix= $DEPENDS_ROOT/$lua_name/$build_dir
INSTALL_BIN= \${prefix}/bin
INSTALL_INC= \${prefix}/include
INSTALL_LIB= \${prefix}/lib
INSTALL_MAN= \${prefix}/share/man/man1
INSTALL_LMOD= \${prefix}/share/lua/\${V}
INSTALL_CMOD= \${prefix}/lib/lua/\${V}
exec_prefix= \${prefix}
libdir= \${exec_prefix}/lib
includedir= \${prefix}/include

Name: Lua
Description: An Extensible Extension Language
Version: ${lua_ver}
Requires:
Libs: -L\${libdir} -llua -lm
Cflags: -I\${includedir}
EOF
            fi
        fi

        ln -sfn "$DEPENDS_ROOT/$lua_name/$build_dir" "$lua_path"
    }
    ZlibInstall()
    {
        local build_dir=build args=() zlib_path="$DEPENDS_ROOT"/zlib

        if [ -n "${1:-}" ]
        then
            zlib_install_options=("$@")

            if EleInArray static zlib_install_options
            then
                build_dir+=-static
                args=(--static)
                zlib_path="$DEPENDS_ROOT"/zlib-static
            fi
        fi

        while IFS= read -r line
        do
            if [[ $line =~ \<A\ HREF=\"(.+)\.tar\.gz ]] 
            then
                zlib_name=${BASH_REMATCH[1]}
                break
            fi
        done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://www.zlib.net 2> /dev/null)

        if [ ! -d "$DEPENDS_ROOT/$zlib_name/$build_dir" ] 
        then
            mkdir -p "$DEPENDS_ROOT"
            cd "$DEPENDS_ROOT"
            curl -L "https://www.zlib.net/$zlib_name.tar.gz" -o "$zlib_name".tar.gz
            Println "$info 解压 $zlib_name ..."
            tar xzf "$zlib_name".tar.gz
            cd "$zlib_name"
            ./configure --prefix="$DEPENDS_ROOT/$zlib_name/$build_dir" ${args[@]+"${args[@]}"}
            make
            make install
        fi

        ln -sfn "$DEPENDS_ROOT/$zlib_name/$build_dir" "$zlib_path"
    }

    DepInstall sudo

    haproxy_options=( '安装' '更新' '卸载' )
    echo
    inquirer list_input_index "请选择" haproxy_options haproxy_options_index

    case $haproxy_options_index in
        0) HAProxyInstall
        ;;
        1) HAProxyUpdate
        ;;
        2) HAProxyUninstall
        ;;
    esac
elif [ "$self" == "tr" ]
then
    TrojanInstall()
    {
        if [ -s "$TR_CONFIG" ] 
        then
            Println "$error $trojan_name 已存在...\n"
            ExitOnList n "`gettext \"是否覆盖原安装\"`"
        fi

        DepsCheck
        JQInstall

        if ! grep -q "$trojan_name:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser $trojan_name --system --group --no-create-home > /dev/null
            else
                adduser $trojan_name --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin $trojan_name
        fi

        Println "$info 安装 $trojan_name..."

        { curl -s -m 10 "$TR_LINK" || curl -s -m 30 "$TR_LINK_FALLBACK"; } \
        | sed "s+nobody+$trojan_name+g" \
        | sed "s+ 'sha1'++g" \
        | sed "s+ 'sha256'++g" \
        | sed "s+ 'sha512'++g" \
        | sed "s+https://api.github.com/repos/p4gefau1t/trojan-go/releases/latest+$FFMPEG_MIRROR_LINK/$trojan_name.json+g" \
        | sed "s+https://github.com/p4gefau1t/trojan-go/releases/download+$FFMPEG_MIRROR_LINK/$trojan_name+g" | bash

        TrojanConfigInstall

        systemctl daemon-reload
        systemctl enable $trojan_name
        systemctl start $trojan_name

        Println "$info $trojan_name 安装成功\n"
    }

    exit 0
fi
